// "ready" means editable/reviewable, not approved. Semantic incompleteness
// survives older records which lost their per-shot pending flag. A failed
// optional external reviewer does not disable explicit human confirmation.
function hasPendingPromptCompilation(project = {}) {
  return ['running','needs_attention'].includes(project.manualDirectionTranslation?.status)
    || (project.productionPlan?.simpleAssetOnly !== true && ['deferred','running','needs_attention','needs_review'].includes(project.h3AssetDirectSemanticCompile?.status))
    || (project.shots || []).some(shot => shot.promptCompilationPending)
    || project.promptReview?.stageAgentAudit?.status === "needs_semantics"
    || (project.promptReview?.items || []).some(item => item.agentAudit?.status === "needs_semantics");
}

