async function probeFacesInImage(filePath) {
  if (!filePath || !fs.existsSync(filePath)) return { ok: false, faceCount: 0, error: "missing" };
  return { ok: false, faceCount: 0, error: "face_probe_not_required_for_h3" };
}

function productSellingPoints(project) {
  return String(project?.product?.sellingPoints || project?.product?.description || "").trim();
}

function productCommerceFacts(project = {}) {
  const product = project?.product || {};
  const price = String(product.price || product.salePrice || product.currentPrice || "").trim();
  const offer = String(product.offer || product.discount || product.promotion || product.promotionText || "").trim();
  const purchase = String(
    product.purchaseInstructions
    || product.purchaseMethod
    || product.purchaseGuide
    || product.callToAction
    || product.cta
    || ""
  ).trim();
  return {
    price,
    offer,
    purchase,
    safePurchaseClose: purchase || "点击当前页面商品入口查看实时活动和下单",
    hasCommercialClaim: Boolean(price || offer)
  };
}

function normalizeProductContextText(value) {
  return String(value || "")
    .normalize("NFKC")
    .replace(/\r\n?/g, "\n")
    .replace(/[\t\f\v ]+/g, " ")
    .replace(/ *\n+ */g, "\n")
    .trim();
}

function canonicalProductContextText(value) {
  return normalizeProductContextText(value)
    .toLocaleLowerCase()
    .replace(/[\s,，;；、。.!！?？:：·•]+/g, "");
}

function projectCommerceMode(project = {}) {
  return require('./renderer/commerce-input-mode')(project);
}

function topicProductReadiness(project = {}) {
  const commerceMode = projectCommerceMode(project);
  if (commerceMode === "none") return { commerceMode, required: false, ready: true, missing: [] };
  const missing = [];
  const imagePath = String(project?.product?.imagePath || "").trim();
  if (!imagePath || !fs.existsSync(imagePath)) missing.push("上传商品图");
  if (!String(project?.product?.name || "").trim()) missing.push("填写商品名称");
  const commerce = productCommerceFacts(project);
  return { commerceMode, required: true, ready: missing.length === 0, missing };
}

function topicProductContext(project = {}) {
  const commerceMode = projectCommerceMode(project);
  const commerce = productCommerceFacts(project);
  return {
    version: 2,
    commerceMode,
    name: commerceMode === "none" ? "" : normalizeProductContextText(project?.product?.name),
    sellingPoints: commerceMode === "none" ? "" : normalizeProductContextText(productSellingPoints(project)),
    price: commerceMode === "none" ? "" : normalizeProductContextText(commerce.price),
    offer: commerceMode === "none" ? "" : normalizeProductContextText(commerce.offer),
    purchase: commerceMode === "none" ? "" : normalizeProductContextText(commerce.purchase),
    imagePath: commerceMode === "none" ? "" : String(project?.product?.imagePath || "").trim()
  };
}

function topicProductContextDelta(project = {}) {
  const current = topicProductContext(project);
  const generated = project?.ideation?.topicProductContext;
  if (!generated || typeof generated !== "object") {
    return {
      generated: null,
      current,
      legacy: true,
      semanticChanged: current.commerceMode !== "none",
      pathChanged: false,
      changed: true,
      changes: ["legacy"]
    };
  }
  const generatedMode = ["natural", "explicit"].includes(String(generated.commerceMode || "").trim().toLowerCase())
    ? String(generated.commerceMode).trim().toLowerCase()
    : "none";
  const changes = [];
  if (generatedMode !== current.commerceMode) changes.push("commerceMode");
  if (canonicalProductContextText(generated.name) !== canonicalProductContextText(current.name)) changes.push("name");
  if (canonicalProductContextText(generated.sellingPoints) !== canonicalProductContextText(current.sellingPoints)) changes.push("sellingPoints");
  if (canonicalProductContextText(generated.price) !== canonicalProductContextText(current.price)) changes.push("price");
  if (canonicalProductContextText(generated.offer) !== canonicalProductContextText(current.offer)) changes.push("offer");
  if (canonicalProductContextText(generated.purchase) !== canonicalProductContextText(current.purchase)) changes.push("purchase");
  if (String(generated.imagePath || "").trim() !== current.imagePath) changes.push("imagePath");
  const semanticChanged = changes.some(item => item !== "imagePath");
  return {
    generated,
    current,
    legacy: false,
    semanticChanged,
    pathChanged: changes.includes("imagePath"),
    changed: changes.length > 0 || Number(generated.version) !== current.version,
    changes
  };
}

function topicProductContextMatches(project = {}) {
  if (projectCommerceMode(project) === "none") return true;
  const delta = topicProductContextDelta(project);
  // Historical batches remain usable. File locations are transport details,
  // not story semantics, so moving the same uploaded image must never strand a
  // paid topic batch.
  return delta.legacy || !delta.semanticChanged;
}

function productAdaptationDirective(context = {}, commerceMode = "none") {
  if (commerceMode === "none") {
    return "当前唯一创作模式是不带货：保留既有故事内核、人物关系、冲突和主反转，废弃旧商品名、旧卖点与旧带货口播，把原商品节点改写成推动同一剧情的生活动作或证据动作。";
  }
  return [
    `当前唯一商品锁：${context.name || "当前商品"}。`,
    `当前唯一卖点锁：${context.sellingPoints || "以用户当前填写内容为准"}。`,
    "保留既有选题的故事内核、人物关系、冲突和主反转，废弃任何旧商品名与旧卖点；围绕当前商品重新建立“此前可见需求→为什么此刻使用→人物具体使用动作→镜头可见的客观结果→关系或决定变化”的因果桥。"
  ].join("");
}

function synchronizeTopicProductContextForWriting(project = {}, nowValue = new Date().toISOString()) {
  const delta = topicProductContextDelta(project);
  if (!delta.changed) return { changed: false, semanticChanged: false, project, delta };
  const ideation = { ...(project.ideation || {}) };
  const topics = Array.isArray(ideation.topics) ? ideation.topics.map(item => ({ ...item })) : [];
  const selectedTopicId = String(ideation.selectedTopicId || "").trim();
  const selectedIndex = topics.findIndex(item => String(item?.id || "") === selectedTopicId);
  let previousProductPlacement = "";
  if (selectedIndex >= 0 && delta.semanticChanged) {
    const selected = topics[selectedIndex];
    previousProductPlacement = String(selected.productPlacement || "").trim();
    topics[selectedIndex] = {
      ...selected,
      productPlacement: productAdaptationDirective(delta.current, delta.current.commerceMode)
    };
  }
  project.ideation = {
    ...ideation,
    topics,
    topicProductContext: delta.current,
    topicProductSynchronization: {
      version: 1,
      semanticChanged: delta.semanticChanged,
      changes: delta.changes,
      previous: delta.generated,
      current: delta.current,
      ...(previousProductPlacement ? { previousProductPlacement } : {}),
      synchronizedAt: nowValue
    },
    ...(delta.semanticChanged ? {
      status: selectedTopicId ? "topic_selected" : ideation.status,
      errorCode: "",
      message: selectedTopicId
        ? "商品资料已自动同步到所选题材；写作会按当前商品重建自然植入因果桥，无需重新抽题"
        : ideation.message
    } : {})
  };
  project.activity = Array.isArray(project.activity) ? project.activity : [];
  project.activity.unshift({
    id: makeId("activity"),
    at: nowValue,
    type: delta.semanticChanged ? "topic_product_auto_adapted" : "topic_product_context_refreshed",
    summary: delta.semanticChanged
      ? "已保留原选题并自动适配当前商品资料，无需重新生成选题"
      : "已同步商品资料存储位置，不影响原选题与写作断点"
  });
  project.activity = project.activity.slice(0, 300);
  return { changed: true, semanticChanged: delta.semanticChanged, project, delta };
}

function projectScriptFormat(project) {
  if (project?.productionPlan?.scriptFormat === "timed_storyboard") return "timed_storyboard";
  return project?.productionPlan?.scriptFormat === "dialogue" ? "dialogue" : "production";
}

function assertAiScriptFormatConfirmed(project) {
  return "production";
}

function scriptFormatDirective(project) {
  const format = projectScriptFormat(project);
  if (format === "dialogue") {
    return `【项目剧本格式·简易对白稿】最终给用户看的剧本必须以对白为主：只保留简短背景情节、必要场景动作，以及“说话人（对谁说、语气、情绪、表情、身体动作）：原句对白”。每句必须明确且正确绑定说话人和听者，语气/表情随冲突变化，禁止把听者反应混进台词原文。内部仍必须完整填写人物、场景、商品因果、连续性、声音、subshots、dialogueTurns 等全部生产 JSON 字段，不能因为显示格式简化而降低资产、分镜图或视频提示词质量。`;
  }
  if (format === "timed_storyboard") {
    return `【项目剧本格式·秒级分镜成片稿】最终给用户看的正文必须先给出【剧情简介】，再按“幕 → 5至15秒分镜 → 秒级子镜”输出。每个分镜必须明确天气/灯光/氛围、场景、人物、物品、人声设定、承接关系、逐秒镜头动作、【对话汇总】、【音效】和无字幕负向提示。对话汇总是唯一台词事实账本：逐句完整保留原话，绑定正确说话人、明确听者、起止秒数、语气、情绪、表情、身体动作、音量、语速、重音和气口；逐秒镜头不得另造、漏掉或重复台词。内部仍必须完整填写人物/场景四视图/道具商品/连续性/subshots/dialogueTurns/sourceDialogueBindings 等全部生产 JSON 字段，并按当前视频供应商允许的单元时长编译。`;
  }
  return `【项目剧本格式·完整制作稿（原先模式）】继续输出原有完整制作结构；人物、场景、道具商品、生成单元、声音、连续性和结尾闭环均不得省略。每句对白仍必须正确绑定说话人、听者、语气、情绪、表情和身体动作。`;
}

function viewerComprehensionPriorityDirective() {
  return `【全局最高优先级·观众看懂并看进去·前30秒讲清故事】前8秒必须出现观众无需猜测就能看懂的可见钩子；累计30秒内必须通过可见行动与逐句对白明确交代：主角是谁、人物关系、刚发生了什么、当前核心冲突、主角此刻要什么、失败会失去什么，并完成一次不可逆冲突或因果转折。禁止只拍接吻、辱骂、炫富、身份悬念或陌生人对话却不解释关系和冲突；禁止看满一分钟仍无法用一句话复述主线。每个最终视频生成单元必须有对白表并按实际语音时窗安排完整台词；静默反应、动作留白和商品特写只能是有对白单元内部子镜。剧情必须由可见行动和逐句攻防推进，禁止靠旁白摘要、空泛独白或无因果跳切。每句对白原文必须完整保留且只说一次，严格绑定正确说话人和明确听者；同时写清贴合当下动机的语气、情绪起伏、面部微表情、身体动作、音量、语速、重音、气口、站位、朝向和视线。说话人必须对听者表演，听者必须有同步可见反应；禁止对镜念稿、平声播音、集体木头脸、A人说B话、漏句、改句、复读和表情语气与台词含义相反。生成任何资产或视频任务前执行三层门禁：剧本爆点与开场清晰度；逐句对白与表演/站位无冲突；资产、参考顺序与最终提示词逐镜对齐。三层通过后仍保留全部既有校验。`;
}

function ideaSignature(project) {
  const commerceMode = projectCommerceMode(project);
  return JSON.stringify({
    version: 2,
    topicId: project?.ideation?.selectedTopicId || "",
    commerceMode,
    productName: commerceMode === "none" ? "" : canonicalProductContextText(project?.product?.name),
    sellingPoints: commerceMode === "none" ? "" : canonicalProductContextText(productSellingPoints(project)),
    ...Object.fromEntries(['price','offer','purchaseInstructions'].map(key=>[key,commerceMode==='none'?'':canonicalProductContextText(project?.product?.[key])])),
    scriptFormat: projectScriptFormat(project)
  });
}

function ideaSignatureMatchesProject(savedSignature, project = {}) {
  if (!savedSignature) return false;
  let saved;
  try { saved = typeof savedSignature === "string" ? JSON.parse(savedSignature) : savedSignature; }
  catch { return savedSignature === ideaSignature(project); }
  if (!saved || typeof saved !== "object") return false;
  const currentMode = projectCommerceMode(project);
  const hasSavedMode = Object.prototype.hasOwnProperty.call(saved, "commerceMode");
  const savedMode = ["natural", "explicit"].includes(String(saved.commerceMode || "").trim().toLowerCase())
    ? String(saved.commerceMode).trim().toLowerCase()
    : "none";
  const legacyHasProduct = Boolean(canonicalProductContextText(saved.productName) || canonicalProductContextText(saved.sellingPoints));
  const commerceCompatible = hasSavedMode
    ? savedMode === currentMode
    : (currentMode === "none" ? !legacyHasProduct : legacyHasProduct);
  return String(saved.topicId || "") === String(project?.ideation?.selectedTopicId || "")
    && commerceCompatible
    && String(saved.scriptFormat || "production") === projectScriptFormat(project)
    && canonicalProductContextText(saved.productName) === (currentMode === "none" ? "" : canonicalProductContextText(project?.product?.name))
    && canonicalProductContextText(saved.sellingPoints) === (currentMode === "none" ? "" : canonicalProductContextText(productSellingPoints(project)))
    && ['price','offer','purchaseInstructions'].every(key=>canonicalProductContextText(saved[key])===(currentMode==='none'?'':canonicalProductContextText(project?.product?.[key])));
}

function normalizeTopicOptions(data, { expectedCount = 10, idOffset = 0, enforceDiversity = true, allowPartial = false } = {}) {
  const source = Array.isArray(data) ? data : data?.topics;
  if (!Array.isArray(source)) throw Object.assign(new Error("选题模型没有返回 topics 数组"), { code: "TOPIC_RESULT_INVALID" });
  const seen = new Set();
  const topics = source.map((item, index) => {
    // Providers regularly localise otherwise valid JSON keys (for example
    // “标题” / “亮点”).  This is a schema-normalisation concern, not a reason
    // to throw away an already completed and billed creative response.
    const field = (...keys) => keys.map(key => item?.[key]).find(value => value !== undefined && value !== null && String(value).trim() !== "");
    const title = String(field("title", "name", "topic", "标题", "选题", "题目") || "").trim().replace(/^[《]|[》]$/g, "");
    const authoredHighlights = field("highlights", "highlight", "亮点", "高光", "看点", "爆点");
    const highlights = (Array.isArray(authoredHighlights) ? authoredHighlights : String(authoredHighlights || "").split(/[\n；;、]/))
      .map(value => String(value || "").trim()).filter(Boolean).slice(0, 3);
    // Do not invent a local topic: when a provider omitted only the list
    // wrapper, retain three distinct facts it already wrote on the same card.
    for (const fallback of [field("hook", "钩子", "开场"), field("logline", "简介", "故事梗概"), field("reversal", "反转", "结局")]) {
      const value = String(fallback || "").trim();
      if (value && highlights.length < 3 && !highlights.includes(value)) highlights.push(value);
    }
    if (!title || (enforceDiversity && seen.has(title)) || highlights.length !== 3) return null;
    seen.add(title);
    const authoredMechanism = String(item?.storyMechanism || "").trim().toLowerCase();
    const storyMechanism = ["rescue_repaid", "kindness_misjudged", "sacrifice_repaid", "evidence_reversal"].includes(authoredMechanism)
      ? authoredMechanism
      : (/双证|互证|红鲱鱼|谜底|查账/.test(String(item?.reversal || item?.proofChain || "")) ? "evidence_reversal" : "kindness_misjudged");
    return {
      id: `TOPIC_${String(idOffset + index + 1).padStart(2, "0")}`,
      slotId: String(field("slotId", "slot", "序号", "编号") || `T${String(index + 1).padStart(2, "0")}`).trim(),
      title,
      genre: String(field("genre", "题材", "类型") || "现实短剧").trim(),
      relationship: String(field("relationship", "关系", "人物关系") || "熟人关系").trim(),
      storyMechanism,
      conflictDomain: String(field("conflictDomain", "conflict", "冲突领域", "矛盾") || "现实生活").trim(),
      protagonist: String(item?.protagonist || "").trim(),
      antagonist: String(item?.antagonist || "").trim(),
      returningAgent: String(item?.returningAgent || "").trim(),
      logline: String(field("logline", "简介", "故事梗概") || "").trim(),
      hook: String(field("hook", "钩子", "开场") || "").trim(),
      hookAction: String(field("hookAction", "钩子动作", "开场动作", "hook") || "").trim(),
      firstDialogue: String(field("firstDialogue", "首句台词", "第一句台词") || "").trim(),
      highlights,
      valueStatement: String(item?.valueStatement || "").trim(),
      protagonistWound: String(item?.protagonistWound || "").trim(),
      falseBelief: String(item?.falseBelief || "").trim(),
      themeObject: String(item?.themeObject || "").trim(),
      kindnessCost: String(item?.kindnessCost || "").trim(),
      proofChain: String(item?.proofChain || item?.reversal || "").trim(),
      reversalSource: String(item?.reversalSource || item?.proofChain || item?.reversal || "").trim(),
      reversal: String(field("reversal", "反转", "结局") || "").trim(),
      emotionalPayoff: String(field("emotionalPayoff", "情绪兑现", "情绪回收", "结局行动", "行动收束") || "").trim(),
      settlementAction: String(field("settlementAction", "结局行动", "行动收束", "emotionalPayoff", "情绪兑现", "情绪回收") || "").trim(),
      referenceKernel: String(field("referenceKernel", "参考内核", "参考剧情内核") || "").trim(),
      originalityReplacements: (Array.isArray(item?.originalityReplacements) ? item.originalityReplacements : []).map(value => String(value || "").trim()).filter(Boolean).slice(0, 5),
      productPlacement: String(item?.productPlacement || "").trim(),
      audienceAppeal: String(item?.audienceAppeal || "").trim(),
      reason: String(item?.reason || "").trim()
    };
  }).filter(Boolean);
  const relationships = new Set(topics.map(item => item.relationship).filter(Boolean));
  const requiredRelationships = expectedCount >= 10 ? 5 : Math.min(2, expectedCount);
  if ((!allowPartial && topics.length !== expectedCount) || (enforceDiversity && relationships.size < requiredRelationships)) {
    throw Object.assign(new Error(`选题必须是 ${expectedCount} 个不同题材并覆盖至少 ${requiredRelationships} 种关系；当前有效选题 ${topics.length} 个、关系 ${relationships.size} 种`), { code: "TOPIC_DIVERSITY_INVALID" });
  }
  return topics;
}

function topicRepairContext(topics = []) {
  // The repair model only needs identities for the cards that are already
  // locked.  Sending every optional creative field back makes a one-card
  // repair almost as slow as the original ten-card request.
  return topics.map(topic => ({
    slotId: String(topic?.slotId || "").trim(),
    title: String(topic?.title || "").trim(),
    relationship: String(topic?.relationship || "").trim(),
    storyMechanism: String(topic?.storyMechanism || "").trim(),
    conflictDomain: String(topic?.conflictDomain || "").trim(),
    hookAction: String(topic?.hookAction || "").trim()
  }));
}

// A non-empty topic response is already useful paid creative work and must be
// shown immediately. Only a zero-valid-card response may use one explicit
// content-continuation turn; never spend repeatedly just to fill ten slots.
const MAX_TOPIC_CONTENT_REPAIR_ROUNDS = 1;

function topicTitleIdentity(value) {
  return String(value || "")
    .trim()
    .toLowerCase()
    .replace(/[\s"'“”‘’`銆娿€媇:：,，.。!?！？]/g, "");
}

function canonicalizeTopicRepairSet(topics = []) {
  const seenTitles = new Set();
  const seenSlots = new Set();
  const slots = Array.from({ length: 10 }, (_, index) => `T${String(index + 1).padStart(2, "0")}`);
  return topics.filter(Boolean).map((topic, index) => {
    const titleKey = topicTitleIdentity(topic.title);
    if (!titleKey || seenTitles.has(titleKey)) return null;
    seenTitles.add(titleKey);
    const authoredSlot = String(topic.slotId || "").trim().toUpperCase();
    const slotId = /^T(?:0[1-9]|10)$/.test(authoredSlot) && !seenSlots.has(authoredSlot)
      ? authoredSlot
      : slots.find(slot => !seenSlots.has(slot)) || `T${String(index + 1).padStart(2, "0")}`;
    seenSlots.add(slotId);
    const slotNumber = Number(slotId.slice(1));
    return {
      ...topic,
      slotId,
      id: Number.isInteger(slotNumber) && slotNumber >= 1 && slotNumber <= 10
        ? `TOPIC_${String(slotNumber).padStart(2, "0")}`
        : `TOPIC_${String(index + 1).padStart(2, "0")}`
    };
  }).filter(Boolean).slice(0, 10);
}

function normalizedTopicRepairSet(candidates = []) {
  if (!Array.isArray(candidates) || candidates.length === 0) return [];
  try {
    return canonicalizeTopicRepairSet(normalizeTopicOptions({ topics: candidates }, {
      expectedCount: 10,
      enforceDiversity: false,
      allowPartial: true
    }));
  } catch {
    return [];
  }
}

function topicRepairCandidates(data, rawText = "") {
  const direct = topicCandidateArray(data);
  const recovered = recoverTopicObjectsFromRaw(rawText);
  return [...direct, ...recovered];
}

function topicRepairGap(topics = [], { expectedCount = 10, enforceDiversity = true } = {}) {
  const locked = canonicalizeTopicRepairSet(topics);
  const occupiedSlots = new Set(locked.map(topic => String(topic.slotId || "").trim().toUpperCase()).filter(Boolean));
  const missingSlots = Array.from({ length: expectedCount }, (_, index) => `T${String(index + 1).padStart(2, "0")}`)
    .filter(slot => !occupiedSlots.has(slot));
  const relationships = [...new Set(locked.map(topic => String(topic.relationship || "").trim()).filter(Boolean))];
  const requiredRelationships = enforceDiversity && expectedCount >= 10 ? 5 : 0;
  const missingRelationshipCount = Math.max(0, requiredRelationships - relationships.length);
  const replacementSlots = [];
  if (missingRelationshipCount > 0) {
    const firstByRelationship = new Set();
    for (const topic of locked) {
      const relationship = String(topic.relationship || "").trim();
      if (!relationship || !firstByRelationship.has(relationship)) {
        if (relationship) firstByRelationship.add(relationship);
        continue;
      }
      replacementSlots.push(String(topic.slotId || "").trim().toUpperCase());
    }
  }
  const requestedReplacementSlots = replacementSlots.slice(0, missingRelationshipCount);
  const requestedSlots = [...missingSlots, ...requestedReplacementSlots];
  return {
    locked,
    relationships,
    requiredRelationships,
    missingRelationshipCount,
    missingSlots,
    replacementSlots: requestedReplacementSlots,
    requestedSlots,
    requestedCount: requestedSlots.length,
    complete: locked.length === expectedCount && missingRelationshipCount === 0
  };
}

