function validateBlueprint(data, productName = "", options = {}) {
  const source = data && typeof data === "object" ? data : {};
  let characters = Array.isArray(source.characters) ? source.characters : [];
  const scenes = Array.isArray(source.scenes) ? source.scenes : [];
  const plans = Array.isArray(source.shotPlan) ? source.shotPlan : [];
  const expectedCount = Math.max(6, Math.round(Number(options.expectedUnitCount) || plans.length || 30));
  const targetSeconds = Math.max(30, Math.round(Number(options.targetDurationSeconds) || plans.reduce((sum, item) => sum + (Number(item?.duration) || 10), 0) || 300));
  const storyMechanism = String(source?.storyCore?.storyMechanism || source?.storyMechanism || "kindness_misjudged").trim().toLowerCase();
  const failures = [];
  if (characters.length < 3 || characters.length > 6) failures.push(`核心人物必须为3-6人，当前${characters.length}人`);
  const density = storyDensityTargets(targetSeconds, expectedCount);
  if (scenes.length < density.sceneMin || scenes.length > density.sceneMax) failures.push(`主要场景必须为${density.sceneMin}-${density.sceneMax}个，当前${scenes.length}个；每个场景都要承担新任务，不得只换背景`);
  if (plans.length !== expectedCount) failures.push(`生成单元计划必须恰好${expectedCount}个，当前${plans.length}个`);
  let normalizedPlans = plans.slice(0, expectedCount).map((item, index) => ({
    ...item,
    ...normalizePlanProductionFields(item, Number(item?.duration) || 10),
    id: `S${String(index + 1).padStart(2, "0")}`,
    duration: Number(item?.duration) || 10,
    characters: (Array.isArray(item?.characters) ? item.characters : []).map(String).filter(Boolean),
    scene: String(item?.scene || "").trim(),
    mainlineStage: String(item?.mainlineStage || "").trim(),
    mainlineBeat: String(item?.mainlineBeat || "").trim(),
    kindnessCost: String(item?.kindnessCost || "无").trim() || "无",
    reversalSetup: String(item?.reversalSetup || "无").trim() || "无",
    stateBefore: String(item?.stateBefore || "").trim(),
    stateAfter: String(item?.stateAfter || "").trim(),
    causalLink: String(item?.causalLink || "").trim(),
    visualBeat: String(item?.visualBeat || item?.action || "").trim(),
    compositionPlan: String(item?.compositionPlan || "").trim(),
    audioPlan: String(item?.audioPlan || "").trim(),
    productMention: Boolean(item?.productMention),
    productCausalBridge: item?.productCausalBridge && typeof item.productCausalBridge === "object" ? { ...item.productCausalBridge } : {},
    subshotTarget: Math.max(1, Number(item?.subshotTarget) || 1)
  }));
  const characterIdByName = new Map(characters.map((character, index) => [String(character?.name || "").trim(), `C${String(index + 1).padStart(2, "0")}`]));
  for (const plan of normalizedPlans) {
    const presenceIds = plan.scenePresenceCharacterIds.length
      ? plan.scenePresenceCharacterIds
      : plan.characters.map(name => characterIdByName.get(String(name || "").trim())).filter(Boolean);
    const isolatedProductFrame = /product_(?:packshot|detail)/i.test(String(plan.productShotType || plan.shotFunction || ""));
    const visibleIds = isolatedProductFrame ? [] : (plan.visibleCharacterIds.length ? plan.visibleCharacterIds : presenceIds.slice(0, 2));
    plan.scenePresenceCharacterIds = [...new Set(presenceIds)];
    plan.visibleCharacterIds = [...new Set(visibleIds)];
    plan.focusCharacterId = plan.focusCharacterId || plan.visibleCharacterIds[0] || "";
    plan.counterpartCharacterId = plan.visibleCharacterIds.find(id => id !== plan.focusCharacterId) || "";
    plan.imageReferenceCharacterIds = [...plan.visibleCharacterIds];
    plan.videoReferenceCharacterIds = [...plan.visibleCharacterIds];
    plan.shotFunction = plan.shotFunction || (plan.productMention ? "product_use" : (plan.visibleCharacterIds.length > 1 ? "two_shot" : "speaker_closeup"));
    plan.sceneObjective = plan.sceneObjective || plan.mainlineBeat;
    plan.transitionReason = plan.transitionReason || "由上一镜动作、视线或声音承接";
    plan.productShotType = plan.productMention ? (plan.productShotType === "none" ? "product_use" : plan.productShotType) : "none";
  }
  const referenceRepair = reconcileOrphanCharacterReferences({
    ...source,
    characters,
    shots: normalizedPlans,
    sourceDialogueLedger: source.sourceDialogueLedger
  });
  characters = referenceRepair.project.characters;
  normalizedPlans = referenceRepair.project.shots;
  const durationSum = normalizedPlans.reduce((sum, item) => sum + (Number(item.duration) || 0), 0);
  if (durationSum !== targetSeconds) failures.push(`单元时长合计 ${durationSum} 秒，必须精确等于剧总时长 ${targetSeconds} 秒`);
  const stages = normalizedPlans.map(item => `${item.mainlineStage} ${item.mainlineBeat}`);
  const count = pattern => stages.filter(value => pattern.test(value)).length;
  const reversalIndex = normalizedPlans.findIndex(item => item.mainlineStage === "main_reversal");
  const pressureNeed = Math.max(4, Math.floor(expectedCount / 5));
  const kindnessNeed = Math.max(1, Math.round(expectedCount / 15));
  const payoffNeed = Math.max(2, Math.round(expectedCount / 20));
  const coverageNeed = Math.floor(expectedCount * 0.9);
  const visualNeed = Math.max(1, expectedCount - 4);
  if (count(/pressure|加压|逼迫|羞辱|退路/) < pressureNeed) failures.push(`逐级加压少于${pressureNeed}次`);
  if (normalizedPlans.filter(item => item.mainlineStage === "cost_kindness" || !/^(无|没有)$/.test(item.kindnessCost)).length < kindnessNeed) failures.push(`有成本善意少于${kindnessNeed}次`);
  const proofNeed = storyMechanism === "evidence_reversal" ? 2 : 1;
  if (count(/evidence|证据|物证|可见事实|见证|恩人|当事人|承诺/) < proofNeed) failures.push(`${storyMechanism === "evidence_reversal" ? "证据谜题" : "清晰善恶主线"}的前置可见证明少于${proofNeed}次`);
  if (normalizedPlans.filter(item => item.mainlineStage === "main_reversal").length !== 1) failures.push("必须且只能有1个主反转单元");
  if (normalizedPlans.filter(item => item.mainlineStage === "payoff" || /兑现|回收|奖惩|承担|归还|救助|站队/.test(item.mainlineBeat)).length < payoffNeed) failures.push(`行动奖惩/回收少于${payoffNeed}次`);
  if (normalizedPlans.filter(item => item.mainlineBeat).length < coverageNeed) failures.push("唯一主线覆盖不足90%");
  const productionFieldCoverage = field => normalizedPlans.filter(item => String(item[field] || "").trim()).length / Math.max(1, normalizedPlans.length);
  for (const [field, label] of [["stateBefore", "单元开始状态"], ["stateAfter", "单元结束状态"], ["causalLink", "因果承接"], ["visualBeat", "独占画面拍点"], ["compositionPlan", "差异构图"], ["audioPlan", "全时段声音计划"]]) {
    if (productionFieldCoverage(field) < 0.9) failures.push(`${label}覆盖不足90%`);
  }
  const visualBeatKeys = normalizedPlans.map(item => item.visualBeat.replace(/[\s，。；、：:！？!?]/g, "").slice(0, 24)).filter(Boolean);
  if (new Set(visualBeatKeys).size < visualNeed) failures.push(`至少${visualNeed}个生成单元必须拥有不同的可见画面拍点`);
  const singleCharacterUnits = normalizedPlans.filter(item => item.visibleCharacterIds.length <= 1).length;
  if (singleCharacterUnits < Math.ceil(expectedCount * 0.5)) failures.push(`单人近景/动作单元必须至少占全片50%，当前${singleCharacterUnits}/${expectedCount}`);
  const sceneCounts = new Map();
  for (const item of normalizedPlans) sceneCounts.set(item.scene, (sceneCounts.get(item.scene) || 0) + 1);
  const dominantSceneCount = Math.max(0, ...sceneCounts.values());
  if (dominantSceneCount > Math.ceil(expectedCount * 0.5)) failures.push(`单一场景最多承载全片50%生成单元，当前最多${dominantSceneCount}/${expectedCount}；必须用有任务的救援/送医/上门/公开清算/结果场景推进`);
  const contractFailures = productionHardContractFailures({ shots: normalizedPlans }, {
    productName,
    commerceShotCount: options.commerceShotCount,
    requireHook: true,
    requireHookDialogue: false,
    requireDialogueTables: false,
    requireProduct: Boolean(productName)
  });
  if (contractFailures.length && !options.bypassProductionContracts && !options.advisoryOnly) {
    throw Object.assign(new Error(`剧本蓝图违反生产硬合同：${contractFailures.map(item => item.message).join("；")}`), {
      code: "SCRIPT_BLUEPRINT_CONTRACT_FAILED",
      failures: contractFailures
    });
  }
  const activeFailures = activeBlueprintFailures(failures, options);
  if (activeFailures.length && !options.skipQualityGates && !options.advisoryOnly) throw Object.assign(new Error(`剧本蓝图未达标：${activeFailures.join("；")}`), { code: "SCRIPT_BLUEPRINT_INVALID", failures: activeFailures });
  return {
    ...source,
    characters: characters.map((item, index) => ({ ...item, id: item.id || `C${String(index + 1).padStart(2, "0")}` })),
    scenes: scenes.map((item, index) => ({ ...item, id: `SC${String(index + 1).padStart(2, "0")}` })),
    props: Array.isArray(source.props) ? source.props : [],
    shotPlan: normalizedPlans,
    targetDurationSeconds: targetSeconds
  };
}

function validateShotBatch(data, plannedShots, productName = "", videoEngine = "hailuo-h3", options = {}) {
  const generationMode = normalizeProjectMode(options.generationMode || "continuation");
  let raw = Array.isArray(data?.shots) ? data.shots : [];
  const failures = [];
  const contractFailures = [];
  if (raw.length !== plannedShots.length) {
    throw Object.assign(new Error(`本批必须返回${plannedShots.length}个单元，当前${raw.length}个`), { code: "SCRIPT_UNIT_BATCH_STRUCTURE_INVALID" });
  }
  const expectedIds = plannedShots.map(plan => String(plan?.id || "").toUpperCase());
  const rawById = new Map(raw.map(item => [String(item?.id || "").toUpperCase(), item]));
  if (rawById.size !== expectedIds.length || expectedIds.some(id => !rawById.has(id))) {
    throw Object.assign(new Error(`生成单元ID必须与 ${expectedIds.join("、")} 一一对应，禁止缺号、重复或错号`), {
      code: "SCRIPT_UNIT_BATCH_SEQUENCE_INVALID",
      expectedIds,
      actualIds: raw.map(item => String(item?.id || "").trim())
    });
  }
  const repairedReferences = reconcileOrphanCharacterReferences({
    characters: options.characters,
    shots: [...plannedShots, ...raw]
  }, { allowCharacterCreation: false });
  plannedShots = repairedReferences.project.shots.slice(0, plannedShots.length);
  raw = repairedReferences.project.shots.slice(plannedShots.length);
  assertUnitCharacterReferencesPlanned(raw, plannedShots);
  const shots = plannedShots.map((plan, index) => {
    const item = rawById.get(String(plan.id || "").toUpperCase());
    const unitDuration = Number(plan.duration) || 10;
    const planProductionFields = normalizePlanProductionFields(plan, unitDuration);
    const allowedVisibleCharacterIds = planProductionFields.visibleCharacterIds;
    const authoredSubshots = Array.isArray(item.subshots) ? item.subshots : [];
    const structuredDialogueTurns = Array.isArray(item.dialogueTurns)
      ? item.dialogueTurns.map(turn => normalizeDialogueTurn(turn, turn?.subshotNumber || 1)).filter(turn => turn.speakerId && turn.text)
      : [];
    const derivedSubshotTurns = authoredSubshots.flatMap((subshot, subIndex) => parseCompiledDialogueSegments(subshot?.dialogue || "", []).map(turn => normalizeDialogueTurn({
      speakerId: turn.speaker,
      text: turn.spokenText,
      metadata: turn.metadata,
      subshotNumber: subIndex + 1,
      onScreen: !normalizeStringArray(subshot?.offscreenSpeakerIds).includes(turn.speaker)
    }, subIndex + 1)));
    const derivedFlatTurns = parseCompiledDialogueSegments(item.dialogue || "", []).map(turn => normalizeDialogueTurn({
      speakerId: turn.speaker,
      text: turn.spokenText,
      metadata: turn.metadata,
      subshotNumber: 1
    }, 1));
    const authoredDialogueTurns = structuredDialogueTurns.length
      ? structuredDialogueTurns
      : (derivedSubshotTurns.length ? derivedSubshotTurns : derivedFlatTurns);
    const atomicSubshotPlan = planAtomicDialogueSubshots(unitDuration, authoredDialogueTurns, {
      visualReserveSeconds: Math.max(3, Number(item?.visualReserveSeconds ?? plan?.visualReserveSeconds) || 3)
    });
    const dialogueTurnsStructured = atomicSubshotPlan.turns;
    const visualSources = authoredSubshots.length ? authoredSubshots : [{
      action: item.action || plan.action,
      framing: item.shotSize || plan.shotSize,
      camera: item.cameraMove || plan.cameraMove,
      sound: item.audioPlan || item.soundDesign || plan.audioPlan,
      visibleCharacterIds: allowedVisibleCharacterIds
    }];
    const rawSubshots = atomicSubshotPlan.units.map((unit, unitIndex) => {
      const unitCount = atomicSubshotPlan.units.length;
      let sources;
      if (unitCount < visualSources.length) {
        const startIndex = Math.floor(unitIndex * visualSources.length / unitCount);
        const endIndex = Math.max(startIndex + 1, Math.floor((unitIndex + 1) * visualSources.length / unitCount));
        sources = visualSources.slice(startIndex, unitIndex === unitCount - 1 ? visualSources.length : endIndex);
      } else {
        const sourceIndex = Math.min(visualSources.length - 1, Math.floor((unitIndex + 0.5) * visualSources.length / unitCount));
        sources = [visualSources[sourceIndex]];
      }
      const base = { ...(sources[0] || {}) };
      const mergeField = key => [...new Set(sources.map(source => String(source?.[key] || "").trim()).filter(Boolean))].join("；");
      return {
        ...base,
        start: unit.start,
        end: unit.end,
        action: mergeField("action") || String(item.action || plan.action || "").trim(),
        actionEn: mergeField("actionEn"),
        sound: mergeField("sound") || String(item.audioPlan || item.soundDesign || plan.audioPlan || "").trim(),
        soundEn: mergeField("soundEn")
      };
    });
    const subshots = rawSubshots.map((subshot, subIndex) => {
      const turns = dialogueTurnsStructured.filter(turn => turn.subshotNumber === subIndex + 1).map(turn => ({ ...turn }));
      const speakerIds = [...new Set(turns.map(turn => String(turn?.speakerId || "").trim()).filter(Boolean))];
      const listenerIds = [...new Set(turns.flatMap(turn => normalizeStringArray(turn?.listenerIds)).filter(Boolean))];
      const authoredVisible = normalizeStringArray(subshot.visibleCharacterIds).filter(id => allowedVisibleCharacterIds.includes(id));
      const shotType = String(subshot.shotType || subshot.function || planProductionFields.shotFunction || "").trim();
      const productIsolated = /product_(?:packshot|detail)/i.test(`${shotType} ${planProductionFields.productShotType}`);
      const onScreenSpeakers = turns.filter(turn => turn.onScreen !== false).map(turn => String(turn.speakerId || "").trim());
      const derivedVisible = productIsolated
        ? []
        : [...new Set([
          ...onScreenSpeakers,
          ...authoredVisible,
          ...listenerIds,
          ...allowedVisibleCharacterIds
        ].filter(id => allowedVisibleCharacterIds.includes(id)))];
      const offscreenSpeakerIds = [...new Set([
        ...normalizeStringArray(subshot.offscreenSpeakerIds),
        ...speakerIds.filter(id => !derivedVisible.includes(id))
      ].filter(Boolean))];
      const primarySpeakerId = speakerIds[0] || "";
      return {
        number: subIndex + 1,
        start: Math.max(0, Number(subshot.start) || 0),
        end: Math.min(unitDuration, Math.max(0, Number(subshot.end) || 0)),
        shotType: shotType || (derivedVisible.length > 1 ? "two_shot" : "speaker_closeup"),
        cutReason: String(subshot.cutReason || subshot.transition || planProductionFields.transitionReason || "由台词、视线或动作承接").trim(),
        framing: String(subshot.framing || "中近景"),
        camera: String(subshot.camera || "稳定机位"),
        action: String(subshot.action || "").trim(),
        actionEn: String(subshot.actionEn || item.actionEn || planProductionFields.actionEn || "").trim(),
        framingEn: String(subshot.framingEn || item.framingEn || planProductionFields.framingEn || "").trim(),
        cameraEn: String(subshot.cameraEn || item.cameraEn || planProductionFields.cameraEn || "").trim(),
        stateBeforeEn: String(subshot.stateBeforeEn || (subIndex === 0 ? item.stateBeforeEn || planProductionFields.stateBeforeEn : "")).trim(),
        stateAfterEn: String(subshot.stateAfterEn || (subIndex === rawSubshots.length - 1 ? item.stateAfterEn || planProductionFields.stateAfterEn : "")).trim(),
        soundEn: String(subshot.soundEn || item.soundEn || planProductionFields.soundEn || "").trim(),
        dialogue: formatDialogueTurns(turns) || String(subshot.dialogue || "").trim(),
        dialogueTurns: turns,
        sound: String(subshot.sound || "连续现场环境声").trim(),
        transition: String(subshot.transition || subshot.cutReason || planProductionFields.transitionReason || "视线/动作承接").trim(),
        visibleCharacterIds: derivedVisible,
        speakerIds,
        cameraOwnerId: String(subshot.cameraOwnerId || item.cameraOwnerId || primarySpeakerId || planProductionFields.focusCharacterId || derivedVisible[0] || "").trim(),
        mouthOwnerId: String(subshot.mouthOwnerId || item.mouthOwnerId || primarySpeakerId).trim(),
        listenerIds,
        offscreenSpeakerIds,
        speakerFacing: String(subshot.speakerFacing || "").trim(),
        listenerFacing: String(subshot.listenerFacing || "").trim(),
        eyelineDirection: String(subshot.eyelineDirection || "").trim(),
        emotionBeat: String(subshot.emotionBeat || "").trim(),
        faceAction: String(subshot.faceAction || "").trim(),
        bodyAction: String(subshot.bodyAction || "").trim(),
        voiceDelivery: String(subshot.voiceDelivery || "").trim()
      };
    });
    const dialogue = formatDialogueTurns(dialogueTurnsStructured) || String(item.dialogue || subshots.map(subshot => subshot.dialogue).filter(Boolean).join("；")).trim();
    const timelineContinuous = subshots.length >= 1
      && Math.abs(subshots[0].start) < 0.01
      && subshots.every((subshot, subIndex) => subshot.end > subshot.start
        && (subIndex === 0 || Math.abs(subshot.start - subshots[subIndex - 1].end) <= 0.1))
      && Math.abs(subshots.at(-1).end - unitDuration) <= 0.5;
    if (!timelineContinuous) {
      contractFailures.push({ code: "SUBSHOT_TIMELINE_CONTRACT", shotId: plan.id, message: `${plan.id}的动态subshots必须无缝连续覆盖0-${unitDuration}秒` });
    }
    if (!plan.productMention && productName && (Boolean(item.productMention) || textMentionsProduct(shotContractText(item), productName))) {
      contractFailures.push({
        code: "PRODUCT_FLAG_MISMATCH",
        shotId: plan.id,
        message: `${plan.id}标记为不出现商品，但标题、动作、对白、画面或提示词已经写入商品名称/俗称`
      });
    }
    const shot = {
      ...item,
      ...planProductionFields,
      id: plan.id,
      title: String(item.title || plan.title || plan.action || plan.id),
      duration: unitDuration,
      characters: plan.characters,
      scene: plan.scene,
      action: String(item.action || plan.action || "").trim(),
      actionEn: String(item.actionEn || plan.actionEn || planProductionFields.actionEn || "").trim(),
      mainlineStage: plan.mainlineStage,
      mainlineBeat: plan.mainlineBeat,
      kindnessCost: plan.kindnessCost,
      reversalSetup: plan.reversalSetup,
      stateBefore: String(item.stateBefore || plan.stateBefore || "").trim(),
      stateAfter: String(item.stateAfter || plan.stateAfter || "").trim(),
      stateBeforeEn: String(item.stateBeforeEn || plan.stateBeforeEn || planProductionFields.stateBeforeEn || "").trim(),
      stateAfterEn: String(item.stateAfterEn || plan.stateAfterEn || planProductionFields.stateAfterEn || "").trim(),
      causalLink: String(item.causalLink || plan.causalLink || "").trim(),
      visualBeat: String(item.visualBeat || plan.visualBeat || item.action || plan.action || "").trim(),
      compositionPlan: String(item.compositionPlan || plan.compositionPlan || "").trim(),
      audioPlan: String(item.audioPlan || plan.audioPlan || item.soundDesign || "").trim(),
      dialogueArc: item.dialogueArc && typeof item.dialogueArc === "object"
        ? { ...item.dialogueArc }
        : { ...planProductionFields.dialogueArc },
      productCausalBridge: item.productCausalBridge && typeof item.productCausalBridge === "object"
        ? { ...item.productCausalBridge }
        : (plan.productCausalBridge && typeof plan.productCausalBridge === "object" ? { ...plan.productCausalBridge } : {}),
      dialogue,
      dialogueTurns: dialogueTurnsStructured,
      cameraOwnerId: String(item.cameraOwnerId || dialogueTurnsStructured[0]?.speakerId || planProductionFields.focusCharacterId || "").trim(),
      mouthOwnerId: String(item.mouthOwnerId || dialogueTurnsStructured[0]?.speakerId || "").trim(),
      criticalOnScreenText: (Array.isArray(item.criticalOnScreenText) ? item.criticalOnScreenText : [])
        .map(cue => ({
          text: String(cue?.text || "").trim(),
          start: Math.max(0, Number(cue?.start) || 0),
          end: Math.min(unitDuration, Math.max(0, Number(cue?.end) || unitDuration)),
          anchor: ["top", "center", "bottom"].includes(String(cue?.anchor || "")) ? String(cue.anchor) : "bottom",
          purpose: String(cue?.purpose || "").trim()
        }))
        .filter(cue => cue.text && cue.end > cue.start),
      shotSize: String(item.shotSize || subshots[0]?.framing || "中景"),
      framingEn: String(item.framingEn || plan.framingEn || planProductionFields.framingEn || subshots[0]?.framingEn || "").trim(),
      cameraMove: String(item.cameraMove || subshots.map(subshot => subshot.camera).join(" → ") || "稳定机位"),
      cameraEn: String(item.cameraEn || plan.cameraEn || planProductionFields.cameraEn || subshots.map(subshot => subshot.cameraEn).filter(Boolean).join("; ")).trim(),
      emotion: String(item.emotion || plan.emotion || "").trim(),
      emotionArc: item.emotionArc && typeof item.emotionArc === "object"
        ? { ...item.emotionArc }
        : { ...planProductionFields.emotionArc },
      performanceBeats: item.performanceBeats && typeof item.performanceBeats === "object"
        ? { ...item.performanceBeats }
        : { ...planProductionFields.performanceBeats },
      performance: String(item.performance || subshots.map(subshot => subshot.action).join("；")).trim(),
      soundDesign: String(item.soundDesign || "对白清晰，现场环境声连续").trim(),
      soundEn: String(item.soundEn || plan.soundEn || planProductionFields.soundEn || subshots.map(subshot => subshot.soundEn).filter(Boolean).join("; ")).trim(),
      soundCueSheet: item.soundCueSheet && typeof item.soundCueSheet === "object" ? {
        bed: String(item.soundCueSheet.bed || "").trim(),
        sfx: String(item.soundCueSheet.sfx || "").trim(),
        bgm: String(item.soundCueSheet.bgm || "").trim(),
        ducking: String(item.soundCueSheet.ducking || "").trim(),
        silenceDesign: String(item.soundCueSheet.silenceDesign || "").trim(),
        motifRecall: String(item.soundCueSheet.motifRecall || "").trim()
      } : null,
      transitionIn: String(item.transitionIn || planProductionFields.transitionReason || "由上一镜动作、视线或声音承接").trim(),
      transitionOut: String(item.transitionOut || planProductionFields.transitionReason || "以动作、视线或声音桥接下一镜").trim(),
      startFrame: String(item.startFrame || plan.startFrame || "").trim(),
      endFrame: String(item.endFrame || plan.endFrame || "").trim(),
      subshots,
      sourceEditShots: [],
      referencePlan: modeAwareReferencePlan(generationMode, plan.productMention, item.referencePlan),
      productMention: plan.productMention,
      imagePrompt: String(item.imagePrompt || [
        generationMode === "storyboard_sheet" ? "由多个独立项目画幅、等比例且绝不拉伸的画格拼成逐秒分镜合图" : "写实短剧关键帧",
        plan.scene,
        item.visualBeat || plan.visualBeat || item.action || plan.action,
        `${item.startFrame || plan.startFrame || "起始动作"}→${item.endFrame || plan.endFrame || "动作结果"}`
      ].filter(Boolean).join("；")).trim().slice(0, 180),
      videoPrompt: String(item.videoPrompt || [
        `${unitDuration}秒连续表演`,
        subshots.map(subshot => `${subshot.start}-${subshot.end}秒 ${subshot.framing}/${subshot.camera}：${subshot.action}`).join("；"),
        dialogue ? `对白节拍：${dialogue}` : "",
        item.soundCueSheet && typeof item.soundCueSheet === "object" ? `声音：${Object.values(item.soundCueSheet).filter(Boolean).join("；")}` : ""
      ].filter(Boolean).join("；")).trim().slice(0, 220),
      secondPanels: generationMode === "storyboard_sheet"
        ? normalizeSecondPanels(item.secondPanels, unitDuration, {
          subshots,
          shotSize: String(item.shotSize || subshots[0]?.framing || "中景"),
          cameraMove: String(item.cameraMove || ""),
          visualBeat: String(item.visualBeat || plan.visualBeat || item.action || plan.action || ""),
          action: String(item.action || plan.action || "").trim(),
          dialogue,
          cameraOwnerId: String(item.cameraOwnerId || dialogueTurnsStructured[0]?.speakerId || planProductionFields.focusCharacterId || "").trim(),
          mouthOwnerId: String(item.mouthOwnerId || dialogueTurnsStructured[0]?.speakerId || "").trim(),
          speakerId: String(dialogueTurnsStructured[0]?.speakerId || "").trim(),
          listenerIds: normalizeStringArray(dialogueTurnsStructured[0]?.listenerIds),
          visibleCharacterIds: planProductionFields.visibleCharacterIds
        })
        : (Array.isArray(item.secondPanels) ? normalizeSecondPanels(item.secondPanels, unitDuration, { subshots }) : [])
    };
    shot.productCausalBridge = deriveProductCausalBridge(shot, { name: productName }, { characters: options.characters });
    if (videoEngine === "hailuo-h3") {
      const assignmentSource = options.allowedSpeakersByShot instanceof Map
        ? options.allowedSpeakersByShot.get(String(plan.id || "").toUpperCase())
        : options.allowedSpeakersByShot?.[String(plan.id || "").toUpperCase()];
      const allowedSpeakerIds = normalizeStringArray(assignmentSource?.ids || assignmentSource?.allowedSpeakerIds).map(value => value.toUpperCase());
      const allowedSpeakerNames = normalizeStringArray(assignmentSource?.names || assignmentSource?.allowedSpeakerNames);
      const speakerAliasToId = new Map(allowedSpeakerIds.map(id => [id, id]));
      allowedSpeakerNames.forEach((name, index) => {
        if (allowedSpeakerIds[index]) speakerAliasToId.set(name, allowedSpeakerIds[index]);
      });
      const rawSpeakerNames = new Set([
        ...dialogueTurnsStructured.map(turn => String(turn?.speakerId || "").trim()),
        ...subshots.flatMap(entry => normalizeStringArray(entry.offscreenSpeakerIds)),
        ...parseDialogueSegments(
        subshots.some(entry => String(entry.dialogue || "").trim())
          ? subshots.map(entry => entry.dialogue).filter(Boolean).join("；")
          : dialogue,
        []
      ).map(turn => String(turn.speaker || "").trim())
      ].filter(Boolean));
      const speakerNames = new Set([...rawSpeakerNames].map(name => speakerAliasToId.get(name) || speakerAliasToId.get(name.toUpperCase()) || name));
      const configuredMax = Number(options.maxSpeakingCharacters);
      const maxSpeakingCharacters = Number.isFinite(configuredMax)
        ? Math.max(1, Math.min(3, Math.round(configuredMax)))
        : 3;
      if (speakerNames.size > maxSpeakingCharacters) {
        contractFailures.push({
          code: maxSpeakingCharacters < 3 ? "HAILUO_AUTOMATIC_SPEAKER_LIMIT" : "HAILUO_AUDIO_REFERENCE_LIMIT",
          shotId: plan.id,
          message: `${plan.id}共有${speakerNames.size}名说话人，超过当前海螺 H3 ${maxSpeakingCharacters < 3 ? "自动写作连续剧情块上限" : "单块音色参考上限"}；本Sxx只保留核心两人问答，第三人拆到有因果动机的相邻单元`
        });
      }
      if (assignmentSource) {
        const allowedTokens = new Set([...allowedSpeakerIds, ...allowedSpeakerNames]);
        const unauthorized = [...rawSpeakerNames].filter(name => !allowedTokens.has(name) && !allowedTokens.has(name.toUpperCase()));
        if (unauthorized.length) {
          contractFailures.push({
            code: "HAILUO_SPEAKER_ASSIGNMENT_VIOLATION",
            shotId: plan.id,
            message: `${plan.id}出现未分配说话人 ${unauthorized.join("、")}；本镜只允许 ${[...allowedSpeakerIds, ...allowedSpeakerNames].join("/") || "无人说话"}，其他人物必须全镜静默反应，禁止拆镜、改ID或改时长`
          });
        }
      }
      // The writing model owns Chinese story, dialogue, performance and sound facts.
      // It is deliberately forbidden from producing hailuoPrompt. The canonical
      // six-section English H3 prompt is compiled only after final references,
      // Picture/Audio numbering and the resolved per-shot mode are known.
    }
    return shot;
  });
  const speakingUnits = shots.filter(shot => (Array.isArray(shot.characters) ? shot.characters : []).length > 0 || dialogueTurns(shot.dialogue) > 0);
  const weakShell = /^(?:[\u4e00-\u9fffA-Za-z0-9_·]{1,16}\s*[：:]\s*(?:好|没事|这……|这\.\.\.|嗯|啊|哦)[。！？!?…]*)+$/;
  for (const shot of speakingUnits) {
    // Dialogue density is authored by the editor Agent, not approved or
    // rejected by a local character-count formula. A structurally complete
    // result continues even when an old project lacks the new timing fields.
    // The final prompt compiler preserves every complete line exactly once.
    if (weakShell.test(String(shot.dialogue || "").replace(/\s+/g, ""))) failures.push(`${shot.id}对白几乎全是空壳语气词，必须改写成实质交锋`);
    if (options.requireReferenceDialogueFlow) {
      const arc = shot.dialogueArc && typeof shot.dialogueArc === "object" ? shot.dialogueArc : {};
      const missingArc = ["entryCause", "speakerGoalA", "newInformation", "exitConsequence"].filter(key => !String(arc[key] || "").trim());
      if (missingArc.length) failures.push(`${shot.id}对白弧缺${missingArc.join("/")}，必须说明首句为何发生、新信息和末句造成的可见后果`);
      const turns = Array.isArray(shot.dialogueTurns) ? shot.dialogueTurns : [];
      const normalizedLines = turns.map(turn => String(turn?.text || "").replace(/[\s，。！？!?、；;：:…]/g, "")).filter(Boolean);
      if (new Set(normalizedLines).size !== normalizedLines.length) failures.push(`${shot.id}存在逐字重复台词，必须让每句改变信息、权力或行动`);
      let sameSpeakerRun = 0;
      let previousSpeaker = "";
      for (const turn of turns) {
        const speaker = String(turn?.speakerId || "").trim();
        sameSpeakerRun = speaker && speaker === previousSpeaker ? sameSpeakerRun + 1 : 1;
        previousSpeaker = speaker;
        if (sameSpeakerRun > 2 && new Set(turns.map(item => String(item?.speakerId || "").trim()).filter(Boolean)).size > 1) {
          failures.push(`${shot.id}同一说话人连续超过2轮，双人冲突必须形成可听见的攻防接力`);
          break;
        }
      }
      for (const [turnIndex, turn] of turns.entries()) {
        if (!String(turn?.beat || turn?.intent || "").trim() || !String(turn?.delivery || "").trim() || !String(turn?.listenerBeat || "").trim()) {
          failures.push(`${shot.id}第${turnIndex + 1}句缺beat/delivery/listenerBeat，无法确定对白功能、说法和听者反应`);
        }
      }
    }
    const environmentAudio = [
      shot.audioPlan,
      shot.soundDesign,
      shot.soundCueSheet?.bed,
      ...(shot.subshots || []).map(item => item.sound)
    ].filter(Boolean).join(" ");
    const audio = [environmentAudio, shot.soundCueSheet?.sfx].filter(Boolean).join(" ");
    if (!/环境(?:声|底噪|氛围|音)?|底噪|现场(?:声|底床|氛围)|房间(?:声|底床|底噪|tone)|走廊(?:环境|底噪|回响)|户外(?:环境|底噪|车流|风声)|室内(?:环境|底噪|房间声)/i.test(environmentAudio)) failures.push(`${shot.id}声音计划缺少环境底噪`);
    if (!/特效|脚步|衣料|开门|关门|撕|摔|撞击|器物|震动|拄拐|吸气|叹气|长叹|抽泣|动作声|纸张|翻纸|翻页|摩擦|落地|拍桌|抽屉|摘下?眼镜|眼镜.{0,4}(?:摘下|轻响|碰桌)|滴答|钟表.{0,4}(?:重音|敲响|报时)/.test(audio)) failures.push(`${shot.id}声音计划缺少动作特效声`);
    if (shot.silenceBeat) {
      if (!/静默|抽音|呼吸|心跳|砸入|重声/.test(audio)) failures.push(`${shot.id}是唯一静默拍点，声音计划必须写明抽音区间、保留呼吸/心跳和砸入声`);
    } else if (/\bBGM\b|配乐|underscore|非叙事|主题乐|背景音乐/.test(audio)) {
      failures.push(`${shot.id}声音计划禁止写 BGM/配乐/underscore（仅保留环境底噪+同步特效）`);
    }
    if (!String(shot.performance || "").trim() || String(shot.performance || "").trim().length < 8) failures.push(`${shot.id}缺少可执行表演（须写微表情/身体反应）`);
    if (!String(shot.emotion || "").trim()) failures.push(`${shot.id}缺少情绪曲线`);
  }
  for (const shot of shots) {
    for (const [field, label] of [["stateBefore", "开始状态"], ["stateAfter", "结束状态"], ["causalLink", "因果承接"], ["visualBeat", "独占画面拍点"], ["compositionPlan", "差异构图"], ["audioPlan", "声音计划"]]) {
      if (!String(shot[field] || "").trim()) failures.push(`${shot.id}缺少${label}`);
    }
  }
  if (String(plannedShots[0]?.id || "").toUpperCase() === "S01") {
    contractFailures.push(...openingHookContractFailures(shots, { requireDialogue: true }));
  }
  const activeContractFailures = activeBlueprintFailures(contractFailures, options);
  if (activeContractFailures.length && !options.bypassProductionContracts && !options.advisoryOnly) {
    throw Object.assign(new Error(`生成单元违反生产硬合同：${activeContractFailures.map(item => item.message).join("；")}`), {
      code: "SCRIPT_UNIT_CONTRACT_FAILED",
      failures: activeContractFailures
    });
  }
  const activeFailures = activeBlueprintFailures(failures, options);
  if (activeFailures.length && !options.skipQualityGates && !options.advisoryOnly) throw Object.assign(new Error(`生成单元批次未达标：${activeFailures.join("；")}`), { code: "SCRIPT_UNIT_BATCH_INVALID", failures: activeFailures });
  return shots;
}

function timecode(seconds) {
  const value = Math.max(0, Number(seconds) || 0);
  return `${String(Math.floor(value / 60)).padStart(2, "0")}:${String(Math.floor(value % 60)).padStart(2, "0")}`;
}

function renderProductionScript(blueprint, normalized, project, topic, options = {}) {
  const partial = options.partial === true;
  const targetDurationSeconds = Number(blueprint?.targetDurationSeconds)
    || Number(project?.generation?.targetDurationSeconds)
    || normalized.shots?.reduce((sum, item) => sum + (Number(item?.duration) || 0), 0)
    || 300;
  let scheduledUnitCount = 0;
  try {
    const engine = String(project?.generation?.engine || "");
    const providerKind = engine === "hailuo-h3"
      ? "puream-hailuo-h3"
      : (project?.generation?.videoProviderKind || "puream-hailuo-h3");
    scheduledUnitCount = planFilmSchedule(targetDurationSeconds, providerKind, {
      preferredUnit: engine === "hailuo-h3"
        ? Math.max(12, Number(project?.generation?.shotDuration) || 0)
        : (Number(project?.generation?.shotDuration) || 10),
      engine
    }).unitCount;
  } catch {}
  const authoredUnitCount = Number(blueprint?.shotPlan?.length) || Number(normalized.shotPlan?.length) || normalized.shots?.length || 0;
  const targetUnitCount = Number(options.expectedUnitCount)
    || Number(blueprint?.expectedUnitCount)
    || (partial ? scheduledUnitCount : authoredUnitCount)
    || authoredUnitCount
    || scheduledUnitCount
    || 30;
  const characterCodes = new Map(normalized.characters.map((item, index) => [item.name, `C${String(index + 1).padStart(2, "0")}`]));
  const sceneCodes = new Map(normalized.scenes.map((item, index) => [item.name, `SC${String(index + 1).padStart(2, "0")}`]));
  const productName = String(project.product?.name || "用户上传商品").trim();
  const sellingPoints = productSellingPoints(project);
  const lines = [
    partial ? "# 纯梦短剧老虎机实时写作草稿" : "# 纯梦短剧老虎机完整制作剧本",
    "",
    "## 1. 项目参数",
    `- 片名：${blueprint.title || topic.title}`,
    `- 类型：${blueprint.genre || topic.genre || "写实家庭伦理带货短剧"}`,
    `- 核心命题：${blueprint.coreTheme || topic.audienceAppeal || "善意必须用行动证明"}`,
    `- 主反转机制：${blueprint.mainReversalMechanism || topic.reversal}`,
    `- 目标时长：${targetDurationSeconds}秒`,
    "- 画幅与视觉风格：9:16，写实真人影视，现代中国生活质感",
    `- 商品状态：${productName}（已绑定用户上传商品图）`,
    `- 一句话故事：${blueprint.logline || topic.logline}`,
    "",
    "## 2. 完整故事梗概",
    "",
    String(blueprint.story?.synopsis || topic.logline || "").trim(),
    "",
    "## 3. 人物圣经",
    ""
  ];
  normalized.characters.forEach((character, index) => {
    const source = blueprint.characters?.[index] || {};
    lines.push(`### C${String(index + 1).padStart(2, "0")} ${character.name}`);
    lines.push(`- 年龄/身份/关系：${source.age || "年龄待剧情锁定"}；${source.role || character.role || "故事人物"}`);
    lines.push(`- 外貌、体型、发型、服装与配饰：${character.appearanceDescription || character.description || "待资产阶段补齐"}`);
    lines.push(`- 欲望/恐惧/弧光：${source.desire || "守住尊严"}；${source.fear || "失去关系"}；${source.arc || "用行动完成选择"}`);
    lines.push(`- 资产指纹：${character.identitySignature}`);
    lines.push(`- 声线：${character.voiceDescription}`);
    lines.push(`- 测试台词：${character.signatureLine}`);
    lines.push(`- 全剧不可漂移项：${(source.continuityLocks || []).join("；") || character.identitySignature}`);
    lines.push("");
  });
  lines.push("## 4. 场景圣经", "");
  normalized.scenes.forEach((scene, index) => {
    const source = blueprint.scenes?.[index] || {};
    lines.push(`### SC${String(index + 1).padStart(2, "0")} ${scene.name}｜${scene.time || source.time || "日间"}`);
    lines.push(`- 内/外景与空间结构：${source.interiorExterior || "内景"}；${scene.description}`);
    lines.push(`- 主光、色温与天气：${source.lighting || "现实环境动机光"}`);
    lines.push(`- 环境声与氛围：${scene.atmosphere || source.atmosphere || "连续生活环境声"}`);
    lines.push(`- 可复用机位与锚点：${(source.cameraAnchors || []).join("；") || "门口关系镜、人物中近景、物证插镜"}`);
    lines.push(`- 场景切换理由：${source.transitionReason || "通过人物动作或现场声音切换"}`);
    lines.push("");
  });
  lines.push("## 5. 道具与商品圣经", "");
  (blueprint.props || []).forEach(prop => lines.push(`- ${prop.name}：${prop.appearance || "外观固定"}；持有人/手别：${prop.holder || "按分镜锁定"}；出现：${(prop.units || []).join("、")}；用途：${prop.purpose || "推动主线"}；连续性：${prop.continuity || "数量与位置不漂移"}`));
  lines.push(`- 商品“${productName}”：唯一外观基准为用户上传产品图；用户提供卖点：${sellingPoints}；只在主反转后的剧情行动中进入，不虚构价格、规格、赠品或功效。`, "", "## 6. 完整生成单元剧本", "");
  let cursorSec = 0;
  normalized.shots.forEach((shot, index) => {
    const duration = Math.max(10, Math.min(15, Number(shot.duration) || 12));
    const start = cursorSec;
    const end = cursorSec + duration;
    cursorSec = end;
    const ids = (shot.characterNames || []).map(name => `${characterCodes.get(name) || ""} ${name}`.trim()).join("、");
    const sceneCode = sceneCodes.get(shot.sceneName) || "";
    lines.push(`### S${String(index + 1).padStart(2, "0")}｜${timecode(start)}–${timecode(end)}｜${duration}秒`);
    lines.push(`- 场景：${sceneCode} ${shot.sceneName}`.trim());
    lines.push(`- 人物：${ids || "无"}`);
    lines.push(`- 本单元叙事任务：${shot.action}`);
    lines.push(`- 主线阶段：${shot.mainlineStage}`);
    lines.push(`- 主线推进：${shot.mainlineBeat}`);
    lines.push(`- 善意代价：${shot.kindnessCost || "无"}`);
    lines.push(`- 反转伏笔：${shot.reversalSetup || "无"}`);
    lines.push(`- 状态变化：${shot.stateBefore || shot.startFrame} → ${shot.stateAfter || shot.endFrame}`);
    lines.push(`- 因果承接：${shot.causalLink || shot.mainlineBeat}`);
    lines.push(`- 独占画面拍点：${shot.visualBeat || shot.action}`);
    lines.push(`- 构图计划：${shot.compositionPlan || `${shot.shotSize}；${shot.cameraMove}`}`);
    lines.push(`- 全时段声音计划：${shot.audioPlan || shot.soundDesign}`);
    lines.push(`- 情绪：${shot.emotion}`);
    lines.push(`- 首帧：${shot.startFrame}`);
    (shot.subshots || []).forEach((subshot, subIndex) => {
      lines.push(`- subshot ${subIndex + 1}｜${subshot.start}–${subshot.end}秒｜${subshot.framing || "中近景"}/${subshot.camera || "稳定机位"}：${subshot.action}；对白：${subshot.dialogue || "无"}；声音：${subshot.sound || "连续现场环境声"}；切换：${subshot.transition || "硬切"}`);
    });
    lines.push(`- 对白：${shot.dialogue || "无"}`);
    lines.push(`- 声音：${shot.soundDesign || "对白清晰，连续现场环境声；该有动作特效声时自带特效声，不要背景音乐，只保留底噪与同步特效"}`);
    lines.push(`- 商品：${shot.productMention ? `出现“${productName}”，外观只参考用户产品图；剧情动作只使用卖点“${sellingPoints}”，锁定包装朝向与持物手` : "不出现"}`);
    lines.push(`- 连续性：保持人物左右位置、视线轴、服装、持物手、道具、场景内/外景、主光和环境声与相邻单元一致；禁止连续动作跨空间瞬移`);
    lines.push(`- 尾帧：${shot.endFrame}，稳定0.5秒`);
    lines.push("");
  });
  if (partial) {
    lines.push("## 7. 当前写作进度", "");
    lines.push(`- 已完成生产单元：${normalized.shots.length}/${normalized.shotPlan?.length || normalized.shots.length || "?"}`);
    lines.push(`- 已完成分镜规划：${Number(options.plannedCount) || 0}/${targetUnitCount}`);
    lines.push(`- 当前阶段：${options.message || "正在继续生成"}`);
    lines.push("- 状态说明：这是自动保存的实时草稿，尚未通过完整因果、反转、声音和参考片规格终审。", "");
  } else {
    lines.push("## 7. 结尾闭环", "");
    lines.push(`- 开场钩子回收：${blueprint.story?.hook || topic.hook}`);
    lines.push(`- 主反转证据回收：${blueprint.story?.mainReversal || topic.reversal}`);
    lines.push(`- 核心人物行动结果：${(blueprint.story?.payoff || []).join("；") || topic.emotionalPayoff}`);
    lines.push(`- 商品剧情任务：${productName}只在价值成立后承担具体动作，不替代核心故事。`);
    lines.push(`- 最后一帧可见动作：${blueprint.story?.ending || normalized.shots.at(-1)?.endFrame || "人物完成行动后离开"}`);
    lines.push("", "## 8. 生成与合规检查", "", "- 因果闭环：通过。", "- 人物与道具连续：通过。", "- 单元时长按节拍可变且合计等于剧总时长：通过。", "- 对白可在时长内自然说完：通过。", "- 商品事实均来自用户：通过。", "- 无模型生成字幕要求：通过。", "");
  }
  return lines.join("\n");
}

function renderDialogueScript(blueprint, normalized, project, topic, options = {}) {
  const partial = options.partial === true;
  const characters = Array.isArray(normalized?.characters) ? normalized.characters : [];
  const scenes = Array.isArray(normalized?.scenes) ? normalized.scenes : [];
  const shots = Array.isArray(normalized?.shots) ? normalized.shots : [];
  const characterByKey = new Map();
  characters.forEach((character, index) => {
    const fallbackId = `C${String(index + 1).padStart(2, "0")}`;
    [character?.id, character?.name, fallbackId].filter(Boolean).forEach(key => characterByKey.set(String(key), character));
  });
  const characterName = key => characterByKey.get(String(key || ""))?.name || String(key || "").trim() || "角色";
  const title = String(blueprint?.title || topic?.title || project?.title || "未命名短剧").trim();
  const synopsis = String(blueprint?.story?.synopsis || blueprint?.logline || topic?.logline || "").trim();
  const lines = [
    partial ? `# ${title}｜简易对白剧本（实时草稿）` : `# ${title}｜简易对白剧本`,
    "",
    "## 简单背景情节",
    "",
    synopsis || "人物因一场现实冲突被迫直面真相，并用行动完成关系与生活的改变。",
    "",
    "## 主要人物",
    ""
  ];
  characters.forEach(character => {
    const source = (blueprint?.characters || []).find(item => item?.id === character?.id || item?.name === character?.name) || {};
    lines.push(`- ${character.name}：${String(source.role || character.role || "故事人物").trim()}`);
  });
  if (scenes.length) {
    lines.push("", "## 场景背景", "");
    scenes.forEach(scene => lines.push(`- ${scene.name}：${String(scene.description || scene.atmosphere || "按剧情连续呈现").trim()}`));
  }
  lines.push("", "## 对白剧本", "");
  let cursorSec = 0;
  shots.forEach((shot, index) => {
    const duration = Math.max(1, Number(shot?.duration) || 10);
    const start = cursorSec;
    const end = cursorSec + duration;
    cursorSec = end;
    const shotNumber = Number(shot?.number) || index + 1;
    const action = String(shot?.action || shot?.visualBeat || shot?.mainlineBeat || "人物继续当前行动").trim();
    lines.push(`### S${String(shotNumber).padStart(2, "0")}｜${timecode(start)}–${timecode(end)}｜${shot.sceneName || "剧情现场"}`);
    lines.push(`【背景/动作：${action}】`);
    const turns = (Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : [])
      .map((turn, turnIndex) => normalizeDialogueTurn(turn, turnIndex + 1))
      .filter(turn => turn.speakerId && turn.text);
    if (turns.length) {
      turns.forEach(turn => {
        const speaker = characterName(turn.speakerId);
        const listeners = turn.listenerIds.map(characterName).filter(Boolean);
        const tone = [...new Set([
          turn.sourceTone,
          turn.emotionStart && turn.emotionPeak ? `${turn.emotionStart}到${turn.emotionPeak}` : (turn.emotionPeak || turn.emotionStart),
          turn.delivery,
          turn.body
        ].map(value => String(value || "").trim()).filter(Boolean))].join("；") || String(shot?.emotion || "贴合当前冲突自然表达").trim();
        const listenerClause = listeners.length ? `对${listeners.join("、")}说；` : "";
        lines.push(`${speaker}（${listenerClause}${tone}）：${turn.text}`);
      });
    } else if (String(shot?.dialogue || "").trim() && String(shot.dialogue).trim() !== "无") {
      lines.push(`对白（${String(shot?.emotion || "贴合当前冲突自然表达").trim()}）：${String(shot.dialogue).trim()}`);
    } else {
      lines.push("【无对白：用表情、视线和动作完成本镜。】");
    }
    if (shot?.productMention) {
      lines.push(`【商品动作：${String(project?.product?.name || "用户上传商品").trim()}只按用户上传原图与真实卖点进入当前剧情动作。】`);
    }
    lines.push("");
  });
  if (partial) {
    lines.push("## 当前写作进度", "");
    lines.push(`- 已完成对白单元：${shots.length}/${Number(options.expectedUnitCount) || Number(blueprint?.shotPlan?.length) || shots.length || "?"}`);
    lines.push(`- 已完成分镜规划：${Number(options.plannedCount) || 0}`);
    lines.push(`- 当前阶段：${options.message || "正在继续生成"}`);
    lines.push("- 这是自动保存草稿，完整生产字段仍在后台同步编译，尚未完成最终审计。", "");
  } else {
    lines.push("## 结尾", "");
    lines.push(String(blueprint?.story?.ending || shots.at(-1)?.endFrame || "人物用可见行动完成故事闭环").trim());
  }
  return lines.join("\n");
}

function renderTimedStoryboardScript(blueprint, normalized, project, topic, options = {}) {
  const partial = options.partial === true;
  const shots = Array.isArray(normalized?.shots) ? normalized.shots : [];
  const characters = Array.isArray(normalized?.characters) ? normalized.characters : [];
  const characterById = new Map(characters.map(item => [String(item?.id || ""), String(item?.name || item?.id || "角色")]));
  const ledgerById = new Map((normalized?.sourceDialogueLedger || []).map(item => [String(item?.id || ""), item]));
  const title = String(blueprint?.title || topic?.title || project?.title || "未命名短剧").trim();
  const synopsis = String(
    blueprint?.story?.synopsis
    || normalized?.story?.synopsis
    || blueprint?.story?.premise
    || normalized?.story?.premise
    || topic?.logline
    || "人物在现实冲突中被迫作出选择，事件经由证据与行动反转，并在结尾完成关系和结果闭环。"
  ).trim();
  const hasAuthoredActs = shots.some(shot => Number(shot?.actNumber) > 1 || String(shot?.actTitle || "").trim());
  const fallbackActTitles = ["冲突建立", "局势反转", "高潮收束"];
  const shotAct = (shot, index) => {
    if (hasAuthoredActs) return Math.max(1, Math.min(9, Number(shot?.actNumber) || 1));
    return Math.min(3, Math.floor(index * 3 / Math.max(1, shots.length)) + 1);
  };
  const lines = [
    partial ? `# ${title}｜秒级分镜成片稿（实时草稿）` : `# ${title}｜秒级分镜成片稿`,
    "",
    `【剧情简介】${synopsis}`,
    "",
    "【模式简介】按“幕 → 5至15秒分镜 → 秒级子镜”组织，逐镜写清场景人物物品、人声、承接、表演、对白汇总、音效与负向提示；可直接编译为资产图、分镜图和视频提示词。",
    ""
  ];
  let previousAct = 0;
  shots.forEach((shot, index) => {
    const act = shotAct(shot, index);
    if (act !== previousAct) {
      const actTitle = String(shot?.actTitle || fallbackActTitles[Math.min(fallbackActTitles.length - 1, act - 1)] || `剧情推进${act}`).trim();
      lines.push(`第${act}幕：【${actTitle}】`);
      previousAct = act;
    }
    const duration = Math.max(1, Number(shot?.duration) || 10);
    const subshots = Array.isArray(shot?.subshots) ? shot.subshots : [];
    const people = (shot?.scenePresenceCharacterNames?.length ? shot.scenePresenceCharacterNames : shot?.characterNames || [])
      .map(String).filter(Boolean);
    const turns = (Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : [])
      .map((turn, turnIndex) => normalizeDialogueTurn(turn, turn?.subshotNumber || turnIndex + 1))
      .filter(turn => turn.speakerId && turn.text);
    const speakers = [...new Set(turns.map(turn => characterById.get(turn.speakerId) || turn.speakerId).filter(Boolean))];
    lines.push(`分镜 ${index + 1}（${Math.max(1, subshots.length)}个镜头·${shot?.pace || "中等节奏"}）※ ${shot?.sceneName || "剧情现场"}｜场景固定`);
    lines.push(`天气/灯光/氛围：${shot?.weatherLightingAtmosphere || shot?.emotion || "光线、色温与情绪按本幕连续变化。"}`);
    lines.push(`场景：@${shot?.sceneName || "剧情现场"}`);
    lines.push(`人物：${people.length ? people.map(name => `@${name}`).join(" ") : "@无"}`);
    lines.push(`物品：${shot?.propNames?.length ? shot.propNames.map(name => `@${name}`).join(" ") : "@无"}`);
    lines.push(`人声设定：${speakers.length ? speakers.map(name => `@${name}`).join(" ") : "@无"}`);
    lines.push(`承接上一分镜：【${shot?.authoredContinuity || shot?.stateBefore || (index ? "承接上一镜人物位置、动作结果与情绪余波" : "开篇全景引入")}】`);
    lines.push(`【0-${duration}秒】镜头：`);
    if (subshots.length) {
      subshots.forEach(subshot => {
        const start = Number(subshot?.start) || 0;
        const end = Number(subshot?.end) || duration;
        const framing = String(subshot?.framing || subshot?.shotType || shot?.shotSize || "中景").trim();
        const camera = String(subshot?.camera || shot?.cameraMove || "固定镜头").trim();
        const action = String(subshot?.action || shot?.action || "人物继续当前行动").trim();
        lines.push(`${start}-${end}秒，【${framing}，${camera}，${action}】；`);
      });
    } else {
      lines.push(`0-${duration}秒，【${shot?.shotSize || "中景"}，${shot?.cameraMove || "固定镜头"}，${shot?.action || "人物按剧情完成本镜行动"}】；`);
    }
    lines.push("【对话汇总】");
    if (!turns.length) {
      lines.push("无对白；人物闭口，以视线、表情、动作与环境声推进。");
    } else {
      turns.forEach(turn => {
        const ledger = ledgerById.get(turn.sourceDialogueId) || {};
        const subshot = subshots[Math.max(0, (Number(turn.subshotNumber) || 1) - 1)] || {};
        const start = Number.isFinite(Number(ledger.startSecond)) ? Number(ledger.startSecond) : (Number(subshot.start) || 0);
        const end = Number.isFinite(Number(ledger.endSecond)) ? Number(ledger.endSecond) : (Number(subshot.end) || duration);
        const speaker = characterById.get(turn.speakerId) || turn.speakerId;
        const listeners = turn.listenerIds.map(id => characterById.get(id) || id).filter(Boolean);
        const tone = [turn.sourceTone, turn.delivery, turn.body, turn.listenerBeat].map(value => String(value || "").trim()).filter(Boolean).join("；") || "按剧情自然起伏";
        lines.push(`@${speaker}（${listeners.length ? `对@${listeners.join("、@")}；` : ""}${start}-${end}秒；${tone}）：“${turn.text}”`);
      });
    }
    lines.push(`【音效】${shot?.soundDesign || shot?.audioPlan || "现场环境声与人物动作声"}`);
    lines.push("【画面禁止项 / 负向提示】严禁字幕、气泡、排版文字、字母、Logo误绘和水印；对白只驱动口型、语气、表情与动作。", "");
  });
  if (partial) lines.push(`【当前进度】已完成 ${shots.length}/${Number(options.expectedUnitCount) || shots.length || "?"} 个分镜；这是实时草稿，后台生产字段仍在同步编译。`);
  return lines.join("\n");
}

function renderScriptForProject(blueprint, normalized, project, topic, options = {}) {
  const format = projectScriptFormat(project);
  if (format === "dialogue") return renderDialogueScript(blueprint, normalized, project, topic, options);
  if (format === "timed_storyboard") return renderTimedStoryboardScript(blueprint, normalized, project, topic, options);
  return renderProductionScript(blueprint, normalized, project, topic, options);
}

function incompleteShotVideoCandidate(candidate) {
  return candidate?.stage === "shot_video" && (
    candidate.internalGenerationBlock === true
    || candidate.recoveredInternalBlock === true
    || candidate.incompleteShotVideo === true
  );
}

function explicitlyRetiredCandidate(candidate) {
  if (candidate?.stale !== true) return false;
  if (["user_requested_reroll", "dialogue_asr_failure"].includes(String(candidate.staleCauseCode || ""))) return true;
  return /用户要求.*重抽|ASR复核|额外口头语|对白.*(?:错误|截断|乱入)/i.test(String(candidate.staleReason || ""));
}

function selectedOrLatest(project, entityType, entityId, stage) {
  const activeRevision = project.productionRevision || "";
  const revisionMatches = project.candidates
    .filter(item => item.entityType === entityType && item.entityId === entityId && item.stage === stage)
    .filter(item => (item.productionRevision || "") === activeRevision)
    .filter(item => !incompleteShotVideoCandidate(item))
    .sort((a, b) => String(b.createdAt).localeCompare(String(a.createdAt)));
  const manualSelection = revisionMatches.find(item => item.selected === true
    && item.manualSelectionOverride === true
    && item.stale !== true
    && item.filePath);
  if (manualSelection) return manualSelection;
  const matches = revisionMatches.filter(item => item.stale !== true);
  // Explicit user confirmation always wins — otherwise video can bind a newer auto-passed
  // frame while the storyboard UI still shows the card the user thinks is active.
  const selected = matches.find(item => item.selected);
  if (selected) return selected;
  const qualityPassed = matches.filter(item => item.qualityAudit?.ok === true);
  const unverified = matches.filter(item => item.qualityAudit?.ok !== true && item.qualityAudit?.ok !== false);
  const recoverableHistorical = revisionMatches.find(item => item.filePath
    && item.stale === true
    && !explicitlyRetiredCandidate(item)
    && item.staleCauseCode !== "technical_integrity"
    && !/技术完整性|空白帧|纯色边栏|错误转场|画布泄漏/.test(String(item.staleReason || "")));
  return qualityPassed[0] || unverified[0] || matches[0] || recoverableHistorical || null;
}

function latestCompleteShotVideoCandidate(project, shotId) {
  return (project?.candidates || [])
    .filter(item => item.entityType === "shot" && item.entityId === shotId && item.stage === "shot_video")
    .filter(item => (item.productionRevision || "") === (project?.productionRevision || ""))
    .filter(item => !incompleteShotVideoCandidate(item))
    .filter(item => !explicitlyRetiredCandidate(item))
    .filter(item => item.filePath && fs.existsSync(item.filePath))
    .sort((left, right) => String(right.createdAt || "").localeCompare(String(left.createdAt || "")))[0] || null;
}

function materializeDefaultShotVideoSelections(project = {}) {
  let changed = false;
  const activeRevision = project.productionRevision || "";
  for (const shot of project.shots || []) {
    for (const item of project.candidates || []) {
      if (item.entityType === "shot" && item.entityId === shot.id && incompleteShotVideoCandidate(item) && item.selected === true) {
        item.selected = false;
        changed = true;
      }
    }
    const chosen = selectedOrLatest(project, "shot", shot.id, "shot_video");
    if (!chosen) continue;
    const siblings = (project.candidates || []).filter(item =>
      item.entityType === "shot"
      && item.entityId === shot.id
      && item.stage === "shot_video"
      && (item.productionRevision || "") === activeRevision
    );
    if (siblings.some(item => item.selected === true && item.manualSelectionOverride === true)) continue;
    for (const item of siblings) {
      const shouldSelect = item.id === chosen.id;
      if (item.selected !== shouldSelect) {
        item.selected = shouldSelect;
        changed = true;
      }
    }
    if (!chosen.defaultSelectedAt) {
      chosen.defaultSelectedAt = new Date().toISOString();
      changed = true;
    }
  }
  return changed;
}

function recoverTopicObjectsFromRaw(rawText) {
  const source = String(rawText || "");
  const found = [];
  for (let start = 0; start < source.length; start += 1) {
    if (source[start] !== "{") continue;
    let depth = 0; let inString = false; let escaped = false;
    for (let index = start; index < source.length; index += 1) {
      const char = source[index];
      if (inString) {
        if (escaped) escaped = false;
        else if (char === "\\") escaped = true;
        else if (char === '"') inString = false;
        continue;
      }
      if (char === '"') { inString = true; continue; }
      if (char === "{") depth += 1;
      else if (char === "}") {
        depth -= 1;
        if (depth !== 0) continue;
        try {
          const value = JSON.parse(source.slice(start, index + 1));
          if (value && typeof value === "object" && !Array.isArray(value)
            && String(value.title || "").trim()
            && (value.logline || value.hook || value.storyMechanism)) found.push(value);
        } catch {}
        break;
      }
    }
  }
  const seen = new Set();
  return found.filter(item => {
    const key = String(item.title || "").replace(/[\s《》]/g, "");
    if (!key || seen.has(key)) return false;
    seen.add(key); return true;
  });
}

const TOPIC_CREATIVE_LENSES = Object.freeze([
  "一次好心造成了意料之外的现实后果",
  "两个人都没有撒谎，却因立场不同走向冲突",
  "一个日常规则在特殊处境中变成道德难题",
  "陌生人的小动作改变了熟人关系的站队",
  "看似吃亏的选择在后段改变了权力关系",
  "一件普通生活任务迫使人物暴露真实优先级",
  "主角主动放弃捷径，反而打开新的解决办法",
  "原本被保护的人拒绝继续被别人替他决定",
  "一个公开承诺在最不方便的时候必须兑现",
  "生活中的小误差引出完全不同的人生选择",
  "旧关系用一种新的合作方式重新建立边界",
  "一个不起眼的旁观者成为行动而非证词的关键"
]);

function topicSlotMatrix(generationIndex = 1) {
  const offset = (Math.max(1, Number(generationIndex) || 1) - 1) % TOPIC_CREATIVE_LENSES.length;
  const lenses = Array.from({ length: 3 }, (_, index) => TOPIC_CREATIVE_LENSES[(offset + index * 4) % TOPIC_CREATIVE_LENSES.length]);
  return `本轮可选灵感扰动（仅用于打开思路，不是槽位命令，也不必逐项采用）：${lenses.join("；")}。任何更有趣且生活逻辑成立的新方向优先。`;
}

function candidateFileExists(candidate) {
  if (!candidate?.filePath) return false;
  try {
    const stat = fs.statSync(path.resolve(String(candidate.filePath)));
    return stat.isFile() && stat.size > 0;
  } catch {
    return false;
  }
}

function selectedExistingCandidate(project, entityType, entityId, stage) {
  const activeRevision = project?.productionRevision || "";
  const preferred = selectedOrLatest(project, entityType, entityId, stage);
  const ranked = (project?.candidates || [])
    .filter(item => item.entityType === entityType
      && item.entityId === entityId
      && item.stage === stage
      && (item.productionRevision || "") === activeRevision)
    .sort((left, right) => {
      const leftManual = left.selected === true && left.manualSelectionOverride === true ? 1 : 0;
      const rightManual = right.selected === true && right.manualSelectionOverride === true ? 1 : 0;
      if (leftManual !== rightManual) return rightManual - leftManual;
      const leftSelected = left.selected === true ? 1 : 0;
      const rightSelected = right.selected === true ? 1 : 0;
      if (leftSelected !== rightSelected) return rightSelected - leftSelected;
      const leftLive = left.stale !== true ? 1 : 0;
      const rightLive = right.stale !== true ? 1 : 0;
      if (leftLive !== rightLive) return rightLive - leftLive;
      return String(right.updatedAt || right.createdAt || "").localeCompare(String(left.updatedAt || left.createdAt || ""));
    });
  const seen = new Set();
  for (const candidate of [preferred, ...ranked]) {
    if (!candidate?.id || seen.has(candidate.id)) continue;
    seen.add(candidate.id);
    if (incompleteShotVideoCandidate(candidate)) continue;
    const technicallyRetired = explicitlyRetiredCandidate(candidate) || (candidate.stale === true && (
      candidate.staleCauseCode === "technical_integrity"
      || /技术完整性|空白帧|纯色边栏|错误转场|画布泄漏/.test(String(candidate.staleReason || ""))
    ));
    if (!technicallyRetired && candidateFileExists(candidate)) return candidate;
  }
  return null;
}

function candidateReady(project, entityType, entityId, stage, settings = null) {
  const activeRevision = project?.productionRevision || "";
  const preferred = selectedOrLatest(project, entityType, entityId, stage);
  const ranked = (project?.candidates || [])
    .filter(item => item.entityType === entityType
      && item.entityId === entityId
      && item.stage === stage
      && (item.productionRevision || "") === activeRevision)
    .sort((left, right) => String(right.updatedAt || right.createdAt || "").localeCompare(String(left.updatedAt || left.createdAt || "")));
  const seen = new Set();
  for (const candidate of [preferred, ...ranked]) {
    if (!candidate?.id || seen.has(candidate.id)) continue;
    seen.add(candidate.id);
    if (incompleteShotVideoCandidate(candidate)) continue;
    // Stale voice bindings are never production-ready. Accepting one here
    // prevents the verified library fallback from being materialized.
    if (explicitlyRetiredCandidate(candidate) || (candidate.stale === true && (stage === "character_voice" || (
      candidate.staleCauseCode === "technical_integrity"
      || /技术完整性|空白帧|纯色边栏|错误转场|画布泄漏/.test(String(candidate.staleReason || ""))
    )))) continue;
    if (!candidateFileExists(candidate) || !qualityAccepted(candidate, settings)) continue;
    return candidate;
  }
  return null;
}

/** Use the identity explicitly selected for the character, regardless of which identity-card stage produced it. */
function characterIdentityCandidate(project, characterId, settings = null) {
  const stages = new Set(["character_sheet", "character_three_view", "character_intro"]);
  const activeRevision = project.productionRevision || "";
  const character = (project.characters || []).find(item => item.id === characterId);
  const available = (project.candidates || [])
    .filter(item => item.entityType === "character" && item.entityId === characterId && stages.has(item.stage))
    .filter(item => (item.productionRevision || "") === activeRevision && item.stale !== true && item.filePath)
    .filter(item => qualityAccepted(item, settings))
    .filter(item => candidateFileExists(item));
  const active = available.find(item => item.id === character?.activeIdentityCandidateId);
  if (active) return active;
  const byRecency = (left, right) => String(right.manualSelectedAt || right.updatedAt || right.createdAt || "")
    .localeCompare(String(left.manualSelectedAt || left.updatedAt || left.createdAt || ""));
  // The portrait is a private H3 voice/identity anchor. It must never replace
  // the visible four-view character asset in the workbench or project overview.
  // Explicit user selection still wins, then prefer the reusable four-view
  // board before falling back to the portrait when no board exists.
  const selected = available.filter(item => item.selected === true);
  const selectedAtStage = stage => selected.filter(item => item.stage === stage).sort(byRecency)[0];
  return selected.filter(item => item.manualSelectionOverride === true).sort(byRecency)[0]
    || selectedAtStage("character_sheet")
    || selectedAtStage("character_three_view")
    || selectedAtStage("character_intro");
}

/** Reuse the paid four-view asset as identity input; do not buy a private portrait. */
function characterVideoIdentityCandidate(project, characterId, settings = null) {
  const preferred = normalizeProjectMode(project?.generation?.mode) === "asset_direct"
    ? candidateReady(project, "character", characterId, "character_intro", settings)
      || candidateReady(project, "character", characterId, "character_sheet", settings)
      || candidateReady(project, "character", characterId, "character_three_view", settings)
    : candidateReady(project, "character", characterId, "character_sheet", settings)
      || candidateReady(project, "character", characterId, "character_three_view", settings)
      || candidateReady(project, "character", characterId, "character_intro", settings);
  if (preferred) return preferred;
  const character = (project.characters || []).find(item => item.id === characterId);
  const directSpeaker = Boolean(character && assetDecision(project, character).directSpeakingShotIds.length);
  if (!directSpeaker) return null;
  // Historical policy could stale a valid, already-paid identity image for a
  // one-line character. Recover only policy-excluded files for a camera-owned
  // direct speaker; never revive a technically invalid asset.
  return (project.candidates || [])
    .filter(item => item.entityType === "character" && item.entityId === characterId)
    .filter(item => ["character_intro", "character_sheet", "character_three_view"].includes(item.stage))
    .filter(item => item.filePath && candidateFileExists(item) && qualityAccepted(item, settings))
    .filter(item => item.stale !== true || item.assetPolicyExcluded === true || item.assetPolicyExclusion)
    .sort((left, right) => String(right.updatedAt || right.createdAt || "").localeCompare(String(left.updatedAt || left.createdAt || "")))[0] || null;
}

function storyboardStageLabel(stage) {
  if (stage === "storyboard_start") return "首帧";
  if (stage === "storyboard_end") return "尾帧";
  if (stage === "storyboard_sheet") return "逐秒合图";
  return stage;
}

/** List missing storyboard frames required by the project's per-shot video strategy. */
function listMissingStoryboardFrames(project, settings = null) {
  const missing = [];
  for (const shot of (project?.shots || []).slice().sort((a, b) => a.number - b.number)) {
    const stages = resolveShotVideoStrategy(project, shot).frameStages || [];
    for (const stage of stages) {
      if (!candidateReady(project, "shot", shot.id, stage, settings)) {
        missing.push({
          shotId: shot.id,
          shotNumber: shot.number,
          stage,
          label: `S${String(shot.number).padStart(2, "0")} · ${storyboardStageLabel(stage)}`
        });
      }
    }
  }
  return missing;
}

function assertProjectStoryboardsReady(project, settings = null) {
  const missing = listMissingStoryboardFrames(project, settings);
  if (!missing.length) return true;
  const preview = missing.slice(0, 8).map(item => item.label).join("、");
  throw Object.assign(new Error(`分镜帧未齐，不能进入分镜视频：缺 ${missing.length} 项（${preview}${missing.length > 8 ? "…" : ""}）。请先回到分镜工作台补齐后再继续。`), {
    code: "STORYBOARDS_INCOMPLETE",
    missing
  });
}

/** Drop stale “running” batch rows when no live operation owns them. */
function sanitizeBatchProgress(progress, automationStatus = "") {
  if (!progress || !Array.isArray(progress.items)) return progress || null;
  const active = ["running", "pausing", "stopping"].includes(String(automationStatus || ""));
  if (active) return progress;
  let changed = false;
  const items = progress.items.map(item => {
    if (item?.status !== "running") return item;
    changed = true;
    return {
      ...item,
      status: "failed",
      errorCode: item.errorCode || "STALE_RUNNING_CLEARED",
      message: item.message || "进程已中断，该项未真正提交上游",
      updatedAt: new Date().toISOString()
    };
  });
  if (!changed) return progress;
  return summarizeAssetBatch(items, progress.waveLabel || "", progress.kind || "asset_batch", {
    batchId: progress.batchId || "",
    batchStartedAt: progress.batchStartedAt || ""
  });
}

function projectVideoEngine(_project) {
  return "hailuo-h3";
}

function shotUsesManualVideoPrompt(shot = {}) {
  return shot?.promptMode === "manual" && Boolean(String(shot?.manualVideoPrompt || "").trim());
}

function referenceRoleIdentity(role = {}) {
  return [
    String(role?.type || "").trim(),
    String(role?.entityId || "").trim(),
    String(role?.characterId || "").trim()
  ].join(":");
}

function promptReviewReferenceManifestMatches(shot = {}, references = {}) {
  const reviewed = shot?.promptReviewReferencePlan || {};
  const reviewedImages = Array.isArray(reviewed.images) ? reviewed.images.map(referenceRoleIdentity) : [];
  const actualImages = Array.isArray(references.imageRoles) ? references.imageRoles.map(referenceRoleIdentity) : [];
  const reviewedAudios = Array.isArray(reviewed.audios)
    ? reviewed.audios.map(item => String(item?.characterId || "").trim())
    : [];
  const actualAudios = Array.isArray(references.audios)
    ? references.audios.map(item => String(item?.characterId || "").trim())
    : [];
  return reviewedImages.length === actualImages.length
    && reviewedImages.every((value, index) => value === actualImages[index])
    && reviewedAudios.length === actualAudios.length
    && reviewedAudios.every((value, index) => value === actualAudios[index]);
}

/**
 * System shot compilers own their complete provider budget. The submit layer is
 * deliberately validation-only for those prompts so a second generic pass can
 * never truncate dialogue, voice bindings, or immutable output policy.
 * Manual and non-shot prompts still use the generic bounded compiler.
 */
function finalizeVideoPromptForSubmission(project, entityType, entityId, stage, prompt, expectedEngine = projectVideoEngine(project), references = {}) {
  const source = String(prompt || "").replace(/\r/g, "").trim();
  if (!source) throw Object.assign(new Error("Video prompt is empty"), { code: "VIDEO_PROMPT_REQUIRED" });
  const shot = entityType === "shot" && stage === "shot_video"
    ? (project?.shots || []).find(item => item.id === entityId)
    : null;
  // Confirmed shot prose is immutable; only line-ending/outer whitespace transport normalization occurs here.
  if(shot){if(expectedEngine==='hailuo-h3')assertAgentHailuoDelivery(source);return source;}
  const compilerOwned = Boolean(shot && !shotUsesManualVideoPrompt(shot));
  if (!compilerOwned) {
    const officialHailuoPrompt = expectedEngine === "hailuo-h3"
      && /^subject_definitions:\s*$/im.test(source)
      && /^summary:\s*$/im.test(source)
      && /^retention_analysis:\s*$/im.test(source)
      && /^detailed_description:\s*$/im.test(source)
      && /^overall_soundscape:\s*$/im.test(source)
      && /^non_diegetic_music:\s*$/im.test(source);
    if (officialHailuoPrompt) {
      assertAgentHailuoDelivery(source, 1900);
      // Content ownership and English staging are reviewed by the configured Agent before user confirmation.
      return source;
    }
    return compactProviderVideoPrompt(source);
  }
  if (expectedEngine === "hailuo-h3" && references?.agentGenerationBlockShot?.agentGenerationBlock) {
    return source;
  }
  if (expectedEngine === "hailuo-h3" && references?.agentTakeShot?.agentTake) {
    return source;
  }
  // Old prompt-review bundles could enumerate every scene-present character
  // while production correctly submitted only the two visible faces.  That
  // shifted every later <Picture N> binding (character -> product/prop), which
  // the provider accepted but could never execute.  Preserve manual prompts,
  // but locally re-render compiler-owned prompts from the exact paid manifest.
  // No model call, new story fact, or dialogue rewrite occurs here.
  const reviewedWithCurrentCompiler = project?.promptReview?.version === PROMPT_REVIEW_BUNDLE_VERSION
    && shot?.promptReviewBundleVersion === PROMPT_REVIEW_BUNDLE_VERSION
    && /^subject_definitions:\s*$/im.test(source)
    && /^summary:\s*$/im.test(source)
    && /^retention_analysis:\s*$/im.test(source)
    && /^detailed_description:\s*$/im.test(source)
    && /^overall_soundscape:\s*$/im.test(source)
    && /^non_diegetic_music:\s*$/im.test(source);
  const executionSource = expectedEngine === "hailuo-h3"
    && (!promptReviewReferenceManifestMatches(shot, references) || !reviewedWithCurrentCompiler)
    ? renderApprovedVideoPrompt(project, shot, references)
    : source;
  // Content ownership and English staging are reviewed by the configured Agent before user confirmation.
  if (expectedEngine === "hailuo-h3") assertAgentHailuoDelivery(executionSource, 1900);
  return executionSource;
}

function assertVideoProviderAligned(project, settings) {
  const expectedEngine = projectVideoEngine(project);
  const providerKind = projectVideoProviderKind(project, settings);
  const projectProviderEngine = providerEngine(providerKind);
  if (expectedEngine !== projectProviderEngine) throw Object.assign(new Error("项目视频引擎记录不一致，请重新确认项目制作策略"), {
    code: "PROJECT_VIDEO_CONTRACT_INVALID",
    expectedEngine,
    providerKind
  });
  return expectedEngine;
}

function projectVideoProviderKind(project, settings = null) {
  void project;
  void settings;
  return "puream-hailuo-h3";
}

function projectVideoProviderConfig(project, settings = null) {
  const configured = settings?.videoProvider || {};
  return {
    ...configured,
    kind: "puream-hailuo-h3",
    model: "hailuo-h3",
    baseUrl: /^https:\/\/([a-z0-9.-]+\.)?puream\.cn(\/|$)/i.test(String(configured.baseUrl || ""))
      ? configured.baseUrl
      : "https://puream.cn"
  };
}

function normalizeProjectMode(value) {
  if (value === PRODUCTION_PACKAGE_MODE) return PRODUCTION_PACKAGE_MODE;
  if (value === "asset_direct") return "asset_direct";
  if (value === "keyframe") return "keyframe";
  if (value === "smart") return "smart";
  if (value === "storyboard_sheet") return "storyboard_sheet";
  return "continuation";
}

function isProductionPackageMode(value) {
  return normalizeProjectMode(value) === PRODUCTION_PACKAGE_MODE;
}

function skipsGeneratedStoryboards(value) {
  const mode = normalizeProjectMode(value);
  return mode === "asset_direct" || mode === PRODUCTION_PACKAGE_MODE;
}

function generationModeLabel(mode) {
  switch (normalizeProjectMode(mode)) {
    case PRODUCTION_PACKAGE_MODE: return "Codex 资产包直抽";
    case "asset_direct": return "资产直投 H3（无分镜图）";
    case "keyframe": return "首尾帧模式";
    case "continuation": return "视频延续模式";
    case "smart": return "智能首尾帧+视频延续";
    case "storyboard_sheet": return "单图多帧/逐秒分镜合图";
    default: return String(mode || "");
  }
}

/** Shared reference-parity text contract injected into EVERY generation mode (keyframe / continuation / smart / storyboard_sheet). */
function referenceParityTextSideContract() {
return require('./generation-prompts').build('shot_plan','本阶段保持给定输出Schema。每句保留实际speaker、listener、画内/画外来源、完整内容、语气、情绪和同时动作；可见人物不以说话人数裁剪。拍点、镜数、每镜句数和切镜数由因果与可演时长决定，换人可以连续构图或有动机切镜。cameraOwnerId表示取景重点，mouthOwnerId表示真实开口者，两者不代替visible cast。按实际场景维护站位和轴线；明确面向观众的购买邀请可直视镜头，工作或驾驶遵守真实视线。商品按源稿和当前明确输入出现，不用固定百分比或固定尾镜数决定出现时机。');
}

/** Source-level directive injected into script unit / analysis prompts so LLM authorship matches the confirmed project mode. */
function h3ReferenceParityTextSideContract() {
return referenceParityTextSideContract();
}

// Every production path is H3-only. Keep the authoring contract close to the
// text stage so source dialogue, performance and shot timing are correct before
// any paid asset request is allowed to start.
function h3TextStageDirective(stage) {
const stages={topic_ideation:'topics',story_bible:'story_plan',shot_plan:'shot_plan',units:'shot_plan',script_analysis:'source_understanding',script_repair:'shot_plan'}; if(!stages[stage])return '审核依据本阶段实际输入及统一有效要求，不增加未授权的生成格式或创作限制。'; return require('./generation-prompts').method(stages[stage]);
}

function textStagePromptForProject(project, settings, promptKey, stage) {
  const base = compileTextStagePrompt(settings?.prompts?.[promptKey], settings?.prompts || {}, stage);
  const stageDirective = h3TextStageDirective(stage);
  const enginePrompt = base.includes(stageDirective) ? base : `${base}\n\n${stageDirective}`;
  const creatorPrompt = promptIntakeText(project, stage, project);
  const creatorDirective = creatorPrompt
    ? `\n\n【用户从零批量上传的本阶段创作提示词·最高创作意图】\n${creatorPrompt}\n只要不改变用户原始对白、不交换说话人/听者、不破坏商品真实信息和机器可读输出结构，就按这份用户提示词执行；不得用系统范例覆盖。`
    : "";
  const productionContract = project?.foundry?.contract || compileProductionContract(project, settings, { source: `text_stage:${stage}` });
  return `${enginePrompt}\n\n${viewerComprehensionPriorityDirective()}\n\n${scriptFormatDirective(project)}${creatorDirective}\n\n${contractPromptBlock(productionContract)}`;
}

/** Source-level directive injected into script unit / analysis prompts. H3 uses the Agent atomic-camera contract. */
function generationModeSourceDirective(mode, engine = "hailuo-h3") {
  const normalizedMode = normalizeProjectMode(mode);
  void engine;
  const matrixPrompt = matrixGlobalPrompt("cloud", normalizedMode);
  const textSide = referenceParityTextSideContract();
  switch (normalizedMode) {
    case PRODUCTION_PACKAGE_MODE:
      return `${matrixPrompt}\n【当前图像/视频策略·Codex 资产包直抽】本模式只消费已通过严格导入校验的 .pdramapack。剧本、人物、场景、核心物品、分镜、逐字对白、英文厂商提示词、中文核对稿和每镜图片引用顺序全部来自导入包并保持不可改写；跳过选题、写作、拆镜、提示词生成、资产生成和分镜图生成。每镜直接提交包内锁定顺序的人物、场景、道具和商品原图，不要求或生成额外镜头锚点图。referencePlan.audios 必须为空，不使用上一镜视频。任何缺失、哈希不一致、说话人不明确或引用顺序变化都在付费提交前停止。\n\n${textSide}`;
    case "asset_direct":
      return `${matrixPrompt}\n【当前图像/视频策略·资产直投 H3】本模式不创建、不请求、不依赖任何首帧、尾帧或逐秒分镜合图，因此文本本身必须承担完整导演蓝图：每个H3任务为10–15秒，保留输入源稿的全部完整台词，按剧情安排必要的因果表演与有动机的构图选择，连续镜头与切镜均可，不设置固定拍点数或必切次数。先建立同场景screenSide/depth/facingCharacterId/eyeline账本；说话人的站位、朝向和视线遵循真实交流、群体称呼或工作动作，换边需拍出合理移动或重建轴线。referencePlan.images只列当前任务真正可见的人物、场景、剧情物品/商品；场景四视图整张原样作为一个参考传入。referencePlan.audios只列实际说话角色的可选音色参考，绝不预生成或承载本任务台词。每句中文台词逐字编译进H3对话标签，绑定唯一说话人、cameraOwnerId、mouthOwnerId、听者，以及起点→触发→峰值→余震的音量、音高、语速、停顿、重音、气息和眉眼下颌变化。换说话人保持清晰的发声所有权与空间轴线，按场景需要决定是否切镜；对白、动作、反应和结果连续覆盖完整时长，禁止站桩。\n\n${textSide}`;
    case "keyframe":
      return `${matrixPrompt}\n【当前图像/视频策略·首尾帧模式】每个单元必须写清可拍的 startFrame 与 endFrame；imagePrompt 描述单张剧情关键帧（不是合图、不是接触印）。referencePlan.images 含「人物/场景/首尾帧」（源稿商品实际出现时另加商品）；不要写「逐秒合图」，不要依赖上一单元视频作为主控。视频将用图1=首帧、图2=尾帧插值；禁止写成延续上一视频开场，禁止写成多格分镜板。单元的 soundCueSheet 与逐句情绪编译照常生效，不因图像策略改变而省略。

${textSide}`;
    case "continuation":
      return `${matrixPrompt}\n【当前图像/视频策略·视频延续模式】开场单元写 startFrame+endFrame；后续单元重点写 endFrame，并自然承接上一单元尾帧/视频。imagePrompt 服务首帧或尾帧关键帧（单张剧情画面）；referencePlan.video 写「延续模式上一单元」。禁止写成 16:9 多格接触印合图；禁止把每镜都当成独立首尾帧重新开场。延续模式下声场也必须延续：同场景底噪不得无故断档，换场单元才允许换底噪；禁止写BGM。

${textSide}`;
    case "smart":
      return `${matrixPrompt}\n【当前图像/视频策略·智能首尾帧+视频延续】同场景连续单元按视频延续写（强调 endFrame 与上一镜承接，声场同步延续）；换场或开场单元按首尾帧写（startFrame 与 endFrame 都必须可拍，换场即换底噪）。每个单元仍须给出 startFrame 与 endFrame，供智能策略择用；imagePrompt 始终是单张关键帧，不是合图。referencePlan 同时保留首尾帧与延续视频用途说明，勿混写合图版式。

${textSide}`;
    case "storyboard_sheet":
      return `${matrixPrompt}\n【当前图像/视频策略·单图多帧/逐秒分镜合图】每个单元只出一张接触印合图（约每秒一格，格子间有分隔缝），不是首+尾两张关键帧。每个独立画格必须完整使用项目设定画幅并保持同一宽高，只能等比例缩放、居中裁切或留边，绝对禁止横向挤压、纵向拉长或人物跨格；总画布由系统按供应商真实支持比例另行编排。必须输出 secondPanels：长度恰好等于 duration，second 从 0 到 duration-1；每项简写 framing/camera/action/faceAction/bodyAction（可含短对白节拍），相邻格可通过说话人所有权、景别、构图、视线、表情、道具状态或剧情必需动作产生变化，不强制每格新增肢体动作。imagePrompt 必须描述多格合图版式与逐格节拍，禁止只写单张剧情剧照文案。referencePlan.images 用「人物/场景/逐秒合图」（商品窗口另加商品），不要写「首尾帧」为主控。视频以合图为时间轴按格顺序演绎；仍可写 startFrame/endFrame 作为首格/末格语义锚点。打脸/悲惨单元的格子顺序必须呈现信息与情绪递进，禁止整板同一构图复制。

${textSide}`;
    default:
      return generationModeSourceDirective("continuation", "hailuo-h3");
  }
}

function productionUnitGenerationModeDirective(mode, engine = "hailuo-h3") {
  const normalized = normalizeProjectMode(mode);
  const modeRule = {
    production_package: "【当前图像/视频策略·Codex 资产包直抽】不创作或重写任何剧本、分镜、提示词或资产；严格使用导入包内逐镜英文提示词和锁定图片引用顺序，直接提交人物、场景、道具和商品原图，不要求或生成额外镜头锚点图。referencePlan.audios 必须为空，不使用上一镜视频。",
    asset_direct: "【当前图像/视频策略·资产直投 H3】不输出首帧、尾帧、逐秒合图或分镜图字段；每个H3任务必须10–15秒，保留源稿分配的全部完整台词，用源稿实际必需的动作完成开场/入场或触发、对白剧情动作、听者闭口反应和可见结果/交接，按内容选择连续构图或有动机切镜。先建立稳定screenSide/depth/facingCharacterId/eyeline账本；说话人的脸、眼睛和上身朝听者，绝不看虚空，换边必须拍出穿越或轴线重建。每句逐字中文对白绑定唯一说话人、嘴型、镜头和听者，写清情绪起点→触发→峰值→余震及音量、音高、语速、停顿、重音、气息、眉眼和下颌变化。人物音频只标识音色，绝不承载当前台词；换说话人保持明确归属，按内容决定连续画面或正反打。场景四视图原始文件整张原样传入。群体只作闭口反应并回同一主轴；对白、动作和结果连续覆盖完整时长，禁止站桩。",
    keyframe: "【当前图像/视频策略·首尾帧模式】每个单元写清可拍的 startFrame 与 endFrame；禁止写成延续上一视频开场或多格分镜板。subshots按连续完整台词的说话人轮次动态组织：同一人相邻句合并，换人再硬切；必要反应或动作结果并入相邻段，不固定三段。画面差异优先由说话人、景别、构图、表情和视线承担，SFX-only 全模式同标。",
    continuation: "【当前图像/视频策略·视频延续模式】开场或真实换场单元写 startFrame+endFrame；只有同场景后续单元重点写 endFrame，并自然承接上一单元尾帧/视频；换场绝不继承旧空间，禁止写成多格分镜板。subshots按连续完整台词的说话人轮次动态组织：同一人相邻句合并，换人再硬切；必要反应或动作结果并入相邻段，不固定三段。画面差异优先由说话人、景别、构图、表情和视线承担，SFX-only 全模式同标。",
    smart: "【当前图像/视频策略·智能首尾帧+视频延续】同场景连续单元强调 endFrame 与上一镜承接；换场或开场单元写清 startFrame 与 endFrame。subshots按连续完整台词的说话人轮次动态组织：同一人相邻句合并，换人再硬切；必要反应或动作结果并入相邻段，不固定三段。画面差异优先由说话人、景别、构图、表情和视线承担，SFX-only 全模式同标。",
    storyboard_sheet: "【当前图像/视频策略·单图多帧/逐秒分镜合图】必须输出 secondPanels：长度恰好等于 duration，second 从 0 到 duration-1，每项简写 framing/camera/action/faceAction/bodyAction；startFrame/endFrame 作为首格/末格语义锚点。逐格新信息可由说话人、景别、构图、视线、表情或关键状态承担，不强制逐格新增肢体动作；口播短锤、SFX-only 全模式同标。"
  }[normalized];
  const source = generationModeSourceDirective(normalized, engine);
  const commonMarker = engine === "hailuo-h3" ? "【文本侧模式约束" : "【像素算力·H3 文本/分镜生产规范】";
  const commonIndex = source.indexOf(commonMarker);
  const common = commonIndex >= 0 ? source.slice(commonIndex) : source;
  return `${modeRule}\nProduct shots are optional; never force them into every shot. For productMention=true, preserve the exact user product name and fill all five productCausalBridge fields from locked authored action/state/subshots only: situationNeed -> whyNow -> action -> observableOutcome -> relationOrDecisionShift. Do not invent dialogue, plot, efficacy, price, discount or claims. For productMention=false, keep the bridge empty.\n【商品收口导演规则】按当前源稿的真实人物需要和动作进入商品，不锁定唯一反转时点、持用人数或固定句式。讲解、优惠、购买引导使用与实际内容相符的shotFunction/productShotType；仅明确向观众邀请购买时设addressMode=viewer、directToViewer=true，人物间推荐保持真实听者。完整体现输入的相关价格、优惠和购买入口；无具体条件时不编造，没有确认入口也不声称某个按钮或橱窗存在。\n【核心物品跨镜连续性】每个核心道具/证据/随身商品的 propBindings 必须填写 holderBeforeCharacterId、holderAfterCharacterId、locationBefore、locationAfter、stateBefore、stateAfter、transferAction。上一镜/上次出现的末态就是下一次出现的前态；只有持有人、位置或物件状态真正变化时，才用一个最短可见动作完成换手、拾起、放下、取出、装包、开合、消耗或损坏，绝不允许道具瞬移或无动作更换持有人。顶层action只作全镜摘要；每个必要物理动作只能放进一个正确时间段执行一次，首段不得提前演后段动作，末段不得重演，最终subshot的stateAfter必须与顶层唯一末态一致。无角色ID/音色的群众只能闭口反应，不能询问或出声；无可读文字的道具不得靠读取姓名、号码或价格推进剧情。\n派生图像提示、视频提示和素材引用计划由系统按上述结构化字段自动编译，模型无需输出。\n${dialogueFirstActionContractZh()}\n${common}`.trim();
}

function modeAwareReferencePlan(mode, productMention, source = null) {
  const normalized = normalizeProjectMode(mode);
  const images = ["人物", "场景"];
  if (normalized === PRODUCTION_PACKAGE_MODE) images.splice(0, images.length, "资产包锁定图片引用");
  if (productMention) images.push("商品");
  if (normalized === PRODUCTION_PACKAGE_MODE) {
    // The imported package owns the exact image list and order. The fallback
    // label exists only for diagnostics before the persisted plan is loaded.
  } else if (normalized === "asset_direct") images.push("剧情物品");
  else if (normalized === "storyboard_sheet") images.push("逐秒合图");
  else images.push("首尾帧");
  const video = normalized === PRODUCTION_PACKAGE_MODE
    ? "不使用上一单元视频；只使用资产包锁定的本镜图片引用"
    : normalized === "asset_direct"
    ? "不使用上一单元视频；由人物/场景/物品/商品/音色资产直接驱动本镜"
    : normalized === "keyframe"
    ? "不使用上一单元视频"
    : normalized === "storyboard_sheet"
      ? "不使用上一单元视频；以逐秒合图为时间轴"
      : "延续模式上一单元";
  const base = source && typeof source === "object" ? source : {};
  return {
    images: Array.isArray(base.images) && base.images.length ? base.images.map(String) : images,
    video: String(base.video || video),
    audios: Array.isArray(base.audios) ? base.audios.map(String) : []
  };
}

function normalizeSecondPanels(rawPanels, durationSeconds, shot = {}) {
  const duration = Math.max(10, Math.min(15, Math.round(Number(durationSeconds) || 12)));
  const panels = Array.isArray(rawPanels) ? rawPanels : [];
  const subshots = Array.isArray(shot.subshots) ? shot.subshots : [];
  const result = [];
  for (let second = 0; second < duration; second += 1) {
    const hit = panels.find(item => Number(item?.second) === second)
      || panels.find(item => Number(item?.t) === second)
      || panels[second]
      || null;
    const sub = subshots.find(item => {
      const start = Number(item.start) || 0;
      const end = Math.max(Number(item.end) || 0, start + 0.1);
      return second >= start && second < end;
    }) || subshots[Math.min(second, Math.max(0, subshots.length - 1))] || null;
    result.push({
      second,
      framing: String(hit?.framing || sub?.framing || shot.shotSize || "").trim(),
      camera: String(hit?.camera || sub?.camera || shot.cameraMove || "").trim(),
      action: String(hit?.action || hit?.beat || hit?.description || sub?.action || shot.visualBeat || shot.action || (`第${second}秒推进`)).trim(),
      dialogue: String(hit?.dialogue || "").trim(),
      takeId: String(hit?.takeId || sub?.takeId || "").trim(),
      cameraOwnerId: String(hit?.cameraOwnerId || sub?.cameraOwnerId || shot.cameraOwnerId || "").trim(),
      mouthOwnerId: String(hit?.mouthOwnerId || sub?.mouthOwnerId || shot.mouthOwnerId || "").trim(),
      speakerId: String(hit?.speakerId || sub?.speakerIds?.[0] || shot.speakerId || "").trim(),
      listenerIds: normalizeStringArray(hit?.listenerIds || sub?.listenerIds || shot.listenerIds),
      visibleCharacterIds: normalizeStringArray(hit?.visibleCharacterIds || sub?.visibleCharacterIds || shot.visibleCharacterIds)
    });
  }
  return result;
}

function formatSecondPanelBeats(panels) {
  return (Array.isArray(panels) ? panels : []).map(item => {
    const second = Number(item.second);
    const label = Number.isFinite(second) ? `${second.toFixed(1)}s` : "?";
    const ownership = [item.cameraOwnerId ? `cameraOwner=${item.cameraOwnerId}` : "", item.mouthOwnerId ? `mouthOwner=${item.mouthOwnerId}` : "", item.speakerId ? `speaker=${item.speakerId}` : ""].filter(Boolean).join(" ");
    return `${label}：${[ownership, item.framing, item.camera, item.action, item.dialogue].filter(Boolean).join(" / ")}`;
  }).join("；");
}

function formatVisualSecondPanelBeats(panels) {
  return (Array.isArray(panels) ? panels : []).map(item => {
    const second = Number(item.second);
    const label = Number.isFinite(second) ? `${second.toFixed(1)}s` : "?";
    const ownership = [item.cameraOwnerId ? `cameraOwner=${item.cameraOwnerId}` : "", item.mouthOwnerId ? `mouthOwner=${item.mouthOwnerId}` : "", item.speakerId ? `speaker=${item.speakerId}` : ""].filter(Boolean).join(" ");
    return `${label}：${[ownership, item.framing, item.camera, item.action].filter(Boolean).join(" / ")}`;
  }).join("；");
}


function shotSceneKey(shot) {
  const id = String(shot?.sceneId || "").trim();
  if (id) return `id:${id}`;
  const name = String(shot?.sceneName || "").trim();
  return name ? `name:${name}` : "";
}

function previousShotByNumber(project, shot) {
  const number = Number(shot?.number);
  if (!Number.isFinite(number) || number <= 1) return null;
  return (project?.shots || []).find(item => Number(item.number) === number - 1) || null;
}

function isSceneSwitch(previousShot, shot) {
  if (!previousShot) return true;
  const previousKey = shotSceneKey(previousShot);
  const currentKey = shotSceneKey(shot);
  if (!previousKey || !currentKey) return true;
  return previousKey !== currentKey;
}

/**
 * Smart hybrid: same scene continuous → video continuation (end frame only);
 * scene cut / open → keyframe (start + end). Fixed continuation also resets on
 * a true scene cut so a previous room can never bleed into the new space.
 */
function resolveShotVideoStrategy(project, shot) {
  const projectMode = normalizeProjectMode(project?.generation?.mode);
  if (projectMode === PRODUCTION_PACKAGE_MODE) {
    return {
      projectMode,
      strategy: PRODUCTION_PACKAGE_MODE,
      usePreviousVideo: false,
      frameStages: [],
      reason: "project_production_package"
    };
  }
  if (projectMode === "asset_direct") {
    return {
      projectMode,
      strategy: "asset_direct",
      usePreviousVideo: false,
      frameStages: [],
      reason: "project_asset_direct"
    };
  }
  if (projectMode === "storyboard_sheet") {
    return {
      projectMode,
      strategy: "keyframe",
      usePreviousVideo: false,
      frameStages: ["storyboard_sheet"],
      reason: "project_storyboard_sheet"
    };
  }
  if (projectMode === "keyframe") {
    return {
      projectMode,
      strategy: "keyframe",
      usePreviousVideo: false,
      frameStages: ["storyboard_start", "storyboard_end"],
      reason: "project_keyframe"
    };
  }
  if (projectMode === "continuation") {
    const opening = Number(shot?.number || 0) <= 1;
    const previous = previousShotByNumber(project, shot);
    const sceneCut = !opening && isSceneSwitch(previous, shot);
    return {
      projectMode,
      strategy: opening || sceneCut ? "keyframe" : "continuation",
      usePreviousVideo: !opening && !sceneCut,
      frameStages: opening || sceneCut ? ["storyboard_start", "storyboard_end"] : ["storyboard_end"],
      reason: opening ? "continuation_open" : sceneCut ? "continuation_scene_cut" : "continuation_chain"
    };
  }
  const previous = previousShotByNumber(project, shot);
  if (!previous || Number(shot?.number || 0) <= 1) {
    return {
      projectMode: "smart",
      strategy: "keyframe",
      usePreviousVideo: false,
      frameStages: ["storyboard_start", "storyboard_end"],
      reason: "smart_open"
    };
  }
  if (isSceneSwitch(previous, shot)) {
    return {
      projectMode: "smart",
      strategy: "keyframe",
      usePreviousVideo: false,
      frameStages: ["storyboard_start", "storyboard_end"],
      reason: "smart_scene_cut"
    };
  }
  return {
    projectMode: "smart",
    strategy: "continuation",
    usePreviousVideo: true,
    frameStages: ["storyboard_end"],
    reason: "smart_same_scene_continue"
  };
}

/** @deprecated Prefer resolveShotVideoStrategy(project, shot).frameStages when project is available. */
function shotStoryboardFrameStages(mode, shot, project = null) {
  if (project) return resolveShotVideoStrategy({ ...project, generation: { ...(project.generation || {}), mode: mode || project.generation?.mode } }, shot).frameStages;
  const normalized = normalizeProjectMode(mode);
  if (skipsGeneratedStoryboards(normalized)) return [];
  if (normalized === "storyboard_sheet") return ["storyboard_sheet"];
  if (normalized === "keyframe" || Number(shot?.number || 0) <= 1) return ["storyboard_start", "storyboard_end"];
  if (normalized === "smart") {
    // Without project context, conservative keyframe for non-opening shots.
    return ["storyboard_start", "storyboard_end"];
  }
  return ["storyboard_end"];
}

function shotRequiresStartFrame(mode, shot, project = null) {
  return shotStoryboardFrameStages(mode, shot, project).includes("storyboard_start");
}

function annotateProjectShotStrategies(project) {
  if (!project || !Array.isArray(project.shots)) return project;
  project.shots = project.shots.map(shot => {
    const resolved = resolveShotVideoStrategy(project, shot);
    return {
      ...shot,
      videoStrategy: resolved.strategy,
      videoStrategyReason: resolved.reason,
      videoFrameStages: resolved.frameStages
    };
  });
  return project;
}

function selectHailuoReferencesForMode(references = {}, modeValue = "auto") {
  const hailuoApiMode = normalizeHailuoApiMode(modeValue);
  const base = {
    ...references,
    images: Array.isArray(references.images) ? references.images : [],
    imageRoles: Array.isArray(references.imageRoles) ? references.imageRoles : [],
    videos: Array.isArray(references.videos) ? references.videos : references.video ? [references.video] : [],
    videoRoles: Array.isArray(references.videoRoles) ? references.videoRoles : [],
    videoAudios: Array.isArray(references.videoAudios) ? references.videoAudios : [],
    audios: Array.isArray(references.audios) ? references.audios : [],
    hailuoApiMode
  };
  if (hailuoApiMode === "text_to_video") return { ...base, images: [], imageRoles: [], videos: [], videoRoles: [], videoAudios: [], audios: [] };
  if (hailuoApiMode === "image_to_video") {
    const startIndex = base.imageRoles.findIndex(role => String(role?.type || "") === "storyboard_start");
    const endIndex = base.imageRoles.findIndex(role => String(role?.type || "") === "storyboard_end");
    const indices = [startIndex, endIndex].filter(index => index >= 0);
    return {
      ...base,
      images: indices.map(index => base.images[index]),
      imageRoles: indices.map(index => base.imageRoles[index]),
      videos: [],
      videoRoles: [],
      videoAudios: [],
      audios: []
    };
  }
  if (hailuoApiMode === "reference_to_video") return { ...base, videos: [], videoRoles: [], videoAudios: [], audios: [] };
  if (hailuoApiMode === "video_to_video") return { ...base, images: [], imageRoles: [], audios: [] };
  if (hailuoApiMode === "audio_to_video") return { ...base, images: [], imageRoles: [], videos: [], videoRoles: [], videoAudios: [] };
  return base;
}

/**
 * Provider mode must describe the references that will actually be submitted,
 * not the parent shot's earlier intention. Director-Agent block filtering can
 * legitimately turn a multimodal parent into a video-only, image-only or
 * audio-only child. Deriving here prevents impossible provider contracts.
 */
function resolveHailuoApiModeForReferences(references = {}, preferredMode = "auto") {
  const media = {
    images: Array.isArray(references.images) ? references.images.filter(Boolean) : [],
    videos: Array.isArray(references.videos) ? references.videos.filter(Boolean) : references.video ? [references.video] : [],
    audios: Array.isArray(references.audios) ? references.audios.filter(Boolean) : [],
    videoAudios: Array.isArray(references.videoAudios) ? references.videoAudios : []
  };
  const categories = hailuoMediaCategories(media);
  if (categories.length >= 2) return "multimodal_to_video";
  if (categories[0] === "image") {
    const roles = Array.isArray(references.imageRoles) ? references.imageRoles : [];
    const temporalRoles = roles.map(item => String(item?.type || "").trim());
    const isFirstLastPair = media.images.length === 2
      && temporalRoles[0] === "storyboard_start"
      && temporalRoles[1] === "storyboard_end";
    return isFirstLastPair ? "image_to_video" : "reference_to_video";
  }
  if (categories[0] === "video") return "video_to_video";
  if (categories[0] === "audio") return "audio_to_video";
  normalizeHailuoApiMode(preferredMode);
  return "text_to_video";
}

function isQualityGatesEnabled(settings, moduleName = "script") {
  // The user-facing switch is authoritative. When it is off, no review module
  // may block, roll back or rewrite user work. Machine-readable JSON shape and
  // provider-required request fields are validated separately.
  const value = settings?.generation?.qualityGatesEnabled;
  const globallyEnabled = value === true || value === 1 || value === "true" || value === "1" || value === "on";
  if (!globallyEnabled) return false;
  const moduleValue = settings?.generation?.qualityGateModules?.[moduleName];
  return moduleValue === true || moduleValue === 1 || moduleValue === "true" || moduleValue === "1" || moduleValue === "on";
}

function productionStructureGateEnabled(settings, project = null) {
  const override = project?.qualityReviewOverrides?.productionStructure;
  if (override && String(override.productionRevision || "") === String(project?.productionRevision || "")) return false;
  return isQualityGatesEnabled(settings, "script")
    && normalizeBlueprintAuditChecks(settings?.generation?.blueprintAuditChecks || {}).productionStructure === true;
}

function dialogueRewriteCharacterSet(value) {
  return new Set(String(value || "")
    .toLowerCase()
    .replace(/[\s，。！？、；：,.!?;:'"“”‘’（）()\[\]【】《》<>—…·-]/g, "")
    .split("")
    .filter(Boolean));
}

function dialogueRewriteSimilarity(source, rewritten) {
  const left = dialogueRewriteCharacterSet(source);
  const right = dialogueRewriteCharacterSet(rewritten);
  if (!left.size || !right.size) return 0;
  let shared = 0;
  for (const character of left) if (right.has(character)) shared += 1;
  return (2 * shared) / (left.size + right.size);
}

function dialogueRewriteNumericTokens(value) {
  return String(value || "").match(/\d+(?:\.\d+)?(?:[%％元万千百十年月日号岁秒分钟天])?/g) || [];
}

function dialogueRewriteNameMap(ledger = []) {
  const genericPattern = /^(?:[A-ZＡ-Ｚ]|[a-zａ-ｚ]|甲|乙|丙|丁|角色\s*\d+|人物\s*\d+)$/i;
  const candidates = ["林岚", "周诚", "秦若", "陈川", "苏晴", "顾言", "许宁", "沈禾", "方予", "程安", "陆遥", "唐悦"];
  const sourceNames = [...new Set(ledger.map(item => String(item?.speaker || item?.speakerRaw || "").trim()).filter(Boolean))];
  const reserved = new Set(sourceNames.filter(name => !genericPattern.test(name)));
  let candidateIndex = 0;
  return sourceNames.map(sourceName => {
    if (!genericPattern.test(sourceName)) return { sourceName, newName: sourceName, renamed: false };
    while (candidateIndex < candidates.length && reserved.has(candidates[candidateIndex])) candidateIndex += 1;
    const newName = candidates[candidateIndex] || `人物${candidateIndex + 1}`;
    candidateIndex += 1;
    reserved.add(newName);
    return { sourceName, newName, renamed: newName !== sourceName };
  });
}

function normalizedCharacterName(value = "") {
  return String(value || "").trim().replace(/\s+/g, "").toLowerCase();
}

function usableCharacterName(value = "") {
  const name = String(value || "").trim();
  if (!name || /^C\d+$/i.test(name)) return "";
  if (/^(?:未知|未命名|待定|角色|人物|剧情人物)(?:\d+|C\d+)?$/i.test(name.replace(/\s+/g, ""))) return "";
  return name;
}

function cloneReferenceTree(value) {
  if (Array.isArray(value)) return value.map(cloneReferenceTree);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, child]) => [key, cloneReferenceTree(child)]));
  }
  return value;
}

function replaceCharacterIdToken(value, sourceId, targetId) {
  if (typeof value !== "string" || !sourceId || !targetId || sourceId === targetId) return value;
  return value.replace(new RegExp(`\\b${sourceId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\b`, "gi"), targetId);
}

/**
 * Repairs legacy/model character-reference drift without rewriting dialogue.
 * Evidence order: source dialogue ledger -> explicit speaker/name -> aligned
 * characterIds/characterNames. Unknown metadata-only IDs are removed. An ID
 * that owns real dialogue is preserved by creating a minimal character asset.
 */
function reconcileOrphanCharacterReferences(project = {}, options = {}) {
  const source = project && typeof project === "object" ? project : {};
  const characters = (Array.isArray(source.characters) ? source.characters : []).map((character, index) => ({
    ...cloneReferenceTree(character),
    id: String(character?.id || `C${String(index + 1).padStart(2, "0")}`).trim()
  }));
  const shots = (Array.isArray(source.shots) ? source.shots : []).map(cloneReferenceTree);
  const failuresBefore = characterReferenceFailures(shots, characters);
  if (!failuresBefore.length) {
    return {
      project: { ...source, characters, shots },
      changed: false,
      addedCharacters: [],
      remappedReferences: {},
      removedReferences: [],
      failuresBefore: [],
      failuresAfter: []
    };
  }

  const unknownIds = [...new Set(failuresBefore.flatMap(item => item.unknownIds || []))].map(id => String(id).toUpperCase());
  const unknownSet = new Set(unknownIds);
  const knownById = new Map(characters.map(character => [String(character.id || "").toUpperCase(), character]).filter(([id]) => id));
  const knownIdByName = new Map(characters.map(character => [normalizedCharacterName(character.name), String(character.id || "")]).filter(([name, id]) => name && id));
  const nameEvidence = new Map(unknownIds.map(id => [id, []]));
  const spokenEvidence = new Map(unknownIds.map(id => [id, []]));
  const ledgerById = new Map((Array.isArray(source.sourceDialogueLedger) ? source.sourceDialogueLedger : [])
    .map(item => [String(item?.id || "").trim(), item])
    .filter(([id]) => id));

  const addNameEvidence = (id, name, weight = 1) => {
    const key = String(id || "").toUpperCase();
    const cleanName = usableCharacterName(name);
    if (!unknownSet.has(key) || !cleanName) return;
    nameEvidence.get(key).push({ name: cleanName, weight });
  };
  const addSpokenEvidence = (id, text = "", name = "") => {
    const key = String(id || "").toUpperCase();
    if (!unknownSet.has(key)) return;
    const line = String(text || "").trim();
    if (line) spokenEvidence.get(key).push(line);
    addNameEvidence(key, name, 5);
  };
  const scanObject = value => {
    if (!value || typeof value !== "object") return;
    if (Array.isArray(value)) {
      value.forEach(scanObject);
      return;
    }
    const speakerId = String(value.speakerId || value.characterId || "").trim().toUpperCase();
    if (unknownSet.has(speakerId) && String(value.text || value.spokenText || "").trim()) {
      const ledgerSpeaker = ledgerById.get(String(value.sourceDialogueId || value.sourceId || "").trim())?.speaker;
      addSpokenEvidence(
        speakerId,
        value.text || value.spokenText,
        ledgerSpeaker || value.speakerName || value.characterName || (/^C\d+$/i.test(String(value.speaker || "")) ? "" : value.speaker)
      );
    }
    for (const [key, child] of Object.entries(value)) {
      if (CHARACTER_REFERENCE_ARRAY_KEYS.has(key) && Array.isArray(child)) {
        child.forEach(id => {
          const token = String(id || "").trim().toUpperCase();
          if (unknownSet.has(token) && ["speakerIds", "offscreenSpeakerIds"].includes(key)) {
            const dialogueText = String(value.dialogue || value.text || value.spokenText || "").trim();
            if (dialogueText && new RegExp(`(?:^|[；;\\n])\\s*${token}\\s*[：:]`, "i").test(dialogueText)) {
              addSpokenEvidence(token, dialogueText);
            }
          }
        });
      }
      scanObject(child);
    }
  };

  for (const shot of shots) {
    const alignedPairs = [
      [shot.characterIds, shot.characterNames],
      [shot.scenePresenceCharacterIds, shot.scenePresenceCharacterNames]
    ];
    for (const [ids, names] of alignedPairs) {
      (Array.isArray(ids) ? ids : []).forEach((id, index) => addNameEvidence(id, Array.isArray(names) ? names[index] : "", 3));
    }
    const dialogueSources = [shot.dialogue, shot.videoPromptDialogueOverride, ...(Array.isArray(shot.subshots) ? shot.subshots.map(item => item?.dialogue) : [])];
    for (const raw of dialogueSources) {
      for (const turn of parseCompiledDialogueSegments(raw || "", [...knownIdByName.keys(), ...unknownIds])) {
        const speaker = String(turn?.speaker || turn?.speakerId || "").trim();
        if (unknownSet.has(speaker.toUpperCase())) addSpokenEvidence(speaker, turn?.spokenText || turn?.text || "");
      }
    }
    scanObject(shot);
  }

  const remap = new Map();
  const addedCharacters = [];
  const removedReferences = [];
  for (const unknownId of unknownIds) {
    const ranked = new Map();
    for (const evidence of nameEvidence.get(unknownId) || []) {
      const key = normalizedCharacterName(evidence.name);
      if (!key) continue;
      const entry = ranked.get(key) || { name: evidence.name, score: 0 };
      entry.score += Number(evidence.weight) || 1;
      ranked.set(key, entry);
    }
    const best = [...ranked.values()].sort((left, right) => right.score - left.score)[0];
    const existingId = best ? knownIdByName.get(normalizedCharacterName(best.name)) : "";
    if (existingId) {
      remap.set(unknownId, existingId);
      continue;
    }
    const spokenLines = spokenEvidence.get(unknownId) || [];
    if (spokenLines.length && options.allowCharacterCreation !== false) {
      const name = best?.name || `剧情人物${unknownId}`;
      const character = {
        id: unknownId,
        name,
        age: "",
        role: "剧情人物",
        description: `${name}是从原剧本对白中自动补齐的出场人物；保持生活化真实外形，并依据剧情上下文统一年龄、发型、体态与服装。`,
        identitySignature: `${unknownId}独立人物身份；脸型、发型、体态和服装跨镜保持一致`,
        voiceDescription: "符合人物年龄与剧情身份的自然中文口语；完整保留原对白的语气、停顿、重音和情绪变化。",
        signatureLine: String(spokenLines[0] || "").slice(0, 80),
        continuityLocks: ["人物身份跨镜一致", "对白说话人不得替换", "情绪与原剧本语气一致"],
        importance: "supporting",
        outfits: []
      };
      characters.push(character);
      addedCharacters.push(character);
      knownById.set(unknownId, character);
      knownIdByName.set(normalizedCharacterName(name), unknownId);
      remap.set(unknownId, unknownId);
      continue;
    }
    removedReferences.push(unknownId);
  }

  const repairTree = (value, key = "") => {
    if (CHARACTER_REFERENCE_ARRAY_KEYS.has(key)) {
      const input = Array.isArray(value) ? value : [];
      return [...new Set(input.map(item => {
        const token = String(item || "").trim();
        if (!/^C\d+$/i.test(token)) return token;
        const upper = token.toUpperCase();
        if (!unknownSet.has(upper)) return token;
        return remap.get(upper) || "";
      }).filter(Boolean))];
    }
    if (CHARACTER_REFERENCE_SCALAR_KEYS.has(key)) {
      const token = String(value || "").trim();
      if (!/^C\d+$/i.test(token)) return value;
      const upper = token.toUpperCase();
      return unknownSet.has(upper) ? (remap.get(upper) || "") : value;
    }
    if (Array.isArray(value)) return value.map(item => repairTree(item, ""));
    if (value && typeof value === "object") {
      return Object.fromEntries(Object.entries(value).map(([childKey, child]) => [childKey, repairTree(child, childKey)]));
    }
    if (typeof value === "string") {
      let output = value;
      for (const [sourceId, targetId] of remap.entries()) output = replaceCharacterIdToken(output, sourceId, targetId);
      return output;
    }
    return value;
  };

  const repairedShots = shots.map(shot => {
    const repaired = repairTree(shot);
    const byId = new Map(characters.map(character => [String(character.id || ""), character]));
    repaired.characterNames = normalizeStringArray(repaired.characterIds).map(id => byId.get(id)?.name || id);
    repaired.scenePresenceCharacterNames = normalizeStringArray(repaired.scenePresenceCharacterIds).map(id => byId.get(id)?.name || id);
    repaired.visibleCharacterIds = normalizeStringArray(repaired.visibleCharacterIds);
    repaired.imageReferenceCharacterIds = normalizeStringArray(repaired.imageReferenceCharacterIds).filter(id => repaired.visibleCharacterIds.includes(id));
    repaired.videoReferenceCharacterIds = normalizeStringArray(repaired.videoReferenceCharacterIds).filter(id => repaired.visibleCharacterIds.includes(id));
    if (!repaired.visibleCharacterIds.includes(repaired.focusCharacterId)) repaired.focusCharacterId = repaired.visibleCharacterIds[0] || "";
    if (!repaired.visibleCharacterIds.includes(repaired.counterpartCharacterId) || repaired.counterpartCharacterId === repaired.focusCharacterId) {
      repaired.counterpartCharacterId = repaired.visibleCharacterIds.find(id => id !== repaired.focusCharacterId) || "";
    }
    const beforeIds = collectCharacterReferenceIds(shot).sort().join(",");
    const afterIds = collectCharacterReferenceIds(repaired).sort().join(",");
    if (beforeIds !== afterIds) {
      repaired.hailuoPromptSpec = null;
      if (!String(repaired.manualImagePrompt || "").trim()) repaired.systemImagePrompt = "";
      if (!String(repaired.manualVideoPrompt || "").trim()) repaired.systemVideoPrompt = "";
    }
    return repaired;
  });
  const failuresAfter = characterReferenceFailures(repairedShots, characters);
  return {
    project: { ...source, characters, shots: repairedShots },
    changed: JSON.stringify(shots) !== JSON.stringify(repairedShots) || addedCharacters.length > 0,
    addedCharacters,
    remappedReferences: Object.fromEntries([...remap.entries()].filter(([sourceId, targetId]) => sourceId !== targetId)),
    removedReferences,
    failuresBefore,
    failuresAfter
  };
}

function validateDialogueRewriteLines(sourceLedger = [], authoredLines = [], nameMap = []) {
  if (!Array.isArray(authoredLines) || authoredLines.length !== sourceLedger.length) {
    throw Object.assign(new Error(`对白轻改必须逐句返回：需要 ${sourceLedger.length} 句，实际 ${Array.isArray(authoredLines) ? authoredLines.length : 0} 句`), {
      code: "DIALOGUE_REWRITE_LINE_COUNT_MISMATCH"
    });
  }
  const mappedNames = new Map(nameMap.map(item => [item.sourceName, item.newName]));
  const seen = new Set();
  return sourceLedger.map((source, index) => {
    const authored = authoredLines[index] || {};
    const sourceId = String(authored.sourceId || authored.id || "").trim();
    if (sourceId !== source.id || seen.has(sourceId)) {
      throw Object.assign(new Error(`对白轻改第 ${index + 1} 句编号或顺序不一致`), { code: "DIALOGUE_REWRITE_ORDER_MISMATCH" });
    }
    seen.add(sourceId);
    const dialogue = String(authored.dialogue || authored.text || authored.spokenText || "").trim();
    if (!dialogue) throw Object.assign(new Error(`对白轻改第 ${index + 1} 句为空`), { code: "DIALOGUE_REWRITE_EMPTY_LINE" });
    const original = String(source.text || "").trim();
    const similarity = dialogueRewriteSimilarity(original, dialogue);
    const maxLength = Math.max(original.length + 28, Math.ceil(original.length * 1.75));
    const sourceNumbers = dialogueRewriteNumericTokens(original);
    const rewrittenNumbers = dialogueRewriteNumericTokens(dialogue);
    const missingNumber = sourceNumbers.find(token => !rewrittenNumbers.includes(token));
    const inventedNumber = rewrittenNumbers.find(token => !sourceNumbers.includes(token));
    if (similarity < 0.42 || dialogue.length > maxLength || missingNumber || inventedNumber) {
      throw Object.assign(new Error(`对白轻改第 ${index + 1} 句偏离原意，已拒绝该批结果`), {
        code: "DIALOGUE_REWRITE_SEMANTIC_DRIFT",
        similarity,
        sourceId
      });
    }
    return {
      sourceId: source.id,
      sourceName: source.speaker,
      speakerName: mappedNames.get(source.speaker) || source.speaker,
      tone: String(authored.tone || source.tone || "自然口语").trim(),
      scene: String(authored.scene || "").trim(),
      action: String(authored.action || "").trim(),
      originalText: original,
      rewrittenText: dialogue,
      similarity
    };
  });
}

function localDialogueRewriteLines(sourceLedger = [], nameMap = []) {
  const mappedNames = new Map(nameMap.map(item => [item.sourceName, item.newName]));
  return sourceLedger.map(item => ({
    sourceId: item.id,
    sourceName: item.speaker,
    speakerName: mappedNames.get(item.speaker) || item.speaker,
    tone: String(item.tone || "自然口语").trim(),
    scene: "",
    action: "按原稿事件顺序和人物关系自然表演",
    originalText: String(item.text || "").trim(),
    rewrittenText: String(item.text || "").trim(),
    similarity: 1
  }));
}

function dialogueRewriteBackgroundAnchors(sourceText, ledger = []) {
  const source = String(sourceText || "").replace(/\r/g, "");
  let offset = 0;
  return source
    .split("\n")
    .map((line, index) => {
      const start = offset;
      const end = start + line.length;
      offset = end + 1;
      return { line: line.trim(), index, start, end };
    })
    .filter(item => item.line && !ledger.some(turn => {
      const turnStart = Number(turn?.sourceStart);
      return Number.isFinite(turnStart) && turnStart >= item.start && turnStart <= item.end;
    }))
    .map(item => item.line)
    .filter(Boolean)
    .slice(0, 80);
}

function renderDialogueRewriteScript(sourceText, ledger, lines, nameMap) {
  const anchors = dialogueRewriteBackgroundAnchors(sourceText, ledger);
  const cast = nameMap.map(item => item.renamed
    ? `${item.newName}（原稿代号：${item.sourceName}）`
    : item.newName);
  const body = lines.map((line, index) => {
    const performance = [line.tone, line.action].map(value => String(value || "").trim()).filter(Boolean).join("；") || "自然口语";
    const scene = line.scene && (index === 0 || line.scene !== lines[index - 1]?.scene)
      ? `\n【场景】${line.scene}\n`
      : "";
    return `${scene}${line.speakerName}（${performance}）：${line.rewrittenText}`;
  }).join("\n");
  return [
    "# 完整对白轻改剧本",
    "",
    "【改写合同】人物名称可重构，措辞只做轻微口语化与少量衔接；故事事实、事件顺序、人物关系、结局和商品出现节点保持不变。",
    cast.length ? `【人物】${cast.join("、")}` : "",
    anchors.length ? `【原稿背景与情节锚点（原样保留）】\n${anchors.join("\n")}` : "",
    "",
    "【正文】",
    body
  ].filter(Boolean).join("\n").trim();
}

function qualityModuleForStage(stage = "") {
  const value = String(stage || "");
  if (value === "shot_video") return "videos";
  if (value.startsWith("storyboard_")) return "storyboards";
  if (value.startsWith("character_") || value === "scene_asset" || value.endsWith("_asset")) return "assets";
  return "script";
}

function isImageContentPolicyError(error) {
  const text = `${error?.code || ""} ${error?.message || ""}`;
  return /content policy|content_policy|safety filter|safety_violation|blocked by safety|moderation_blocked|moderation stage|image_generation_user_error|photorealistic faces|celebrity likeness|real person photos|copyrighted content|adult, violent|religiously sensitive/i.test(text);
}

function isTransientProviderError(error) {
  // A video POST may already have been accepted even when the HTTP response was
  // lost. Retrying that POST from the generic backoff loop can create a second
  // paid upstream task on servers that have not yet persisted the idempotency
  // record. Keep the stable clientRequestId/job as remote_pending and recover it
  // explicitly; do not treat an unknown submission response as an immediate
  // resubmission opportunity.
  if (error?.remoteSubmissionUnknown === true
    || String(error?.code || "") === "VIDEO_SUBMISSION_RESPONSE_UNKNOWN") return false;
  // An upstream response that explicitly says retryable=false is an
  // authoritative terminal decision even when a gateway wrapped it in 5xx.
  // Respecting it prevents an endless same-task poll loop and repeated spend.
  if (error?.retryable === false) return false;
  // An HTTP gateway status describes how the local bridge relayed the
  // rejection, not whether the provider decision is temporary. Authoritative
  // quota/auth/policy errors must win over a surrounding 5xx or the outer
  // unlimited recovery loop will hammer the provider forever.
  const terminalProviderCode = String(error?.code || "");
  if (/^(?:PROVIDER_DAILY_QUOTA_EXHAUSTED|H3_DAILY_QUOTA_EXHAUSTED|VIDEO_DAILY_QUOTA_EXHAUSTED|ACCOUNT_SWITCH_IN_PROGRESS|LICENSE_REQUIRED|LICENSE_EXPIRED|AUTH(?:ENTICATION)?_FAILED|INSUFFICIENT_(?:BALANCE|CREDIT)|CONTENT_POLICY|MODERATION_BLOCKED)$/i.test(terminalProviderCode)) return false;
  const providerCode = String(error?.code || "").trim().toUpperCase();
  if ([
    "MEDIA_UPLOAD_STALLED",
    "PUREAM_TEXT_STREAM_ERROR",
    "PUREAM_TRANSPORT_INTERRUPTED",
    "TEXT_RESULT_EMPTY"
  ].includes(providerCode)) return true;
  const text = `${error?.code || ""} ${error?.status || ""} ${error?.message || ""}`;
  return /502|503|504|429|408|500|SERVER_ERROR|PROVIDER_HTTP|PROVIDER_TIMEOUT|TIMEOUT|ECONNRESET|ETIMEDOUT|ENOTFOUND|EAI_AGAIN|socket hang up|fetch failed|network|VIDEO_REMOTE_PENDING|VIDEO_DOWNLOAD_PENDING|REMOTE_TASK_PENDING|BRIDGE_HTTP_ERROR|网关|超时|限流|繁忙|远端待恢复|稍后再试|Bad Gateway|Service Unavailable|Too Many Requests|Internal Server Error/i.test(text);
}

const NON_RETRYABLE_STORYBOARD_ERROR_PATTERN = /^(?:CONTINUITY_REFERENCE_REQUIRED|STORYBOARD_(?:PREVIOUS_END|CHARACTER|SCENE|WARDROBE|PROP)_REFERENCE_REQUIRED|IMAGE_REFERENCE_(?:URL_REQUIRED|LIMIT_EXCEEDED)|IMAGE_REFERENCE_PLATE_[A-Z_]+|PRODUCT_REFERENCE_REQUIRED|PUREAM_AUTH_REQUIRED|PUREAM_MANAGED_MEDIA_UPLOAD_FAILED|OSS_[A-Z_]+_REQUIRED|MEDIA_FILE_MISSING)$/i;

function isRetryableStoryboardFailure(failure = {}) {
  const code = String(failure.code || "").trim();
  if (NON_RETRYABLE_STORYBOARD_ERROR_PATTERN.test(code)) return false;
  return isTransientProviderError({
    code,
    status: Number(failure.status) || 0,
    message: String(failure.message || "")
  });
}

/** Retry transient upstream image failures with backoff; never swallow non-transient errors. */
async function withTransientProviderRetries(run, {
  attempts = UNLIMITED_ATTEMPTS,
  baseDelayMs = 2500,
  onRetry = null,
  label = "上游任务",
  signal = null
} = {}) {
  let lastError = null;
  const maxAttempts = resolveAttemptLimit(attempts, UNLIMITED_ATTEMPTS);
  for (let attempt = 1; attempt <= maxAttempts; attempt += 1) {
    try {
      return await run(attempt);
    } catch (error) {
      lastError = error;
      if (!isTransientProviderError(error) || attempt === maxAttempts) throw error;
      if (typeof onRetry === "function") {
        await onRetry(error, attempt, attemptLimitLabel(maxAttempts));
      }
      await abortableDelay(Math.min(30_000, baseDelayMs * attempt), signal);
    }
  }
  throw lastError || Object.assign(new Error(`${label}重试耗尽`), { code: "PROVIDER_RETRY_EXHAUSTED" });
}

/** Strip drama/genre slogans that trip GPT Image face safety filters on character sheets. */
function stripDramaStyleSlogans(text = "") {
  return String(text || "")
    .replace(/写实影视短剧|写实真人影视短剧|写实影视级|写实影视|真人影视短剧|短剧角色|全剧视觉基准|全剧视觉基调/g, "")
    .replace(/现代中国生活质感，真实皮肤与布料，表演克制自然，有动机的电影光，清晰主体层次，竖屏安全构图，人物、服装、场景、道具和商品跨镜一致/g, "")
    .replace(/校服|学生装|中学校服/g, "日常休闲外套与长裤")
    .replace(/\s{2,}/g, " ")
    .trim();
}

function imageSafetyStageContract(stage = "", language = "zh") {
  const key = String(stage || "").trim();
  const english = {
    character_sheet: "Create one fictional adult character reference board on a clean neutral background. Preserve the requested age, face, hair, body and complete wardrobe; no celebrity likeness, real-person claim, brand, text or sensitive content.",
    character_three_view: "Create one fictional adult character turn-around board on a clean neutral background. Preserve one identity and one complete wardrobe; no celebrity likeness, real-person claim, brand, text or sensitive content.",
    character_intro: "Create one fictional adult character portrait on a seamless neutral background. Center the face, keep both eyes visible and the head within 15 degrees of frontal; no celebrity likeness, real-person claim, brand, text or sensitive content.",
    scene_asset: "Create one 16:9 image containing an exact 2-by-2 four-angle empty-scene reference board: front master, reverse axis, left 45-degree and right 45-degree views of the same coherent fictional space. Preserve identical doors, windows, walls, furniture topology, entrances, time of day and light direction across all four panels; no people, labels, text, brand or sensitive content.",
    storyboard_start: "Create one fictional live-action opening frame for the current shot. Preserve supplied identities, complete wardrobes, scene topology, screen axis and prop states; show the action before it happens; no collage, reference board, text, brand or sensitive content.",
    storyboard_end: "Create one fictional live-action ending frame for the current shot. Preserve supplied identities, complete wardrobes, scene topology, screen axis and prop states; show the stable result after the action; no collage, reference board, text, brand or sensitive content.",
    storyboard_sheet: "Create one fictional chronological contact sheet for the current shot. Every individual panel is a complete portrait 9:16 live-action frame inside the locked drama location; tile the exact requested panel count left-to-right, top-to-bottom with narrow gutters. If a product appears, place it in that same room, never a white studio, catalog backdrop, e-commerce model shot or packaging still-life. Preserve supplied identities, wardrobes, scene topology, prop continuity and panel order; no design-board layout, extra person, text, brand or sensitive content.",
    wardrobe_asset: "Create one fictional wardrobe reference board for the assigned adult character. Preserve that character identity and show the complete requested garment clearly; no unrelated person, brand, text or sensitive content.",
    prop_asset: "Create one fictional single-prop reference image showing the requested shape, material, quantity and state clearly; no person, brand, text or sensitive content."
  };
  const chinese = {
    character_sheet: "只生成一张成年虚构角色设定板：中性干净背景，锁定年龄、脸、发型、体型和整套服装；不得影射名人或真人，不得出现品牌、文字和敏感内容。",
    character_three_view: "只生成一张成年虚构角色转面设定板：同一身份、同一整套服装、中性干净背景；不得影射名人或真人，不得出现品牌、文字和敏感内容。",
    character_intro: "只生成一张成年虚构角色独立正脸肖像：无缝中性背景、脸在视觉中心、双眼清楚、头部偏转不超过15度；不得影射名人或真人，不得出现品牌、文字和敏感内容。",
    scene_asset: "只生成一张16:9、严格2×2分割的无人场景四视图：左上主入口正向、右上反向轴、左下左侧45度、右下右侧45度；四格必须是同一空间、同一门窗家具拓扑、同一时段和光向。禁止人物、标签、文字、品牌和敏感内容。",
    storyboard_start: "只生成本镜一张动作发生前的电影首帧：严格保留参考人物身份、整套服装、场景拓扑、轴线和道具状态；禁止拼贴、设定板、文字、品牌和敏感内容。",
    storyboard_end: "只生成本镜一张动作完成后的电影尾帧：严格保留参考人物身份、整套服装、场景拓扑、轴线和道具状态；禁止拼贴、设定板、文字、品牌和敏感内容。",
    storyboard_sheet: "只生成本镜一张逐时接触印合图：每个独立小格必须是完整9:16竖屏剧情画面，发生在已锁定的戏剧场景里，按从左到右、从上到下拼接；若有商品，必须放在该场景中使用，禁止电商白底、棚拍、模特展示图或包装静物；格数与时间顺序必须准确，人物、服装、场景和道具连续；画面内严禁任何字幕、对白文字、气泡、标题、旁白文字、可读标签、Logo、水印、序号、格线或UI，台词只能通过人物口型、表情和动作呈现；禁止设定板、额外人物、文字、品牌和敏感内容。",
    wardrobe_asset: "只生成指定成年角色的一张服装资产图：锁定该角色身份并清楚展示整套指定服装；禁止无关人物、品牌、文字和敏感内容。",
    prop_asset: "只生成一张单一道具资产图：准确展示指定外形、材质、数量和状态；禁止人物、品牌、文字和敏感内容。"
  };
  const fallback = language === "en"
    ? "Create one fictional production reference image for the requested stage; preserve supplied continuity references and omit real-person claims, brands, text and sensitive content."
    : "只生成当前阶段所需的一张虚构制作参考图；保留所有已给连续性参考，删除真人影射、品牌、文字和敏感内容。";
  return (language === "en" ? english[key] : chinese[key]) || fallback;
}

/** Stage-aware rewrite when the image provider blocks unsafe wording. */
function sanitizePromptAgainstSafetyFilters(prompt, attempt = 1, stage = "") {
  let next = String(prompt || "");
  next = next
    .replace(/为写实影视短剧角色|写实影视短剧角色|写实影视短剧|写实真人影视短剧|写实影视级|写实影视剧质感|写实面孔|真人面孔|真人照片|真实照片|证件照|自拍|网红脸|明星脸|名人脸|明星|名人|photorealistic|live-action cinematic|celebrity|real[\s-]?person|photorealistic\s+faces?/gi, "虚构角色")
    .replace(/全剧视觉基准[：:].*/g, "")
    .replace(/全剧视觉基调[：:].*/g, "")
    .replace(/校服|学生装|中学校服/g, "日常休闲外套与长裤")
    .replace(/Logo|商标|品牌标识|版权角色|IP角色/gi, "无品牌素面道具")
    .replace(/政治|宗教|血腥|色情|暴力|敏感/g, "日常");
  if (/^storyboard_(?:sheet|start|end)$/.test(String(stage || ""))) {
    next = next
      .replace(/跪行(?:到|向)?/g, "缓慢走近")
      .replace(/跪地|跪着|跪姿/g, "站在一旁")
      .replace(/磕头|额头触地|额头落地|额头向下落/g, "深深鞠躬致歉")
      .replace(/红指甲按地前行|红指甲按地|双手按地|按地前行/g, "双手交叠在身前")
      .replace(/按地/g, "交叠双手")
      .replace(/脚边/g, "面前")
      .replace(/膝盖挪地/g, "衣料轻擦声")
      .replace(/低机位跪地|跪地近景|磕头特写|低机位跪地动作/g, "平视站立中景")
      .replace(/痛哭|哭求|服从|哭着|崩塌|敌对/g, "真诚致歉")
      .replace(/用力把她扶起|用力扶起/g, "温和扶住手臂")
      .replace(/真人、真实场景|真人|真实场景/g, "虚构成年影视角色、虚构室内场景")
      .replace(/额头/g, "视线");
  }
  if (attempt === 1) {
    next += `\n\n【安全改写·自动】${imageSafetyStageContract(stage, "zh")}`;
  } else if (attempt >= 2) {
    next = [
      imageSafetyStageContract(stage, "en"),
      "No celebrity likeness, no real-person photo, no school uniform for minors, no brand logos, no NSFW/violence/politics/religion.",
      "Keep every supplied continuity reference and the requested production-stage output form.",
      next.slice(0, 1800)
    ].join("\n");
  }
  return next.trim();
}

function skippedQualityAudit(type = "disabled") {
  return {
    ok: null, status: "not_verified",
    skipped: true,
    mode: "disabled",
    type,
    checkedAt: new Date().toISOString(),
    failures: [],
    note: "尚未执行质量审核；跳过不代表通过"
  };
}

function qualityAccepted(candidate, settings = null) {
  if (!candidate?.filePath) return false;
  if (!isQualityGatesEnabled(settings, qualityModuleForStage(candidate.stage))) return true;
  return candidate.manualSelectionOverride === true
    || candidate.qualityAudit?.ok === true
    || candidate.qualityAudit?.accepted === true
    || candidate.qualityAudit?.overridden === true
    || ["manual", "human_override", "advisory_continue"].includes(String(candidate.qualityAudit?.mode || ""));
}

const QUALITY_ADVISORY_ERROR_CODES = new Set([
  "PRODUCTION_HARD_CONTRACT_FAILED",
  "SCRIPT_BLUEPRINT_SEMANTIC_REVIEW_FAILED",
  "SCRIPT_SEMANTIC_REVIEW_FAILED",
  "SCRIPT_REFERENCE_SPEC_FAILED",
  "SCENE_EMPTY_RETRY_EXHAUSTED",
  "CHARACTER_INTRO_QUALITY_RETRY_EXHAUSTED",
  "STORYBOARD_QUALITY_RETRY_EXHAUSTED",
  "CHARACTER_VIDEO_QUALITY_RETRY_EXHAUSTED",
  "SHOT_QUALITY_RETRY_EXHAUSTED",
  "PROJECT_MEDIA_QUALITY_FAILED",
  "FINAL_MEDIA_QUALITY_FAILED",
  "CANDIDATE_QUALITY_FAILED",
  "SHOT_VIDEO_QUALITY_REQUIRED",
  "CHARACTER_VIDEO_QUALITY_REQUIRED"
]);

function qualityWarningCanBeIgnored(code = "") {
  return QUALITY_ADVISORY_ERROR_CODES.has(String(code || "").trim().toUpperCase());
}

function ignoredQualityAudit(audit = null, details = {}) {
  const original = audit && typeof audit === "object" ? JSON.parse(JSON.stringify(audit)) : { ok: null, failures: [] };
  return {
    ...original,
    ok: true,
    verdict: "ignored",
    accepted: true,
    overridden: true,
    mode: "human_override",
    overriddenAt: new Date().toISOString(),
    originalOk: original.ok,
    originalFailures: Array.isArray(original.failures) ? original.failures : [],
    failures: [],
    note: details.note || "用户已查看质检提醒，并人工确认忽略后继续使用原结果"
  };
}

function advisoryQualityAudit(audit = null, details = {}) {
  const original = audit && typeof audit === "object" ? audit : { ok: true, failures: [] };
  if (original.ok !== false) return original;
  return {
    ...original,
    advisory: true,
    blocking: false,
    verdict: original.verdict || "review",
    advisoryAt: new Date().toISOString(),
    note: details.note || "质检发现可优化项；当前内容已保留，可选择 AI 修复或人工忽略后继续"
  };
}

function fileSha256(filePath) {
  if (!filePath || !fs.existsSync(filePath)) return "";
  return crypto.createHash("sha256").update(fs.readFileSync(filePath)).digest("hex");
}

const VIDEO_REFERENCE_HASH_CACHE = new Map();

async function fileSha256Async(filePath) {
  const normalizedPath = String(filePath || "");
  if (!normalizedPath) return "";
  let stat;
  try {
    // Electron's Windows main process can leave fs.promises stat/readFile
    // unresolved when a headless production runner exits its launcher while
    // the app process stays alive.  That deadlocks before a durable video job
    // or upstream task id exists.  Reference files are bounded by the H3 input
    // contract, so one synchronous read per immutable stat key is both fast and
    // deterministic; the shared cache prevents repeated reads across shots.
    stat = fs.statSync(normalizedPath);
  } catch (error) {
    if (error?.code === "ENOENT") return "";
    throw error;
  }
  if (!stat.isFile()) return "";

  // Electron main-process batches used to hash every reference through a
  // createReadStream.  When several character videos entered this boundary at
  // once on Windows, the streams could remain open without ever emitting
  // `end`, leaving the project looking "in progress" even though no paid H3
  // task had been created.  A stat-keyed shared promise gives concurrent calls
  // one deterministic read and also prevents the same immutable reference from
  // being re-read for every shot.  Rejections are evicted so a transient local
  // file error remains recoverable.
  const cacheKey = `${path.resolve(normalizedPath)}|${stat.size}|${stat.mtimeMs}`;
  let digest = VIDEO_REFERENCE_HASH_CACHE.get(cacheKey);
  if (!digest) {
    digest = crypto.createHash("sha256").update(fs.readFileSync(normalizedPath)).digest("hex");
    VIDEO_REFERENCE_HASH_CACHE.set(cacheKey, digest);
  }
  return digest;
}

function stableRemoteReferenceIdentity(value) {
  const raw = String(value || "").trim();
  if (!raw) return "";
  try {
    const parsed = new URL(raw);
    if (!/^https?:$/i.test(parsed.protocol)) return "";
    return `${parsed.protocol}//${parsed.host}${parsed.pathname}`;
  } catch {
    return "";
  }
}

function stableVideoFingerprintValue(value) {
  if (Array.isArray(value)) return value.map(stableVideoFingerprintValue);
  if (!value || typeof value !== "object") {
    return /^https?:\/\//i.test(String(value || "")) ? stableRemoteReferenceIdentity(value) : value;
  }
  const output = {};
  for (const [key, entry] of Object.entries(value)) {
    if (/(?:^|_)(?:remote)?url$|(?:^|_)(?:file)?path$|signed|expires?|signature|authorization|api[_-]?key|token/i.test(key)) continue;
    output[key] = stableVideoFingerprintValue(entry);
  }
  return output;
}

async function videoSubmissionFingerprint(project, providerKind, entityType, entityId, stage, prompt, references = {}, duration = 0, hailuoApiMode = "", cloudVideoResolution = "480") {
  const videos = Array.isArray(references.videos) ? references.videos : references.video ? [references.video] : [];
  const hashCache = new Map();
  const hashFile = filePath => {
    const key = String(filePath || "");
    if (!hashCache.has(key)) hashCache.set(key, fileSha256Async(key));
    return hashCache.get(key);
  };
  const payload = {
    projectId: String(project?.id || ""),
    productionRevision: String(project?.productionRevision || ""),
    providerKind: String(providerKind || ""),
    entityType: String(entityType || ""),
    entityId: String(entityId || ""),
    stage: String(stage || ""),
    promptSha256: crypto.createHash("sha256").update(String(prompt || "")).digest("hex"),
    duration: Number(duration) || 0,
    aspectRatio: String(references.aspectRatio || project?.generation?.aspectRatio || ""),
    hailuoApiMode: String(hailuoApiMode || ""),
    cloudVideoResolution: normalizeCloudVideoResolution(cloudVideoResolution),
    // A transport retry must keep this empty so it resolves to the exact same
    // paid task.  An explicit user reroll (or a terminal not-charged repair)
    // supplies a new nonce so the provider is allowed to create one new task
    // instead of returning a previously failed idempotency record forever.
    rerollNonce: String(references.rerollNonce || ""),
    images: await Promise.all((references.images || []).map(async (filePath, index) => ({
      sha256: await hashFile(filePath),
      remoteObject: stableRemoteReferenceIdentity(references.imageRoles?.[index]?.remoteUrl),
      role: stableVideoFingerprintValue(references.imageRoles?.[index] || null)
    }))),
    videos: await Promise.all(videos.map(async (item, index) => ({
      sha256: await hashFile(item?.path),
      remoteObject: stableRemoteReferenceIdentity(item?.remoteUrl),
      duration: Number(item?.duration) || 0,
      role: stableVideoFingerprintValue(references.videoRoles?.[index] || null)
    }))),
    videoAudios: await Promise.all((references.videoAudios || []).map(async item => item ? ({
      sha256: await hashFile(item.path),
      remoteObject: stableRemoteReferenceIdentity(item.remoteUrl),
      duration: Number(item.duration) || 0
    }) : null)),
    audios: await Promise.all((references.audios || []).map(async item => ({
      sha256: await hashFile(item?.path),
      remoteObject: stableRemoteReferenceIdentity(item?.remoteUrl),
      duration: Number(item?.duration) || 0,
      characterId: String(item?.characterId || "")
    }))),
    agentGenerationBlock: stableVideoFingerprintValue(references.agentGenerationBlock || null),
    agentTake: stableVideoFingerprintValue(references.agentTake || null)
  };
  return crypto.createHash("sha256").update(JSON.stringify(payload)).digest("hex");
}

function upstreamVideoSubmissionState(job) {
  if (!job || typeof job !== "object") return "";
  if (job.taskId || job.providerTaskId) return "created";
  const explicit = String(job.upstreamSubmissionState || "").trim().toLowerCase();
  if (["not_started", "preparing", "submitting", "not_created", "unknown", "created"].includes(explicit)) return explicit;
  const code = String(job.errorCode || "").trim().toUpperCase();
  if (["VIDEO_SUBMISSION_RESPONSE_UNKNOWN", "VIDEO_SUBMISSION_RECOVERY_REQUIRED"].includes(code)
    || job.remoteSubmissionUnknown === true) return "unknown";
  if (job.noRemoteTaskCreated === true) return "not_created";
  return "";
}

function hasCreatedUpstreamVideoTask(job) {
  return upstreamVideoSubmissionState(job) === "created";
}

function canRecoverVideoSubmissionWithSameKey(job) {
  if (!job || hasCreatedUpstreamVideoTask(job)) return false;
  return Boolean(String(job.clientRequestId || "").trim()
    && String(job.submissionFingerprint || "").trim());
}

function wasPrematurelyAbandonedExactlyOnceJob(job) {
  if (!job || String(job.errorCode || "") !== "VIDEO_JOB_ABANDONED") return false;
  if (job.exactlyOnceSubmission !== true || !canRecoverVideoSubmissionWithSameKey(job)) return false;
  const createdAt = Date.parse(job.createdAt || "");
  const abandonedAt = Date.parse(job.updatedAt || "");
  if (!Number.isFinite(createdAt) || !Number.isFinite(abandonedAt) || abandonedAt < createdAt) return false;
  return abandonedAt - createdAt < VIDEO_SUBMISSION_PHANTOM_AFTER_MS;
}

function isRecoverableVideoBatchError(error) {
  const code = String(error?.code || "");
  return error?.remoteGenerationCompleted === true
    || error?.remoteSubmissionUnknown === true
    || error?.remoteGenerationPending === true
    || (error?.retryable === true && error?.noRemoteTaskCreated === true)
    || [
      "VIDEO_SUBMISSION_RESPONSE_UNKNOWN", "VIDEO_REMOTE_PENDING", "VIDEO_POLL_TIMEOUT",
      "PROVIDER_QUARANTINED", "REFERENCE_MEDIA_UPLOAD_RETRYABLE", "BRIDGE_NETWORK_ERROR",
      "BRIDGE_REQUEST_TIMEOUT", "REMOTE_VIDEO_DOWNLOAD_RETRYABLE"
    ].includes(code)
    || /(?:QUARANTINED|ISOLATED)$/i.test(code);
}

async function executeShotVideoBatch(shots, runShot, concurrency = VIDEO_BATCH_MAX_CONCURRENCY, onProgress = () => {}) {
  const orderedShots = Array.isArray(shots) ? shots : [];
  const results = new Array(orderedShots.length);
  const batchFailures = [];
  const recoverablePending = [];
  let cursor = 0;
  let controlError = null;
  const worker = async () => {
    while (!controlError && cursor < orderedShots.length) {
      const index = cursor++;
      const shot = orderedShots[index];
      try {
        results[index] = await runShot(shot, index);
      } catch (error) {
        // Pause/stop is a single user control signal, never a failure for every
        // remaining shot in the batch.  Let sibling workers settle, then return
        // the control signal once so the tracked operation can save a clean
        // resumable checkpoint without a red batch-failure cascade.
        if (isPipelineControlError(error)) {
          controlError ||= error;
          results[index] = null;
          break;
        }
        const record = {
          shotId: shot?.id || "",
          shotNumber: Number(shot?.number) || index + 1,
          code: error?.code || "SHOT_VIDEO_FAILED",
          message: sanitizePublicMessage(error?.message || String(error), error?.code || "SHOT_VIDEO_FAILED")
        };
        if (isRecoverableVideoBatchError(error)) recoverablePending.push(record);
        else batchFailures.push(record);
        results[index] = null;
      } finally {
        await onProgress({shotId:shot?.id,index,completed:results.filter(Boolean).length,failures:[...batchFailures],pending:[...recoverablePending],total:orderedShots.length});
      }
    }
  };
  // The authenticated admin session is the concurrency authority.  The caller
  // passes that limit for paid video submissions; the legacy constant is only
  // a safe fallback for local/dev callers that have no license client.
  const workerCount = Math.max(1, Math.min(
    orderedShots.length || 1,
    Math.floor(Number(concurrency) || VIDEO_BATCH_MAX_CONCURRENCY)
  ));
  await Promise.all(Array.from({ length: workerCount }, worker));
  if (controlError) throw controlError;
  return { results, batchFailures, recoverablePending };
}

function fileIdentity(filePath) {
  try {
    const stat = fs.statSync(filePath);
    return { path: String(filePath || ""), size: stat.size, mtimeMs: Math.round(stat.mtimeMs) };
  } catch {
    return { path: String(filePath || ""), missing: true };
  }
}

function stitchInputFingerprint(project, videos = []) {
  const voices = (project.characters || []).map(character => {
    const candidate = selectedOrLatest(project, "character", character.id, "character_voice");
    return { characterId: character.id, candidateId: candidate?.id || "", file: fileIdentity(candidate?.filePath), duration: candidate?.duration || 0 };
  });
  const payload = {
    productionRevision: project.productionRevision || "",
    generation: project.generation || {},
    shots: project.shots || [],
    voices,
    videos: videos.map(candidate => ({
      id: candidate?.id || "",
      entityId: candidate?.entityId || "",
      taskId: candidate?.taskId || "",
      updatedAt: candidate?.updatedAt || candidate?.createdAt || "",
      file: fileIdentity(candidate?.filePath),
      referenceManifest: candidate?.referenceManifest || null,
      stale: candidate?.stale === true
    }))
  };
  return crypto.createHash("sha256").update(JSON.stringify(payload)).digest("hex");
}

function wavDurationSeconds(buffer, fileSize = buffer?.length || 0) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 44 || buffer.toString("ascii", 0, 4) !== "RIFF" || buffer.toString("ascii", 8, 12) !== "WAVE") return null;
  let offset = 12;
  let byteRate = 0;
  let dataBytes = 0;
  while (offset + 8 <= buffer.length) {
    const chunkId = buffer.toString("ascii", offset, offset + 4);
    const chunkSize = buffer.readUInt32LE(offset + 4);
    const dataStart = offset + 8;
    if (chunkId === "fmt " && chunkSize >= 16 && dataStart + 12 <= buffer.length) byteRate = buffer.readUInt32LE(dataStart + 8);
    if (chunkId === "data") {
      dataBytes = Math.min(chunkSize, Math.max(0, fileSize - dataStart));
      break;
    }
    offset = dataStart + chunkSize + (chunkSize % 2);
  }
  return byteRate > 0 && dataBytes > 0 ? dataBytes / byteRate : null;
}

function wavSignalAudit(buffer) {
  if (!Buffer.isBuffer(buffer) || buffer.length < 44) return { checkable: false, ok: false };
  let offset = 12;
  let formatTag = 0;
  let channels = 0;
  let sampleRate = 0;
  let byteRate = 0;
  let blockAlign = 0;
  let bitsPerSample = 0;
  let dataStart = -1;
  let dataBytes = 0;
  while (offset + 8 <= buffer.length) {
    const chunkId = buffer.toString("ascii", offset, offset + 4);
    const chunkSize = buffer.readUInt32LE(offset + 4);
    const chunkStart = offset + 8;
    if (chunkId === "fmt " && chunkSize >= 16 && chunkStart + 16 <= buffer.length) {
      formatTag = buffer.readUInt16LE(chunkStart);
      channels = buffer.readUInt16LE(chunkStart + 2);
      sampleRate = buffer.readUInt32LE(chunkStart + 4);
      byteRate = buffer.readUInt32LE(chunkStart + 8);
      blockAlign = buffer.readUInt16LE(chunkStart + 12);
      bitsPerSample = buffer.readUInt16LE(chunkStart + 14);
    }
    if (chunkId === "data") {
      dataStart = chunkStart;
      dataBytes = Math.min(chunkSize, Math.max(0, buffer.length - chunkStart));
      break;
    }
    offset = chunkStart + chunkSize + (chunkSize % 2);
  }
  const validFormat = (formatTag === 1 && [8, 16, 24, 32].includes(bitsPerSample)) || (formatTag === 3 && bitsPerSample === 32);
  const expectedBlockAlign = channels * bitsPerSample / 8;
  const validLayout = channels >= 1 && channels <= 2
    && sampleRate >= 8000 && sampleRate <= 192000
    && blockAlign === expectedBlockAlign
    && byteRate === sampleRate * blockAlign;
  if (dataStart < 0 || dataBytes <= 0 || !validFormat || !validLayout) {
    return { checkable: false, ok: false, formatTag, channels, sampleRate, byteRate, blockAlign, bitsPerSample };
  }
  const bytesPerSample = bitsPerSample / 8;
  const sampleCount = Math.floor(dataBytes / bytesPerSample);
  const stride = Math.max(1, Math.floor(sampleCount / 50_000));
  let checked = 0;
  let nonSilent = 0;
  let peak = 0;
  for (let sampleIndex = 0; sampleIndex < sampleCount; sampleIndex += stride) {
    const position = dataStart + sampleIndex * bytesPerSample;
    if (position + bytesPerSample > buffer.length) break;
    let normalized = 0;
    if (formatTag === 3 && bitsPerSample === 32) normalized = Math.abs(buffer.readFloatLE(position));
    else if (bitsPerSample === 8) normalized = Math.abs(buffer.readUInt8(position) - 128) / 128;
    else if (bitsPerSample === 16) normalized = Math.abs(buffer.readInt16LE(position)) / 32768;
    else if (bitsPerSample === 24) normalized = Math.abs(buffer.readIntLE(position, 3)) / 8388608;
    else normalized = Math.abs(buffer.readInt32LE(position)) / 2147483648;
    checked += 1;
    peak = Math.max(peak, normalized);
    if (normalized >= 0.001) nonSilent += 1;
  }
  const nonSilentRatio = checked ? nonSilent / checked : 0;
  return { checkable: true, ok: checked > 0 && peak >= 0.001 && nonSilentRatio >= 0.001, checked, peak, nonSilentRatio };
}

function audioReferenceAudit(audio = {}) {
  const filePath = String(audio.path || audio.filePath || "").trim();
  const declaredDuration = Number(audio.duration);
  if (!filePath || !fs.existsSync(filePath)) return { ok: false, code: "AUDIO_FILE_MISSING", message: "音色文件不存在" };
  if (!Number.isFinite(declaredDuration) || declaredDuration <= 0 || declaredDuration > 15) {
    return { ok: false, code: "AUDIO_DURATION_INVALID", message: `音色时长必须大于0且不超过15秒，当前${audio.duration ?? "未填写"}` };
  }
  let buffer;
  let fileSize = 0;
  try {
    fileSize = fs.statSync(filePath).size;
    if (fileSize < 16) return { ok: false, code: "AUDIO_FILE_INVALID", message: "音色文件过小或为空" };
    const fd = fs.openSync(filePath, "r");
    try {
      buffer = Buffer.alloc(Math.min(fileSize, 1024 * 1024));
      fs.readSync(fd, buffer, 0, buffer.length, 0);
    } finally {
      fs.closeSync(fd);
    }
  } catch (error) {
    return { ok: false, code: "AUDIO_FILE_UNREADABLE", message: error?.message || "音色文件无法读取" };
  }
  const ascii4 = buffer.toString("ascii", 0, 4);
  const isWav = ascii4 === "RIFF" && buffer.toString("ascii", 8, 12) === "WAVE";
  const isMp3 = buffer.toString("ascii", 0, 3) === "ID3" || (buffer[0] === 0xff && (buffer[1] & 0xe0) === 0xe0);
  const isMp4Audio = buffer.toString("ascii", 4, 8) === "ftyp";
  const isOgg = ascii4 === "OggS";
  const isFlac = ascii4 === "fLaC";
  const isWebm = buffer.length >= 4 && buffer.subarray(0, 4).equals(Buffer.from([0x1a, 0x45, 0xdf, 0xa3]));
  if (!isWav && !isMp3 && !isMp4Audio && !isOgg && !isFlac && !isWebm) {
    return { ok: false, code: "AUDIO_CONTAINER_INVALID", message: "音色文件不是可识别的 WAV/MP3/M4A/OGG/FLAC/WebM 音频" };
  }
  if (!isWav && audio.mediaProbeVerified !== true) {
    return { ok: false, code: "AUDIO_DECODE_AUDIT_REQUIRED", message: "非 WAV 音色必须先经过本地解码与时长验证" };
  }
  let actualDuration = null;
  if (isWav) {
    actualDuration = wavDurationSeconds(buffer, fileSize);
    if (!Number.isFinite(actualDuration) || actualDuration <= 0 || actualDuration > 15.05) {
      return { ok: false, code: "AUDIO_DURATION_INVALID", message: `WAV 实际时长必须大于0且不超过15秒，当前${Number.isFinite(actualDuration) ? actualDuration.toFixed(2) : "无法读取"}秒` };
    }
    const signal = wavSignalAudit(buffer);
    if (!signal.ok) {
      return signal.checkable
        ? { ok: false, code: "AUDIO_SILENT", message: "WAV 音色没有检测到有效人声采样，不能作为说话人参考" }
        : { ok: false, code: "AUDIO_CONTAINER_INVALID", message: "WAV 音色不是可解码的 PCM/IEEE Float 采样" };
    }
  }
  return { ok: true, declaredDuration, duration: Number.isFinite(actualDuration) ? actualDuration : declaredDuration, container: isWav ? "wav" : isMp3 ? "mp3" : isMp4Audio ? "mp4-audio" : isOgg ? "ogg" : isFlac ? "flac" : "webm" };
}

function assertShotReferenceBundle(project, shot, mode, references, previousVideo, settings = null) {
  const activeRevision = project.productionRevision || "";
  const gatesOn = isQualityGatesEnabled(settings);
  const images = Array.isArray(references?.images) ? references.images : [];
  const roles = Array.isArray(references?.imageRoles) ? references.imageRoles : [];
  const fail = (message, code = "SHOT_REFERENCE_LINEAGE_INVALID") => {
    throw Object.assign(new Error(message), { code, shotId: shot.id });
  };
  if (images.length !== roles.length) fail("分镜参考图与参考角色清单数量不一致");
  if (images.length > 9) fail("分镜参考图超过当前视频引擎 9 图上限", "IMAGE_COUNT_INVALID");
  const h3ApiMode = projectVideoEngine(project) === "hailuo-h3" ? normalizeHailuoApiMode(references?.hailuoApiMode) : "";
  if (h3ApiMode === "image_to_video") {
    const ordinaryFirstLast = images.length === 2
      && roles[0]?.type === "storyboard_start"
      && roles[1]?.type === "storyboard_end";
    if (!ordinaryFirstLast) {
      fail("海螺 image_to_video 只允许图1=剧情首帧、图2=剧情尾帧；人物、场景、商品等独立资产必须使用 reference_to_video", "HAILUO_FIRST_LAST_ROLE_INVALID");
    }
  }
  if (h3ApiMode === "reference_to_video") {
    if (!images.length) fail("海螺 reference_to_video 至少需要一张整段参考图", "HAILUO_REFERENCE_IMAGE_REQUIRED");
    const temporal = roles.find(role => ["storyboard_start", "storyboard_end"].includes(String(role?.type || "")));
    if (temporal) fail("reference_to_video 不能混入首帧或尾帧角色；官方规定 reference_image 与 first_frame/last_frame 互斥", "HAILUO_REFERENCE_AND_FRAME_ROLE_MIXED");
  }
  const shotStrategy = resolveShotVideoStrategy({ ...project, generation: { ...(project.generation || {}), mode } }, shot);
  const frameStages = shotStrategy.frameStages;
  const requiresImageAnchors = projectVideoEngine(project) === "hailuo-h3"
    || shotStrategy.strategy === "keyframe"
    || mode === "keyframe"
    || h3ApiMode === "image_to_video"
    || h3ApiMode === "multimodal_to_video"
    || (h3ApiMode === "auto" && images.length > 0)
    || ((mode === "continuation" || mode === "smart" || shotStrategy.strategy === "continuation") && frameStages.includes("storyboard_end") && images.length > 0);
  // asset_direct and production_package intentionally have no generated
  // temporal-frame role. Their locked references are validated below by
  // lineage instead of being misclassified as a missing end frame.
  if (requiresImageAnchors && !skipsGeneratedStoryboards(shotStrategy.strategy)) {
    if (frameStages.includes("storyboard_sheet")) {
      if (!["storyboard_sheet", "storyboard_take_sheet", "storyboard_panel_anchor", "storyboard_timeline_panel"].includes(String(roles[0]?.type || ""))) {
        fail("逐秒合图模式：图1必须是本镜由多个完整9:16竖屏画格拼成的逐秒分镜合图", "SHOT_FRAME_ANCHORS_REQUIRED");
      }
      if (roles[0]?.entityId && roles[0].entityId !== shot.id) fail("图1逐秒合图必须属于本镜，不能串用其他镜头帧");
    } else if (frameStages.includes("storyboard_start")) {
      if (roles[0]?.type !== "storyboard_start" || roles[1]?.type !== "storyboard_end") {
        fail("图1必须是本镜首帧、图2必须是本镜尾帧；人物素材不得占用首帧锚点", "SHOT_FRAME_ANCHORS_REQUIRED");
      }
      if (roles[0]?.entityId && roles[0].entityId !== shot.id) fail("图1首帧必须属于本镜，不能串用其他镜头帧");
      if (roles[1]?.entityId && roles[1].entityId !== shot.id) fail("图2尾帧必须属于本镜，不能串用其他镜头帧");
    } else if (roles[0]?.type !== "storyboard_end") {
      fail("同场景延续：图1必须是本镜尾帧目标；时间起点由上一镜完整视频提供，不再单独生成首帧", "SHOT_FRAME_ANCHORS_REQUIRED");
    } else if (roles[0]?.entityId && roles[0].entityId !== shot.id) {
      fail("延续模式图1尾帧必须属于本镜，不能串用其他镜头帧");
    }
  }
  const seen = new Set();
  roles.forEach((role, index) => {
    if (!role || role.path !== images[index]) fail(`图${index + 1}的路径与资产角色不一致`);
    if (!path.isAbsolute(role.path) || !fs.existsSync(role.path)) fail(`图${index + 1}素材文件不存在`, "MEDIA_FILE_MISSING");
    if (seen.has(role.path)) fail(`图${index + 1}重复引用了同一个文件`);
    seen.add(role.path);
    if (["character_three_view", "character_sheet"].includes(role.sourceStage)
      && !(role.type === "character" && role.identityOnly === true)) {
      fail(`图${index + 1}直接引用人物设定板，可能被模型误当成成片画面`, "CHARACTER_SHEET_VIDEO_REFERENCE_FORBIDDEN");
    }
    if (!role.candidateId) return;
    const candidate = project.candidates.find(item => item.id === role.candidateId);
    if (!candidate) fail(`图${index + 1}引用的候选资产不存在`);
    const isSanitizedStoryboardDerivative = ["storyboard_take_sheet", "storyboard_panel_anchor", "storyboard_timeline_panel"].includes(String(role.type || ""));
    const candidatePathMatches = candidate.filePath === role.path
      || (isSanitizedStoryboardDerivative
        && Boolean(role.parentFilePath)
        && candidate.filePath === role.parentFilePath);
    if (!candidatePathMatches
      || candidate.stage !== role.sourceStage
      || candidate.entityType !== role.entityType
      || candidate.entityId !== role.entityId) {
      fail(`图${index + 1}的候选资产归属与实际文件不一致`);
    }
    if ((candidate.productionRevision || "") !== activeRevision) {
      fail(`图${index + 1}来自旧制作版本，不能进入当前视频任务`, "ARCHIVED_REFERENCE_FORBIDDEN");
    }
    if (gatesOn && candidate.qualityAudit?.ok === false) fail(`图${index + 1}未通过资产质检`, "REFERENCE_QUALITY_FAILED");
  });
  const requiresPreviousVideo = shotStrategy.usePreviousVideo;
  if (requiresPreviousVideo) {
    if (!previousVideo?.path) fail("延续模式缺少上一镜已确认视频", "PREVIOUS_SHOT_REQUIRED");
    if (!path.isAbsolute(previousVideo.path) || !fs.existsSync(previousVideo.path)) fail("上一镜视频文件不存在", "PREVIOUS_SHOT_REQUIRED");
  }
  return true;
}

function assertProjectGenerationMode(project, requestedMode = "") {
  const confirmedMode = normalizeProjectMode(project?.generation?.mode);
  if (project?.generation?.modeConfirmed !== true) {
    throw Object.assign(new Error("请先确认当前项目使用“Codex 资产包直抽”“资产直投 H3（无分镜图）”“首尾帧”“视频延续”“智能首尾帧+视频延续”或“逐秒分镜合图”模式，再进入生产"), {
      code: "GENERATION_MODE_CONFIRMATION_REQUIRED"
    });
  }
  if (requestedMode && normalizeProjectMode(requestedMode) !== confirmedMode) {
    throw Object.assign(new Error("本次视频请求与项目开局确认的生成模式不一致，请先在项目制作策略中修改"), {
      code: "GENERATION_MODE_MISMATCH"
    });
  }
  return confirmedMode;
}

function applyCandidateQualityAudits(project, audit) {
  for (const record of audit?.shots || []) {
    const candidate = project.candidates.find(item => item.id === record?.candidateId);
    if (!candidate) continue;
    candidate.qualityAudit = {
      ok: record.ok,
      checkedAt: audit.checkedAt,
      hasDialogue: record.hasDialogue,
      audio: record.audio,
      visual: record.visual,
      anchors: record.anchors,
      failures: record.failures || [],
      repairDirective: buildRepairDirective(record.failures || [])
    };
  }
  return project;
}

function beginProductionRevision(project) {
  archiveCurrentFinalVideo(project, "production-revision");
  project.productionRevision = makeId("revision");
  project.finalVideoPath = "";
  project.finalAudioAudit = null;
  project.finalVisualAudit = null;
  project.finalQualityAudit = null;
  project.mediaQualityAudit = null;
  project.audioQualityAudit = null;
  return project.productionRevision;
}

function archiveCurrentFinalVideo(project, reason = "replaced") {
  if (!project?.finalVideoPath) return project;
  project.finalVideoHistory = Array.isArray(project.finalVideoHistory) ? project.finalVideoHistory : [];
  const latest = project.finalVideoHistory[0];
  if (latest?.filePath !== project.finalVideoPath) {
    project.finalVideoHistory.unshift({
      id: makeId("final"),
      filePath: project.finalVideoPath,
      source: project.finalVideoSource || "generated",
      productionRevision: project.productionRevision || "",
      replacedAt: new Date().toISOString(),
      stale: project.finalVideoStale === true,
      staleReason: project.finalVideoStaleReason || reason
    });
    project.finalVideoHistory = project.finalVideoHistory.slice(0, 50);
  }
  return project;
}

function isResumableVideoPause(error) {
  const code = String(error?.code || "");
  return (error?.retryable === true && error?.noRemoteTaskCreated === true)
    || /(?:QUARANTINED|ISOLATED)$/i.test(code) || [
    "PROVIDER_DAILY_QUOTA_EXHAUSTED",
    "ACCOUNT_SWITCH_IN_PROGRESS",
    "PROVIDER_QUARANTINED",
    "VIDEO_SUBMISSION_RESPONSE_UNKNOWN",
    "VIDEO_REMOTE_PENDING",
    "VIDEO_POLL_TIMEOUT",
    "REFERENCE_MEDIA_UPLOAD_RETRYABLE",
    "BRIDGE_NETWORK_ERROR",
    "BRIDGE_REQUEST_TIMEOUT",
    "SHOT_VIDEO_BATCH_REMOTE_PENDING",
    "ASSET_VIDEO_DEPENDENCIES_PENDING",
    "SHOT_SPEAKER_VOICE_REQUIRED",
    "HAILUO_SPEAKER_VOICE_REQUIRED"
  ].includes(code);
}

function isOperationControlError(error) {
  return isScriptControlError(error) || ["PIPELINE_PAUSED", "PIPELINE_STOPPED", "ACCOUNT_SWITCH_IN_PROGRESS", "AGENT_EVIDENCE_PENDING", "PROMPT_CONFIRMATION_REQUIRED", "PROMPT_TRANSLATION_PENDING"].includes(error?.code);
}

const ADVISORY_LEGACY_ERROR_CODES = new Set([
  "SHOT_QUALITY_RETRY_EXHAUSTED",
  "STORYBOARD_QUALITY_RETRY_EXHAUSTED",
  "CHARACTER_QUALITY_RETRY_EXHAUSTED",
  "CHARACTER_VIDEO_QUALITY_RETRY_EXHAUSTED",
  "SCENE_QUALITY_RETRY_EXHAUSTED",
  "PROJECT_MEDIA_QUALITY_FAILED",
  "FINAL_MEDIA_QUALITY_FAILED",
  "SCRIPT_GENERATION_PAUSED",
  "SCRIPT_GENERATION_STOPPED"
]);

const RETIRED_PRODUCTION_ONLY_VIDEO_ERROR_CODES = new Set([
  "AGENT_TAKE_SHEET_REQUIRED",
  "AGENT_TAKE_SHEET_GRID_UNSAFE",
  "AGENT_TAKE_PANEL_REQUIRED",
  "AGENT_TAKE_SHEET_CROP_FAILED"
]);

function legacyAutomationIsAdvisory(automation = {}) {
  const directCode = String(automation.errorCode || "").trim();
  if (ADVISORY_LEGACY_ERROR_CODES.has(directCode)) return true;
  const nested = [
    ...(automation.progress?.items || []),
    ...(automation.lastStoryboardFailures || []),
    ...(automation.lastShotVideoFailures || [])
  ].map(item => String(item?.errorCode || item?.code || "").trim()).filter(Boolean);
  const messageCodes = [...String(automation.message || "").matchAll(/\b([A-Z][A-Z0-9_]{4,})\b/g)]
    .map(match => match[1])
    .filter(code => !["SHOT_VIDEO_BATCH_PARTIAL_FAILED", "STORYBOARD_BATCH_PARTIAL_FAILED"].includes(code));
  const childCodes = [...nested, ...messageCodes];
  if (!["SHOT_VIDEO_BATCH_PARTIAL_FAILED", "STORYBOARD_BATCH_PARTIAL_FAILED"].includes(directCode)) return false;
  return childCodes.length > 0 && childCodes.every(code => ADVISORY_LEGACY_ERROR_CODES.has(code));
}

function productionOnlyLegacyVideoFailureCanResume(automation = {}, settings = {}, project = {}) {
  if (String(automation.status || "") !== "failed") return false;
  if (!["shot_video", "shot_videos", "full_pipeline", "idea_to_full_pipeline", "pipeline_from_stage"].includes(String(automation.operation || ""))) return false;
  const code = String(automation.errorCode || "").trim();
  if (code === "PRODUCTION_PACKAGE_SHOT_ANCHOR_REQUIRED") {
    const productionPackage = normalizeProjectMode(project?.generation?.mode) === "production_package";
    const hasCreatedTask = (project?.jobs || []).some(job => ["shot_video", "character_video"].includes(job?.type)
      && Boolean(job?.taskId || job?.providerTaskId));
    return productionPackage && !hasCreatedTask;
  }
  if (settings?.generation?.qualityGatesEnabled === true) return false;
  return RETIRED_PRODUCTION_ONLY_VIDEO_ERROR_CODES.has(code);
}

function retiredVideoGateRecovered(project = {}) {
  return project?.automation?.retiredVideoGateRecovered === true;
}

