function buildCharacterSpeechScript(character = {}, durationSeconds = 6) {
  const duration = Math.max(4, Math.round(Number(durationSeconds) || 6));
  const spokenLength = value => (String(value || "").match(/[\u4e00-\u9fffA-Za-z0-9]/g) || []).length;
  if (duration === 5) {
    const voice = `${character.voiceDescription || ""} ${character.role || ""} ${character.appearanceDescription || character.description || ""}`;
    if (/强势|泼辣|尖锐|拔高|反派|刻薄/.test(voice)) return "现在开始校准声音，我会说得清楚、有力、稳定。";
    if (/沉稳|克制|老人|父亲|母亲|温和|善良/.test(voice)) return "现在开始校准声音，我会说得自然、清楚、平稳。";
    return "现在开始校准声音，我会保持自然、清楚、稳定。";
  }
  const targetChars = Math.max(18, Math.round(duration * 4));
  const chunks = [
    "现在开始校准声音。",
    "我会保持自然呼吸，吐字清楚，音量稳定。",
    "接下来声音略微提高，再平稳落下。",
    "这段内容只用于识别声线，不属于任何剧情。"
  ];
  const complete = [];
  for (const chunk of chunks) {
    const normalized = /[。！？]$/.test(chunk) ? chunk : `${chunk}。`;
    const candidate = `${complete.join("")}${normalized}`;
    if (spokenLength(candidate) > targetChars + 8 && complete.length) break;
    complete.push(normalized);
    if (spokenLength(candidate) >= targetChars) break;
  }
  return complete.join("");
}

/** Convert the authored Chinese role/voice bible into a compact English H3 voice target. */
function characterVoiceProfileEnglish(character = {}) {
  const source = `${character.voiceDescription || ""} ${character.role || ""} ${character.appearanceDescription || character.description || ""}`;
  const age = /七十|八十|高龄|老年|老人|爷爷|奶奶|外公|外婆/.test(source)
    ? "an elderly"
    : /五十|六十|中老年|中年|父亲|母亲|公公|婆婆/.test(source)
      ? "a middle-aged"
      : "an adult";
  const gender = /女性|女人|母亲|妈妈|妻子|女儿|姐姐|妹妹|奶奶|婆婆|阿姨|外婆/.test(source)
    ? "female voice"
    : /男性|男人|父亲|爸爸|丈夫|儿子|哥哥|弟弟|爷爷|公公|叔叔|外公/.test(source)
      ? "male voice"
      : "voice";
  const pitch = /低沉|低音|浑厚|厚重/.test(source)
    ? "low-pitched"
    : /尖锐|高音|拔高|清亮/.test(source)
      ? "higher-pitched"
      : "mid-pitched";
  const texture = /沙哑|嘶哑|粗粝|烟嗓/.test(source)
    ? "slightly hoarse and textured"
    : /温柔|温和|柔和|慈祥/.test(source)
      ? "warm and gentle"
      : /尖刻|刻薄|泼辣|强势/.test(source)
        ? "sharp-edged and forceful"
        : /清脆|清晰|利落/.test(source)
          ? "clear and crisp"
          : "natural and recognizable";
  const pace = /语速快|急促|快嘴|连珠炮/.test(source)
    ? "brisk but intelligible pace"
    : /语速慢|缓慢|慢条斯理/.test(source)
      ? "measured slow pace"
      : "steady conversational pace";
  const manner = /克制|隐忍|压火/.test(source)
    ? "restrained pressure that rises to firm conviction"
    : /强势|泼辣|尖锐|拔高|反派|刻薄/.test(source)
      ? "direct, confrontational authority without screaming"
      : /温柔|善良|慈祥/.test(source)
        ? "kind everyday warmth that becomes quietly firm"
        : "natural everyday speech that becomes firmly resolved";
  return `${age} ${gender}, ${pitch}, ${texture}, with a ${pace}; ${manner}`;
}

function characterVideoOutputContract(project, settings) {
  const engine = projectVideoEngine(project);
  const outputConstraint = engine === "hailuo-h3"
    ? "Output-form constraint: the result is exactly 5.00 seconds. <Picture 1> defines only this single character's identity and complete wardrobe. At 0.00 seconds the frame is a centered frontal static live-action medium close-up and speech starts immediately. The same uninterrupted utterance continues through the entire clip, with the final syllable completing between 4.90 and 5.00 seconds and no silent tail. Keep both eyes visible, head yaw within 10 degrees, the mouth unobstructed, the complete face inside the visual center, and the same identity, wardrobe and voice timbre through the final frame. Use a plain neutral seamless background and clean dry speech with faint room tone. Keep one uninterrupted clean single-subject portrait without displayed reference material, graphic layers, interface elements, readable content, extra people or cutaways."
    : "【输出形态正向限制】图1只锁定这个角色的单人身份。0.00秒就是视觉中心内的正脸真人中近景并立刻开口；双眼全程清楚，头部左右偏转不超过15度，身份与整套服装直到尾帧不漂移。完整视频保持同一个干净、连续的单人真人肖像，只呈现角色、纯色背景与自然微表演，不叠加参考素材、网格、后期图形层、界面或可读内容。";
  const parityStage = engine === "hailuo-h3" ? "hailuo_character_video" : "character_video";
  return withStageParity(outputConstraint, settings.prompts, parityStage);
}


function hasOssCredentials(config = {}) {
  if (config.storageMode === "managed" && /^https:\/\/puream\.cn$/i.test(String(config.managedStorageBaseUrl || "https://puream.cn").replace(/\/$/, ""))) {
    // Managed mode still needs a PureAM credential; without it upload always 401s.
    return Boolean(String(config.apiKey || "").trim());
  }
  return Boolean(String(config.ossAccessKeyId || "").trim()
    && String(config.ossAccessKeySecret || "").trim()
    && String(config.ossBucket || "").trim()
    && String(config.ossEndpoint || "").trim());
}

/** Signed OSS/CDN URLs that carry Expires=... must be refreshed before submit. Permanent http(s) stay reusable. */
function signedUrlExpiryUnix(url) {
  try {
    const parsed = new URL(String(url || "").trim());
    const raw = parsed.searchParams.get("Expires") || parsed.searchParams.get("expires") || "";
    const expires = Number(raw);
    return Number.isFinite(expires) && expires > 0 ? Math.floor(expires) : 0;
  } catch {
    return 0;
  }
}

function isHttpsReferenceExpiredOrExpiring(url, skewSeconds = 300) {
  const expires = signedUrlExpiryUnix(url);
  if (!expires) return false;
  return expires <= Math.floor(Date.now() / 1000) + Math.max(0, Number(skewSeconds) || 0);
}

// Static storyboard prompts contain several independent production contracts
// (speaker ownership, product identity, aspect ratio, state and output shape).
// 1500 characters was small enough for the old prompt, but it made a newly
// inserted contract push an earlier one out of the request. Keep a bounded,
// provider-safe prompt while leaving enough room for every structured block.
const STATIC_STORYBOARD_IMAGE_PROMPT_MAX = 3200;

function stripStaticStoryboardDialogueBlocks(prompt) {
  return String(prompt || "")
    .replace(/【对白与表演依据】[^\n]*/g, "")
    .replace(/【对白】[^\n]*/g, "")
    .replace(/\n{3,}/g, "\n\n")
    .trim();
}

function trimStaticStoryboardSection(value, maxChars) {
  const text = String(value || "").trim();
  const limit = Math.max(1, Number(maxChars) || 1);
  if (text.length <= limit) return text;
  if (limit <= 2) return text.slice(0, limit);
  let kept = text.slice(0, limit - 1);
  for (const token of ["\n- ", "\n", "；", "。", "，", " "]) {
    const index = kept.lastIndexOf(token);
    if (index >= Math.floor(limit * 0.62)) {
      kept = kept.slice(0, index).trim();
      break;
    }
  }
  return `${kept || text.slice(0, limit - 1)}…`;
}

/**
 * Keep every authored `【...】` contract visible. The former "last marker wins"
 * limiter could silently remove a product lock (or speaker/aspect contract)
 * merely because another contract was appended later. Unstructured prose is
 * now the only first-choice trimming target; if the structured blocks alone
 * exceed the provider budget, each block is compacted but none is discarded.
 */
function limitStaticStoryboardImagePrompt(prompt, maxChars = STATIC_STORYBOARD_IMAGE_PROMPT_MAX) {
  const text = stripStaticStoryboardDialogueBlocks(prompt);
  const limit = Math.max(400, Number(maxChars) || STATIC_STORYBOARD_IMAGE_PROMPT_MAX);
  if (text.length <= limit) return text;
  const lines = text.split("\n");
  const sections = [];
  let current = { structured: false, lines: [] };
  const pushCurrent = () => {
    const value = current.lines.join("\n").trim();
    if (value) sections.push({ structured: current.structured, text: value });
  };
  for (const line of lines) {
    if (/^【[^】\n]+】/.test(line.trimStart())) {
      pushCurrent();
      current = { structured: true, lines: [line] };
    } else {
      current.lines.push(line);
    }
  }
  pushCurrent();

  const structured = sections.filter(section => section.structured);
  const unstructured = sections.filter(section => !section.structured);
  if (!structured.length) return trimStaticStoryboardSection(text, limit);

  const separators = Math.max(0, sections.length - 1) * 2;
  const structuredChars = structured.reduce((sum, section) => sum + section.text.length, 0);
  if (structuredChars + separators < limit) {
    let proseBudget = Math.max(0, limit - structuredChars - separators);
    return sections.map(section => {
      if (section.structured) return section.text;
      const kept = trimStaticStoryboardSection(section.text, proseBudget);
      proseBudget = Math.max(0, proseBudget - kept.length);
      return kept;
    }).filter(Boolean).join("\n\n").slice(0, limit).trim();
  }

  // Pathological user descriptions may make the structured contracts exceed
  // the bound. Give every block a non-zero budget, then distribute remaining
  // characters in source order. This preserves every heading, including the
  // exact product and speaker ownership contracts, instead of dropping one.
  const leadBudget = unstructured.length ? Math.min(120, Math.floor(limit * 0.08)) : 0;
  const structuredBudget = Math.max(structured.length * 48, limit - leadBudget - separators);
  const minimumPerBlock = Math.max(48, Math.min(180, Math.floor(structuredBudget / structured.length)));
  const blockBudgets = structured.map(section => Math.min(section.text.length, minimumPerBlock));
  let remaining = Math.max(0, structuredBudget - blockBudgets.reduce((sum, value) => sum + value, 0));
  for (let index = 0; index < structured.length && remaining > 0; index += 1) {
    const wanted = structured[index].text.length - blockBudgets[index];
    const extra = Math.min(wanted, remaining);
    blockBudgets[index] += extra;
    remaining -= extra;
  }
  let structuredIndex = 0;
  let proseRemaining = leadBudget;
  const compacted = sections.map(section => {
    if (section.structured) {
      const budget = blockBudgets[structuredIndex++] || 48;
      return trimStaticStoryboardSection(section.text, budget);
    }
    const kept = trimStaticStoryboardSection(section.text, proseRemaining);
    proseRemaining = Math.max(0, proseRemaining - kept.length);
    return kept;
  }).filter(Boolean).join("\n\n").trim();
  return compacted.length <= limit ? compacted : compacted.slice(0, limit).trim();
}

function parsePropBibleFromScript(text) {
  const source = String(text || "").replace(/\r\n/g, "\n");
  const section = source.match(/##\s*5[\.．]?\s*[^\n]*道具[^\n]*\n([\s\S]*?)(?=\n##\s*\d+|$)/);
  if (!section) return [];
  const props = [];
  const seen = new Set();
  for (const line of section[1].split("\n")) {
    const match = line.match(/^\s*[-*]\s*([^：:（(]{1,40})[：:](.+)$/);
    if (!match) continue;
    const name = String(match[1] || "").trim();
    const rest = String(match[2] || "").trim();
    if (!name || /^(商品状态|带货商品|上传商品)$/.test(name)) continue;
    const propId = `prop_${slug(name)}`;
    if (seen.has(propId)) continue;
    seen.add(propId);
    const field = key => {
      const hit = rest.match(new RegExp(`${key}[：:]\\s*([^；;]+)`));
      return hit ? String(hit[1] || "").trim() : "";
    };
    props.push({
      id: propId,
      name,
      description: rest.split(/[；;]/)[0].trim() || rest,
      holder: field("持有人\\/手别") || field("持有人"),
      units: [...rest.matchAll(/\bS\d{2,}\b/g)].map(item => item[0]),
      purpose: field("用途"),
      continuity: field("连续性")
    });
  }
  return props;
}

/** Keep required refs (e.g. product) inside the provider image-reference cap. */
function selectImageReferenceInputs(items = [], maxCount = 9, options = {}) {
  const max = Math.max(1, Math.min(9, Number(maxCount) || 9));
  const mustKeep = new Set((options.mustKeep || []).map(String).filter(Boolean));
  const unique = [];
  const seen = new Set();
  for (const item of items || []) {
    const key = String(item?.url || "").trim() || (item?.path ? path.resolve(item.path).toLowerCase() : "");
    if (!key || seen.has(key)) continue;
    seen.add(key);
    unique.push(item);
  }
  const isRequired = item => mustKeep.has(String(item?.entityType || ""))
    || mustKeep.has(String(item?.sourceStage || ""))
    || mustKeep.has(String(item?.type || ""));
  const required = unique.filter(isRequired);
  const optional = unique.filter(item => !isRequired(item));
  if (required.length >= max) return required.slice(0, max);
  return [...required, ...optional.slice(0, max - required.length)];
}

const WIDE_IMAGE_ASSET_STAGES = new Set([
  "character_sheet",
  "character_three_view",
  "scene_asset",
  "prop_asset",
  "wardrobe_asset"
]);

const CONTINUITY_REQUIRED_IMAGE_STAGES = new Set([
  "character_intro",
  "storyboard_start",
  "storyboard_end",
  "storyboard_sheet",
  "wardrobe_asset"
]);

function storyboardSheetGrid(panelCount = 10, panelAspectRatio = "9:16") {
  const count = Math.max(1, Math.round(Number(panelCount) || 10));
  const parseRatio = (value, fallback = 9 / 16) => {
    const match = String(value || "").trim().match(/^(\d+(?:\.\d+)?):(\d+(?:\.\d+)?)$/);
    return match ? Number(match[1]) / Math.max(0.001, Number(match[2])) : fallback;
  };
  const normalizedPanelAspect = ["9:16", "16:9", "4:3", "1:1", "3:4", "21:9"].includes(String(panelAspectRatio || ""))
    ? String(panelAspectRatio)
    : "9:16";
  // When the provider supports the requested panel ratio directly, a square
  // grid on the same-ratio canvas is the only topology that guarantees every
  // cell keeps that ratio without relying on the image model to honour margins.
  // The old occupancy-first tie-break selected 4x2 on a 1:1 canvas for eight
  // vertical frames, which physically made every cell 1:2 and stretched faces.
  if (["9:16", "1:1", "16:9"].includes(normalizedPanelAspect)) {
    const side = Math.max(1, Math.ceil(Math.sqrt(count)));
    return {
      panelCount: count,
      columns: side,
      rows: side,
      panelAspectRatio: normalizedPanelAspect,
      canvasAspectRatio: normalizedPanelAspect,
      contentWidthPercent: 100,
      contentHeightPercent: 100,
      outerMarginXPercent: 0,
      outerMarginYPercent: 0,
      usedAreaPercent: Number((count / (side * side) * 100).toFixed(2)),
      emptyCells: side * side - count,
      order: "left-to-right, top-to-bottom",
      fitPolicy: "exact-panel-ratio-square-grid-never-stretch"
    };
  }
  const panelRatio = parseRatio(normalizedPanelAspect);
  const canvases = [
    { label: "9:16", ratio: 9 / 16 },
    { label: "1:1", ratio: 1 },
    { label: "16:9", ratio: 16 / 9 }
  ];
  let best = null;
  for (let columns = 1; columns <= Math.min(5, count); columns += 1) {
    const rows = Math.ceil(count / columns);
    const contentRatio = columns * panelRatio / rows;
    const occupancy = count / (columns * rows);
    for (const canvas of canvases) {
      const contentWidthFraction = contentRatio <= canvas.ratio ? contentRatio / canvas.ratio : 1;
      const contentHeightFraction = contentRatio <= canvas.ratio ? 1 : canvas.ratio / contentRatio;
      const usedArea = contentWidthFraction * contentHeightFraction * occupancy;
      const candidate = {
        columns,
        rows,
        canvas,
        contentRatio,
        contentWidthFraction,
        contentHeightFraction,
        usedArea,
        emptyCells: columns * rows - count
      };
      if (!best
        || candidate.usedArea > best.usedArea + 1e-9
        || (Math.abs(candidate.usedArea - best.usedArea) <= 1e-9 && candidate.emptyCells < best.emptyCells)) best = candidate;
    }
  }
  const pct = value => Number((Math.max(0, Math.min(1, value)) * 100).toFixed(2));
  return {
    panelCount: count,
    columns: best.columns,
    rows: best.rows,
    panelAspectRatio: normalizedPanelAspect,
    canvasAspectRatio: best.canvas.label,
    contentWidthPercent: pct(best.contentWidthFraction),
    contentHeightPercent: pct(best.contentHeightFraction),
    outerMarginXPercent: pct((1 - best.contentWidthFraction) / 2),
    outerMarginYPercent: pct((1 - best.contentHeightFraction) / 2),
    usedAreaPercent: pct(best.usedArea),
    emptyCells: best.emptyCells,
    order: "left-to-right, top-to-bottom",
    fitPolicy: "uniform-scale-or-crop-never-stretch"
  };
}

function sampleOrderedPanelIndices(panelIndices = [], maxCount = 9) {
  const ordered = [...new Set((Array.isArray(panelIndices) ? panelIndices : [])
    .map(Number)
    .filter(index => Number.isInteger(index) && index >= 0))].sort((left, right) => left - right);
  const limit = Math.max(1, Math.round(Number(maxCount) || 1));
  if (ordered.length <= limit) return ordered;
  if (limit === 1) return [ordered[0]];
  const selected = [];
  for (let slot = 0; slot < limit; slot += 1) {
    const sourceIndex = Math.round(slot * (ordered.length - 1) / (limit - 1));
    const panelIndex = ordered[sourceIndex];
    if (!selected.includes(panelIndex)) selected.push(panelIndex);
  }
  for (const panelIndex of ordered) {
    if (selected.length >= limit) break;
    if (!selected.includes(panelIndex)) selected.push(panelIndex);
  }
  return selected.sort((left, right) => left - right);
}

function deterministicStoryboardGridCells(grid = {}, panelCount = 10) {
  const count = Math.max(1, Math.round(Number(panelCount) || 10));
  const columns = Math.max(1, Math.round(Number(grid?.columns) || Math.ceil(Math.sqrt(count))));
  const rows = Math.max(1, Math.round(Number(grid?.rows) || Math.ceil(count / columns)));
  const cells = [];
  for (let row = 0; row < rows && cells.length < count; row += 1) {
    for (let column = 0; column < columns && cells.length < count; column += 1) {
      cells.push({
        index: cells.length,
        column,
        row,
        x: column / columns,
        y: row / rows,
        width: 1 / columns,
        height: 1 / rows
      });
    }
  }
  return { ok: cells.length >= count, columns, rows, cells, detectionMethod: "declared-grid-fallback" };
}

function skippedSemanticReview(phase = "full", summary = "蓝图/质检限制已关闭，已跳过语义终审") {
  return {
    ok: true,
    skipped: true,
    scored: false,
    verdict: "skipped",
    scores: {},
    enabledFields: [],
    skippedFields: [...SEMANTIC_SCORE_FIELDS],
    hardFailures: [],
    summary,
    repairDirectives: [],
    phase
  };
}

function imageStageAspectRatio(project, stage, entity = null) {
  if (String(stage || "") === "storyboard_sheet") {
    return storyboardSheetGrid(entity?.panelCount || entity?.duration || 10, project?.generation?.aspectRatio || "9:16").canvasAspectRatio;
  }
  if (WIDE_IMAGE_ASSET_STAGES.has(String(stage || ""))) return "16:9";
  return String(project?.generation?.aspectRatio || "9:16").trim() || "9:16";
}

function imageGenerationOptions(project, stage, referenceInputs = [], entity = null, signal = null) {
  const aspectRatio = imageStageAspectRatio(project, stage, entity);
  // Public image providers commonly support only these three ratios. Sending a
  // dynamic sheet ratio (for example 9:8) was silently coerced to 9:16, which
  // then failed our own contact-sheet audit. Use the nearest supported canvas
  // while keeping the exact logical grid in the prompt and audit metadata.
  const parsed = String(aspectRatio).match(/^(\d+(?:\.\d+)?):(\d+(?:\.\d+)?)$/);
  const ratio = parsed ? Number(parsed[1]) / Math.max(Number(parsed[2]), 0.001) : 1;
  const supported = [["9:16", 9 / 16], ["1:1", 1], ["16:9", 16 / 9]];
  const size = supported.slice().sort((left, right) => Math.abs(Math.log(ratio / left[1])) - Math.abs(Math.log(ratio / right[1])))[0][0];
  return { referenceInputs, size, aspectRatio, costProjectId: project.id, costOperation: stage, ...(signal ? { signal } : {}) };
}

function localUngatedHailuoPromptSpec(shot, fingerprint = "", mode = "", source = null) {
  const supplied = source && typeof source === "object" ? source : {};
  const planned = Array.isArray(shot?.subshots) && shot.subshots.length
    ? shot.subshots
    : [{ number: 1, start: 0, end: Number(shot?.duration) || 10 }];
  const suppliedSubshots = Array.isArray(supplied.subshots) ? supplied.subshots : [];
  return normalizePromptSpec({
    ...supplied,
    mode: supplied.mode || mode,
    styleEn: supplied.styleEn || "Live-action vertical short drama with naturalistic performance, readable faces, grounded blocking, and stable cinematic continuity.",
    summaryEn: supplied.summaryEn || "Perform the complete authored story beat in causal order, preserving every planned speaker, reaction, action result, and final state.",
    subshots: planned.map((item, index) => {
      const existing = suppliedSubshots.find(entry => Number(entry?.number) === index + 1) || suppliedSubshots[index] || {};
      return {
        ...existing,
        number: index + 1,
        visualEn: existing.visualEn || `Perform authored beat ${index + 1} with clear speaker-to-listener eyelines, visible emotion changes, motivated body action, and a distinct end state.`,
        soundEn: existing.soundEn || "Continuous natural room tone with only visible synchronized physical sound effects; no background music.",
        visibleCharacterIds: Array.isArray(item?.visibleCharacterIds) ? item.visibleCharacterIds : (existing.visibleCharacterIds || shot?.visibleCharacterIds || []),
        offscreenSpeakerIds: Array.isArray(item?.offscreenSpeakerIds) ? item.offscreenSpeakerIds : (existing.offscreenSpeakerIds || shot?.offscreenSpeakerIds || []),
        speakerIds: existing.speakerIds || []
      };
    }),
    overallSoundscapeEn: supplied.overallSoundscapeEn || "Continuous natural ambience and synchronized visible physical effects only; every authored line remains complete and audible; no background music.",
    nonDiegeticMusicEn: "N/A"
  }, shot, fingerprint);
}

function continuityReferenceRequired(stage) {
  return CONTINUITY_REQUIRED_IMAGE_STAGES.has(String(stage || ""));
}

function continuityReferenceError(stage, message = "", cause = null) {
  const error = Object.assign(new Error(message || `阶段 ${stage} 缺少当前镜头所需的人物、场景或道具参考图，已在调用图片供应商前停止，禁止无参考生成。`), {
    code: "CONTINUITY_REFERENCE_REQUIRED",
    stage: String(stage || ""),
    uploadErrors: cause?.uploadErrors || []
  });
  if (cause) error.cause = cause;
  return error;
}

function isSameProductName(name = "", productName = "") {
  const left = String(name || "").trim().toLowerCase();
  const right = String(productName || "").trim().toLowerCase();
  if (!left || !right) return false;
  return left === right || left.includes(right) || right.includes(left);
}

/** Tokens that count as early product leakage (full name + common short aliases). */
function productMentionTokens(productName = "") {
  const name = String(productName || "").trim();
  if (!name) return [];
  const tokens = new Set([name]);
  const stripped = name.replace(/硅胶|医用|老人|中老年|加厚|保暖|运动|智能|多功能|便携|家用|纯棉|实木|天然|护膝套|护腰带|护踝套/g, "").trim();
  if (stripped.length >= 2) tokens.add(stripped);
  if (/护膝/.test(name)) tokens.add("护膝");
  if (/护膝/.test(name)) tokens.add("膝盖护具");
  if (/护腰/.test(name)) ["护腰", "腰带", "腰部护具"].forEach(item => tokens.add(item));
  if (/护踝/.test(name)) ["护踝", "脚踝护具"].forEach(item => tokens.add(item));
  if (/茶盘/.test(name)) ["茶盘", "托盘"].forEach(item => tokens.add(item));
  if (/按摩/.test(name)) ["按摩器", "按摩仪", "理疗仪"].forEach(item => tokens.add(item));
  if (/枕/.test(name)) ["枕头", "枕芯"].forEach(item => tokens.add(item));
  return [...tokens].filter(token => token.length >= 2);
}

function textMentionsProduct(text = "", productName = "") {
  const blob = String(text || "");
  if (!blob) return false;
  return productMentionTokens(productName).some(token => blob.includes(token));
}

function productSemanticTokens(project = {}) {
  const product = project?.product || {};
  const facts = `${product.name || ""} ${product.description || ""} ${product.sellingPoints || ""}`;
  const tokens = new Set(productMentionTokens(product.name));
  const categories = [
    [/书|读物|绘本|小说|教材/, ["这本书", "书本", "图书", "翻书", "翻开书"]],
    [/茶|饮料|咖啡|牛奶|果汁/, ["这杯茶", "茶饮", "这款饮料", "这杯饮料", "这杯咖啡", "这盒牛奶", "这瓶果汁"]],
    [/食品|零食|糕点|饼干|米|面|粮|果干/, ["这款食品", "这袋零食", "这盒糕点", "这包饼干", "这袋米", "这袋果干"]],
    [/护膝|护腰|护踝|护具/, ["这件护具", "护膝", "护腰", "护踝", "膝盖护具", "腰部护具", "脚踝护具"]],
    [/按摩|理疗/, ["按摩器", "按摩仪", "理疗仪", "这台理疗设备"]],
    [/灯|台灯|照明/, ["台灯", "灯具", "这盏灯", "这款灯"]],
    [/锅|杯|壶|餐具|厨具/, ["这口锅", "这只杯子", "这把壶", "这套餐具", "这件厨具"]],
    [/枕|床垫|被|家纺/, ["枕头", "床垫", "这床被子", "这套床品", "这款家纺"]],
    [/鞋|衣|裤|帽|穿戴/, ["这双鞋", "这件衣服", "这条裤子", "这顶帽子", "这款穿戴产品"]]
  ];
  for (const [pattern, aliases] of categories) if (pattern.test(facts)) aliases.forEach(token => tokens.add(token));
  return [...tokens].map(item => String(item || "").trim()).filter(item => item.length >= 2);
}

function inferProductShotType(shot = {}) {
  const text = `${shot.action || ""} ${shot.visualBeat || ""} ${shot.dialogue || ""} ${JSON.stringify(shot.subshots || [])}`;
  if (/效果|结果|完成|变得|亮起|恢复|改善|更清楚|更方便/.test(text)) return "product_result";
  if (/反应|点头|笑|决定|答应|认可|放心/.test(text)) return "product_reaction";
  if (/打开|翻开|阅读|冲泡|喝|吃|穿|戴|按下|开机|使用|操作|安装|倒入|擦拭/.test(text)) return "product_use";
  if (/特写|细节|标签|材质|接口|纹理/.test(text)) return "product_detail";
  return "product_packshot";
}

function applyUploadedProductBindings(normalized, project = {}) {
  const product = project?.product || {};
  const productName = String(product.name || "").trim();
  const hasProductFacts = Boolean(productName || product.imagePath || product.publicUrl || product.description || product.sellingPoints);
  if (!hasProductFacts) return normalized;
  const tokens = productSemanticTokens(project);
  const shots = (Array.isArray(normalized?.shots) ? normalized.shots : []).map(shot => {
    const sourceDialogue = (Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : [])
      .map(turn => String(turn?.text || turn?.spokenText || "").trim()).filter(Boolean);
    const narrativeText = [shot.action, shot.visualBeat, shot.startFrame, shot.endFrame, ...sourceDialogue].map(value => String(value || "")).join("\n");
    const matchedTokens = tokens.filter(token => narrativeText.includes(token));
    const authoredHidden = /(?:不直接出现|不出现|不直接操作|暂不展示)/.test(String(shot.productNote || shot.productInstruction || ""));
    const productMention = authoredHidden
      ? false
      : Boolean(shot.productMention || matchedTokens.length);
    if (!productMention) return { ...shot, productBinding: null };
    const sourceDialogueIds = (Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : [])
      .filter(turn => tokens.some(token => String(turn?.text || "").includes(token)))
      .map(turn => String(turn?.sourceDialogueId || "").trim()).filter(Boolean);
    const next = {
      ...shot,
      productMention: true,
      productShotType: !shot.productShotType || shot.productShotType === "none" ? inferProductShotType(shot) : shot.productShotType,
      productBinding: {
        source: "user_uploaded_product",
        name: productName,
        description: String(product.description || "").trim(),
        sellingPoints: String(product.sellingPoints || "").trim(),
        matchedTokens,
        sourceDialogueIds,
        trigger: sourceDialogueIds.length ? "source_dialogue" : (matchedTokens.length ? "story_semantics" : "director_assignment")
      }
    };
    next.productCausalBridge = deriveProductCausalBridge(next, product, {
      characters: normalized?.characters || project?.characters || []
    });
    return next;
  });
  return { ...normalized, shots };
}

function productPromptDirective(project = {}, shot = {}) {
  if (!shot?.productMention) return "本镜没有商品剧情触发，禁止凭空加入商品、包装、品牌或销售口播。";
  const product = project?.product || {};
  const commerceFacts = productCommerceFacts(project);
  const binding = shot.productBinding || {};
  const trigger = Array.isArray(binding.sourceDialogueIds) && binding.sourceDialogueIds.length
    ? `由原稿台词 ${binding.sourceDialogueIds.join("、")} 触发`
    : "由本镜剧情动作触发";
  const presenterRule = /product_(?:presentation|offer|cta)/i.test(`${shot.productShotType || ""} ${shot.shotFunction || ""}`)
    ? `本镜由一名已有角色手持商品，脸、眼睛与上半身正对镜头向观众介绍；对应 dialogueTurn 必须 addressMode=viewer、directToViewer=true。用户价格：${commerceFacts.price || "未提供"}；用户优惠：${commerceFacts.offer || "未提供"}；购买收口：${commerceFacts.safePurchaseClose}。未提供的价格或优惠绝不编造。`
    : "";
  return `【用户上传商品硬绑定】${trigger}；本镜商品只能是“${product.name || binding.name || "用户上传商品"}”。外观逐像素服从用户商品图，包装/颜色/Logo/形状不得改画；商品说明：${product.description || binding.description || "仅按上传信息"}；允许表达的卖点：${product.sellingPoints || binding.sellingPoints || "仅按上传信息"}。不得虚构价格、品牌、功效、疗效或与剧本无关的口播。${presenterRule}`;
}

function storyboardDialogueVisualDirective(project = {}, shot = {}) {
  const turns = uniqueDialogueTurns(project, shot);
  if (!turns.length) return "【对白表演画面】本镜无台词，所有人物闭口，只用原稿剧情要求的动作和反应推进。";
  const characterNameById = new Map((project?.characters || []).map(item => [String(item?.id || "").trim(), String(item?.name || "").trim()]));
  const lines = turns.map(turn => {
    const listeners = (turn.listenerIds || []).map(id => characterNameById.get(String(id || "").trim()) || String(id || "").trim()).filter(Boolean);
    const target = listeners.length ? listeners.join("、") : "剧情中的明确听者/动作对象";
    const tone = turn.sourceTone || turn.metadata?.sourceTone || turn.metadata?.emotion || turn.metadata?.delivery || "按剧情自然起伏";
    return `${turn.speaker}以“${tone}”面向${target}说话；说话人口型、眼神和表情同步，${target}闭口并给出可见反应`;
  });
  return `【对白表演画面】${lines.join("；")}。台词文字只用于决定口型和表情，图片中禁止生成字幕、气泡、台词字样或水印。`;
}

function storyAssetDirective(project = {}, stage = "", entity = {}) {
  if (stage.startsWith("character_")) {
    const related = (project?.shots || []).filter(shot => (shot.characterIds || []).includes(entity.id));
    const tones = related.flatMap(shot => uniqueDialogueTurns(project, shot)
      .filter(turn => turn.speakerId === entity.id || turn.speaker === entity.name)
      .map(turn => turn.sourceTone || turn.metadata?.emotion || turn.metadata?.delivery || shot.emotion)).filter(Boolean);
    return `【独立人物资产合同】只描绘角色“${entity.name || entity.id}”本人；身份分档：${[entity.gender,entity.ageBand,entity.role].filter(Boolean).join("，")}。只依据已确认外形设计锁定脸、体态、发型、服装与自然闭口表情，不在身份图中演剧情，不加入其他角色、剧情物品或商品。职业不等于统一制服，服装仅服从本人已确认设计。`;
  }
  if (stage === "scene_asset") {
    const related = (project?.shots || []).filter(shot => shot.sceneId === entity.id || shot.sceneName === entity.name);
    // Scene-library prompts describe only space. Raw story beats contain actor
    // names/actions and were leaking people into otherwise empty-scene prompts.
    const productUsed = related.some(shot => shot.productMention);
    return `【独立场景四视图合同】一张16:9画布严格分成2×2四格：沿已定义主轴的正向、反向、左侧45度、右侧45度；四格锁定同一空间拓扑、光向、拍摄轴和可行动区域。户外道路按道路主轴取景，不套用室内房间或入口；室内仅保留已定义的建筑与固定陈设。${productUsed ? "预留已定义的干净操作面，但空场景不得提前画入商品。" : "不得画入商品或广告陈列。"}四个角度都必须无人，不演动作，不呈现对白内容。`;
  }
  if (stage === "prop_asset") {
    const photoEvidence = /照片|合照|相片|旧照|证件照/.test(`${entity.name || ""} ${entity.description || ""}`);
    const outputLock = photoEvidence
      ? "只生成这一张实体照片道具：照片纸面内部按剧情描述呈现被摄人物关系；照片纸面之外不得出现真人、手、场景或其他物品。不得新增可读姓名、字幕、标签、水印、广告文案或拼贴。"
      : "只生成单个道具的写实资产图，固定纯色背景、均匀棚拍光、完整轮廓与清晰材质；保留源稿已确认的物件固有印刷文字和图案，不虚构未提供的姓名、数字或证据。不得出现物体外部的人物、手、场景、桌椅杂物、商品替代品、额外字幕、说明标签、水印或拼贴。";
    return `【AI 核心道具资产合同】只描绘独立物件“${entity.name || entity.id}”的已确认可见形状、材质、颜色、磨损与固有图案。持有人、转交、拾取、摔落及其他剧情动作属于分镜，不能写入此物件身份图。${outputLock}`;
  }
  return "";
}

function sellingPointTokens(sellingPoints = "") {
  return String(sellingPoints || "")
    .split(/[,，、；;\s]+/)
    .map(item => item.trim())
    .filter(item => item.length >= 2);
}

function resolveHailuoApiModeForStrategy(strategy, hailuoApiMode, hasAudios = false) {
  const mode = normalizeHailuoApiMode(hailuoApiMode);
  if (strategy === PRODUCTION_PACKAGE_MODE) {
    if (hasAudios) {
      throw Object.assign(new Error("Codex 资产包直抽模式禁止参考音频；中文对白只能存在于已锁定的英文视频提示词对白标签中"), {
        code: "PRODUCTION_PACKAGE_AUDIO_FORBIDDEN"
      });
    }
    return "reference_to_video";
  }
  if (strategy === "asset_direct") {
    return hasAudios ? "multimodal_to_video" : "reference_to_video";
  }
  if (strategy === "keyframe") {
    if (["text_to_video", "video_to_video", "audio_to_video"].includes(mode)) {
      throw Object.assign(new Error("首尾帧模式必须提交首帧+尾帧参考图，不能使用文生视频/纯视频/纯音频模式"), {
        code: "HAILUO_KEYFRAME_MODE_INVALID"
      });
    }
    if (mode === "auto" || mode === "image_to_video") {
      return hasAudios ? "multimodal_to_video" : "image_to_video";
    }
    return mode;
  }
  if (strategy === "continuation") {
    // Continuation is inherently a multi-reference job: the previous confirmed
    // video is its temporal origin, the current frame/scene/identity assets lock
    // continuity, and dialogue shots add character voice references. Never let
    // a stale pure-mode setting strip one of those reference classes.
    return "multimodal_to_video";
  }
  return mode;
}

function protectDialogueSegments(text, transform) {
  const lines = [];
  const protectedText = String(text || "").replace(/(^|[\n；;])([^：:\n；;]{1,24})([：:])([^\n；;]+)/g, (match) => {
    const token = `\u0000DL${lines.length}\u0000`;
    lines.push(match);
    return token;
  });
  const transformed = transform(protectedText);
  return transformed.replace(/\u0000DL(\d+)\u0000/g, (_, index) => lines[Number(index)] || "");
}

function rewriteH3AuthoredWithPictureTokens(text, project, references = {}) {
  const roles = Array.isArray(references.imageRoles) ? references.imageRoles : [];
  const replacements = [];
  roles.forEach((role, index) => {
    const token = `图${index + 1}`;
    if (role.type === "character" && role.entityId) {
      const character = (project.characters || []).find(item => item.id === role.entityId);
      if (character?.name) replacements.push({ from: character.name, to: token });
    } else if (role.type === "scene") {
      const scene = (project.scenes || []).find(item => item.id === role.entityId);
      const name = scene?.name || "";
      if (name) replacements.push({ from: name, to: token });
    } else if (role.type === "product" && project.product?.name) {
      replacements.push({ from: project.product.name, to: token });
    }
  });
  replacements.sort((a, b) => b.from.length - a.from.length);
  return protectDialogueSegments(text, (chunk) => {
    const roleBindings = [];
    let output = String(chunk || "").replace(/角色[“\"]([^”\"]+)[”\"]/g, match => {
      const token = `\u0000RB${roleBindings.length}\u0000`;
      roleBindings.push(match);
      return token;
    });
    for (const item of replacements) {
      if (!item.from) continue;
      output = output.split(item.from).join(item.to);
    }
    return output.replace(/\u0000RB(\d+)\u0000/g, (_, index) => roleBindings[Number(index)] || "");
  });
}

function formatDialogueWithAudioBinding(dialogueText, references = {}, options = {}) {
  const raw = String(dialogueText || "").trim();
  if (!raw) return { instruction: "本镜头没有对白。", bound: "" };
  const audios = Array.isArray(references.audios) ? references.audios : [];
  const audioByName = new Map(audios.map((item, index) => [String(item.characterName || "").trim(), { index: index + 1, name: item.characterName }]));
  const deliveryTone = String(options.deliveryTone || "").trim() || "带情绪起伏，有轻重气口，禁止平声念词";
  const turns = parseCompiledDialogueSegments(raw, audios.map(item => item.characterName));
  const boundLines = [];
  for (const turn of turns) {
    const speaker = turn.speaker;
    const text = turn.spokenText;
    const audio = audioByName.get(speaker);
    const meta = turn.metadata || {};
    const lineDeliveryTone = String(meta.sourceTone || meta.delivery || deliveryTone).trim();
    const performance = [
      meta.sourceTone ? `原稿语气=${meta.sourceTone}` : "",
      meta.intent ? `意图=${meta.intent}` : "",
      meta.emotion ? `情绪=${meta.emotion}` : "",
      meta.delivery ? `表达=${meta.delivery}` : "",
      meta.volume ? `音量=${meta.volume}` : "",
      meta.pace ? `语速=${meta.pace}` : "",
      meta.stressWord ? `重音落在计划关键词` : "",
      meta.breath ? `气口=${meta.breath}` : "",
      meta.body ? `身体表演=${meta.body}` : "",
      meta.listenerBeat ? `听者反应=${meta.listenerBeat}` : ""
    ].filter(Boolean).join("、");
    const spoken = `用「${lineDeliveryTone}${performance ? `；${performance}` : ""}」只说一遍：${text}`;
    if (audio) boundLines.push(`仅由音频${audio.index}对应的角色“${speaker}”${spoken}`);
    else boundLines.push(`角色“${speaker}”${spoken}（没有与该角色同名绑定的音色时严禁借用其他人的音频，禁止串角）`);
  }
  const audioInstruction = audios.length
    ? audios.map((item, index) => `音频${index + 1}=角色“${item.characterName}”的音色底色（只锁声线，不锁成平淡播音腔）`).join("；") + "。"
    : "";
  return {
    instruction: boundLines.length
      ? `${audioInstruction}对白只说一遍，禁止复读；每句必须有可听出的情绪语气，禁止平静播音式念白。对白必须严格按说话人绑定音色，严禁 A 人说 B 话。${boundLines.join("；")}。`
      : "本镜头没有对白。",
    bound: boundLines.join("；")
  };
}

function stageEmotionIntensity(mainlineStage = "") {
  const key = String(mainlineStage || "").toLowerCase();
  if (/main_reversal|climax|高潮|主反转|爆发/.test(key)) return "high";
  if (/pressure|cost_kindness|evidence|加压|代价|对质|摊牌/.test(key)) return "elevated";
  if (/payoff|ending|回收|收束|释然/.test(key)) return "settling";
  if (/hook|开场|钩子/.test(key)) return "alert";
  return "dramatic";
}

function inferDeliveryTone(emotionText = "", intensity = "dramatic") {
  const emotion = String(emotionText || "");
  if (/怒|火|吼|爆发|质问|愤/.test(emotion)) return "压着火气、字字加重，音量先低后顶";
  if (/哭|泪|哽|悲|委屈|心酸/.test(emotion)) return "带着哽咽与鼻音，气口发紧，尾音发颤";
  if (/惊|慌|急|怕|慌乱/.test(emotion)) return "语速加快、气息发飘，尾字发虚";
  if (/冷|嘲|讥|嫌弃|刻薄/.test(emotion)) return "冷笑压音、咬字干净带刺";
  if (/柔|暖|劝|心疼|哄/.test(emotion)) return "放软放慢，但仍有情绪重心，不是念稿";
  if (/释然|疲惫|无奈|叹气/.test(emotion)) return "气声加重、句尾下落，带着疲惫";
  if (intensity === "high") return "情绪顶格：音高起伏大、气口明显、绝非平静";
  if (intensity === "elevated") return "情绪加压：语速与重音变化清楚，听者能感到张力";
  if (intensity === "settling") return "情绪回落但仍有余波，不能立刻变木头脸";
  if (intensity === "alert") return "警觉试探：语气拎着，不能松垮";
  return "有生活感的情绪起伏，禁止平声念词";
}

/** Visible acting + vocal tone for short-drama video prompts. */
function buildEmotionPerformanceInstruction(project, shot = {}) {
  const emotion = String(shot.emotion || "").trim();
  const performance = String(shot.performance || "").trim();
  const intensity = stageEmotionIntensity(shot.mainlineStage);
  const intensityLabel = {
    high: "高强度爆发",
    elevated: "中高强度加压",
    settling: "回落但仍有余波",
    alert: "警惕试探",
    dramatic: "短剧情绪戏"
  }[intensity] || "短剧情绪戏";
  const deliveryTone = inferDeliveryTone(emotion, intensity);
  const speakersFromIds = (shot.characterIds || [])
    .map(id => (project.characters || []).find(item => item.id === id))
    .filter(Boolean);
  const spokenNames = new Set(uniqueDialogueTurns(project, shot).map(item => item.speaker));
  const speakers = (spokenNames.size
    ? (project.characters || []).filter(item => spokenNames.has(item.name))
    : speakersFromIds).slice(0, 4);
  const voiceHints = speakers
    .map(item => `${item.name}：${String(item.voiceDescription || "生活口语，有情绪习惯").trim()}`)
    .join("；");
  const defaultEmotion = intensity === "high"
    ? "压抑到爆发"
    : intensity === "elevated"
      ? "试探加压到刺痛"
      : intensity === "settling"
        ? "余痛未消到勉强撑住"
        : intensity === "alert"
          ? "警惕到心口发紧"
          : "有来有回的情绪拉扯";
  return [
    `【情绪硬控制·${intensityLabel}】禁止全程平静脸、平声念词、无反应听戏、温吞念稿。情绪曲线：${emotion || defaultEmotion}。`,
    `对白语气：${deliveryTone}；必须有抢话/打断/气口/音量起伏，禁止播音腔。`,
    `表演落地：${performance || "眉心皱紧、鼻翼翕动、咬牙、手指发抖、后退半步、甩手或泪光崩开；说话人有重音与气口，听者必须有愣神/皱眉/抖手/避开视线等反应，不能集体木然。"}`,
    voiceHints ? `角色声线习惯：${voiceHints}。音色参考只定声线，不把角色演成冷静播音员。` : "",
    "脸、身、声三者必须同步：有情绪的对白 = 有表情 + 有身体张力 + 有语气起伏；感染力不够就加大微表情与音量顶格。"
  ].filter(Boolean).join("");
}

/** Speaking turns in source order. Repeated dramatic lines are intentional and must survive. */
function uniqueDialogueTurns(project, shot) {
  const characters = project?.characters || [];
  const names = characters.map(item => item.name);
  const canonicalSpeaker = new Map(characters.flatMap(item => [[String(item.name || "").trim(), String(item.name || "").trim()], [String(item.id || "").trim(), String(item.name || "").trim()]]));
  const items = [];
  const finish = () => items.map((item, index) => {
    const existingTone = String(item.sourceTone || item.metadata?.sourceTone || item.metadata?.delivery || item.metadata?.emotion || "").trim();
    const tone = existingTone || inferDialogueTone({
      text: item.text,
      action: shot?.action || shot?.visualBeat || shot?.performance || "",
      scene: shot?.scene || shot?.sceneName || "",
      previousText: items[index - 1]?.text || "",
      nextText: items[index + 1]?.text || ""
    });
    return { ...item, sourceTone: tone, metadata: { ...item.metadata, sourceTone: tone, delivery: item.metadata?.delivery || tone, emotion: item.metadata?.emotion || tone } };
  });
  const push = (turn, subshotNumber, context = {}) => {
    const rawSpeaker = String(turn.speaker || turn.speakerId || turn.characterId || "").trim();
    const normalizedSpeaker = normalizeSpeakerCue(rawSpeaker).speaker;
    const speaker = canonicalSpeaker.get(normalizedSpeaker) || canonicalSpeaker.get(rawSpeaker) || normalizedSpeaker || rawSpeaker;
    const character = characters.find(item => item.name === speaker || item.id === rawSpeaker || item.id === speaker);
    const speakerId = String(turn.speakerId || turn.characterId || character?.id || "").trim();
    const text = String(turn.spokenText || turn.text || "").trim();
    if (!speaker || !text) return;
    const metadata = turn.metadata && typeof turn.metadata === "object" ? { ...turn.metadata } : {};
    for (const key of ["beat", "tone", "delivery", "body", "listenerBeat", "listenerReaction", "blocking", "position", "speakerFacing", "listenerFacing", "eyeline", "eyelineDirection", "intent", "emotionStart", "emotionPeak", "volume", "pace", "stressWord", "breath", "plannedSpeechSeconds", "plannedAfterBeatSeconds"]) {
      if (turn[key] != null && String(turn[key]).trim()) metadata[key] = String(turn[key]).trim();
    }
    // Provider-facing performance fields are compiled after the immutable
    // Chinese dialogue ledger.  Keep them on both the normalized turn and its
    // metadata so later IR/source-ledger reconciliation cannot silently drop
    // the exact delivery, facial expression or body action.
    const providerPerformance = {};
    for (const key of [
      "deliveryEn", "vocalArcEn", "facialPerformanceEn", "expressionEn", "expressionArcEn", "faceEn", "bodyActionEn", "bodyEn", "blockingEn",
      "speakerFacingEn", "listenerFacingEn", "eyelineEn", "listenerReactionEn", "listenerBeatEn",
      "deliveryZh", "vocalArcZh", "expressionZh", "bodyZh", "blockingZh", "speakerFacingZh", "listenerReactionZh"
    ]) {
      const value = String(turn?.[key] || metadata?.[key] || "").trim();
      if (value) {
        providerPerformance[key] = value;
        metadata[key] = value;
      }
    }
    items.push({
      sourceDialogueId: String(turn.sourceDialogueId || "").trim(),
      sourceTone: String(turn.sourceTone || turn.tone || metadata.sourceTone || metadata.tone || metadata.delivery || "").trim(),
      speaker,
      speakerId,
      primaryListenerId:String(turn.primaryListenerId||turn.addresseeId||metadata.primaryListenerId||''),
      addressMode:String(turn.addressMode||metadata.addressMode||''),
      directToViewer:turn.directToViewer===true||metadata.directToViewer===true,
      speechMode:String(turn.speechMode||metadata.speechMode||''),
      listenerIds: [...new Set((Array.isArray(turn.listenerIds) ? turn.listenerIds : Array.isArray(turn.listeners) ? turn.listeners : [])
        .map(value => String(value || "").trim()).filter(Boolean))],
      text,
      spokenText: text,
      ...providerPerformance,
      metadata,
      plannedSpeechSeconds: Number(turn?.plannedSpeechSeconds ?? metadata.plannedSpeechSeconds) > 0
        ? Number(turn?.plannedSpeechSeconds ?? metadata.plannedSpeechSeconds)
        : 0,
      plannedAfterBeatSeconds: Number(turn?.plannedAfterBeatSeconds ?? metadata.plannedAfterBeatSeconds) >= 0
        ? Number(turn?.plannedAfterBeatSeconds ?? metadata.plannedAfterBeatSeconds)
        : 0,
      ...(Number.isFinite(Number(turn?.startSecond ?? turn?.start ?? metadata.startSecond))
        ? { startSecond: Number(turn?.startSecond ?? turn?.start ?? metadata.startSecond) }
        : {}),
      ...(Number.isFinite(Number(turn?.endSecond ?? turn?.end ?? metadata.endSecond))
        ? { endSecond: Number(turn?.endSecond ?? turn?.end ?? metadata.endSecond) }
        : {}),
      onScreen: turn.onScreen !== false
        && !context.offscreenSpeakers?.has(speaker)
        && !context.offscreenSpeakers?.has(speakerId)
        && !context.offscreenSpeakers?.has(rawSpeaker),
      subshotNumber
    });
  };
  if (Object.prototype.hasOwnProperty.call(shot || {}, "videoPromptDialogueOverride")) {
    for (const turn of parseCompiledDialogueSegments(shot.videoPromptDialogueOverride, names)) push(turn, 1);
    return finish();
  }
  const subshots = Array.isArray(shot?.subshots) && shot.subshots.length
    ? shot.subshots
    : [];
  // Shot-level dialogueTurns are the canonical source ledger. Subshot dialogue
  // is allowed to describe where a line starts, continues off-screen, or lands
  // on a stressed word, but it must never create a second spoken copy.
  if (Array.isArray(shot?.dialogueTurns) && shot.dialogueTurns.length) {
    for (const turn of shot.dialogueTurns) {
      const requested = Math.max(1, Number(turn?.subshotNumber) || 1);
      const sourceId = String(turn?.sourceDialogueId || "").trim();
      const matchedIndex = sourceId
        ? subshots.findIndex(item => (Array.isArray(item?.sourceDialogueIds) ? item.sourceDialogueIds : []).map(String).includes(sourceId))
        : -1;
      const index = matchedIndex >= 0 ? matchedIndex : Math.min(subshots.length - 1, requested - 1);
      const subshot = index >= 0 ? subshots[index] : null;
      const offscreenSpeakers = new Set();
      for (const value of Array.isArray(subshot?.offscreenSpeakerIds) ? subshot.offscreenSpeakerIds : []) {
        const token = String(value || "").trim();
        if (!token) continue;
        offscreenSpeakers.add(token);
        const character = characters.find(item => item.id === token || item.name === token);
        if (character?.id) offscreenSpeakers.add(String(character.id));
        if (character?.name) offscreenSpeakers.add(String(character.name));
      }
      push(turn, index >= 0 ? index + 1 : requested, { offscreenSpeakers });
    }
    return finish();
  }
  const subshotDialoguePresent = subshots.some(item => String(item?.dialogue || "").trim() || (Array.isArray(item?.dialogueTurns) && item.dialogueTurns.length));
  if (subshotDialoguePresent) {
    for (const [index, subshot] of subshots.entries()) {
      const offscreenSpeakers = new Set();
      for (const value of Array.isArray(subshot?.offscreenSpeakerIds) ? subshot.offscreenSpeakerIds : []) {
        const token = String(value || "").trim();
        if (!token) continue;
        offscreenSpeakers.add(token);
        const character = characters.find(item => item.id === token || item.name === token);
        if (character?.id) offscreenSpeakers.add(String(character.id));
        if (character?.name) offscreenSpeakers.add(String(character.name));
      }
      if (Array.isArray(subshot?.dialogueTurns) && subshot.dialogueTurns.length) {
        for (const turn of subshot.dialogueTurns) push(turn, index + 1, { offscreenSpeakers });
      } else {
        for (const turn of parseCompiledDialogueSegments(subshot.dialogue, names)) push(turn, index + 1, { offscreenSpeakers });
      }
    }
    return finish();
  }
  // Empty block-local dialogue is authoritative. This guard survives store
  // round-trips and prevents a silent later generation block from inheriting
  // and repeating the parent shot's complete legacy dialogue string.
  if (shot?.dialogueTurnsAuthoritative === true || shot?.agentGenerationBlock) return finish();
  for (const turn of parseCompiledDialogueSegments(shot?.dialogue || "", names)) push(turn, 1);
  return finish();
}

function canonicalShotForVideoPrompt(project = {}, shot = {}) {
  // Accepted Agent directions are the authority, including their exact source
  // fingerprint. Display whitespace cleanup must not revive the legacy writer.
  if(shot.agentProductionDecision?.status==='authored'&&require('./h3-final-prompt-editor').current(shot))return structuredClone(shot);
  const irUnit = project?.foundry?.scriptUnderstanding?.productionIR?.units?.find(unit => String(unit.id || "") === String(shot?.id || ""));
  const compiledTurns = Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : [];
  const irTurns = Array.isArray(irUnit?.spokenTurns) ? irUnit.spokenTurns : [];
  const dialogueSignature = turn => [
    String(turn?.sourceDialogueId || turn?.id || "").trim(),
    String(turn?.speakerId || turn?.speaker || "").trim(),
    String(turn?.text || turn?.spokenText || "").trim()
  ].join("\u241f");
  const irMatchesCurrentLedger = irTurns.length === compiledTurns.length
    && irTurns.every((turn, index) => dialogueSignature(turn) === dialogueSignature(compiledTurns[index]));
  const compiledTurnsById = new Map(compiledTurns
    .map((turn, index) => [String(turn?.sourceDialogueId || turn?.id || `#${index}`), turn]));
  const preserveProviderPerformance = (turn, index) => {
    const compiled = compiledTurnsById.get(String(turn?.sourceDialogueId || turn?.id || `#${index}`)) || compiledTurns[index] || {};
    const providerFields = {};
    for (const key of [
      "deliveryEn", "vocalArcEn", "expressionEn", "expressionArcEn", "faceEn", "bodyEn", "blockingEn",
      "speakerFacingEn", "listenerFacingEn", "eyelineEn", "listenerReactionEn", "listenerBeatEn", "performanceEn",
      "deliveryZh", "vocalArcZh", "expressionZh", "bodyZh", "blockingZh", "speakerFacingZh", "listenerReactionZh"
    ]) {
      if (String(compiled?.[key] || "").trim()) providerFields[key] = compiled[key];
    }
    const timingFields = {};
    for (const key of ["startSecond", "endSecond", "plannedSpeechSeconds", "plannedAfterBeatSeconds", "subshotNumber"]) {
      const value = turn?.[key] ?? compiled?.[key];
      if (Number.isFinite(Number(value))) timingFields[key] = Number(value);
    }
    return {
      ...turn,
      ...timingFields,
      ...providerFields,
      metadata: {
        ...(turn?.metadata || {}),
        ...(compiled?.metadata || {}),
        ...providerFields
      }
    };
  };
  const canonicalShotSource = irUnit ? {
    ...shot,
    // productionIR and the Chinese editing稿 must share one exact dialogue
    // authority. Provider-only performance fields are overlaid by immutable
    // sourceDialogueId, never by array position alone when an ID is available.
    // IR is a derived cache. Matching words/IDs do not prove that its older
    // structured tone/rate fields are current. Preserve the complete reviewed
    // turn before overlaying provider fields, including sourceTone and the
    // argument/dialogue clock; otherwise saving/importing assets can silently
    // turn an 8-cps confrontation into a 5.5-cps line and discard final editing.
    dialogueTurns: (irMatchesCurrentLedger ? irTurns.map((turn,index)=>({...turn,...compiledTurns[index]})) : compiledTurns)
      .map(preserveProviderPerformance),
    action: shot.action || irUnit.silentDirections?.action,
    visualBeat: shot.visualBeat || irUnit.silentDirections?.visualBeat,
    stateBefore: shot.stateBefore || irUnit.silentDirections?.stateBefore,
    stateAfter: shot.stateAfter || irUnit.silentDirections?.stateAfter
  } : shot;
  return sanitizeShotVisualCues(canonicalShotSource);
}

function renderApprovedVideoPrompt(project = {}, shot = {}, references = {}) {
  const canonicalShot = canonicalShotForVideoPrompt(project, shot);
  const turns = uniqueDialogueTurns(project, canonicalShot);
  const assetDirect = normalizeProjectMode(project?.generation?.mode) === "asset_direct";
  const imageRoles = Array.isArray(references?.imageRoles)
    ? references.imageRoles
    : [
      ...(assetDirect ? [] : [{ type: "storyboard_sheet", entityId: shot?.id }]),
      ...(shot?.sceneId && sceneReferenceRequired(project, shot) ? [{ type: "scene", entityId: shot.sceneId }] : []),
      ...normalizeStringArray(shot?.characterIds).map(id => ({ type: "character", entityId: id }))
    ];
  const images = Array.isArray(references?.images)
    ? references.images
    : imageRoles.map((_item, index) => `bound-image-${index + 1}`);
  // Only the explicit manifest can establish an audio input. A selected voice
  // option or a dialogue owner does not prove any audio was actually supplied.
  const audios = references.referenceAudioMode !== "image_only" && turns.length && Array.isArray(references.audios)
    ? references.audios : [];
  return compactFullReferencePrompt(buildApprovedHailuoPrompt({
      project,
      shot: canonicalShot,
      references: { ...references, images, imageRoles, audios },
      dialogueTurns: turns
  }));
}

function chineseAuthoringValue(value, fallback = "") {
  const text = promptPerformanceText(value);
  if (!text) return String(fallback || "").trim();
  const hanCount = (text.match(/[\u3400-\u9fff]/g) || []).length;
  const latinCount = (text.match(/[A-Za-z]/g) || []).length;
  return hanCount > 0 && hanCount * 3 >= latinCount
    ? text
    : String(fallback || "").trim();
}

function sanitizeShotVisualCues(shot = {}) {
  const visualFields = ["action", "visualBeat", "stateBefore", "stateAfter", "startFrame", "endFrame", "audioPlan", "soundDesign"];
  const next = { ...shot };
  for (const field of visualFields) {
    if (shot?.[field] !== undefined) next[field] = sanitizeVisualPromptCue(shot[field]);
  }
  next.subshots = Array.isArray(shot?.subshots) ? shot.subshots.map(item => ({
    ...item,
    action: sanitizeVisualPromptCue(item?.action),
    visualBeat: sanitizeVisualPromptCue(item?.visualBeat),
    stateBefore: sanitizeVisualPromptCue(item?.stateBefore),
    stateAfter: sanitizeVisualPromptCue(item?.stateAfter),
    sound: sanitizeVisualPromptCue(item?.sound)
  })) : shot?.subshots;
  next.dialogueTurns = Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns.map(turn => ({
    ...turn,
    body: sanitizeVisualPromptCue(turn?.body),
    listenerBeat: sanitizeVisualPromptCue(turn?.listenerBeat),
    metadata: turn?.metadata ? {
      ...turn.metadata,
      body: sanitizeVisualPromptCue(turn.metadata.body),
      listenerBeat: sanitizeVisualPromptCue(turn.metadata.listenerBeat)
    } : turn?.metadata
  })) : shot?.dialogueTurns;
  return next;
}

function renderApprovedVideoPromptChinese(project = {}, shot = {}, references = {}) {
  // The provider receives the official English six-section prompt. This local
  // Chinese mirror is review-only and must never replace the execution prompt.
  const integrated = renderApprovedVideoPrompt(project, shot, references);
  if (require('./h3-final-prompt-editor').current(shot)) {
    return `【最终视频提示词中文对照｜${shot.id}｜${shot.duration}秒】\n模式与参考编号以同页英文正式提交稿为准；以下为同一动作时间线的完整中文译文。\n${shot.finalPromptEditing.detailedDescriptionZh}`;
  }
  if (/^integrated_multimodal_description（多模态综合描述）/u.test(integrated)) return integrated;
  shot = canonicalShotForVideoPrompt(project, shot);
  const duration = Math.max(1, Number(shot?.duration) || 10);
  const assetDirect = normalizeProjectMode(project?.generation?.mode) === "asset_direct";
  const characters = Array.isArray(project?.characters) ? project.characters : [];
  const characterByToken = token => {
    const key = String(token || "").trim();
    return characters.find(item => String(item?.id || "") === key || String(item?.name || "") === key) || null;
  };
  const characterLabel = token => {
    const character = characterByToken(token);
    if (!character) return String(token || "未指定角色").trim() || "未指定角色";
    const id = String(character.id || "").trim();
    return id && id !== character.name ? `${character.name}｜${id}` : String(character.name || id || "未指定角色");
  };
  const turns = uniqueDialogueTurns(project, shot);
  const timing = dialogueTimingPlan(turns, duration);
  const visibleCharacterIds = [...new Set([
    ...normalizeStringArray(shot?.characterIds),
    ...normalizeStringArray(shot?.visibleCharacterIds),
    ...turns.flatMap(turn => [turn?.speakerId || turn?.speaker, ...normalizeStringArray(turn?.listenerIds)])
  ].filter(Boolean))];
  const audioIndexByCharacter = new Map((Array.isArray(references?.audios) ? references.audios : [])
    .map((audio, index) => [String(audio?.characterId || audio?.characterName || "").trim(), index + 1])
    .filter(([id]) => id));
  const dialogueLines = turns.map((turn, index) => {
    const slot = timing.slots[index] || { start: 0, end: timing.speechSpan };
    const speakerToken = String(turn?.speakerId || turn?.speaker || "").trim();
    const speaker = characterLabel(speakerToken);
    const explicitListeners = normalizeStringArray(turn?.listenerIds);
    const listeners = (explicitListeners.length
      ? explicitListeners
      : visibleCharacterIds.filter(id => String(id) !== speakerToken))
      .map(characterLabel)
      .filter(Boolean);
    const audioIndex = audioIndexByCharacter.get(speakerToken)
      || audioIndexByCharacter.get(String(characterByToken(speakerToken)?.name || ""))
      || 0;
    const metadata = turn?.metadata || {};
    const toneSource = turn?.deliveryZh || metadata?.deliveryZh || turn?.sourceTone || metadata?.delivery || metadata?.tone || metadata?.emotion || shot?.emotion || "";
    const tone = chineseAuthoringValue(toneSource, inferDeliveryTone(toneSource || shot?.emotion, stageEmotionIntensity(shot?.mainlineStage)));
    const vocalArc = chineseAuthoringValue(turn?.vocalArcZh || metadata?.vocalArcZh, `音量、声调、语速、停顿、重音和气息围绕【${tone}】从起句到压力词再到句尾形成清楚起伏`);
    const expression = chineseAuthoringValue(turn?.expressionZh || metadata?.expressionZh || turn?.emotionPeak || metadata?.emotionPeak, "眼神、眉峰、下颌、呼吸和微表情从起句情绪推进到压力点，并在句尾留下余震");
    const body = chineseAuthoringValue(turn?.bodyZh || metadata?.bodyZh || metadata?.body || turn?.body || "", "身体重心、手部动作和呼吸随语义与重音产生可见变化");
    const reaction = chineseAuthoringValue(turn?.listenerReactionZh || metadata?.listenerReactionZh || metadata?.listenerReaction || metadata?.listenerBeat || turn?.listenerReaction || turn?.listenerBeat || "", "闭口，并针对这句话的含义用眼神、呼吸、下颌或身体重心给出同步反应");
    const speakerIndex = Math.max(0, visibleCharacterIds.findIndex(id => String(id) === speakerToken));
    const listenerToken = explicitListeners[0] || visibleCharacterIds.find(id => String(id) !== speakerToken) || "";
    const speakerSide = speakerIndex % 2 === 0 ? "画面左侧" : "画面右侧";
    const listenerSide = speakerSide === "画面左侧" ? "画面右侧" : "画面左侧";
    const blocking = chineseAuthoringValue(turn?.blockingZh || metadata?.blockingZh || turn?.blocking || metadata?.blocking, `说话人【${speaker}】稳定在${speakerSide}，${listenerToken ? `听者【${characterLabel(listenerToken)}】稳定在${listenerSide}` : "视线目标保持在既定方向"}，前后景距离和遮挡关系连续`);
    const facing = chineseAuthoringValue(turn?.speakerFacingZh || metadata?.speakerFacingZh || turn?.speakerFacing || metadata?.speakerFacing, `说话人脸部、眼球和上半身朝向${listeners.length ? `听者【${listeners.join("、")}】` : "既定视线目标"}，以可读三分之四侧脸说话，机位始终位于180度视线轴同一侧，不朝镜头或虚空念词`);
    const ownership = turn?.onScreen === false
      ? `说话人【${speaker}】位于画外，本段画面内所有人物闭口，不生成任何可见口型`
      : `镜头与口型只属于说话人【${speaker}】，不得转移给其他人物`;
    return `${slot.start.toFixed(1)}—${slot.end.toFixed(1)}秒：${ownership}；${audioIndex ? `只使用【音频${audioIndex}｜${speaker}】的声线` : `只使用【${speaker}】自己的既定声线`}；语气与声调【${vocalArc}】；表情弧线【${expression}】；站位【${blocking}】；朝向与视线【${facing}】；肢体动作【${body}】；${listeners.length ? `听者【${listeners.join("、")}】闭口反应【${reaction}】` : "其他可见人物全部闭口反应"}；逐字对白「${String(turn?.text || turn?.spokenText || "").trim()}」。`;
  });
  if (!dialogueLines.length) {
    dialogueLines.push(`0.0—${duration.toFixed(1)}秒：本镜无对白，所有可见人物始终闭口，只完成原稿规定的动作与反应。`);
  } else if (timing.speechSpan < duration - 0.05) {
    dialogueLines.push(`${timing.speechSpan.toFixed(1)}—${duration.toFixed(1)}秒：对白结束，所有人物闭口，以呼吸、眼神、身体和道具动作完成本镜结尾状态。`);
  }

  const imageRoles = Array.isArray(references?.imageRoles) ? references.imageRoles : [];
  const referenceLines = imageRoles.map((role, index) => {
    const type = String(role?.type || "").trim();
    if (type === "storyboard_timeline_panel") {
      const panel = Math.max(1, Number(role?.panelIndex) + 1 || Number(role?.sequenceIndex) || index + 1);
      const start = Number.isFinite(Number(role?.startSecond)) ? Number(role.startSecond).toFixed(1) : "对应";
      const end = Number.isFinite(Number(role?.endSecond)) ? Number(role.endSecond).toFixed(1) : "时段";
      return `图片${index + 1}：逐秒分镜第${panel}格，严格作为${start}—${end}秒的构图、人物站位、动作状态和景别依据。`;
    }
    if (["storyboard_sheet", "storyboard_take_sheet", "storyboard_generation_block_sheet"].includes(type)) {
      return `图片${index + 1}：本镜逐秒分镜合图，按从左到右、从上到下的顺序执行全部画格，不得只停留在第一格。`;
    }
    if (type === "storyboard_start") return `图片${index + 1}：本镜精确首帧，作为动作开始前的状态。`;
    if (type === "storyboard_end") return `图片${index + 1}：本镜精确尾帧，作为动作完成后的状态。`;
    if (type === "scene") {
      const scene = (project?.scenes || []).find(item => item.id === role?.entityId);
      return `图片${index + 1}：场景【${scene?.name || role?.entityId || "当前场景"}】，锁定空间布局、门窗家具、时间、光线和轴线。`;
    }
    if (type === "character") return `图片${index + 1}：人物【${characterLabel(role?.entityId || role?.characterId)}】，只锁定该人物的脸、发型、年龄和服装身份。`;
    if (type === "product") return `图片${index + 1}：商品【${project?.product?.name || "用户上传商品"}】，只锁定真实外观、材质、比例和使用方式。`;
    if (type === "prop") return `图片${index + 1}：剧情道具参考，锁定外观与持有关系。`;
    if (type === "wardrobe") return `图片${index + 1}：服装参考，锁定对应人物的服装连续性。`;
    return `图片${index + 1}：本镜相关视觉参考，只按原稿用途使用。`;
  });
  if (!referenceLines.length) referenceLines.push(assetDirect
    ? "本镜不使用分镜图；提交时只绑定已确认的人物、场景和剧情物品/商品资产，本镜不传参考音频。"
    : "本镜按已确认的人物、场景和分镜结构执行，提交时自动绑定实际参考素材。");
  const audioLines = (Array.isArray(references?.audios) ? references.audios : []).map((audio, index) => (
    `音频${index + 1}：只属于人物【${characterLabel(audio?.characterId || audio?.characterName)}】，仅锁定该人物声线，禁止借给其他人物。`
  ));
  const referenceAudioEnabled = audioLines.length > 0;

  const subshots = Array.isArray(shot?.subshots) ? shot.subshots : [];
  const providerTimeline = Array.isArray(shot?.providerTimedDirections)
    ? shot.providerTimedDirections.filter(item => Number.isFinite(Number(item?.start)) && Number.isFinite(Number(item?.end)))
    : [];
  const usesProviderTimeline = providerTimeline.length > 0;
  const visualSources = usesProviderTimeline ? providerTimeline : subshots;
  const alignedVisualWindows = dialogueAlignedVisualWindows(shot, turns, duration);
  const visualLines = visualSources.length
    ? visualSources.map((item, index) => {
      const sourceSubshot = subshots[index] || {};
      // The provider builder aligns legacy/un-timed segments to actual speaker
      // cuts.  Mirror that same final schedule in the Chinese editor; otherwise
      // the user can approve one cut time while H3 receives another.  A fully
      // AI-authored timing plan remains authoritative in both languages.
      const aligned = alignedVisualWindows[index] || {};
      const useAlignedSchedule = !timing.authoredTimingAdequate
        && Number.isFinite(Number(aligned.start))
        && Number.isFinite(Number(aligned.end));
      const start = useAlignedSchedule
        ? Number(aligned.start)
        : (Number.isFinite(Number(item?.start)) ? Number(item.start) : duration * index / visualSources.length);
      const end = useAlignedSchedule
        ? Number(aligned.end)
        : (Number.isFinite(Number(item?.end)) ? Number(item.end) : duration * (index + 1) / visualSources.length);
      const framing = chineseAuthoringValue(item?.framingZh || sourceSubshot?.framing || sourceSubshot?.shotSize, "按当前说话人与动作结果选择合适景别");
      const camera = chineseAuthoringValue(item?.cameraZh || sourceSubshot?.camera || sourceSubshot?.cameraMove, "机位稳定，人物说话交替时按说话人切换正反打");
      const blocking = chineseAuthoringValue(item?.blockingZh || sourceSubshot?.blocking || sourceSubshot?.position || sourceSubshot?.eyelineDirection, "明确人物左右/前后站位、彼此朝向和视线轴，并保持相邻时段连续");
      const backgroundAction = chineseAuthoringValue(item?.backgroundActionZh || sourceSubshot?.backgroundAction || sourceSubshot?.ensembleAction || sourceSubshot?.listenerReaction, "");
      const segmentFallback = index === 0
        ? chineseAuthoringValue(shot?.action || shot?.visualBeat, "推进本镜唯一因果动作并形成可见变化")
        : "承接上一时段已经到达的状态，只完成本时段明确安排的反应与收束动作，不重复此前动作";
      const action = chineseAuthoringValue(item?.actionZh || sourceSubshot?.action || sourceSubshot?.visualBeat, segmentFallback);
      const stateBefore = chineseAuthoringValue(item?.stateBeforeZh || sourceSubshot?.stateBefore, "");
      const stateAfter = chineseAuthoringValue(item?.stateAfterZh || sourceSubshot?.stateAfter, "");
      const stateTransition = stateBefore || stateAfter
        ? `；状态${stateBefore ? `从【${stateBefore}】` : "承接上一时段"}${stateAfter ? `推进到【${stateAfter}】` : "继续推进"}`
        : "";
      return `${start.toFixed(1)}—${end.toFixed(1)}秒：${framing}；${camera}；站位朝向【${blocking}】；${action}${backgroundAction ? `；背景/听者反应【${backgroundAction}】` : ""}${stateTransition}。`;
    })
    : [`0.0—${duration.toFixed(1)}秒：${chineseAuthoringValue(shot?.compositionPlan || shot?.shotSize, "按当前说话人与动作结果选择合适景别")}；${chineseAuthoringValue(shot?.cameraMove, turns.length > 1 ? "人物说话交替时按说话人切换正反打，镜头始终落在当前说话人" : "镜头围绕当前剧情动作稳定推进")}；${chineseAuthoringValue(shot?.action || shot?.visualBeat, "推进原稿规定的因果动作并形成清晰可见的结尾状态")}。`];

  const currentNumber = Number(shot?.number) || Number(String(shot?.id || "").match(/\d+/)?.[0]) || 0;
  const previousRawShot = (Array.isArray(project?.shots) ? project.shots : [])
    .filter(item => String(item?.id || "") !== String(shot?.id || ""))
    .filter(item => (Number(item?.number) || Number(String(item?.id || "").match(/\d+/)?.[0]) || 0) < currentNumber)
    .sort((left, right) => (Number(right?.number) || 0) - (Number(left?.number) || 0))[0] || null;
  const previousShot = previousRawShot ? canonicalShotForVideoPrompt(project, previousRawShot) : null;
  const previousSceneId = String(previousShot?.sceneId || previousShot?.sceneName || previousShot?.scene || "").trim();
  const currentSceneId = String(shot?.sceneId || shot?.sceneName || shot?.scene || "").trim();
  const sameScene = Boolean(previousShot && previousSceneId && currentSceneId && previousSceneId === currentSceneId);
  const previousState = chineseAuthoringValue(previousShot?.stateAfter || previousShot?.endFrame, "上一镜最终人物站位、表情、服装、道具持有和动作结果");
  const currentState = chineseAuthoringValue(shot?.stateBefore || shot?.startFrame, "本镜原稿规定的开场状态");
  const transitionReason = chineseAuthoringValue(shot?.transitionReason || shot?.causalLink || shot?.cutReason, sameScene
    ? "沿同一因果动作继续推进"
    : "按原稿给出的因果理由完成场景切换");
  const crossShotHandoff = previousShot
    ? `跨镜承接：从镜头${previousShot?.number || previousShot?.id || "上一镜"}的结束状态【${previousState}】直接进入本镜开场状态【${currentState}】；${transitionReason}；${sameScene ? "同一场景内保持人物左右/前后站位、朝向、视线轴、服装、道具持有和情绪余波，不跳位、不重演上一镜。" : `场景由【${previousSceneId || "上一场景"}】切到【${currentSceneId || "当前场景"}】，必须用原稿动作或因果结果完成有动机的转场，不得无理由瞬移、换人或重置人物状态。`}`
    : `跨镜承接：这是首镜，从原稿开场状态【${currentState}】开始，不虚构前置动作。`;

  return [
    `【镜头${shot?.number || shot?.id || ""}｜分镜视频中文编辑稿】`,
    assetDirect
      ? `制作参数：竖屏${project?.generation?.aspectRatio || "9:16"}；时长${duration.toFixed(1)}秒；资产直投 H3，不使用首帧、尾帧或逐秒分镜合图；由人物、场景、剧情物品/商品参考图直接连续演绎；${referenceAudioEnabled ? "同时使用已绑定的可选音色参考。" : "不传参考音频，中文台词由人物图和逐字文本原生发声。"}`
      : `制作参数：竖屏${project?.generation?.aspectRatio || "9:16"}；时长${duration.toFixed(1)}秒；按已确认分镜顺序连续演绎。`,
    `参考素材：\n${referenceLines.join("\n")}${audioLines.length ? `\n${audioLines.join("\n")}` : ""}`,
    crossShotHandoff,
    `逐秒对白、说话人和口型：\n${dialogueLines.join("\n")}`,
    `画面与切镜时间线：\n${visualLines.join("\n")}`,
    assetDirect
      ? `连续性：人物脸型、发型、年龄、服装、${referenceAudioEnabled ? "已绑定音色、" : "角色一致的原生声线、"}场景布局、光线、人物左右/前后站位、彼此朝向、视线落点、180度轴线、道具/商品持有关系和上一时刻动作状态连续一致；资产仅锁定身份与空间，不作为剧情画面；本镜动作建立、对白、听者反应、原稿指定的群像切镜和动作结果必须完整执行。`
      : `连续性：人物脸型、发型、年龄、服装、场景布局、光线、人物左右/前后站位、彼此朝向、视线落点、180度轴线、道具持有关系和上一时刻动作状态连续一致；逐秒分镜中的每一格都必须被执行，不得只复现第一格。`,
    `声音：${referenceAudioEnabled ? "使用已绑定的可选音色参考；" : "本镜不传参考音频；"}每句对白只说一次，只由该句指定说话人开口并${referenceAudioEnabled ? "使用其绑定音色" : "依据人物身份保持角色一致的原生声线"}；听者闭口反应；保留连续环境底噪和与动作同步的现场声。`
  ].join("\n\n");
}

function renderApprovedVideoPromptLegacyUnused(project = {}, shot = {}) {
  const duration = Math.max(10, Math.min(15, Number(shot?.duration) || 12));
  const characters = new Map((Array.isArray(project?.characters) ? project.characters : [])
    .map(item => [String(item?.id || "").trim(), String(item?.name || item?.id || "").trim()]));
  const scene = (project?.scenes || []).find(item => item.id === shot?.sceneId || item.name === shot?.scene);
  const turns = uniqueDialogueTurns(project, shot);
  const characterNames = [...characters.values()].filter(Boolean);
  const cleanNarrativeAction = value => {
    const candidate = String(value || "").replace(/^【背景\/动作[:：]?|】$/g, "").trim();
    if (!candidate) return "";
    const directSpeakerLabel = characterNames.some(name => candidate.startsWith(`${name}：`) || candidate.startsWith(`${name}:`));
    const directedSpeakerLabel = characterNames.some(name => (candidate.startsWith(`${name}（`) && candidate.includes("）：")) || (candidate.startsWith(`${name}(`) && candidate.includes("):")));
    if (directSpeakerLabel || directedSpeakerLabel) return "";
    if (/^#{1,6}\s*(?:S|SC)\d+|^【(?:无对白|商品动作|商品说明|制作说明|分镜说明)/i.test(candidate)) return "";
    return candidate.replace(/[。！？!?]{2,}$/g, match => match.charAt(0));
  };
  const weights = turns.map(turn => Math.max(1, String(turn.text || "").replace(/[^\u3400-\u9fffA-Za-z0-9]/g, "").length));
  const totalWeight = weights.reduce((sum, value) => sum + value, 0) || 1;
  const reactionTail = turns.length ? Math.min(0.8, Math.max(0.4, duration * 0.12)) : duration;
  const speechSpan = Math.max(0, duration - reactionTail);
  let cursor = 0;
  const timeline = [];
  turns.forEach((turn, index) => {
    const start = cursor;
    const end = index === turns.length - 1 ? speechSpan : start + speechSpan * (weights[index] / totalWeight);
    cursor = end;
    const speaker = turn.speaker || characters.get(turn.speakerId) || turn.speakerId || "未绑定角色";
    const listener = (turn.listenerIds || []).map(id => characters.get(String(id)) || id).filter(Boolean).join("、") || "明确听者";
    const meta = turn.metadata || {};
    const tone = turn.sourceTone || meta.sourceTone || meta.delivery || "按当前处境自然起伏";
    const rawEmotion = meta.emotionPeak || meta.emotion || turn.emotionPeak || shot.emotion || "";
    const emotionPhases = [
      "先压住本能反应，被事实刺中后眼神收紧",
      "防御感被逼出，语气与呼吸开始失稳",
      "情绪冲到本镜峰值，重音和身体动作同时落下",
      "峰值回落但立场更硬，句尾留下清楚余震"
    ];
    const rawBody = meta.body || turn.body || "面部、手部和重心随台词发生可见变化";
    const fallbackEmotion = emotionPhases[Math.min(emotionPhases.length - 1, Math.floor(index * emotionPhases.length / Math.max(1, turns.length)))];
    const emotion = !rawEmotion || rawEmotion === tone || rawEmotion === shot.emotion
      ? fallbackEmotion
      : rawEmotion;
    const body = rawBody === tone || rawBody === rawEmotion ? "眉眼、呼吸、手部和重心随重音发生可见变化" : rawBody;
    const rawListenerBeat = meta.listenerBeat || turn.listenerBeat || "眼神、呼吸或手部给出同步反应";
    const listenerBeat = rawListenerBeat.startsWith(listener)
      ? rawListenerBeat
      : /^听者/.test(rawListenerBeat)
        ? rawListenerBeat.replace(/^听者/, listener)
        : /^闭口/.test(rawListenerBeat)
          ? `${listener}${rawListenerBeat}`
          : `${listener}闭口并${rawListenerBeat}`;
    timeline.push(`${start.toFixed(1)}-${end.toFixed(1)}秒：${speaker}面向${listener}，${tone}；${emotion}；说：“${turn.text}”——${body}；${listenerBeat}。`);
  });
  if (!turns.length) timeline.push(`0.0-${duration.toFixed(1)}秒：本镜无对白，人物闭口，只执行可见动作和同步环境声。`);
  timeline.push(`${speechSpan.toFixed(1)}-${duration.toFixed(1)}秒：对白结束后保留呼吸、眨眼、衣料或道具微动，落到“${shot.stateAfter || shot.endFrame || "新的可见状态"}”。`);
  const action = cleanNarrativeAction(shot.action) || cleanNarrativeAction(shot.visualBeat);
  const subshots = Array.isArray(shot.subshots) ? shot.subshots : [];
  const camera = subshots.length
    ? subshots.map((item, index) => `${Number(item.start) || 0}-${Number(item.end) || duration}秒${index + 1}段：${item.framing || "中近景"}，${item.camera || "稳定机位"}，${cleanNarrativeAction(item.action) || action || "说话人完成台词动作，听者给出同步可见反应"}；切换：${item.transition || "按对白、视线或动作结果硬切"}`).join("\n")
    : `0-${duration}秒：${shot.compositionPlan || "说话人近景与听者反应正反打"}；${shot.cameraMove || "稳定机位，按说话人变化硬切"}。`;
  const product = shot.productMention ? `商品：只按用户上传的“${project.product?.name || "用户商品"}”原图和真实卖点，在本镜剧情动作需要时出现；不得新增功效、价格或口播。` : "商品：不出现。";
  return [
    `${shot.id || "SXX"}分镜视频提示词。竖屏9:16，写实真人短剧，严格${duration}秒。`,
    "对白优先级：对白内容＞语气＞情绪＞场景＞运镜＞其他。以下对白必须逐字完整说完，每句只说一次，当前说话人开口时其他人物闭口；不得把时间码、场景标题、动作说明、商品说明或制作备注当成对白。",
    `时间和完整台词：\n${timeline.join("\n")}`,
    `核心表演：${shot.emotion || "情绪从压抑、受刺激、峰值到余震/决定递进"}；${shot.performance || "眉眼、下颌、呼吸、手部和重心必须随每句台词发生可见变化，禁止平声念稿。"}`,
    `场景与动作：${scene?.name || shot.scene || "同一连续场景"}；${action || "只执行本镜唯一因果动作，并以听者的可见反应承接下一状态"}。`,
    `分镜与运镜：\n${camera}`,
    `声音：${shot.audioPlan || shot.soundDesign || "连续现场环境底噪，动作声与对白同步；禁止BGM、配乐、字幕、水印和旁白。"}`,
    product,
    "SPOKEN CONTENT BOUNDARY: only the actual dialogue text may be spoken verbatim; scene headings, actions, camera directions, emotions, timecodes, asset bindings and quality rules are silent production metadata and must never be narrated, voiced, subtitled or rendered as readable text. If uncertain, keep the character silent.",
    "连续性：人物脸、年龄、发型、服装、站位、持物手、180度视线轴、场景门窗家具和主光保持不变；不新增人物，不串角，不换场，不冻结尾帧。"
  ].join("\n");
}

function nestedReferenceManifests(referenceManifest = null) {
  if (!referenceManifest || typeof referenceManifest !== "object") return [];
  const manifests = [referenceManifest];
  for (const block of Array.isArray(referenceManifest.generationBlocks) ? referenceManifest.generationBlocks : []) {
    manifests.push(...nestedReferenceManifests(block?.referenceManifest));
  }
  return manifests;
}

function referenceManifestAudios(referenceManifest = null) {
  const seen = new Set();
  const audios = [];
  for (const manifest of nestedReferenceManifests(referenceManifest)) {
    for (const item of Array.isArray(manifest?.audios) ? manifest.audios : []) {
      const key = [item?.characterId, item?.sha256, item?.filePath].map(value => String(value || "")).join("|");
      if (!key.replace(/\|/g, "") || seen.has(key)) continue;
      seen.add(key);
      audios.push(item);
    }
  }
  return audios;
}

function referenceManifestVisualControls(referenceManifest = null) {
  const seen = new Set();
  const controls = [];
  const unsafeTypes = new Set([
    "character", "scene", "product", "prop", "wardrobe",
    "storyboard_sheet", "storyboard_take_sheet", "storyboard_generation_block_sheet"
  ]);
  for (const manifest of nestedReferenceManifests(referenceManifest)) {
    for (const item of Array.isArray(manifest?.images) ? manifest.images : []) {
      const type = String(item?.type || "").trim();
      const sourceStage = String(item?.sourceStage || "").trim();
      const filePath = String(item?.filePath || item?.path || "").trim();
      if (!filePath || !fs.existsSync(filePath)) continue;
      // A generated shot is expected to resemble its exact opening/ending
      // story frame. These are live-scene anchors, not forbidden asset boards.
      // Keep storyboard sheets and every identity/set/prop board in the leak
      // audit, but never punish faithful animation of a sanctioned story frame.
      if (["storyboard_start", "storyboard_end", "storyboard_panel_anchor"].includes(type)) continue;
      if (!unsafeTypes.has(type)
        && !/(?:character_(?:intro|sheet|three_view)|scene_asset|prop_asset|wardrobe_asset|product_asset|storyboard_sheet)/i.test(sourceStage)) continue;
      const key = path.resolve(filePath).toLowerCase();
      if (seen.has(key)) continue;
      seen.add(key);
      controls.push({ ...item, type, sourceStage, filePath });
    }
  }
  return controls;
}

function candidateHasHailuoDialogueMode(candidate = {}) {
  // A manually imported, operator-selected clip is already materialized media;
  // it did not travel through an H3 request mode at all.  Requiring an H3 mode
  // marker here made every reusable/manual shot in an H3 project stale on the
  // next reconciliation pass.
  if (candidate.manualSelectionOverride === true || candidate.qualityAudit?.mode === "manual") return true;
  const resolvedMode = normalizeHailuoApiMode(candidate.hailuoResolvedMode || candidate.hailuoRequestedMode || "auto");
  // H3 reference-to-video supports prompt-authored native dialogue even when
  // the operator intentionally selects image-only references.  Treating that
  // official mode as voice-lineage-incompatible caused a successfully
  // downloaded clip to be marked stale solely because no optional voice file
  // was supplied.
  if (["multimodal_to_video", "image_to_video", "reference_to_video"].includes(resolvedMode)) return true;
  const blocks = Array.isArray(candidate.referenceManifest?.generationBlocks)
    ? candidate.referenceManifest.generationBlocks.map(item => item?.referenceManifest).filter(Boolean)
    : [];
  if (!blocks.length) return false;
  return blocks.length > 0 && blocks.every(manifest => {
    const categories = hailuoMediaCategories(manifest);
    const hasVisualReference = categories.includes("image") || categories.includes("video");
    const hasAudioReference = categories.includes("audio");
    return hasVisualReference && (!hasAudioReference || categories.length >= 2);
  });
}

function hailuoVoiceLineageAudit(project, shot, candidate, currentVoiceSha = new Map()) {
  const speakerIds = shotSpeakingCharacterIds(project, shot);
  const audios = referenceManifestAudios(candidate?.referenceManifest);
  const generationBlockManifests = Array.isArray(candidate?.referenceManifest?.generationBlocks)
    ? candidate.referenceManifest.generationBlocks.map(item => item?.referenceManifest).filter(Boolean)
    : [];
  const providerBlockVoiceOverflow = (generationBlockManifests.length
    ? generationBlockManifests
    : [candidate?.referenceManifest || {}]
  ).some(manifest => new Set(referenceManifestAudios(manifest).map(item => item.characterId).filter(Boolean)).size > 2);
  const changedBoundVoice = audios.some(item => {
    const expectedSha = currentVoiceSha.get(item.characterId);
    return !expectedSha || item.sha256 !== expectedSha;
  });
  const extraSpeakerVoice = audios.some(item => item.characterId && !speakerIds.includes(item.characterId));
  const badMode = !candidateHasHailuoDialogueMode(candidate);
  const unknownSpeakers = [...(speakerIds.unknownSpeakers || [])];
  return {
    ok: !unknownSpeakers.length && !badMode && !changedBoundVoice && !extraSpeakerVoice && !providerBlockVoiceOverflow,
    unknownSpeakers,
    badMode,
    changedBoundVoice,
    extraSpeakerVoice,
    providerBlockVoiceOverflow,
    speakerIds: [...speakerIds]
  };
}

const GENERATED_VIDEO_PROMPT_LIMIT = 1200;

function compactPromptValue(value, limit) {
  const normalized = String(value || "").replace(/\s+/g, " ").trim();
  if (!limit || normalized.length <= limit) return normalized;
  return `${normalized.slice(0, Math.max(0, limit - 1)).trim()}…`;
}

function compactGeneratedImagePrompt(prompt, stage = "", maxLength = 1850) {
  const source = String(prompt || "").replace(/\r/g, "").trim();
  const limit = Math.max(800, Math.min(1950, Number(maxLength) || 1850));
  if (source.length <= limit) return source;
  const clauses = source.split(/\n+/).map(item => item.replace(/\s+/g, " ").trim()).filter(Boolean);
  const high = item => /不可变|输出形态|最高优先级|参考图编号|商品硬锁定|本镜强制人物|逐秒节拍|首帧强制状态|尾帧必须不同|场景四视图|2×2|合图|接触印|格数|panel|grid|canvas|gutter/i.test(item);
  const medium = item => /人物|身份|服装|场景|道具|商品|动作|表演|时序|起始|结束|镜头/i.test(item);
  const ordered = [
    ...clauses.filter(high),
    ...clauses.filter(item => !high(item) && medium(item)),
    ...clauses.filter(item => !high(item) && !medium(item))
  ];
  const stageLock = imageSafetyStageContract(stage, "zh");
  const result = [];
  let used = stageLock.length + 1;
  const seen = new Set();
  for (const clause of ordered) {
    const key = clause.replace(/[\s，。；、：:！？!?]/g, "").toLowerCase();
    if (!key || seen.has(key)) continue;
    seen.add(key);
    const remaining = limit - used - 1;
    if (remaining < 24) break;
    const value = compactPromptValue(clause, Math.min(remaining, high(clause) ? 520 : 260));
    if (!value) continue;
    result.push(value);
    used += value.length + 1;
  }
  return [stageLock, ...result].join("\n").slice(0, limit).trim();
}

function isPromptTooLongError(error) {
  return /PROMPT_TOO_LONG|prompt.{0,12}(?:too long|length|limit)|提示词.{0,10}(?:过长|超长|超限)/i.test(`${error?.code || ""} ${error?.message || ""}`);
}

/**
 * Rebuild every generated H3 prompt from canonical shot data and keep it
 * inside the conservative 1,200-character compatibility budget. This removes
 * internal Agent labels such as listenerBeat/subshot/matrix/product enums that
 * the video model may reject as unknown keywords. Manual prompts never enter
 * this compiler.
 */
function compactGeneratedH3VideoPrompt(project, shot, references = {}, mode = "", prompt = "", maxLength = GENERATED_VIDEO_PROMPT_LIMIT, qualityRepair = "", qualityRepairKey = "") {
  void prompt;
  const limit = Math.max(800, Math.min(GENERATED_VIDEO_PROMPT_LIMIT, Number(maxLength) || GENERATED_VIDEO_PROMPT_LIMIT));

  // Generated video payloads describe the clean narrative image positively.
  // Naming a specific post-production text artefact makes video models attend to
  // that concept. Keep exact dialogue untouched, but neutralize legacy/custom
  // production metadata before it enters the provider payload. Static
  // storyboard-image prompts retain their explicit no-readable-text contract.
  const stripScreenTextPriming = value => {
    const original = String(value || "").replace(/\r/g, "").trim();
    const concept = /字幕|字卡|对白文字|旁白文字|姓名条|价格文字|价格字|可读文字|屏幕文字|subtitles?|captions?|title\s*cards?|dialogue\s*text|narration\s*text|readable\s*(?:on[- ]screen\s*)?text/i;
    const clauses = original
      .split(/(?<=[。！？!?])\s*|[；;\n]+/)
      .map(item => item.trim())
      .filter(item => item && !concept.test(item));
    const positive = concept.test(original)
      ? (/[^\x00-\x7f]/.test(original)
        ? "保持干净、连续的真人剧情摄影，只呈现本镜叙事空间、人物表演、商品动作和必要道具。"
        : "Keep clean continuous live-action story photography showing only this shot's story space, performance, product action and necessary props.")
      : "";
    return [positive, ...clauses]
      .filter(Boolean)
      .join(" ")
      .replace(/\s+/g, " ")
      .trim();
  };

  const turns = uniqueDialogueTurns(project, shot);
  const stripInternalAgentLabels = value => String(value || "")
    .replace(/\bsubshot\s*(\d+)\b/gi, "第$1机位")
    .replace(/\blistenerBeat\s*=/gi, "听者反应=")
    .replace(/\bproduct_packshot\b/gi, "商品自然整体特写")
    .replace(/\bproduct_detail\b/gi, "商品关键细节特写")
    .replace(/\bproduct_use\b/gi, "商品真实使用动作")
    .replace(/\bproduct_result\b/gi, "商品使用后的客观结果")
    .replace(/\bproduct_reaction\b/gi, "受益者自然反应")
    .replace(/\bspeaker_closeup\b/gi, "说话人单人近景")
    .replace(/\blistener_reaction\b/gi, "听者反应近景")
    .replace(/\btwo_shot\b/gi, "双人关系镜头")
    .replace(/\baction_insert\b/gi, "关键动作特写")
    .replace(/\bevidence_insert\b/gi, "证据细节特写")
    .replace(/\b(?:confess|attack|deflect|counter|reveal|decision|delivery|intent)\b/gi, "")
    .replace(/\b(?:h3|cloud):(?:keyframe|continuation|smart|storyboard_sheet)\b/gi, "")
    .replace(/承接\s*S\d+/gi, "承接上一镜")
    .replace(/\s+/g, " ")
    .trim();
  const stripDialogueEchoes = value => {
    let text = stripInternalAgentLabels(value);
    for (const turn of turns) {
      const exact = String(turn.text || "").trim();
      const bare = exact.replace(/[。！？!?]+$/g, "");
      for (const variant of [...new Set([exact, bare].filter(Boolean))]) {
        text = text.split(variant).join("");
      }
    }
    return text
      .replace(/['“”]{2,}/g, "")
      .replace(/[；，、]\s*[；，、]/g, "；")
      .replace(/\s+/g, " ")
      .trim();
  };
  const dialogueLines = turns.map(turn => {
    const listeners = (turn.listenerIds || []).map(id => (
      (project.characters || []).find(character => character.id === id || character.name === id)?.name || id
    )).filter(Boolean);
    const meta = turn.metadata || {};
    const tone = turn.sourceTone || meta.sourceTone || meta.delivery || meta.emotion || shot.emotion || "符合剧情的生活化情绪语气";
    const semanticBeat = /[\u3400-\u9fff]/.test(String(meta.beat || "")) ? meta.beat : "";
    const acting = [meta.body, semanticBeat, meta.emotionPeak, meta.breath].filter(Boolean).join("；") || shot.performance || "脸、身体与声线同步表演";
    const reaction = meta.listenerBeat || (listeners.length ? "听者闭嘴并给出同步可见反应" : "");
    return `角色“${turn.speaker}”${listeners.length ? `面对${listeners.join("、")}` : ""}；语气=${tone}；表演=${stripDialogueEchoes(acting)}${reaction ? `；听者反应=${stripDialogueEchoes(reaction)}` : ""}；只说一遍：${turn.text}`;
  });
  const dialogueContract = dialogueLines.length
    ? `【对白最高优先级·逐字完整】${dialogueLines.join("；")}；说话人、听者和音色不得互换，每句只说一遍。`
    : "【对白】本镜无对白，禁止新增台词或画外音。";
  const hardContract = "【成片正向边界】写实竖屏纯剧情摄影；身份、服装、商品、场景与参考素材一致；镜头按剧情从首态推进到肉眼不同的尾态；画面只呈现叙事空间、人物表演、商品动作与必要道具，保持干净且不叠加后期图形层、标识、界面或可读内容；声音只由逐字对白、连续现场环境底噪和同步动作声构成；参考板、资产卡与制作信息只作控制依据，不进入成片。";
  const qualityRepairId = qualityRepair
    ? crypto.createHash("sha256").update(`${qualityRepair}\u0000${qualityRepairKey || "repair"}`).digest("hex").slice(0, 12)
    : "";
  const repairContract = qualityRepair
    ? `【技术修复批次${qualityRepairId}】本次必须生成全新候选，不得复用上次结果；${compactPromptValue(stripScreenTextPriming(qualityRepair), 180)}`
    : "";

  if (dialogueContract.length + hardContract.length + repairContract.length + 3 > limit) {
    // A single short video unit should never contain this much dialogue. Keep
    // every authored word and only drop optional prose; do not silently damage
    // the user's script to satisfy a provider limit.
    return [dialogueContract, repairContract, hardContract].filter(Boolean).join("\n");
  }

  const imageManifest = (references.imageRoles || []).map((item, index) => `图${index + 1}=${item.label || item.type || "参考资产"}`).join("；");
  const videoManifest = (references.videoRoles || []).map((item, index) => `视频${index + 1}=${item.label || item.type || "上一镜"}`).join("；");
  const audioManifest = (references.audios || []).map((item, index) => `音频${index + 1}=${item.characterName || "角色"}音色`).join("；");
  const scene = (project.scenes || []).find(item => item.id === shot.sceneId);
  const performanceBeats = Array.isArray(shot.performanceBeats)
    ? shot.performanceBeats
    : shot.performanceBeats && typeof shot.performanceBeats === "object"
      ? Object.values(shot.performanceBeats)
      : shot.performanceBeats
        ? [shot.performanceBeats]
        : [];
  const sheetPanelAnchor = mode === "storyboard_sheet"
    && String(references.imageRoles?.[0]?.type || "") === "storyboard_panel_anchor";
  const modeLabel = mode === "storyboard_sheet"
    ? (sheetPanelAnchor
      ? "图1是从逐秒合图安全裁出的干净剧情起点，只锁定场景、人物和动作起态；第一帧直接进入剧情并继续人物动作"
      : "按逐秒合图从左到右、从上到下演绎，禁止把格线和序号生成进成片")
    : mode === "continuation"
      ? "从上一视频末态无缝继续，禁止重演、重置或切换空间"
      : "首帧到尾帧形成连续因果动作，禁止中途换空间";
  const productDirectives = [shot.productRole, shot.productAction, shot.productShotType]
    .filter(value => String(value || "").trim() && !/^(?:none|无|不植入)$/i.test(String(value).trim()));
  const productSection = project.product?.name
    ? `用户上传商品硬绑定：${[project.product.name, ...productDirectives].join("；")}`
    : productDirectives.join("；");
  const optionalSections = [
    ["剧情动作", shot.action || shot.visualBeat || shot.shotFunction, 300],
    ["表演推进", [shot.emotion, shot.performance, ...performanceBeats].filter(Boolean).join("；"), 320],
    ["镜头调度", [shot.shotSize, shot.cameraMove, shot.compositionPlan, shot.transitionReason].filter(Boolean).join("；"), 230],
    ["模式", modeLabel, 150],
    ["参考素材", [imageManifest, videoManifest, audioManifest].filter(Boolean).join("；"), 250],
    ["场景", [scene?.name, scene?.description, shot.stateBefore, shot.stateAfter].filter(Boolean).join("；"), 220],
    ["商品", productSection, 220],
    ["声音", shot.audioPlan || shot.soundDesign || "对白清晰，环境底噪连续，只保留同步动作声", 160]
  ];

  const parts = [dialogueContract, repairContract].filter(Boolean);
  let used = dialogueContract.length + repairContract.length + hardContract.length + 3;
  for (const [label, value, preferred] of optionalSections) {
    if (!String(value || "").trim()) continue;
    const remaining = limit - used - label.length - 4;
    if (remaining < 24) continue;
    const body = compactPromptValue(stripScreenTextPriming(stripDialogueEchoes(value)), Math.min(preferred, remaining));
    const section = `【${label}】${body}`;
    parts.push(section);
    used += section.length + 1;
  }
  parts.push(hardContract);
  return parts.join("\n").slice(0, limit).trim();
}

function assertSystemPromptDialogueParity(project, shot, prompt, engine = projectVideoEngine(project), references = null) {
  const turns = uniqueDialogueTurns(project, shot);
  if (!turns.length) return true;
  const text = String(prompt || "");
  const expectedCounts = new Map();
  for (const turn of turns) expectedCounts.set(turn.text, (expectedCounts.get(turn.text) || 0) + 1);
  const failures = [];
  if (engine === "hailuo-h3") {
    const canonical = require("./drama-staging-contract").canonicalizeStagingShot(project, shot, turns);
    failures.push(...require("./drama-staging-contract").stagingContractFailures(project, canonical.shot, prompt, references));
  }
  if (engine === "hailuo-h3" && shot.performanceTimelineVersion === "performance-timeline-v1") {
    failures.push(...require("./drama-performance-timeline").performanceTimelineFailures(shot, text));
  }
  const normalizedLine = value => String(value || "").replace(/[\s，。！？!?、；;：:"“”‘’'\-—]/g, "").trim();
  const seenSourceIds = new Set();
  for (let index = 0; index < turns.length; index += 1) {
    const current = turns[index];
    const sourceId = String(current?.sourceDialogueId || "").trim();
    if (sourceId && seenSourceIds.has(sourceId)) failures.push(`sourceDialogueId ${sourceId} 在同一分镜重复绑定，禁止生成两次配音`);
    if (sourceId) seenSourceIds.add(sourceId);
    const previous = turns[index - 1];
    if (previous
      && normalizedLine(previous.text) === normalizedLine(current.text)
      && String(previous.speakerId || previous.speaker) === String(current.speakerId || current.speaker)
      && Number(current.subshotNumber || 1) - Number(previous.subshotNumber || 1) <= 1) {
      failures.push(`相邻分镜重复对白“${current.text}”，必须合并为一个sourceDialogueId或改为新的剧情信息`);
    }
  }
  for (const [line, expected] of expectedCounts) {
    const actual = line ? text.split(line).length - 1 : 0;
    if (actual !== expected) failures.push(`台词“${line}”应在视频提示词出现${expected}次，实际${actual}次`);
  }
  if (engine === "hailuo-h3") {
    const orderedSpeakerIds = [...new Set(turns.map(turn => String(
      turn.speakerId || (project.characters || []).find(item => item.name === turn.speaker)?.id || ""
    ).trim()).filter(Boolean))];
    for (const [turnIndex, turn] of turns.entries()) {
      const taggedMarker = `<d>[Chinese] ${turn.text}</d>`;
      const containingLine = text.split("\n").find(line => line.includes(taggedMarker)) || "";
      const tagOffset = containingLine.indexOf(taggedMarker);
      const precedingTagEnd = containingLine.lastIndexOf("</d>", tagOffset);
      const ownerCandidates = [...containingLine.slice(Math.max(0, precedingTagEnd + 4), tagOffset).matchAll(/<Subject\s+\d+>\s+\(S\d+\)\s+(?:faces|remains)/g)];
      const ownerOffset = ownerCandidates.at(-1)?.index;
      const dialogueLine = ownerOffset === undefined ? containingLine : containingLine.slice(Math.max(0, precedingTagEnd + 4) + ownerOffset);
      if (!dialogueLine) failures.push(`海螺提示词缺少逐字原话：${turn.sourceDialogueId || turn.text}`);
      const stableSpeakerId = String(turn.speakerId || (project.characters || []).find(item => item.name === turn.speaker)?.id || "").trim();
      const stableOwnership = stableSpeakerId
        ? new RegExp(`(?:speaker=${stableSpeakerId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")};\\s*mouth=<Subject\\s+\\d+>\\/camera|(?:^|\\s)${stableSpeakerId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}:<Subject\\s+\\d+>\\/mouth\\+camera\\/<Audio\\s+\\d+>->)`).test(dialogueLine)
        : /speaker=[^;]+;\s*mouth=<Subject\s+\d+>\/camera/.test(dialogueLine);
      const expectedSpeakerNumber = Math.max(1, orderedSpeakerIds.indexOf(stableSpeakerId) + 1);
      // Official H3 ownership is carried by the Subject/Speaker token pair,
      // not by a Chinese display name. A monologue can correctly face a
      // mirror or another established scene focal point instead of a listener.
      const officialOwner = dialogueLine.match(/(<Subject\s+\d+>)\s+\(S(\d+)\)\s+(?:(?:faces\s+[^\n;]+?|remains\s+off-screen|remains\s+outside\s+the\s+frame)\s+and\s+(?:speaks\s+once|says\s+exactly\s+once))/i);
      const officialOwnership = Boolean(officialOwner
        && Number(officialOwner[2]) === expectedSpeakerNumber
        && (new RegExp(`Only\\s+${officialOwner[1].replace(/[.*+?^${}()|[\]\\]/g, "\\$&")}\\s+\\(S${expectedSpeakerNumber}\\)\\s+moves\\s+the\\s+lips`, "i").test(dialogueLine)
          || /remains\s+(?:off-screen|outside\s+the\s+frame)[\s\S]+No\s+visible\s+mouth\s+moves/i.test(dialogueLine)));
      const escapedSpeakerId = stableSpeakerId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      const integratedOwnership = /^integrated_multimodal_description（多模态综合描述）/u.test(text.trim())
        && (!stableSpeakerId || dialogueLine.includes(`人物 ${stableSpeakerId}`))
        && (new RegExp(`仅人物\\s+${escapedSpeakerId}(?:\\s|（)[^。]*开口并驱动口型`).test(dialogueLine)
          || (dialogueLine.includes(`人物 ${stableSpeakerId}`) && /位于画外；画面内所有人物全程闭口/.test(dialogueLine)));
      const naturalOwnership = require('./h3-natural-dialogue-ownership').naturalDialogueOwnership(text, {...turn, speakerId:stableSpeakerId}, turnIndex, expectedSpeakerNumber, {structuredSource:require("./shot-screenplay").runtimeCurrent(project) && require("./h3-final-prompt-editor").current(shot)});
      if (turn.speaker && !/<Subject\s+\d+>(?:\/<Audio\s+\d+>)?->/.test(dialogueLine) && !stableOwnership && !officialOwnership && !integratedOwnership && !naturalOwnership) {
        failures.push(`海螺提示词未把“${turn.text}”绑定给说话人“${turn.speaker}”`);
      }
    }
  } else {
    for (const turn of turns) {
      const speakerMarker = `角色“${turn.speaker}”`;
      const speakerPosition = text.indexOf(speakerMarker);
      const linePosition = text.indexOf(turn.text, Math.max(0, speakerPosition));
      if (speakerPosition < 0 || linePosition < speakerPosition) failures.push(`H3提示词未把“${turn.text}”绑定给说话人“${turn.speaker}”`);
    }
  }
  if (failures.length) {
    throw Object.assign(new Error(`视频提示词未通过上传剧本逐句校验：${failures.join("；")}`), {
      code: "VIDEO_PROMPT_DIALOGUE_PARITY_FAILED",
      failures,
      shotId: shot?.id || ""
    });
  }
  return true;
}

/** Only narrative fields count here. Reference metadata itself must not be mistaken for an on-screen product. */
function shotContractText(shot = {}) {
  const fields = [
    shot.title,
    shot.action,
    shot.visualBeat,
    shot.dialogue,
    shot.startFrame,
    shot.endFrame,
    shot.imagePrompt,
    shot.videoPrompt,
    shot.systemImagePrompt,
    shot.systemVideoPrompt,
    shot.manualImagePrompt,
    shot.manualVideoPrompt,
    shot.performance,
    shot.compositionPlan,
    shot.mainlineBeat,
    shot.stateBefore,
    shot.stateAfter,
    shot.causalLink,
    Array.isArray(shot.propNames) ? shot.propNames.join("；") : shot.propNames,
    shot.productCausalBridge ? JSON.stringify(shot.productCausalBridge) : "",
    shot.hailuoPromptSpec ? JSON.stringify(shot.hailuoPromptSpec) : "",
    Array.isArray(shot.subshots) ? JSON.stringify(shot.subshots) : "",
    Array.isArray(shot.secondPanels) ? JSON.stringify(shot.secondPanels) : ""
  ];
  return fields.map(value => String(value || "")).join("\n");
}

function openingHookContractFailures(shots = [], options = {}) {
  const ordered = (Array.isArray(shots) ? shots : [])
    .slice()
    .sort((left, right) => (Number(left?.number) || Number(String(left?.id || "").replace(/\D/g, "")) || 0)
      - (Number(right?.number) || Number(String(right?.id || "").replace(/\D/g, "")) || 0));
  const shot = ordered[0];
  if (!shot) return [{ code: "OPENING_HOOK_MISSING", shotId: "S01", message: "缺少开场生成单元 S01" }];
  const shotId = shot.id || "S01";
  const failures = [];
  const stage = String(shot.mainlineStage || "").toLowerCase();
  if (!/hook|钩子|冷开场/.test(stage)) {
    failures.push({ code: "OPENING_HOOK_STAGE", shotId, message: `${shotId}必须明确标记为 hook 冷开场，不能用普通铺垫或慢叙事开场` });
  }
  const openingSubshots = (shot.subshots || []).filter(item => (Number(item?.start) || 0) < 8);
  const actionText = [shot.title, shot.action, shot.visualBeat, ...openingSubshots.map(item => item.action)].join(" ");
  const visibleCrisis = /抢走|夺走|扯下|拽住|砸碎|砸门|摔倒|扔掉|撕毁|撕碎|推倒|推开|扇耳光|拦住|锁门|赶出|断电|拔管|昏倒|倒地|流血|逼跪|踹倒|按住|拖走|掀翻|泼水|扣住|救人|冲撞|当众翻脸|当众辱骂|拍桌|拍在(?:餐桌|桌面|桌上)|(?:摔|砸|掷|甩)地|(?:摔|砸|掷|甩)[^，。；]{0,12}(?:地面|地上|墙上|门上|桌上|纸箱|垃圾堆)|踢(?:飞|进|开|翻|倒|碎|向|下|出|落)|逼[^，。；]{0,12}(?:签字|签协议|按指纹|摁手印)|(?:按|摁)(?:下|向)?(?:指纹|手印)|(?:手指|食指)点向[^，。；]{0,12}(?:脸|面前)/.test(actionText);
  if (!visibleCrisis) {
    failures.push({ code: "OPENING_VISIBLE_CRISIS", shotId, message: `${shotId}前8秒必须有正在发生、能直接看懂的危机动作，不能只靠站桩解释` });
  }
  // scenePresence/legacy characters describe continuity, not necessarily who is rendered.
  // Once the director supplies explicit visible IDs, those IDs are the sole visual truth;
  // otherwise old projects fall back to characterIds/characters for a safe local audit.
  const explicitVisible = [
    ...normalizeStringArray(shot.visibleCharacterIds),
    ...openingSubshots.flatMap(item => normalizeStringArray(item?.visibleCharacterIds))
  ].map(String).filter(Boolean);
  const fallbackVisible = [
    ...normalizeStringArray(shot.characterIds),
    ...normalizeStringArray(shot.characters),
    ...openingSubshots.flatMap(item => [
      ...normalizeStringArray(item?.characterIds),
      ...normalizeStringArray(item?.characters)
    ])
  ].map(String).filter(Boolean);
  const cast = [...new Set(explicitVisible.length ? explicitVisible : fallbackVisible)];
  if (cast.length < 1 || cast.length > 2) {
    failures.push({ code: "OPENING_FOCUS_CAST", shotId, message: `${shotId}开场主画面必须聚焦1–2人，当前${cast.length}人；见证者、家属或权威人物需要时拆到相邻单人反应/入场镜，禁止挤进危机主镜` });
  }
  if (options.requireDialogue !== false) {
    const subshots = Array.isArray(shot.subshots) ? shot.subshots : [];
    const firstDialogueSubshot = subshots.find(item => String(item?.dialogue || "").trim());
    const dialogueSource = firstDialogueSubshot?.dialogue || shot.dialogue || "";
    const firstTurn = parseDialogueSegments(dialogueSource, [])[0];
    const startsAt = firstDialogueSubshot ? Number(firstDialogueSubshot.start) || 0 : 0;
    const length = String(firstTurn?.text || "").replace(/[^\u4e00-\u9fffA-Za-z0-9]/g, "").length;
    if (!firstTurn || startsAt > 2) {
      failures.push({ code: "OPENING_DIALOGUE_DELAY", shotId, message: `${shotId}必须在前2秒开口，禁止长时间空镜或旁白热场` });
    } else if (length < 6 || length > 12 || !/[？?!！]|凭什么|还敢|住手|滚|你也配|谁让|别碰|放开|跪下/.test(String(firstTurn.text || ""))) {
      failures.push({ code: "OPENING_DIALOGUE_PUNCH", shotId, message: `${shotId}第一句必须是6-12字、带质问/制止/打脸语气的短句，当前约${length}字` });
    }
  }
  return failures;
}

/** Non-negotiable production contracts remain active even when subjective quality scoring is disabled. */
const PRODUCT_CAUSAL_BRIDGE_ALIASES = Object.freeze({
  situationNeed: ["situationNeed", "currentProblem"],
  whyNow: ["whyNow"],
  action: ["action"],
  observableOutcome: ["observableOutcome", "visibleEffect"],
  relationOrDecisionShift: ["relationOrDecisionShift", "relationShift"]
});

function productCausalBridgeValue(bridge = {}, semanticField = "") {
  const aliases = PRODUCT_CAUSAL_BRIDGE_ALIASES[semanticField] || [semanticField];
  return aliases.map(key => String(bridge?.[key] || "").trim()).find(Boolean) || "";
}

function normalizeProductCausalBridge(value) {
  const source = value && typeof value === "object" && !Array.isArray(value) ? { ...value } : {};
  return {
    ...source,
    situationNeed: productCausalBridgeValue(source, "situationNeed"),
    whyNow: productCausalBridgeValue(source, "whyNow"),
    action: productCausalBridgeValue(source, "action"),
    observableOutcome: productCausalBridgeValue(source, "observableOutcome"),
    relationOrDecisionShift: productCausalBridgeValue(source, "relationOrDecisionShift")
  };
}

// Gemini sometimes returns the locked product action/result while omitting the
// bridge object.  Fill only missing semantic fields from text already present
// in the authored shot; this is metadata completion, never plot generation.
function deriveProductCausalBridge(shot = {}, product = {}, options = {}) {
  const productName = String(product?.name || options.productName || "").trim();
  if (!productName || shot?.productMention !== true) return normalizeProductCausalBridge(shot?.productCausalBridge);
  const existing = normalizeProductCausalBridge(shot?.productCausalBridge);
  const sourceCandidates = [
    shot.action,
    shot.visualBeat,
    shot.stateBefore,
    shot.causalLink,
    shot.stateAfter,
    shot.startFrame,
    shot.endFrame,
    shot.performance,
    ...(Array.isArray(shot.subshots) ? shot.subshots.flatMap(subshot => [subshot?.action, subshot?.dialogue]) : []),
    shot.dialogue
  ].map(value => String(value || "").replace(/\s+/g, " ").trim()).filter(Boolean);
  const sourceText = sourceCandidates.join("；");
  const compact = value => String(value || "").replace(/\s+/g, " ").trim().slice(0, 180);
  const actionCandidates = [
    ...(Array.isArray(shot.subshots) ? shot.subshots.map(subshot => subshot?.action) : []),
    shot.action,
    shot.visualBeat,
    shot.performance
  ].map(compact).filter(Boolean);
  const productAction = actionCandidates.find(value => value.includes(productName))
    || actionCandidates[0]
    || compact(sourceText)
    || productName;
  const outcome = [
    ...(Array.isArray(shot.subshots) ? shot.subshots.slice().reverse().map(subshot => subshot?.action) : []),
    shot.stateAfter,
    shot.endFrame,
    shot.action,
    shot.visualBeat
  ].map(compact).filter(Boolean).find(value => value.includes(productName))
    || compact(shot.stateAfter)
    || compact(shot.action)
    || productAction;
  const characters = Array.isArray(options.characters) ? options.characters : [];
  const visibleIds = normalizeStringArray(shot.visibleCharacterIds);
  const visibleNames = visibleIds.map(id => {
    const record = characters.find(item => String(item?.id || "").trim() === id);
    return String(record?.name || id).trim();
  }).filter(Boolean);
  const actorLabel = visibleNames.join("、");
  const needSource = compact(shot.stateBefore) || compact(shot.causalLink) || compact(shot.action) || productAction;
  const whySource = compact(shot.causalLink) || compact(shot.stateBefore) || compact(shot.action) || productAction;
  const relationSource = compact(shot.stateAfter) || outcome || productAction;
  const derived = {
    situationNeed: `本镜原稿已成立的情境需求：${needSource}`,
    whyNow: `承接原稿既有动作，${productName}在此刻进入该行动：${whySource}`,
    action: `${productName}按原稿可见动作：${productAction}`,
    observableOutcome: `本镜可直接观察到的结果：${outcome}`,
    relationOrDecisionShift: actorLabel
      ? `${actorLabel}在本镜完成原稿已写明的关系或决定动作：${relationSource}`
      : ""
  };
  return {
    ...existing,
    situationNeed: existing.situationNeed || derived.situationNeed,
    whyNow: existing.whyNow || derived.whyNow,
    action: existing.action || derived.action,
    observableOutcome: existing.observableOutcome || derived.observableOutcome,
    relationOrDecisionShift: existing.relationOrDecisionShift || derived.relationOrDecisionShift
  };
}

const PRODUCT_SHIFT_VISIBLE_ACTION_PATTERN = /决定|答应|同意|承诺|配合|商量|改口|接过|递给|交给|交出|扶起|搀扶|分享|整理|保留|选择|购买|使用|翻阅|查看|收纳|送给|带走|留下|托住|坐下|起身|道歉|原谅|拒绝|推荐|记录|记账|签字|拥抱|握手|归还|安排|执行/;

function productShiftCharacterRecords(normalized = {}) {
  return (Array.isArray(normalized?.characters) ? normalized.characters : []).map((item, index) => ({
    id: String(item?.id || `C${String(index + 1).padStart(2, "0")}`).trim().toUpperCase(),
    name: String(item?.name || (typeof item === "string" ? item : "")).trim()
  })).filter(item => item.id || item.name);
}

function productRelationShiftVisibilityFailures(normalized = {}, shot = {}, index = 0) {
  const bridge = shot.productCausalBridge && typeof shot.productCausalBridge === "object" ? shot.productCausalBridge : {};
  const shift = productCausalBridgeValue(bridge, "relationOrDecisionShift");
  const records = productShiftCharacterRecords(normalized);
  if (!shift || !records.length) return [];
  const shotId = shot.id || `S${String(index + 1).padStart(2, "0")}`;
  const visibleTokens = new Set(normalizeStringArray(shot.visibleCharacterIds).map(value => value.toUpperCase()));
  const isVisible = record => visibleTokens.has(record.id) || (record.name && visibleTokens.has(record.name.toUpperCase()));
  const mentioned = records.filter(record => [record.id, record.name].filter(Boolean).some(token => shift.includes(token)));
  const offscreen = mentioned.filter(record => !isVisible(record));
  const failures = [];
  if (offscreen.length) {
    failures.push({
      code: "PRODUCT_RELATION_SHIFT_OFFSCREEN_CHARACTER",
      shotId,
      message: `${shotId}的 relationOrDecisionShift 写入未在本镜 visibleCharacterIds 出镜的人物：${offscreen.map(item => `${item.name || item.id}(${item.id})`).join("、")}；关系或决定变化只能由本镜出镜人物及其可见动作承载`
    });
  }
  const visibleMentioned = mentioned.filter(isVisible);
  const visibleActionText = [
    shift,
    shot.action,
    shot.visualBeat,
    shot.performance,
    ...(Array.isArray(shot.subshots) ? shot.subshots.map(item => item?.action) : [])
  ].map(value => String(value || "")).join("；");
  const hasVisibleActionCarrier = visibleMentioned.some(record => [record.id, record.name].filter(Boolean).some(token => {
    let position = visibleActionText.indexOf(token);
    while (position >= 0) {
      const window = visibleActionText.slice(Math.max(0, position - 18), position + token.length + 28);
      if (PRODUCT_SHIFT_VISIBLE_ACTION_PATTERN.test(window)) return true;
      position = visibleActionText.indexOf(token, position + token.length);
    }
    return false;
  }));
  if (!visibleMentioned.length || !hasVisibleActionCarrier) {
    failures.push({
      code: "PRODUCT_RELATION_SHIFT_VISIBLE_ACTION_MISSING",
      shotId,
      message: `${shotId}的 relationOrDecisionShift 必须点名本镜 visibleCharacterIds 中的人物，并由 action/visualBeat/subshots 的可见动作落实；禁止只写抽象关系变化或让未出镜人物完成决定`
    });
  }
  return failures;
}

function productionHardContractFailures(normalized = {}, options = {}) {
  const shots = (Array.isArray(normalized?.shots) ? normalized.shots : [])
    .slice()
    .sort((left, right) => (Number(left?.number) || Number(String(left?.id || "").replace(/\D/g, "")) || 0)
      - (Number(right?.number) || Number(String(right?.id || "").replace(/\D/g, "")) || 0));
  const failures = require("./commerce-authoring-policy").characterProductIssues(shots);
  if (options.requireDialogueTables !== false) {
  let openingElapsed = 0;
  const opening30 = [];
  for (const shot of shots) {
    if (openingElapsed < 30) opening30.push(shot);
    openingElapsed += Math.max(0, Number(shot?.duration) || 0);
    const stats = shotDialogueStats(shot);
    if (stats.turns < 1) {
      failures.push({
        code: "DIALOGUE_TABLE_EMPTY",
        shotId: shot?.id || "",
        message: `${shot?.id || "未编号分镜"}没有对白表；每个最终视频生成单元必须有完整台词，静默反应、动作留白和商品特写只能并入相邻有对白单元的内部子镜`
      });
    }
  }
  const openingTurns = opening30.flatMap(shot => Array.isArray(shot?.dialogueTurns)
    ? shot.dialogueTurns
    : parseDialogueSegments(String(shot?.dialogue || ""), []));
  const openingSpeakers = new Set(openingTurns.map(turn => String(turn?.speakerId || turn?.speaker || "").trim()).filter(Boolean));
  if (openingTurns.length < 3 || openingSpeakers.size < 2) {
    failures.push({
      code: "OPENING_30S_DIALOGUE_CLARITY",
      shotId: opening30[0]?.id || "S01",
      message: `前30秒必须用至少3句、至少2个明确说话人的因果对白讲清主角、关系、事件、冲突、目标和代价；当前${openingTurns.length}句、${openingSpeakers.size}个说话人`
    });
  }
  const openingStages = opening30.map(shot => String(shot?.mainlineStage || "").toLowerCase());
  const openingHasConflictTurn = openingStages.some(stage => /pressure|escalation|conflict|危机|冲突|加压/.test(stage))
    || opening30.slice(1).some(shot => String(shot?.dialogueArc?.exitConsequence || "").trim() && String(shot?.stateAfter || "").trim());
  if (!openingHasConflictTurn) {
    failures.push({
      code: "OPENING_30S_CONFLICT_TURN_MISSING",
      shotId: opening30.at(-1)?.id || "S01",
      message: "前30秒只有钩子或背景，没有明确的冲突升级和不可逆结果；至少一镜必须同时写清对话后果与stateAfter"
    });
  }
  }
  if (options.requireHook !== false) failures.push(...openingHookContractFailures(shots, { requireDialogue: options.requireHookDialogue !== false }));
  const totalDuration = shots.reduce((sum, shot) => sum + Math.max(0, Number(shot.duration) || 0), 0);
  const reversalIndexes = shots.map((shot, index) => String(shot.mainlineStage || "").trim() === "main_reversal" ? index : -1).filter(index => index >= 0);
  const reversalIndex = reversalIndexes[0] ?? -1;
  if (reversalIndexes.length !== 1) {
    failures.push({ code: "MAIN_REVERSAL_COUNT", shotId: "", message: `全剧必须且只能有1个 main_reversal，当前${reversalIndexes.length}个` });
  } else {
    const reversalWindow = mainReversalWindow(shots.length);
    const shotId = shots[reversalIndex]?.id || `S${String(reversalIndex + 1).padStart(2, "0")}`;
    if (reversalIndex < reversalWindow.startIndex || reversalIndex > reversalWindow.endIndex) {
      failures.push({
        code: "MAIN_REVERSAL_TIMING_WINDOW",
        shotId,
        message: `${shotId}主反转镜号中点位于全片${Math.round(((reversalIndex + 0.5) / Math.max(shots.length, 1)) * 100)}%处；`
          + `唯一 main_reversal 必须位于 S${String(reversalWindow.startIndex + 1).padStart(2, "0")}`
          + `-S${String(reversalWindow.endIndex + 1).padStart(2, "0")}（全片65%-80%），`
          + `优选 S${String(reversalWindow.preferredIndex + 1).padStart(2, "0")}`
      });
    }
    const reversalTimeRatio = mainReversalTimeRatio(shots, reversalIndex, totalDuration);
    if (reversalTimeRatio !== null && (reversalTimeRatio < 0.65 || reversalTimeRatio > 0.8)) {
      failures.push({
        code: "MAIN_REVERSAL_TIME_WINDOW",
        shotId,
        message: `${shotId}镜头中点位于全片${Math.round(reversalTimeRatio * 100)}%处；`
          + "唯一 main_reversal 的累计时长中点必须在65%-80%，优选约72%"
      });
    }
  }
  const productName = String(options.productName || normalized?.product?.name || "").trim();
  if (!productName) return failures;
  const semanticProductIndexes = [];
  for (const [index, shot] of shots.entries()) {
    const semanticMention = textMentionsProduct(shotContractText(shot), productName);
    const flagged = Boolean(shot.productMention);
    if (semanticMention) semanticProductIndexes.push(index);
    if (semanticMention && !flagged) {
      failures.push({
        code: "PRODUCT_FLAG_MISMATCH",
        shotId: shot.id || `S${String(index + 1).padStart(2, "0")}`,
        message: `${shot.id || `S${String(index + 1).padStart(2, "0")}`}实际写入了“${productName}”或俗称，但 productMention=false；商品窗口门禁因此失效`
      });
    }
    if (flagged && !semanticMention) {
      failures.push({
        code: "PRODUCT_FLAG_WITHOUT_CONTENT",
        shotId: shot.id || `S${String(index + 1).padStart(2, "0")}`,
        message: `${shot.id || `S${String(index + 1).padStart(2, "0")}`}仅设置 productMention=true，但剧情、动作、对白和提示词没有真实商品内容`
      });
    }
    if (semanticMention) {
      const bridge = shot.productCausalBridge && typeof shot.productCausalBridge === "object" ? shot.productCausalBridge : {};
      const bridgeKeys = ["situationNeed", "whyNow", "action", "observableOutcome", "relationOrDecisionShift"];
      const filled = bridgeKeys.filter(key => productCausalBridgeValue(bridge, key)).length;
      if (filled < 3) {
        failures.push({
          code: "PRODUCT_CAUSAL_BRIDGE_MISSING",
          shotId: shot.id || `S${String(index + 1).padStart(2, "0")}`,
          message: `${shot.id || `S${String(index + 1).padStart(2, "0")}`}商品入场缺少品类自适应因果桥，situationNeed/whyNow/action/observableOutcome/relationOrDecisionShift 至少写满3项，当前${filled}项；旧键可兼容承载同义内容`
        });
      }
      failures.push(...productRelationShiftVisibilityFailures(normalized, shot, index));
    }
  }
  if (!semanticProductIndexes.length) {
    if (options.requireProduct !== false) failures.push({ code: "PRODUCT_REQUIRED", shotId: "", message: `全剧没有在反转后安排“${productName}”的剧情动作` });
    return failures;
  }
  const productDuration = semanticProductIndexes.reduce((sum, index) => sum + Math.max(0, Number(shots[index]?.duration) || 0), 0);
  // The user controls commerce depth. A larger requested tail is intentional,
  // so never reject it with the old fixed 20% ceiling.
  // The late product chain scales with the real film length. A 6/7/10-minute
  // film must not inherit a fixed S27-S30 template, and a short film must not
  // surrender half its running time to product shots.
  if (shots.length >= 24 && totalDuration >= 240) {
  const tailRange = productTailRange(shots.length, Math.floor(shots.length * 0.65), totalDuration, options.commerceShotCount);
  const productTailStartIndex = Math.max(0, tailRange.startNumber - 1);
  const productTail = shots.slice(productTailStartIndex);
  const productTailStartId = shots[productTailStartIndex]?.id || `S${String(productTailStartIndex + 1).padStart(2, "0")}`;
  const productTailEndId = shots.at(-1)?.id || `S${String(shots.length).padStart(2, "0")}`;
  const tailProductFlags = productTail.map(shot => textMentionsProduct(shotContractText(shot), productName));
  let longestTailProductRun = 0;
  let currentTailProductRun = 0;
  for (const flagged of tailProductFlags) {
    currentTailProductRun = flagged ? currentTailProductRun + 1 : 0;
    longestTailProductRun = Math.max(longestTailProductRun, currentTailProductRun);
  }
  const requiredTailProductRun = Math.min(
    Math.max(1, Number(options.commerceShotCount) > 0 ? normalizeCommerceShotCount(options.commerceShotCount, 3) : 3),
    productTail.length
  );
  if (longestTailProductRun < requiredTailProductRun) {
    failures.push({
      code: "PRODUCT_TAIL_CHAIN_MISSING",
      shotId: productTailStartId,
      shotRange: { start: productTailStartId, end: productTailEndId },
      message: `${productTailStartId}-${productTailEndId}必须形成至少${requiredTailProductRun}镜连续的品类自适应商品因果链（真实情境/需求→自然品类动作→可观察合规结果→人物决定或关系变化），当前最长仅${longestTailProductRun}镜`
    });
  }
  const tailRoleContracts = [
    { code: "PRODUCT_TAIL_NEED_MISSING", fields: ["situationNeed", "whyNow"], label: "具体使用情境、真实需求与为什么此刻发生", expectedIndex: 0 },
    { code: "PRODUCT_TAIL_ACTION_MISSING", fields: ["action"], label: "符合商品品类的自然动作", expectedIndex: Math.min(1, productTail.length - 1) },
    { code: "PRODUCT_TAIL_OUTCOME_MISSING", fields: ["observableOutcome"], label: "可观察且合规的结果、体验或证据", expectedIndex: Math.max(0, productTail.length - 2) },
    { code: "PRODUCT_TAIL_DECISION_SHIFT_MISSING", fields: ["relationOrDecisionShift"], label: "人物决定、关系或生活方式变化与自然收束", expectedIndex: productTail.length - 1 }
  ];
  for (const role of tailRoleContracts) {
    const matchingShot = productTail.find(shot => {
      const bridge = shot?.productCausalBridge && typeof shot.productCausalBridge === "object" ? shot.productCausalBridge : {};
      return role.fields.every(field => productCausalBridgeValue(bridge, field));
    });
    if (matchingShot) continue;
    failures.push({
      code: role.code,
      shotId: productTail[Math.max(0, role.expectedIndex)]?.id || productTailStartId,
      shotRange: { start: productTailStartId, end: productTailEndId },
      message: `${productTailStartId}-${productTailEndId}缺少商品链职责“${role.label}”；可按品类和节奏在任一相邻商品镜合并，但必须在 productCausalBridge 明确填写 ${role.fields.join("+")}`
    });
  }
  // Commerce coverage follows the scene and present characters, not isolated packshots.
  }
  const firstIndex = semanticProductIndexes[0];
  const elapsed = shots.slice(0, firstIndex).reduce((sum, shot) => sum + Math.max(0, Number(shot.duration) || 0), 0);
  const ratio = totalDuration > 0 ? elapsed / totalDuration : firstIndex / Math.max(shots.length, 1);
  if (ratio < 0.65 || reversalIndex < 0 || firstIndex <= reversalIndex) {
    const shotId = shots[firstIndex]?.id || `S${String(firstIndex + 1).padStart(2, "0")}`;
    failures.push({
      code: "PRODUCT_EARLY_LEAK",
      shotId,
      message: `${shotId}在全剧${Math.round(ratio * 100)}%处已出现商品；必须同时晚于65%和唯一主反转（当前主反转${reversalIndex >= 0 ? `为S${String(reversalIndex + 1).padStart(2, "0")}` : "缺失"}）`
    });
  }
  return failures;
}

function assertProductionHardContracts(normalized = {}, options = {}) {
  const failures = productionHardContractFailures(normalized, options);
  if (failures.length) {
    throw Object.assign(new Error(`生产硬合同未通过：${failures.map(item => item.message).join("；")}`), {
      code: "PRODUCTION_HARD_CONTRACT_FAILED",
      failures
    });
  }
  return true;
}

function productionContractRepairShotIds(project = {}, failures = []) {
  const shots = (Array.isArray(project?.shots) ? project.shots : [])
    .slice()
    .sort((left, right) => (Number(left?.number) || Number(String(left?.id || "").replace(/\D/g, "")) || 0)
      - (Number(right?.number) || Number(String(right?.id || "").replace(/\D/g, "")) || 0));
  const known = new Set(shots.map((shot, index) => String(shot?.id || `S${String(index + 1).padStart(2, "0")}`)));
  const selected = new Set();
  const addNumber = number => {
    const shot = shots[Math.max(0, Math.min(shots.length - 1, Number(number) - 1))];
    if (shot?.id) selected.add(String(shot.id));
  };
  for (const failure of Array.isArray(failures) ? failures : []) {
    const direct = normalizeFailureShotId(failure?.shotId);
    if (direct && known.has(direct)) selected.add(direct);
    const range = normalizeFailureShotRange(failure?.shotRange || failure?.range);
    if (range) {
      for (let number = Number(range.start.slice(1)); number <= Number(range.end.slice(1)); number += 1) addNumber(number);
    }
    const code = String(failure?.code || "").toUpperCase();
    if (code.startsWith("MAIN_REVERSAL_")) {
      const window = mainReversalWindow(shots.length);
      // mainReversalWindow returns zero-based indexes. Convert only that exact
      // window to one-based shot numbers so a targeted repair never rewrites
      // valid neighbouring shots.
      for (let number = window.startIndex + 1; number <= window.endIndex + 1; number += 1) addNumber(number);
      shots.forEach((shot, index) => { if (String(shot?.mainlineStage || "") === "main_reversal") addNumber(index + 1); });
    }
    if (code === "PRODUCT_REQUIRED" || code.startsWith("PRODUCT_TAIL_")) {
      const totalDuration = shots.reduce((sum, shot) => sum + Math.max(0, Number(shot?.duration) || 0), 0);
      const tail = productTailRange(shots.length, Math.floor(shots.length * 0.65), totalDuration);
      for (let number = tail.startNumber; number <= shots.length; number += 1) addNumber(number);
    }
  }
  if (!selected.size && shots[0]?.id) selected.add(String(shots[0].id));
  return shots.map(shot => String(shot.id)).filter(id => selected.has(id));
}

function shotSpeakingCharacterIds(project, shot) {
  const characters = Array.isArray(project?.characters) ? project.characters : [];
  const ids = [];
  const unknownSpeakers = [];
  for (const turn of uniqueDialogueTurns(project, shot)) {
    const speaker = String(turn.speaker || "").trim();
    const character = characters.find(item => item.name === speaker || item.id === speaker);
    if (!character) {
      if (speaker && !unknownSpeakers.includes(speaker)) unknownSpeakers.push(speaker);
      continue;
    }
    if (!ids.includes(character.id)) ids.push(character.id);
  }
  Object.defineProperty(ids, "unknownSpeakers", { value: unknownSpeakers, enumerable: false });
  return ids;
}

function shotSemanticCharacterIds(project = {}, shot = {}) {
  const characters = Array.isArray(project?.characters) ? project.characters : [];
  const parts = [
    shot?.action,
    shot?.actionEn,
    shot?.visualBeat,
    shot?.visualBeatEn,
    shot?.stateBefore,
    shot?.stateBeforeEn,
    shot?.stateAfter,
    shot?.stateAfterEn,
    shot?.startFrame,
    shot?.endFrame,
    shot?.blocking,
    shot?.blockingEn,
    shot?.screenDirection,
    shot?.screenDirectionEn,
    shot?.performance,
    shot?.performanceEn
  ];
  for (const item of [
    ...(Array.isArray(shot?.providerTimedDirections) ? shot.providerTimedDirections : []),
    ...(Array.isArray(shot?.subshots) ? shot.subshots : []),
    ...(Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : [])
  ]) {
    if (item && typeof item === "object") parts.push(...Object.values(item));
    if (item?.metadata && typeof item.metadata === "object") parts.push(...Object.values(item.metadata));
    for (const turn of Array.isArray(item?.dialogueTurns) ? item.dialogueTurns : []) {
      parts.push(...Object.values(turn && typeof turn === "object" ? turn : {}));
      if (turn?.metadata && typeof turn.metadata === "object") parts.push(...Object.values(turn.metadata));
    }
  }
  const corpus = parts
    .flatMap(value => Array.isArray(value) ? value : [value])
    .map(value => typeof value === "string" || typeof value === "number" ? String(value) : "")
    .filter(Boolean)
    .join("\n");
  return characters
    .filter(character => {
      const id = String(character?.id || "").trim();
      const name = String(character?.name || "").trim();
      const escapedId = id.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
      return (id && new RegExp(`(^|[^A-Za-z0-9_])${escapedId}(?=$|[^A-Za-z0-9_])`, "i").test(corpus))
        || (name && corpus.includes(name));
    })
    .map(character => String(character.id));
}

function shotReferenceCharacterIds(project = {}, shot = {}) {
  if (require('./agent-production-decisions').current(project,shot)) return [...shot.agentProductionDecision.item.visibleCharacterIds];
  const visibleIds = visibleShotCharacterCast(project, shot);
  const speakingIds = shotSpeakingCharacterIds(project, shot);
  const directSpeakerIds = uniqueDialogueTurns(project, shot)
    .filter(turn => turn?.onScreen !== false)
    .map(turn => {
      const token = String(turn?.speakerId || turn?.speaker || "").trim();
      return (project.characters || []).find(character => character.id === token || character.name === token)?.id || "";
    })
    .filter(Boolean);
  const semanticIds = shotSemanticCharacterIds(project, shot);
  const knownIds = new Set((project.characters || []).map(item => String(item?.id || "")).filter(Boolean));
  const authoredIds = Array.isArray(shot.videoReferenceCharacterIds)
    ? shot.videoReferenceCharacterIds.map(String).filter(id => knownIds.has(id)
      && (visibleIds.includes(id) || speakingIds.includes(id) || semanticIds.includes(id)))
    : visibleIds;
  if (projectVideoEngine(project) !== "hailuo-h3") return authoredIds;
  // The declared visible cast is authoritative, including silent entrants.
  // An audio/speaker limit is not an image-identity limit.
  const assetCharacterIds = new Set(assetBearingCharacters(project).map(item => String(item.id)));
  const declaredVisibleIds = normalizeStringArray(shot.visibleCharacterIds);
  // A completed semantic plan has already resolved entrants and screen/voice
  // ownership. Mentioning someone in dialogue or "has not entered" is NOT a
  // request for that person's image. Legacy incomplete plans retain discovery.
  if (shot.providerSemanticCompileSource === "ai-batch" && Array.isArray(shot.visibleCharacterIds)) {
    return [...new Set([...directSpeakerIds, ...declaredVisibleIds])]
      .filter(id => knownIds.has(id));
  }
  return [...new Set([
    ...directSpeakerIds,
    ...declaredVisibleIds,
    ...visibleIds,
    ...speakingIds,
    ...semanticIds,
    ...authoredIds
  ])].filter(id => knownIds.has(id) && (directSpeakerIds.includes(id) || declaredVisibleIds.includes(id) || assetCharacterIds.has(id)));
}

function requiredHailuoVoiceCharacterIds(project) {
  const ids = [];
  const required = new Set((project?.characters || []).filter(character => (
    character.voiceAssetRequired === true
    || (character.voiceAssetRequired !== false && assetDecision(project, character).voiceAssetRequired)
  )).map(character => String(character.id)));
  for (const shot of project?.shots || []) {
    for (const id of shotSpeakingCharacterIds(project, shot)) if (required.has(String(id)) && !ids.includes(id)) ids.push(id);
  }
  return ids;
}

function assertStrictCharacterMediaBindings(project, shot, references = {}) {
  const characters = Array.isArray(project?.characters) ? project.characters : [];
  const turns = uniqueDialogueTurns(project, shot);
  const characterById = new Map(characters.map(item => [String(item?.id || "").trim(), item]).filter(([id]) => id));
  const charactersByName = new Map();
  for (const character of characters) {
    const name = String(character?.name || "").trim();
    if (!name) continue;
    if (!charactersByName.has(name)) charactersByName.set(name, []);
    charactersByName.get(name).push(character);
  }
  const speakerIds = [];
  for (const turn of turns) {
    const speakerToken = String(turn?.speakerId || turn?.speaker || "").trim();
    const namedMatches = charactersByName.get(String(turn?.speaker || "").trim()) || [];
    const character = characterById.get(speakerToken) || (namedMatches.length === 1 ? namedMatches[0] : null);
    if (!character) {
      throw Object.assign(new Error(`${shot.id}对白“${turn?.text || ""}”没有唯一说话人资产，禁止提交视频`), {
        code: "SHOT_SPEAKER_IDENTITY_AMBIGUOUS",
        shotId: shot.id,
        speaker: turn?.speaker || speakerToken
      });
    }
    if (namedMatches.length > 1) {
      throw Object.assign(new Error(`${shot.id}说话人姓名“${turn.speaker}”对应${namedMatches.length}个角色ID，无法保证音色和台词一一对应`), {
        code: "SHOT_SPEAKER_NAME_DUPLICATED",
        shotId: shot.id,
        speaker: turn.speaker,
        characterIds: namedMatches.map(item => item.id)
      });
    }
    if (!speakerIds.includes(character.id)) speakerIds.push(character.id);
    const invalidListeners = normalizeStringArray(turn?.listenerIds).filter(id => id === character.id || !characterById.has(id));
    if (invalidListeners.length) {
      throw Object.assign(new Error(`${shot.id}对白“${turn.text}”的听者绑定无效：${invalidListeners.join("、")}`), {
        code: "SHOT_DIALOGUE_LISTENER_BINDING_INVALID",
        shotId: shot.id,
        speakerId: character.id,
        listenerIds: invalidListeners
      });
    }
    const subshotNumber = Math.max(1, Number(turn?.subshotNumber) || 1);
    const subshot = (Array.isArray(shot?.subshots) ? shot.subshots : [])[subshotNumber - 1];
    const mouthOwnerId = String(subshot?.mouthOwnerId || "").trim();
    if (turn?.onScreen !== false && mouthOwnerId && mouthOwnerId !== character.id) {
      throw Object.assign(new Error(`${shot.id}第${subshotNumber}段嘴型属于${mouthOwnerId}，但台词属于${character.id}`), {
        code: "SHOT_DIALOGUE_MOUTH_OWNER_MISMATCH",
        shotId: shot.id,
        subshotNumber,
        speakerId: character.id,
        mouthOwnerId
      });
    }
  }

  const audios = Array.isArray(references?.audios) ? references.audios : [];
  const audioByCharacterId = new Map();
  const audioPathOwner = new Map();
  for (const audio of audios) {
    const characterId = String(audio?.characterId || "").trim();
    const character = characterById.get(characterId);
    if (!character || String(audio?.characterName || "").trim() !== String(character.name || "").trim()) {
      throw Object.assign(new Error(`${shot.id}音色文件的角色ID与姓名不一致，禁止提交`), {
        code: "SHOT_VOICE_CHARACTER_METADATA_MISMATCH",
        shotId: shot.id,
        characterId,
        characterName: audio?.characterName || ""
      });
    }
    if (audioByCharacterId.has(characterId)) {
      throw Object.assign(new Error(`${shot.id}角色“${character.name}”重复绑定多条音色`), {
        code: "SHOT_VOICE_DUPLICATED",
        shotId: shot.id,
        characterId
      });
    }
    const resolvedPath = path.resolve(String(audio?.path || ""));
    const priorOwner = audioPathOwner.get(resolvedPath);
    if (priorOwner && priorOwner !== characterId) {
      throw Object.assign(new Error(`${shot.id}角色${priorOwner}与${characterId}共用了同一个音色文件，禁止提交`), {
        code: "SHOT_VOICE_FILE_SHARED_BETWEEN_CHARACTERS",
        shotId: shot.id,
        characterIds: [priorOwner, characterId],
        filePath: resolvedPath
      });
    }
    audioByCharacterId.set(characterId, audio);
    audioPathOwner.set(resolvedPath, characterId);
  }
  const extraAudio = [...audioByCharacterId.keys()].filter(id => !speakerIds.includes(id));
  if (extraAudio.length) {
    throw Object.assign(new Error(`${shot.id}混入了非本任务说话人的音色：[${extraAudio.join("、")}]`), {
      code: "SHOT_DIALOGUE_VOICE_BIJECTION_FAILED",
      shotId: shot.id,
      extraAudio
    });
  }

  const visibleIds = references?.importedReferenceOrderLocked === true
    ? [...new Set([
      ...normalizeStringArray(shot?.characterIds),
      ...speakerIds
    ])]
    : shotReferenceCharacterIds(project, shot);
  const imageRoles = Array.isArray(references?.imageRoles) ? references.imageRoles : [];
  const shotAnchorRoles = imageRoles.filter(item => item?.type === "shot_anchor");
  if (shotAnchorRoles.length > 1) {
    throw Object.assign(new Error(`${shot.id}绑定了多张分镜锚点图，无法保证官方首尾图映射`), {
      code: "SHOT_ANCHOR_DUPLICATED",
      shotId: shot.id
    });
  }
  const anchorCoveredIds = new Set();
  for (const role of shotAnchorRoles) {
    if (String(role?.entityId || "").trim() !== String(shot?.id || "").trim()) {
      throw Object.assign(new Error(`${shot.id}分镜锚点图归属错误：${role?.entityId || "空"}`), {
        code: "SHOT_ANCHOR_ENTITY_MISMATCH",
        shotId: shot.id,
        entityId: role?.entityId || ""
      });
    }
    for (const id of normalizeStringArray(role?.coversEntityIds)) anchorCoveredIds.add(id);
  }
  const identityRoles = imageRoles.filter(item => item?.type === "character");
  const identityByCharacterId = new Map();
  const identityPathOwner = new Map();
  for (const role of identityRoles) {
    const characterId = String(role?.entityId || "").trim();
    if (!visibleIds.includes(characterId) || identityByCharacterId.has(characterId)) {
      throw Object.assign(new Error(`${shot.id}人物身份图绑定重复或不属于本镜可见人物：${characterId}`), {
        code: "SHOT_CHARACTER_IDENTITY_BINDING_INVALID",
        shotId: shot.id,
        characterId
      });
    }
    const resolvedPath = path.resolve(String(role?.path || ""));
    const priorOwner = identityPathOwner.get(resolvedPath);
    if (priorOwner && priorOwner !== characterId) {
      throw Object.assign(new Error(`${shot.id}角色${priorOwner}与${characterId}共用了同一个人物身份图，禁止提交`), {
        code: "SHOT_CHARACTER_IDENTITY_FILE_SHARED",
        shotId: shot.id,
        characterIds: [priorOwner, characterId],
        filePath: resolvedPath
      });
    }
    identityByCharacterId.set(characterId, role);
    identityPathOwner.set(resolvedPath, characterId);
  }
  const missingIdentity = visibleIds.filter(id => {
    const character = characterById.get(id);
    return character?.assetRequired !== false
      && character?.visualAssetRequired !== false
      && !identityByCharacterId.has(id)
      && !anchorCoveredIds.has(id);
  });
  if (missingIdentity.length) {
    throw Object.assign(new Error(`${shot.id}可见人物缺少唯一身份图：${missingIdentity.join("、")}`), {
      code: "SHOT_CHARACTER_IDENTITY_BIJECTION_FAILED",
      shotId: shot.id,
      characterIds: missingIdentity
    });
  }
  return true;
}

function assertHailuoDialogueVoiceReferences(project, shot, references = {}, options = {}) {
  const turns = uniqueDialogueTurns(project, shot);
  if (!turns.length) return { speakerIds: [], audioByCharacterId: new Map() };
  const speakerIds = shotSpeakingCharacterIds(project, shot);
  if (speakerIds.unknownSpeakers?.length) {
    throw Object.assign(new Error(`${shot.id}对白存在未绑定角色：${speakerIds.unknownSpeakers.join("、")}`), {
      code: "HAILUO_DIALOGUE_SPEAKER_UNKNOWN",
      shotId: shot.id,
      speakers: speakerIds.unknownSpeakers
    });
  }
  // An optional voice-reference file limit is not a limit on native vocal
  // identities. Preserve the authored cast; validate actual supplied media
  // separately below, and validate each speaker/tag binding in the prompt.
  const audios = Array.isArray(references.audios) ? references.audios : [];
  if (audios.length > 2) {
    throw Object.assign(new Error(`${shot.id}绑定了${audios.length}条音色，超过当前H3任务最多2条可选音色参考`), {
      code: "HAILUO_AUDIO_REFERENCE_LIMIT",
      shotId: shot.id
    });
  }
  const totalAudioDuration = audios.reduce((sum, audio) => sum + (Number(audio?.duration) || 0), 0);
  if (totalAudioDuration > 15) {
    throw Object.assign(new Error(`${shot.id}音色参考合计${totalAudioDuration}秒，超过海螺 H3 的15秒总上限`), {
      code: "HAILUO_AUDIO_DURATION_LIMIT",
      shotId: shot.id,
      totalAudioDuration
    });
  }
  const audioByCharacterId = new Map();
  for (const audio of audios) {
    const id = String(audio?.characterId || "");
    if (!id) continue;
    if (audioByCharacterId.has(id)) {
      throw Object.assign(new Error(`${shot.id}为角色${id}重复绑定了多条音色`), { code: "HAILUO_VOICE_DUPLICATED", shotId: shot.id, characterId: id });
    }
    audioByCharacterId.set(id, audio);
  }
  const invalid = [...audioByCharacterId.entries()]
    .map(([id, audio]) => ({ id, audit: audioReferenceAudit(audio) }))
    .filter(item => !item.audit.ok);
  if (invalid.length) {
    const labels = invalid.map(item => `${project.characters?.find(character => character.id === item.id)?.name || item.id}（${item.audit.message}）`);
    throw Object.assign(new Error(`${shot.id}说话人音色不可用：${labels.join("、")}`), {
      code: "HAILUO_SPEAKER_VOICE_INVALID",
      shotId: shot.id,
      invalid
    });
  }
  const auditedTotalDuration = [...audioByCharacterId.values()]
    .reduce((sum, audio) => sum + (Number(audioReferenceAudit(audio).duration) || 0), 0);
  if (auditedTotalDuration > 15.05) {
    throw Object.assign(new Error(`${shot.id}音色参考实际合计${auditedTotalDuration.toFixed(2)}秒，超过海螺 H3 的15秒总上限`), {
      code: "HAILUO_AUDIO_DURATION_LIMIT",
      shotId: shot.id,
      totalAudioDuration: auditedTotalDuration
    });
  }
  const unexpected = [...audioByCharacterId.keys()].filter(id => !speakerIds.includes(id));
  if (unexpected.length) {
    throw Object.assign(new Error(`${shot.id}混入了非本镜说话人的音色：${unexpected.join("、")}`), {
      code: "HAILUO_VOICE_SPEAKER_MISMATCH",
      shotId: shot.id,
      characterIds: unexpected
    });
  }
  if (options.requireMultimodal === true && audios.length > 0 && normalizeHailuoApiMode(references.hailuoApiMode) !== "multimodal_to_video") {
    throw Object.assign(new Error(`${shot.id}含对白和音色，必须使用海螺 H3 全能多参 multimodal_to_video`), {
      code: "HAILUO_DIALOGUE_MULTIMODAL_REQUIRED",
      shotId: shot.id
    });
  }
  return {
    speakerIds,
    audioByCharacterId,
    missingVoiceCharacterIds: speakerIds.filter(id => !audioByCharacterId.has(id))
  };
}

function assertHailuoPromptVoiceBindings(project, shot, references = {}, prompt = "") {
  const audios = Array.isArray(references.audios) ? references.audios : [];
  const { speakerIds } = assertHailuoDialogueVoiceReferences(project, shot, references, {
    requireMultimodal: audios.length > 0
  });
  if (!speakerIds.length) return true;
  const text = String(prompt || "");
  // Current H3 natural-language authoring is validated against its exact
  // source-bound compiler, not legacy phrases such as FACE= or <Subject N>
  // that are deliberately absent from official native I2VA/FL2VA prompts.
  if (require('./h3-final-prompt-editor').current(shot)
    && text === renderApprovedVideoPrompt(project, shot, references)) {
    require('./hailuo-h3-prompt').assertAgentHailuoDelivery(text, 10000, { strictOfficial: true });
    return true;
  }
  const escapeForRegExp = value => String(value || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const subjectByCharacterId = new Map();
  const characterRoles = [];
  for (const [imageIndex, role] of (Array.isArray(references.imageRoles) ? references.imageRoles : []).entries()) {
    if (role?.type !== "character") continue;
    const characterId = String(role?.entityId || "").trim();
    if (!characterId) continue;
    characterRoles.push({ characterId, imageIndex: imageIndex + 1 });
    // buildApprovedHailuoPrompt numbers character subjects by first speaking
    // ownership, not by image-role order. Resolve the actual subject from the
    // authoritative Picture binding written in subject_definitions so a C02 ->
    // C01 exchange remains valid when the image manifest is scene,C01,C02.
    const legacyDefinition = text.match(new RegExp(`^<Subject\\s+(\\d+)>[^\\n]*<Picture\\s+${imageIndex + 1}>[^\\n]*$`, "im"));
    const integratedDefinition = text.match(new RegExp(`人物\\s+${escapeForRegExp(characterId)}[^；\\n]{0,120}（(<Subject\\s+\\d+>)）[^；\\n]*<Picture\\s+${imageIndex + 1}>`, "i"));
    if (integratedDefinition?.[1]) subjectByCharacterId.set(characterId, integratedDefinition[1]);
    else if (legacyDefinition?.[1]) subjectByCharacterId.set(characterId, `<Subject ${legacyDefinition[1]}>`);
  }
  // Legacy compact prompts did number subjects in character-image order. Keep
  // that fallback only when no explicit subject/Picture definition is present.
  characterRoles.forEach((item, index) => {
    if (!subjectByCharacterId.has(item.characterId)) subjectByCharacterId.set(item.characterId, `<Subject ${index + 1}>`);
  });
  const missingTokens = [];
  for (let index = 0; index < audios.length; index += 1) {
    const audio = audios[index];
    const token = `<Audio ${index + 1}>`;
    const subjectToken = subjectByCharacterId.get(String(audio?.characterId || ""));
    const subjectPattern = subjectToken ? escapeForRegExp(subjectToken) : "<Subject\\s+\\d+>";
    const manifest = new RegExp(`${escapeForRegExp(token)}(?:\\s+is\\s+the\\s+voice-timbre\\s+reference\\s+for|\\s*:\\s*(?:optional\\s+)?timbre\\s+reference\\s+only\\s+for|=)\\s*${subjectPattern}|${escapeForRegExp(token)}只提供人物[^；\\n]*（${subjectPattern}）的声线身份`, "i");
    if (!text.includes(token) || !manifest.test(text)) missingTokens.push(token);
  }
  if (missingTokens.length) {
    throw Object.assign(new Error(`${shot.id}海螺提示词缺少已提供的可选音色绑定：${missingTokens.join("、")}`), {
      code: "HAILUO_PROMPT_AUDIO_BINDING_MISSING",
      shotId: shot.id,
      missingTokens
    });
  }
  const lineFailures = [];
  const performanceFailures = [];
  const taggedDialogue = [...text.matchAll(/<d>\s*\[Chinese\]\s*([\s\S]*?)<\/d>/gi)].map(match => String(match[1] || "").trim());
  for (const turn of uniqueDialogueTurns(project, shot)) {
    const character = (project.characters || []).find(item => item.name === turn.speaker || item.id === turn.speaker || item.id === turn.speakerId);
    const index = audios.findIndex(item => item.characterId === character?.id);
    const token = index >= 0 ? `<Audio ${index + 1}>` : "";
    const spokenText = String(turn.text || "").replace(/<\/?d>/gi, "");
    const taggedMarker = `<d>[Chinese] ${spokenText}</d>`;
    const dialogueLine = text.split("\n").find(line => line.includes(taggedMarker)) || "";
    if (!dialogueLine || taggedDialogue.filter(line => line === spokenText).length !== 1) {
      lineFailures.push(`${turn.speaker}:${spokenText}`);
      continue;
    }
    if (token && !dialogueLine.includes(token)) lineFailures.push(`${turn.speaker}:${spokenText}`);
    const manifestMatch = token
      ? text.match(new RegExp(`${escapeForRegExp(token)}(?:\\s+is\\s+the\\s+voice-timbre\\s+reference\\s+for|\\s*:\\s*(?:optional\\s+)?timbre\\s+reference\\s+only\\s+for|=)\\s*(<Subject\\s+\\d+>)(?:\\s+\\((S\\d+)\\))?`, "i"))
      : null;
    const subjectToken = subjectByCharacterId.get(String(character?.id || ""))
      || manifestMatch?.[1]
      || dialogueLine.match(/<Subject\s+\d+>/i)?.[0]
      || "";
    const speakerToken = manifestMatch?.[2] || "";
    const subjectOwned = subjectToken
      && dialogueLine.includes(subjectToken)
      && (!speakerToken || dialogueLine.includes(`(${speakerToken})`));
    const visibleSpeakerContract = subjectOwned
      && new RegExp(`${escapeForRegExp(subjectToken)}(?:\\s+\\(S\\d+\\))?\\s+faces\\s+[^;:]+?\\s+and\\s+(?:alone\\s+)?(?:speaks|says)\\s+(?:exactly\\s+)?once`, "i").test(dialogueLine)
      && new RegExp(`only\\s+${escapeForRegExp(subjectToken)}(?:\\s+\\(S\\d+\\))?\\s+moves\\s+the\\s+lips`, "i").test(dialogueLine);
    const offscreenSpeakerContract = subjectOwned
      && /remains\s+(?:outside(?:\s+the)?\s+frame|off-screen)/i.test(dialogueLine)
      && /no\s+visible\s+mouth\s+moves/i.test(dialogueLine);
    const optionalAudioPattern = token ? `\\/${escapeForRegExp(token)}` : "";
    const compactDialogueContract = new RegExp(`(?:^|\\s)${escapeForRegExp(String(character?.id || turn.speakerId || ""))}:<Subject\\s+\\d+>\\/mouth\\+camera${optionalAudioPattern}-><Subject\\s+\\d+>\\(closed lips\\+react\\)`).test(dialogueLine);
    const legacyContract = (/<Subject\s+\d+>(?:\/<Audio\s+\d+>)?->/.test(dialogueLine)
        || /speaker=[^;]+;\s*mouth=<Subject\s+\d+>\/camera;\s*(?:voice=<Audio\s+\d+>;\s*)?listener=<Subject\s+\d+>/.test(dialogueLine)
        || compactDialogueContract)
      && /T=[^;]+/.test(dialogueLine)
      && /A=[^;]+/.test(dialogueLine)
      && (/mouth=<Subject\s+\d+>/.test(dialogueLine) || /<Subject\s+\d+>\/mouth\+camera/.test(dialogueLine))
      && (/L=[^.]+/.test(dialogueLine) || /-><Subject\s+\d+>\(closed lips\+react\)/.test(dialogueLine));
    const listenerContract = /every\s+listener\s+keeps\s+lips\s+at\s+rest\s+and\s+reacts\s+visibly/i.test(dialogueLine)
      || /<Subject\s+\d+>(?:\s+and\s+<Subject\s+\d+>)*\s+remains\s+closed-lipped\s+and\s+reacts\s+visibly/i.test(dialogueLine)
      || /no\s+other\s+visible\s+mouth\s+moves\s+or\s+inherits\s+any\s+part\s+of\s+the\s+line/i.test(dialogueLine);
    const officialContract = (visibleSpeakerContract || offscreenSpeakerContract)
      && /delivery\s+is\s+[^;:]+/i.test(dialogueLine)
      && /body\s+action\s+is\s+[^:]+/i.test(dialogueLine)
      && (offscreenSpeakerContract || listenerContract);
    const compactOfficialContract = (visibleSpeakerContract || offscreenSpeakerContract)
      && /Deliver\s+at\s+no\s+less\s+than\s+\d+(?:\.\d+)?\s+effective\s+Chinese\s+characters\s+per\s+second\s*:\s*[^;]+/i.test(dialogueLine)
      && /Camera:\s*[^.]+/i.test(dialogueLine)
      && /Finish\s+inside\s+this\s+window/i.test(dialogueLine)
      && (offscreenSpeakerContract || listenerContract);
    const causalDirectorContract = subjectOwned
      && (offscreenSpeakerContract || (
        dialogueLine.includes(`${subjectToken} addresses `)
        && dialogueLine.includes("and alone speaks this exact once-only line=")
        && dialogueLine.includes(`Only ${subjectToken} moves the lips`)
      ))
      && dialogueLine.includes("CAUSE/INTENT=")
      && dialogueLine.includes("VOCAL ARC=")
      && dialogueLine.includes("BODY PERFORMANCE=")
      && (offscreenSpeakerContract || (dialogueLine.includes("FACIAL ARC=") && dialogueLine.includes("FACING/BLOCKING=")))
      && dialogueLine.includes("every listener keeps resting lips and gives this caused reaction=");
    // v22 keeps the same semantic performance contract but uses shorter field
    // labels so the provider sees the Chinese line and speaker ownership before
    // the long-form direction. Treat it as valid only when every causal acting
    // field is still present; this is not a permissive bypass.
    const compactDirectorContract = subjectOwned
      && (offscreenSpeakerContract || (
        dialogueLine.includes(`${subjectToken} addresses `)
        && dialogueLine.includes("and alone says exactly once")
        && dialogueLine.includes(`Only ${subjectToken} moves the lips`)
      ))
      && dialogueLine.includes("CAUSE=")
      && dialogueLine.includes("VOICE=")
      && (offscreenSpeakerContract || (
        dialogueLine.includes("FACE=")
        && dialogueLine.includes("BODY=")
        && dialogueLine.includes("FACING=")
      ))
      && (offscreenSpeakerContract
        ? /visible listeners keep closed lips and react=/i.test(dialogueLine)
        : /all other visible people keep closed lips and react=/i.test(dialogueLine));
    const integratedContract = /^integrated_multimodal_description（多模态综合描述）/u.test(text.trim())
      && subjectOwned
      // Tone arcs legitimately quote stressed words inside the outer Chinese
      // quotation marks (for example 重读“活得体面”).  A negated character
      // class stops at that inner quote and falsely rejects the canonical
      // compiler output.  Match through the final outer quote on this line.
      && /以“.+”的语气和声调完整说一遍/u.test(dialogueLine)
      && /眼神|眉峰|下颌|微表情/.test(dialogueLine)
      && /身体重心|手部动作|肢体动作/.test(dialogueLine)
      && (/开口并驱动口型/.test(dialogueLine) || /位于画外；画面内所有人物全程闭口/.test(dialogueLine))
      && /闭口/.test(dialogueLine);
    if (!(integratedContract || compactDirectorContract || causalDirectorContract || compactOfficialContract || officialContract || legacyContract)) performanceFailures.push(`${turn.speaker}:${spokenText}`);
  }
  if (lineFailures.length) {
    throw Object.assign(new Error(`${shot.id}海螺提示词缺少逐字台词、人物图归属或已提供的可选音色绑定：${lineFailures.join("；")}`), {
      code: "HAILUO_PROMPT_DIALOGUE_AUDIO_BINDING_MISSING",
      shotId: shot.id,
      dialogue: lineFailures
    });
  }
  if (performanceFailures.length) {
    throw Object.assign(new Error(`${shot.id}云端视频提示词缺少逐句表演合同（说话人、对象、语气、情绪、原话或听者反应）：${performanceFailures.join("；")}`), {
      code: "HAILUO_PROMPT_DIALOGUE_PERFORMANCE_MISSING",
      shotId: shot.id,
      dialogue: performanceFailures
    });
  }
  return true;
}

function summarizeAssetBatch(items = [], waveLabel = "", kind = "asset_batch", metadata = {}) {
  const total = items.length;
  const completed = items.filter(item => item.status === "completed" || item.status === "skipped").length;
  const failed = items.filter(item => item.status === "failed").length;
  const running = items.filter(item => item.status === "running").map(item => ({ key: item.key, label: item.label }));
  const queued = items.filter(item => item.status === "queued").length;
  return {
    kind: kind || "asset_batch",
    total,
    completed,
    failed,
    queued,
    running,
    percent: total ? Math.round((completed / total) * 100) : 100,
    waveLabel: waveLabel || "",
    items,
    ...(metadata.batchId ? { batchId: String(metadata.batchId) } : {}),
    ...(metadata.batchStartedAt ? { batchStartedAt: String(metadata.batchStartedAt) } : {}),
    updatedAt: new Date().toISOString()
  };
}

function imageBatchConcurrency(project) {
  const requested = Number(project?.generation?.keyframeConcurrency) || IMAGE_BATCH_MAX_CONCURRENCY;
  return Math.max(1, Math.min(IMAGE_BATCH_MAX_CONCURRENCY, requested));
}

const PROMPT_REVIEW_BUNDLE_VERSION = "prompt-review-v16-confirmation-inplace-editor";

const PROMPT_REVIEW_GENERATED_KEYS = new Set([
  "__storeBaseline", "automation", "candidates", "candidateSlots", "jobs", "costLedger",
  "foundry", "promptReview", "promptOverrides", "promptReviewReferencePlan",
  "agentCameraTakePlan", "hailuoPromptSpec", "h3AssetDirectSemanticCompile",
  "systemImagePrompt", "systemVideoPrompt", "systemVideoPromptDisplayZh",
  "promptReviewApprovedAt", "promptReviewBundleVersion", "qualityAudit", "runtime", "progress",
  // Media selection is runtime state. Confirming or rerolling an already-approved
  // identity must not make the authored prompt bundle look stale.
  "activeIdentityCandidateId", "activeIdentitySelectedAt", "visualAssetLibraryId",
  "voiceLibraryId", "voiceLibraryBindingMode",
  // Provider planning is compiled only after the user-approved prompt bundle.
  // It is an execution cache, not authored screenplay or prompt input.
  "videoProviderPlan"
]);

function promptReviewStableSource(value, key = "") {
  if (value == null || typeof value !== "object") return value;
  if (Array.isArray(value)) return value.map(item => promptReviewStableSource(item));
  const next = {};
  for (const name of Object.keys(value).sort()) {
    if (PROMPT_REVIEW_GENERATED_KEYS.has(name) || /(?:created|updated|generated|approved|confirmed|requested|completed)At$/i.test(name)) continue;
    next[name] = promptReviewStableSource(value[name], name);
  }
  return next;
}

function promptReviewHash(value) {
  return crypto.createHash("sha256").update(JSON.stringify(promptReviewStableSource(value))).digest("hex").toUpperCase();
}

function promptReviewCanonicalDialogueTurn(turn = {}) {
  const metadata = turn?.metadata && typeof turn.metadata === "object" ? turn.metadata : {};
  const text = (...values) => values.map(value => String(value ?? "").trim()).find(Boolean) || "";
  const number = (...values) => {
    const value = values.map(item => Number(item)).find(Number.isFinite);
    return Number.isFinite(value) ? value : 0;
  };
  const next = {
    sourceDialogueId: text(turn.sourceDialogueId, turn.id),
    primaryListenerId: text(turn.primaryListenerId, turn.addresseeId),
    speechMode: text(turn.speechMode, metadata.speechMode),
    addressBeats: Array.isArray(turn.addressBeats) ? turn.addressBeats : [],
    sourceTone: text(turn.sourceTone, metadata.sourceTone, turn.tone, metadata.tone, metadata.delivery),
    speaker: text(turn.speaker, turn.speakerId, turn.characterId),
    speakerId: text(turn.speakerId, turn.characterId),
    listenerIds: normalizeStringArray(turn.listenerIds || turn.listeners),
    text: text(turn.spokenText, turn.text),
    beat: text(turn.beat, metadata.beat),
    intent: text(turn.intent, metadata.intent),
    emotionStart: text(turn.emotionStart, metadata.emotionStart, metadata.emotion),
    emotionPeak: text(turn.emotionPeak, metadata.emotionPeak),
    delivery: text(turn.delivery, metadata.delivery),
    volume: text(turn.volume, metadata.volume),
    pace: text(turn.pace, metadata.pace),
    stressWord: text(turn.stressWord, metadata.stressWord),
    breath: text(turn.breath, metadata.breath),
    body: text(turn.body, turn.bodyAction, metadata.body, metadata.bodyAction),
    listenerBeat: text(turn.listenerBeat, turn.listenerReaction, metadata.listenerBeat, metadata.listenerReaction),
    blocking: text(turn.blocking, turn.position, metadata.blocking, metadata.position),
    speakerFacing: text(turn.speakerFacing, metadata.speakerFacing),
    listenerFacing: text(turn.listenerFacing, metadata.listenerFacing),
    eyeline: text(turn.eyeline, turn.eyelineDirection, metadata.eyeline, metadata.eyelineDirection),
    plannedSpeechSeconds: number(turn.plannedSpeechSeconds, metadata.plannedSpeechSeconds),
    plannedAfterBeatSeconds: number(turn.plannedAfterBeatSeconds, metadata.plannedAfterBeatSeconds),
    subshotNumber: Math.max(1, number(turn.subshotNumber) || 1),
    onScreen: turn.onScreen !== false
  };
  for (const key of [
    "deliveryEn", "vocalArcEn", "expressionEn", "expressionArcEn", "facialPerformanceEn", "faceEn", "bodyEn", "bodyActionEn", "blockingEn",
    "speakerFacingEn", "listenerFacingEn", "eyelineEn", "listenerReactionEn", "listenerBeatEn", "performanceEn",
    "deliveryZh", "vocalArcZh", "expressionZh", "bodyZh", "blockingZh", "speakerFacingZh", "listenerReactionZh"
  ]) {
    const value = text(turn?.[key], metadata?.[key]);
    if (value) next[key] = value;
  }
  const startSecond = number(turn.startSecond, turn.start, metadata.startSecond);
  const endSecond = number(turn.endSecond, turn.end, metadata.endSecond);
  if (endSecond > startSecond) {
    next.startSecond = startSecond;
    next.endSecond = endSecond;
  }
  return next;
}

function promptReviewCanonicalShots(project = {}) {
  return (project?.shots || []).map(shot => {
    const next = {
      ...shot,
      dialogueTurns: uniqueDialogueTurns(project, shot).map(promptReviewCanonicalDialogueTurn),
      subshots: (Array.isArray(shot?.subshots) ? shot.subshots : []).map(subshot => {
        const copy = { ...subshot };
        delete copy.dialogue;
        delete copy.dialogueTurns;
        return copy;
      })
    };
    // These are lossy display mirrors of the immutable source ledger and the
    // canonical turns above. Moving base fields between turn.metadata and the
    // turn itself must not invalidate 68 user-confirmed production prompts.
    delete next.dialogue;
    return next;
  });
}

function promptReviewSourceFingerprint(project = {}) {
  // Asset eligibility and clean appearance fields are deterministic derivatives
  // of the shot/dialogue facts. Canonicalize them before hashing so a project
  // saved by WorkbenchStore hashes exactly like the same in-memory draft while
  // genuine appearance/shot edits still invalidate approval.
  let canonicalProject = project;
  try {
    canonicalProject = decorateProjectAssetMetadata(JSON.parse(JSON.stringify(project || {})));
  } catch {}
  return promptReviewHash({
    requirementsVersion: require("./production-content-requirements").VERSION,
    productionRevision: String(canonicalProject?.productionRevision || ""),
    script: {
      rawSha256: crypto.createHash("sha256").update(String(canonicalProject?.script?.raw || "")).digest("hex"),
      sourceDialogueLedger: canonicalProject?.script?.sourceDialogueLedger || canonicalProject?.sourceDialogueLedger || [],
      sourceSceneLedger: canonicalProject?.script?.sourceSceneLedger || null
    },
    productionPlan: canonicalProject?.productionPlan || {},
    promptIntake: canonicalProject?.promptIntake || {},
    product: canonicalProject?.product || {},
    generation: canonicalProject?.generation || {},
    characters: canonicalProject?.characters || [],
    scenes: canonicalProject?.scenes || [],
    assetLibraries: {
      props: canonicalProject?.assetLibraries?.props || [],
      wardrobes: canonicalProject?.assetLibraries?.wardrobes || []
      // Project voice-library rows contain runtime file paths, decode durations
      // and deposition metadata. Character voiceDescription/gender/age remain
      // above as authored source, while binding and materialization must never
      // invalidate already-approved prompts during zero-submit H3 preflight.
    },
    shots: promptReviewCanonicalShots(canonicalProject)
  });
}

function promptReviewSettingsFingerprint(settings = {}) {
  return promptReviewHash({
    requirementsVersion:require('./production-content-requirements').VERSION,agentReviewer:require('./unified-audit-policy').executionProfile(settings),
    generation: settings?.generation || {},
    prompts: settings?.prompts || {},
    imageProvider: {
      kind: settings?.imageProvider?.kind || "",
      model: settings?.imageProvider?.model || "",
      aspectRatio: settings?.imageProvider?.aspectRatio || ""
    },
    videoProvider: {
      kind: settings?.videoProvider?.kind || "",
      engine: settings?.videoProvider?.engine || "",
      model: settings?.videoProvider?.model || "",
      hailuoApiMode: settings?.videoProvider?.hailuoApiMode || "",
      hailuoReferenceAudioMode: settings?.videoProvider?.hailuoReferenceAudioMode || "image_only",
      resolution: settings?.videoProvider?.resolution || ""
    }
  });
}

function savePromptReviewWithStableFingerprint(store, project) {
  let saved = store.saveProject(project);
  if (!saved?.promptReview) return saved;
  // WorkbenchStore normalizes a few durable project fields during save. The
  // review fingerprint must describe that persisted project, not the transient
  // object that existed immediately before normalization. Otherwise a freshly
  // prepared or confirmed bundle can be stale the instant it is written.
  for (let attempt = 0; attempt < 3; attempt += 1) {
    const fingerprint = promptReviewSourceFingerprint(saved);
    if (String(saved.promptReview.sourceFingerprint || "") === fingerprint) return saved;
    saved = store.saveProject({
      ...saved,
      promptReview: { ...saved.promptReview, sourceFingerprint: fingerprint }
    });
  }
  const expected = promptReviewSourceFingerprint(saved);
  if (String(saved.promptReview?.sourceFingerprint || "") !== expected) {
    throw Object.assign(new Error("提示词清单的持久化指纹无法稳定，已停止确认和付费生成"), {
      code: "PROMPT_REVIEW_FINGERPRINT_UNSTABLE"
    });
  }
  return saved;
}

function approvedPromptReviewItem(project = {}, entityType = "", entityId = "", stage = "") {
  const review = project?.promptReview;
  if (!review || review.version !== PROMPT_REVIEW_BUNDLE_VERSION || review.status !== "approved") return null;
  if (String(review.productionRevision || "") !== String(project.productionRevision || "")) return null;
  if (String(review.sourceFingerprint || "") !== promptReviewSourceFingerprint(project)) return null;
  const item = (Array.isArray(review.items) ? review.items : []).find(entry => (
    entry?.status === "confirmed"
    && String(entry?.entityType || "") === String(entityType || "")
    && String(entry?.entityId || "") === String(entityId || "")
    && String(entry?.stage || "") === String(stage || "")
  ));
  return item && String(item.prompt || "").trim() ? item : null;
}

function promptReviewExecutionLanguage(prompt = "", context = {}) {
  const text = String(prompt || "");
  if (/^integrated_multimodal_description（多模态综合描述）/u.test(text.trim())) return "zh-CN";
  // The provider execution contract is authoritative. H3 video prompts embed
  // exact Chinese dialogue inside an English control envelope, so counting Han
  // characters misclassified dialogue-heavy shots as Chinese and skipped the
  // editable translation. Recognise the contract/stage before using a generic
  // language heuristic.
  const englishVideoContract = /^production\s*:/im.test(text)
    && /^(?:references|visual_timeline|temporal_contract|continuity|sound|delivery)\s*:/im.test(text);
  const officialHailuoContract = /^subject_definitions:\s*$/im.test(text)
    && /^summary:\s*$/im.test(text)
    && /^retention_analysis:\s*$/im.test(text)
    && /^detailed_description:\s*$/im.test(text)
    && /^overall_soundscape:\s*$/im.test(text)
    && /^non_diegetic_music:\s*$/im.test(text);
  if (officialHailuoContract || englishVideoContract || (context?.stage === "shot_video" && context?.mode !== "manual")) return "en";
  const chineseCount = (text.match(/[\u3400-\u9fff]/g) || []).length;
  const latinCount = (text.match(/[A-Za-z]/g) || []).length;
  if (chineseCount >= 8 || chineseCount >= latinCount * 0.12) return "zh-CN";
  return latinCount >= 24 ? "en" : "zh-CN";
}

function localPromptReviewChineseMirror(prompt = "") {
  let text = String(prompt || "").trim();
  if (!text) return "";
  const replacements = [
    [/^production\s*:/gim, "制作参数："],
    [/\bmode=multimodal_to_video\b/gi, "模式=多模态视频"],
    [/\bmode=image_to_video\b/gi, "模式=图生视频"],
    [/<Subject\s+(\d+)>/gi, "<人物 $1>"],
    [/<Audio\s+(\d+)>/gi, "<音频 $1>"],
    [/<Picture\s+(\d+)>/gi, "<图片 $1>"],
    [/\bsay1\s+<d>\[Chinese\]/gi, "说原话 <d>[中文]"],
    [/\bT=/g, "语气="],
    [/\bA=/g, "动作="],
    [/\bmouth=/gi, "口型归属="],
    [/\bL=/g, "听者反应="],
    [/\bno speech\b/gi, "无对白"],
    [/all mouths stay closed/gi, "所有人物保持闭口"],
    [/visible mouths remain still/gi, "可见人物保持闭口"],
    [/complete the authored physical action and visible reactions to the stable end state/gi, "完成原稿动作和可见反应并到达稳定结束状态"],
    [/^references\s*:/gim, "参考素材："],
    [/ordered frames/gi, "有序画面帧"],
    [/set\/light\/axis/gi, "场景、光线与轴线"],
    [/identity\/wardrobe/gi, "身份与服装"],
    [/voice timbre/gi, "音色"],
    [/^visual_timeline\s*:/gim, "画面时间线："],
    [/hard cut(?: on|@)?/gi, "硬切"],
    [/speaker changes?/gi, "说话人切换"],
    [/advance the authored causal action(?: to a visible change)?/gi, "推进原稿因果动作并形成可见变化"],
    [/hold the authored framing(?: on the active story beat)?/gi, "保持当前剧情拍点的原稿构图"],
    [/state=opening pose and prop state>next/gi, "状态=开场姿态与道具状态>下一状态"],
    [/state=opening pose>completed state/gi, "状态=开场姿态>完成状态"],
    [/state=prior>next/gi, "状态=上一状态>下一状态"],
    [/state=prior>authored completed state/gi, "状态=上一状态>原稿完成状态"],
    [/^temporal_contract\s*:/gim, "时间合同："],
    [/ordered temporal frames/gi, "按顺序执行时间帧"],
    [/continuation mode/gi, "视频延续模式"],
    [/keyframe mode/gi, "首尾帧模式"],
    [/^continuity\s*:/gim, "连续性："],
    [/preserve identity\/wardrobe\/set\/props\/eyeline\/state coherently/gi, "保持人物身份、服装、场景、道具、视线和状态连贯"],
    [/^sound\s*:/gim, "声音："],
    [/assigned voices/gi, "使用已绑定音色"],
    [/continuous location ambience and synchronized visible-action sound/gi, "连续环境底噪和与可见动作同步的声音"],
    [/continuous room tone/gi, "连续房间底噪"],
    [/others silent/gi, "其他人物静默"],
    [/^delivery\s*:/gim, "交付要求："],
    [/live-action continuity/gi, "真人实拍连续性"],
    [/exact speech, ambience and visible action sound/gi, "逐字对白、环境声和可见动作声音准确"],
    [/soft, reassuring, even pace/gi, "轻柔安抚、节奏平稳"],
    [/restrained anger, clipped stress/gi, "压住怒火、重音短促"],
    [/high volume, sharp attack/gi, "高音量、起音凌厉"],
    [/fast pace, clipped breath/gi, "语速快、气口短"],
    [/firm keyword stress/gi, "关键词重读坚定"],
    [/tearful breath, trembling tail/gi, "含泪气息、尾音发颤"],
    [/lower volume, slower ending/gi, "降低音量、句尾放慢"],
    [/face\/body follow/gi, "面部和身体跟随语义"],
    [/still lips; visible reaction/gi, "闭口并给出可见反应"],
    [/the authored listener/gi, "原稿指定听者"],
    [/opening pose/gi, "开场姿态"],
    [/completed state/gi, "完成状态"]
  ];
  for (const [pattern, replacement] of replacements) text = text.replace(pattern, replacement);
  return `【完整中文查看稿｜技术编号与占位符原样保留】\n${text}`;
}

function promptReviewGroup(entityType = "", stage = "") {
  if (stage === "shot_video" || stage === "character_video") return stage === "shot_video" ? "videos" : "characters";
  if (["storyboard_sheet", "storyboard_start", "storyboard_end"].includes(stage)) return "storyboards";
  if (entityType === "character") return "characters";
  if (entityType === "scene") return "scenes";
  return "objects";
}

function shotPropMentionCorpus(shot = {}, options = {}) {
  const authoredOnly = options.authoredOnly === true;
  const parts = [
    shot?.action,
    shot?.visualBeat,
    shot?.stateBefore,
    shot?.stateAfter,
    shot?.startFrame,
    shot?.endFrame,
    shot?.blocking,
    shot?.screenDirection,
    ...normalizeStringArray(shot?.propNames)
  ];
  if (!authoredOnly) parts.push(
    shot?.actionEn,
    shot?.visualBeatEn,
    shot?.stateBeforeEn,
    shot?.stateAfterEn,
    shot?.blockingEn,
    shot?.screenDirectionEn
  );
  for (const direction of !authoredOnly && Array.isArray(shot?.providerTimedDirections) ? shot.providerTimedDirections : []) {
    parts.push(
      direction?.action,
      direction?.actionEn,
      direction?.stateBefore,
      direction?.stateBeforeEn,
      direction?.stateAfter,
      direction?.stateAfterEn,
      direction?.blocking,
      direction?.blockingEn,
      direction?.sound,
      direction?.soundEn
    );
  }
  for (const subshot of Array.isArray(shot?.subshots) ? shot.subshots : []) {
    parts.push(
      subshot?.action,
      subshot?.visual,
      subshot?.visualBeat,
      subshot?.stateBefore,
      subshot?.stateAfter,
      subshot?.blocking,
      subshot?.sound
    );
    if (!authoredOnly) parts.push(
      subshot?.actionEn,
      subshot?.visualEn,
      subshot?.visualBeatEn,
      subshot?.stateBeforeEn,
      subshot?.stateAfterEn,
      subshot?.blockingEn,
      subshot?.soundEn
    );
    for (const turn of !authoredOnly && Array.isArray(subshot?.dialogueTurns) ? subshot.dialogueTurns : []) {
      parts.push(
        turn?.body,
        turn?.bodyAction,
        turn?.bodyEn,
        turn?.bodyActionEn,
        ...Object.values(turn?.metadata && typeof turn.metadata === "object" ? turn.metadata : {})
      );
    }
  }
  for (const turn of !authoredOnly && Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : []) {
    parts.push(
      turn?.body,
      turn?.bodyAction,
      turn?.bodyEn,
      turn?.bodyActionEn,
      ...Object.values(turn?.metadata && typeof turn.metadata === "object" ? turn.metadata : {})
    );
  }
  return parts.map(value => String(value || "").trim()).filter(Boolean).join("\n");
}

function propMentionTokens(prop = {}) {
  const cleanName = value => String(value || "").replace(/[^\p{L}\p{N}]/gu, "").toLocaleLowerCase();
  const exact = [prop?.id, prop?.name, ...(Array.isArray(prop?.aliases) ? prop.aliases : [])]
    .map(cleanName)
    .filter(value => value.length >= 2);
  // IDs such as prop_ab12 are exact ledger keys, not language. Deriving short
  // substrings from them produced the shared token "pro", so one authored
  // prop id made every prop in the project look visible in every shot.
  const semanticNames = [prop?.name, ...(Array.isArray(prop?.aliases) ? prop.aliases : [])]
    .map(cleanName)
    .filter(value => value.length >= 2);
  const derived = [];
  for (const name of semanticNames) {
    // AI occasionally writes a material/occasion modifier in one place but not
    // another ("婚礼座位卡" vs "烫金座位卡").  A longest shared noun phrase
    // of at least three CJK characters safely reconnects an already-declared
    // asset without creating a new object or widening the asset library.
    for (let length = Math.min(6, name.length); length >= 3; length -= 1) {
      for (let start = 0; start + length <= name.length; start += 1) {
        derived.push(name.slice(start, start + length));
      }
    }
    // Asset names commonly carry material/occasion prefixes while the authored
    // action uses only the concrete noun (for example "白色婚礼礼服" -> "礼服").
    // Suffixes are safe here because the source is already a declared prop, not
    // an open-world noun extractor.
    if (/\p{Script=Han}/u.test(name)) {
      for (let length = Math.min(6, name.length); length >= 2; length -= 1) {
        derived.push(name.slice(-length));
      }
    }
  }
  return [...new Set([...exact, ...derived])].sort((left, right) => right.length - left.length);
}

function inferredShotPropBindings(project = {}, shot = {}, options = {}) {
  const explicit = normalizePropBindings(shot?.propBindings);
  const result = explicit.map(item => ({ ...item }));
  const existingIds = new Set(explicit.map(item => String(item?.propId || "")).filter(Boolean));
  const corpus = shotPropMentionCorpus(shot, options).toLocaleLowerCase();
  const normalizedCorpus = corpus.replace(/[^\p{L}\p{N}]/gu, "");
  const shotId = String(shot?.id || `S${shot?.number || ""}`);

  for (const prop of Array.isArray(project?.assetLibraries?.props) ? project.assetLibraries.props : []) {
    const propId = String(prop?.id || "").trim();
    if (!propId || existingIds.has(propId)) continue;
    const tokens = propMentionTokens(prop);
    const unitBound = (Array.isArray(prop?.units) ? prop.units : []).map(String).includes(shotId);
    const matchedToken = tokens.find(token => normalizedCorpus.includes(token));
    if (!unitBound && !matchedToken) continue;

    // Mention proves relevance, not possession. The first named person, sole
    // visible actor or speaker describing a prop is not necessarily its holder.
    // Preserve explicit bindings above; leave inferred ownership unresolved for
    // the source-grounded directing pass instead of emitting false character IDs.
    result.push({
      propId,
      holderCharacterId: "",
      stateBefore: String(shot?.stateBefore || "").trim(),
      stateAfter: String(shot?.stateAfter || "").trim(),
      inferredFromExistingAsset: true
    });
    existingIds.add(propId);
  }
  return result;
}

function shotVideoPropBindings(project = {}, shot = {}) {
  if (require('./agent-production-decisions').current(project,shot)) return shot.agentProductionDecision.item.visiblePropIds
    .filter(id=>{const prop=(project.assetLibraries?.props||[]).find(p=>p.id===id);return prop&&prop.assetRequired!==false&&prop.sourceInventory?.classification!=='in_scene';})
    .map(propId=>({propId,source:'agent-production-decision'}));
  const explicitIds = new Set(normalizePropBindings(shot?.propBindings)
    .map(item => String(item?.propId || "").trim())
    .filter(Boolean));
  const named = new Set(normalizeStringArray(shot?.propNames).map(value => String(value || "").trim()).filter(Boolean));
  const corpus = shotPropMentionCorpus(shot).toLocaleLowerCase();
  const normalizedCorpus = corpus.replace(/[^\p{L}\p{N}]/gu, "");
  const propById = new Map((project?.assetLibraries?.props || []).map(item => [String(item?.id || "").trim(), item]));
  const inventory = require("./source-prop-inventory");
  const receipt = project.sourcePropInventory;
  const currentInventory = receipt?.status === "completed"
    && receipt.fingerprint === inventory.fingerprint(project)
    && inventory.identitiesCurrent(project, receipt);
  const sourceText = [shot.action, shot.stateBefore, shot.stateAfter, shot.visualBeat, shot.dialogue].filter(Boolean).join("\n");
  const candidates = inferredShotPropBindings(project, shot);
  // Legacy named assets are normalized here too, so neither the review path
  // nor the paid path can bypass visibility through a propNames fallback.
  for (const prop of propById.values()) {
    if ((named.has(prop.id) || named.has(prop.name)) && !candidates.some(b => b.propId === prop.id)) candidates.push({ propId: prop.id });
  }
  // Asset-library unit ranges are useful for continuity bookkeeping, but they
  // are not proof that an object is visible in this paid clip.  Sending every
  // unit-bound prop overloaded H3 and shifted unrelated Picture tokens.  A
  // video reference therefore needs explicit binding/name or concrete visual
  // evidence in this shot's action/state/performance text.
  const matched = candidates.filter(binding => {
    const propId = String(binding?.propId || "").trim();
    if (!propId) return false;
    const prop = propById.get(propId) || {};
    if (currentInventory && Array.isArray(prop.sourceInventory?.appearances)) {
      // A stored occurrence is continuity context, not an uploaded image.
      // Any grounded visible occurrence wins if an object is taken out later
      // in this very shot. Do not remove the whole shot on a negative phrase.
      return prop.sourceInventory.appearances.some(row => row.shotId === shot.id
        && row.visibility === "visible" && row.evidence && sourceText.includes(row.evidence));
    }
    if (explicitIds.has(propId)) return true;
    if (named.has(propId) || named.has(String(prop?.name || "").trim())) return true;
    return propMentionTokens(prop).some(token => normalizedCorpus.includes(token));
  });
  const canonical = [];
  for (const binding of matched) {
    const authoredProp = propById.get(String(binding?.propId || ""));
    const assetProp = authoredProp?.assetMergedIntoId
      ? propById.get(String(authoredProp.assetMergedIntoId))
      : authoredProp;
    // One-shot paper, cups and product components stay authored in the action
    // but do not become independent visual assets. Duplicate aliases resolve
    // to the one core asset chosen by the asset-eligibility pass.
    const legacyNamed = assetProp?.assetRequired == null && (named.has(assetProp?.id) || named.has(assetProp?.name));
    if (!assetProp || (assetProp.assetRequired !== true && !legacyNamed)) continue;
    const next = {
      ...binding,
      propId: String(assetProp.id),
      ...(authoredProp?.id && authoredProp.id !== assetProp.id ? { authoredPropId: authoredProp.id } : {})
    };
    const prior = canonical.find(item => item.propId === next.propId);
    if (prior) Object.assign(prior, { ...next, ...prior });
    else canonical.push(next);
  }
  return canonical;
}

function shotVideoProductReferenceRequired(project = {}, shot = {}) {
  if (require('./agent-production-decisions').current(project,shot)) return shot.agentProductionDecision.item.productVisible;
  if (!shot?.productMention || shot?.videoReferenceIncludeProduct === false) return false;
  if (shot?.videoReferenceIncludeProduct === true) return true;

  const product = project?.product || {};
  const subshots = Array.isArray(shot?.subshots) ? shot.subshots : [];
  // A reference image is a visual identity lock, never a semantic/product-
  // placement hint.  Spoken product names, derived productBinding text and a
  // residue/result state (for example dye foam already on hair) do not make the
  // photographed package visible.  Feeding that image anyway consumes a scarce
  // H3 reference slot and can hallucinate the package into an unrelated shot.
  const visualCorpus = [
    shot?.action,
    shot?.visualBeat,
    shot?.startFrame,
    shot?.endFrame,
    ...subshots.flatMap(item => [item?.action, item?.visualEn])
  ].map(value => String(value || "").trim()).filter(Boolean).join("\n");
  const explicitProductShot = /product_(?:packshot|detail)/i.test(`${shot?.productShotType || ""} ${shot?.shotFunction || ""}`);
  if (explicitProductShot) return true;

  // Dye packaging photos should only be sent when the bottle/box/sachet itself
  // is authored on camera.  Foam application, foam coverage and the final hair
  // colour are generic physical states and must not inherit the package image.
  const productFacts = `${product?.name || ""} ${product?.description || ""} ${product?.sellingPoints || ""}`;
  if (/染发|染膏|泡泡染|盖白发/.test(productFacts)) {
    const visibleEvidence = visualCorpus.replace(
      /(?:包装|包装盒|商品盒|产品盒|外盒|盒身|瓶身|瓶子|小袋|独立包装|独立装|包装袋|袋装|染发膏包装)[^。；\n]{0,16}(?:不在画面(?:内|中)?|不入镜|未入镜|没有入镜|不出现|未出现|不可见)/g,
      ""
    );
    const packageVisible = /(?:包装盒|商品盒|产品盒|外盒|盒身|瓶身|瓶子|小袋|独立包装|独立装|包装袋|袋装|染发膏包装)/.test(visibleEvidence);
    const packageHandling = /(?:拿出|拿起|取出|掏出|举起|展示|对准镜头|放到镜前|摆到镜前|打开|拆开|撕开|挤出|倒出)[^。；\n]{0,24}(?:染发膏|染膏|泡泡染|包装|盒|瓶|小袋|独立装|product)/i.test(visibleEvidence)
      || /(?:染发膏|染膏|泡泡染|包装|盒|瓶|小袋|独立装|product)[^。；\n]{0,24}(?:被拿出|被取出|被举起|被展示|入镜|打开|拆开|撕开|挤出|倒出)/i.test(visibleEvidence);
    return packageVisible || packageHandling;
  }

  // Package lettering is often separated across lines or by slashes. Match
  // that typography without requiring a single contiguous marketing name.
  const compactVisual = visualCorpus.replace(/[^\p{L}\p{N}]/gu, "");
  const compactName = String(product.name || "").replace(/[^\p{L}\p{N}]/gu, "");
  if (compactName.length >= 2 && compactVisual.includes(compactName)) return true;
  // Later handling beats refer to the already identified original container.
  // A dialogue-derived productBinding alone is insufficient: require an
  // original-package noun and positive physical handling in the same clause.
  const sourceProductBound = shot.productBinding?.source === "user_uploaded_product"
    && isSameProductName(shot.productBinding.name, product.name);
  if (sourceProductBound) {
    const packageNoun = /(?:原装|同一|这只|这个)(?:未开封的|密封的|广口|密封)?(?:罐|瓶|盒|袋|包装)|(?:original|same)\s+(?:sealed\s+)?(?:jar|bottle|box|pouch|package)/i;
    const handling = /托握|托住|握住|双手托|拿起|拿出|取出|捧起|放回|放到|移至|递给|交给|展示|holds?\b|grips?\b|lifts?\b|places?\b|hands?\s+over/i;
    const hidden = /始终收|始终藏|不入镜|未入镜|没有入镜|不在画面|不可见|not visible|offscreen|out of (?:the )?frame/i;
    const supported = /(?:留在|放在|立在|摆在|置于)[^。；\n]{0,12}(?:桌面|台面|柜面|床头柜|柜顶|桌上|台上)[上]?|(?:rests?|stands?)\s+on\s+(?:the\s+)?(?:table|counter|nightstand)/i;
    const clauses = visualCorpus.split(/[。；;\n]/u).filter(clause => !hidden.test(clause));
    if (clauses.some(clause => packageNoun.test(clause) && (handling.test(clause) || supported.test(clause)))) return true;
    // A performed contact with a part observed on this exact uploaded package
    // still needs its identity. Do not use imagined/unknown packaging parts.
    const observed = product.visualEvidence?.status === "observed"
      ? [product.visualEvidence.containerType, ...(product.visualEvidence.visibleParts || [])].join(" ") : "";
    const parts = [...new Set(observed.match(/旋盖|瓶盖|罐盖|瓶身|罐身|盒身/g) || [])];
    if (parts.some(part => clauses.some(clause => clause.includes(part) && /手指|指尖|接触|抚上|握住|fingers?|touch/i.test(clause)))) return true;
  }
  if (textMentionsProduct(visualCorpus, product?.name)) return true;
  if (productSemanticTokens(project).some(token => visualCorpus.includes(token))) return true;
  return false;
}

function criticalPropContinuityLedger(project = {}, options = {}) {
  const propById = new Map((project?.assetLibraries?.props || []).map(item => [String(item?.id || "").trim(), item]));
  const ledgerById = new Map();
  const shots = [...(project?.shots || [])].sort((left, right) => (Number(left?.number) || 0) - (Number(right?.number) || 0));
  for (const shot of shots) {
    for (const binding of inferredShotPropBindings(project, shot, options)) {
      const propId = String(binding?.propId || "").trim();
      if (!propId) continue;
      const entry = ledgerById.get(propId) || {
        propId,
        name: String(propById.get(propId)?.name || propId),
        continuity: String(propById.get(propId)?.continuity || ""),
        appearances: []
      };
      const previous = entry.appearances[entry.appearances.length - 1] || null;
      const hasHolderBefore = Object.prototype.hasOwnProperty.call(binding || {}, "holderBeforeCharacterId");
      const hasHolderAfter = Object.prototype.hasOwnProperty.call(binding || {}, "holderAfterCharacterId");
      const inferredOwnership = binding.inferredFromExistingAsset === true;
      const holderBeforeCharacterId = inferredOwnership ? "" : hasHolderBefore
        ? String(binding?.holderBeforeCharacterId || "").trim()
        : String(previous?.holderAfterCharacterId || binding?.holderCharacterId || "").trim();
      const holderAfterCharacterId = inferredOwnership ? "" : hasHolderAfter
        ? String(binding?.holderAfterCharacterId || "").trim()
        : String(binding?.holderCharacterId || holderBeforeCharacterId || "").trim();
      const locationBefore = String(binding?.locationBefore || previous?.locationAfter || "").trim();
      const locationAfter = String(binding?.locationAfter || locationBefore || "").trim();
      const stateBefore = String(binding?.stateBefore || previous?.stateAfter || shot?.stateBefore || "").trim();
      const stateAfter = String(binding?.stateAfter || shot?.stateAfter || stateBefore || "").trim();
      const transferAction = String(binding?.transferAction || "").trim();
      entry.appearances.push({
        shotId: String(shot?.id || `S${shot?.number || ""}`),
        holderBeforeCharacterId,
        holderAfterCharacterId,
        locationBefore,
        locationAfter,
        stateBefore,
        stateAfter,
        transferAction,
        previousAppearanceShotId: String(previous?.shotId || ""),
        action: String(shot?.action || shot?.visualBeat || "").trim()
      });
      ledgerById.set(propId, entry);
    }
  }
  return [...ledgerById.values()].filter(entry => entry.appearances.length);
}

const H3_ASSET_DIRECT_SEMANTIC_CONTRACT_VERSION = "2026.09.11-source-opening-state-v6";

function h3AssetDirectSemanticSource(project = {}) {
  const physicalProps = project?.assetLibraries?.props || [];
  const collectionIds = new Set(physicalProps.map(item => item.sourceInventory?.parentId).filter(Boolean));
  return {
    contractVersion: H3_ASSET_DIRECT_SEMANTIC_CONTRACT_VERSION,
    characters: (project?.characters || []).map(item => ({ id: item.id, name: item.name,role:item.role||'',ageBand:item.ageBand||'',gender:item.gender||'',physicalDesign:item.visualDesign?.descriptionEn||item.descriptionEn||item.sourceDescription||item.description||'' })),
    scenes: (project?.scenes || []).map(item => ({id:item.id,name:item.name,referencePurpose:'Static background reference geometry only. Empty/no-people constraints apply to that reference image, never to the shot cast, opening occupancy or acting.',physicalGeometry:item.visualDesign?.descriptionEn||item.descriptionEn||item.description||''})),
    props: physicalProps.map(item => ({ id: item.id, name: item.name, aliases: item.aliases || [],
      ...(item.sourceInventory?.parentId ? { parentId: item.sourceInventory.parentId } : {}),
      ...(collectionIds.has(item.id) ? { containsMemberIds: physicalProps.filter(child => child.sourceInventory?.parentId === item.id).map(child => child.id) } : {}),
      ...(item.sourceInventory?.parentId || collectionIds.has(item.id) ? { physicalDesign: item.visualDesign?.descriptionEn || item.descriptionEn || item.description || "" } : {})
    })),
    product: project?.product?.name ? { id: "product", name: project.product.name, physicalEvidence:project.product.visualEvidence?.status==='observed'?project.product.visualEvidence:null } : null,
    // Provider-timed English directions and compiled performance text are the
    // output of this semantic pass.  They must never feed back into its own
    // cache key, otherwise every completed batch changes the fingerprint and
    // the next app launch pays to compile the same 42 shots again.
    propContinuityLedger: criticalPropContinuityLedger(project, { authoredOnly: true }),
    shots: (project?.shots || []).map(shot => ({
      shotId: shot.id,
      duration: shot.duration,
      sceneId: shot.sceneId || "",
      sceneName: shot.sceneName || shot.scene || "",
      sceneLayout: shot.sceneLayout || shot.blocking || "",
      screenDirection: shot.screenDirection || shot.eyelineDirection || "",
      mainlineStage: shot.mainlineStage || "",
      emotionArc: shot.emotionArc || shot.emotion || "",
      performance: shot.performance || "",
      sourcePerformanceBudget:shot.sourcePerformanceBudget||null,
      visibleCharacterIds: normalizeStringArray(shot.visibleCharacterIds || shot.characterIds),
      action: shot.action || shot.visualBeat || "",
      stateBefore: shot.stateBefore || shot.startFrame || "",
      stateAfter: shot.stateAfter || shot.endFrame || "",
      propBindings: inferredShotPropBindings(project, shot, { authoredOnly: true }).map(binding => ({
        propId: binding.propId,
        holderBeforeCharacterId: Object.prototype.hasOwnProperty.call(binding || {}, "holderBeforeCharacterId")
          ? String(binding.holderBeforeCharacterId || "")
          : "",
        holderAfterCharacterId: Object.prototype.hasOwnProperty.call(binding || {}, "holderAfterCharacterId")
          ? String(binding.holderAfterCharacterId || "")
          : String(binding.holderCharacterId || ""),
        locationBefore: binding.locationBefore || "",
        locationAfter: binding.locationAfter || "",
        stateBefore: binding.stateBefore || "",
        stateAfter: binding.stateAfter || "",
        transferAction: binding.transferAction || ""
      })),
      subshots: (shot.subshots || []).map((item, index) => ({
        index,
        start: item.start,
        end: item.end,
        action: item.action || item.visualBeat || "",
        framing: item.framing || "",
        camera: item.camera || "",
        blocking: item.blocking || item.position || "",
        speakerFacing: item.speakerFacing || "",
        listenerFacing: item.listenerFacing || "",
        eyelineDirection: item.eyelineDirection || item.eyeline || "",
        emotionBeat: item.emotionBeat || "",
        faceAction: item.faceAction || "",
        bodyAction: item.bodyAction || "",
        voiceDelivery: item.voiceDelivery || "",
        listenerReaction: item.listenerReaction || item.listenerBeat || "",
        backgroundAction: item.backgroundAction || item.ensembleAction || "",
        stateBefore: item.stateBefore || "",
        stateAfter: item.stateAfter || "",
        sound: item.sound || ""
      })),
      dialogue: require('./drama-staging-contract').canonicalizeStagingShot(project,shot,uniqueDialogueTurns(project,shot)).turns.map((turn, index, turns) => ({
        index,
        sourceDialogueId: turn.sourceDialogueId || turn.id || `D${index + 1}`,
        text: String(turn.text || turn.spokenText || ''),
        speakerId: turn.speakerId || "",
        listenerIds: turn.listenerIds || [],
        primaryListenerId: turn.primaryListenerId || turn.metadata?.primaryListenerId || (turn.listenerIds?.length===1?turn.listenerIds[0]:'') || '',
        addressMode:turn.addressMode||'',
        directToViewer:turn.directToViewer===true,
        speechMode: turn.speechMode || turn.metadata?.speechMode || (turn.onScreen===false?'off_screen':'on_screen'),
        calculatedSpeechWindow: require('./drama-timing').speechWindowBounds(turn.text||turn.spokenText,turn),
        delivery: turn.delivery || turn.sourceTone || turn.metadata?.delivery || "",
        expression: turn.emotionPeak || turn.faceAction || turn.metadata?.emotionPeak || turn.metadata?.faceAction || "",
        emotionStart: turn.emotionStart || turn.metadata?.emotionStart || "",
        emotionPeak: turn.emotionPeak || turn.metadata?.emotionPeak || "",
        volume: turn.volume || turn.metadata?.volume || "",
        pace: turn.pace || turn.metadata?.pace || "",
        stressWord: turn.stressWord || turn.metadata?.stressWord || "",
        breath: turn.breath || turn.metadata?.breath || "",
        body: turn.body || turn.bodyAction || turn.metadata?.body || turn.metadata?.bodyAction || "",
        listenerReaction: turn.listenerReaction || turn.listenerBeat || turn.metadata?.listenerReaction || turn.metadata?.listenerBeat || "",
        blocking: turn.blocking || turn.position || turn.metadata?.blocking || turn.metadata?.position || "",
        speakerFacing: turn.speakerFacing || turn.metadata?.speakerFacing || "",
        listenerFacing: turn.listenerFacing || turn.metadata?.listenerFacing || "",
        eyeline: turn.eyeline || turn.eyelineDirection || turn.metadata?.eyeline || turn.metadata?.eyelineDirection || "",
        plannedSpeechSeconds: require('./source-performance-budget').preferredSpeechSeconds(turn,turns,shot.sourcePerformanceBudget),
        plannedAfterBeatSeconds: Number(turn?.plannedAfterBeatSeconds ?? turn?.metadata?.plannedAfterBeatSeconds) || 0
      }))
    }))
  };
}

function h3AssetDirectSemanticFingerprint(project = {}) {
  return crypto.createHash("sha256").update(require('./foundry/canonical').canonicalJson(h3AssetDirectSemanticSource(project))).digest("hex").toUpperCase();
}

const H3_ASSET_DIRECT_SEMANTIC_BATCH_MAX_SHOTS = 5;
const H3_ASSET_DIRECT_SEMANTIC_BATCH_MAX_ATTEMPTS = 2;

function h3AssetDirectSemanticBatches(source = {}, maxShots = H3_ASSET_DIRECT_SEMANTIC_BATCH_MAX_SHOTS) {
  const shots = Array.isArray(source?.shots) ? source.shots : [];
  const size = Math.max(1, Math.round(Number(maxShots) || H3_ASSET_DIRECT_SEMANTIC_BATCH_MAX_SHOTS));
  const batches = [];
  for (let index = 0; index < shots.length; index += size) batches.push(shots.slice(index, index + size));
  return batches;
}

function h3SemanticCompilerItemMissing(sourceShot = {}, item = {}) {
  const missing = [];
  if (item.status === 'source_planning_repair_required') {
    return [`sourcePlanningRepair:${String(item.reasonEn || item.reasonZh || item.reason || 'replan the complete source timeline')}`];
  }
  if (String(item?.shotId || "") !== String(sourceShot?.shotId || "")) missing.push("shotId");
  const sourceSegments = Array.isArray(sourceShot?.subshots) ? sourceShot.subshots : [];
  const segments = Array.isArray(item?.segments) ? item.segments : [];
  if (segments.length !== sourceSegments.length) missing.push(`segments:${sourceSegments.length}`);
  for (let index = 0; index < sourceSegments.length; index += 1) {
    const segment = segments.find(entry => Number(entry?.index) === index) || segments[index] || {};
    for (const field of ["actionZh", "framingZh", "cameraZh", "blockingZh", "stateBeforeZh", "stateAfterZh", "soundZh", "actionEn", "framingEn", "cameraEn", "blockingEn", "stateBeforeEn", "stateAfterEn", "soundEn"]) {
      if (!String(segment?.[field] || "").trim()) missing.push(`segments[${index}].${field}`);
    }
  }
  const sourceDialogue = Array.isArray(sourceShot?.dialogue) ? sourceShot.dialogue : [];
  const dialogue = Array.isArray(item?.dialogue) ? item.dialogue : [];
  let previousSpeechEnd=0,totalSpeechSeconds=0;
  if (dialogue.length !== sourceDialogue.length) missing.push(`dialogue:${sourceDialogue.length}`);
  for (let index = 0; index < sourceDialogue.length; index += 1) {
    const sourceTurn = sourceDialogue[index] || {};
    const turn = dialogue.find(entry => String(entry?.sourceDialogueId || "") === String(sourceTurn?.sourceDialogueId || "")) || dialogue[index] || {};
    if (String(turn.sourceDialogueId || '') !== String(sourceTurn.sourceDialogueId || '')) missing.push(`dialogue[${index}].sourceDialogueId`);
    for (const field of ["deliveryZh", "deliveryEn", "vocalArcZh", "vocalArcEn", "expressionZh", "expressionEn", "expressionArcEn", "bodyZh", "bodyEn", "blockingZh", "blockingEn", "speakerFacingZh", "speakerFacingEn", "listenerReactionZh", "listenerReactionEn"]) {
      if (!String(turn?.[field] || "").trim()) missing.push(`dialogue[${index}].${field}`);
    }
    const start = Number(turn?.startSecond ?? turn?.start);
    const end = Number(turn?.endSecond ?? turn?.end);
    if (!Number.isFinite(start) || !Number.isFinite(end) || start < 0 || end <= start || end > Number(sourceShot?.duration || 15) + 0.05) {
      missing.push(`dialogue[${index}].timeWindow`);
    }
    if(sourceTurn.calculatedSpeechWindow?.characters>0){
      const bounds=sourceTurn.calculatedSpeechWindow,seconds=end-start;
      if(start<0.29||end>Number(sourceShot.duration)-0.34||start<previousSpeechEnd-0.01||seconds<bounds.minSeconds-0.02||seconds>bounds.maxSeconds+0.02)missing.push(`dialogue[${index}].calculatedSpeechWindow:${bounds.minSeconds}-${bounds.maxSeconds}s`);
      previousSpeechEnd=end;totalSpeechSeconds+=seconds;
    }
  }
  missing.push(...require('./shot-performance-contract').silenceFailures(dialogue,Number(sourceShot.duration)));
  return [...new Set(missing)];
}

function mergeH3SemanticCompilerItem(previous = {}, incoming = {}) {
  const mergeDefined = (base, patch) => {
    const merged = { ...(base || {}) };
    for (const [key, value] of Object.entries(patch || {})) {
      if (value === undefined || value === null || value === "") continue;
      merged[key] = value;
    }
    return merged;
  };
  const previousSegments = Array.isArray(previous?.segments) ? previous.segments : [];
  const incomingSegments = Array.isArray(incoming?.segments) ? incoming.segments : [];
  const segmentIndexes = [...new Set([...previousSegments, ...incomingSegments].map((entry, index) => Number(entry?.index ?? index)))].sort((left, right) => left - right);
  const segments = segmentIndexes.map(index => mergeDefined(
    previousSegments.find(entry => Number(entry?.index) === index) || previousSegments[index] || {},
    incomingSegments.find(entry => Number(entry?.index) === index) || (incomingSegments[index]?.index == null ? incomingSegments[index] : {}) || {}
  ));
  const previousDialogue = Array.isArray(previous?.dialogue) ? previous.dialogue : [];
  const incomingDialogue = Array.isArray(incoming?.dialogue) ? incoming.dialogue : [];
  const dialogueKeys = [...new Set([...previousDialogue, ...incomingDialogue].map((entry, index) => String(entry?.sourceDialogueId || entry?.id || `#${index}`)))];
  const dialogue = dialogueKeys.map((key, index) => mergeDefined(
    previousDialogue.find(entry => String(entry?.sourceDialogueId || entry?.id || "") === key) || previousDialogue[index] || {},
    incomingDialogue.find(entry => String(entry?.sourceDialogueId || entry?.id || "") === key) || (!incomingDialogue[index]?.sourceDialogueId && !incomingDialogue[index]?.id ? incomingDialogue[index] : {}) || {}
  ));
  return mergeDefined(previous, {
    ...incoming,
    status: incoming.status || 'compiled',
    ...(segments.length ? { segments } : {}),
    ...(dialogue.length ? { dialogue } : {})
  });
}

function recoverH3SemanticCompilerItems(rawText = "") {
  const text = String(rawText || "");
  const candidates = [];
  for (let index = 0; index < text.length; index += 1) {
    if (text[index] !== "\"") continue;
    const stringEnd = jsonStringTokenEnd(text, index);
    if (stringEnd < 0) break;
    let decoded = "";
    try { decoded = JSON.parse(text.slice(index, stringEnd + 1)); } catch {}
    if (decoded === "items") {
      let cursor = stringEnd + 1;
      while (/\s/.test(text[cursor] || "")) cursor += 1;
      if (text[cursor] === ":") {
        cursor += 1;
        while (/\s/.test(text[cursor] || "")) cursor += 1;
        if (text[cursor] === "[") candidates.push(shotPlanArrayCandidate(text, cursor));
      }
    }
    index = stringEnd;
  }
  const byShotId = new Map();
  for (const candidate of candidates) {
    for (const item of candidate.items || []) {
      const shotId = String(item?.shotId || "");
      if (shotId) byShotId.set(shotId, item);
    }
  }
  return [...byShotId.values()];
}

function strictProviderEnglish(value, maxLength = 360) {
  const source = String(value || "").replace(/\s+/g, " ").trim();
  if (!source || /[\u3400-\u9fff\uf900-\ufaff]/.test(source) || (source.match(/[A-Za-z]/g) || []).length < 3) return "";
  // maxLength is a legacy authoring hint, not permission to discard the
  // completed consequence, final holder, listener or source sound in a field.
  return source;
}

function strictProviderChinese(value, maxLength = 360) {
  const source = sanitizeVisualPromptCue(value).replace(/\s+/g, " ").trim();
  if (!source || !/[\u3400-\u9fff\uf900-\ufaff]/.test(source)) return "";
  return source;
}

function mergeH3AssetDirectSemanticItem(project = {}, shot = {}, compiled = {}) {
  const compiledDialogue = new Map((Array.isArray(compiled?.dialogue) ? compiled.dialogue : []).map((item, index) => [
    String(item?.sourceDialogueId || item?.id || `#${index}`),
    item
  ]));
  const enrichTurn = (turn, index) => {
    const key = String(turn?.sourceDialogueId || turn?.id || `#${index}`);
    const translated = compiledDialogue.get(key) || (Array.isArray(compiled?.dialogue) ? compiled.dialogue[index] : null) || {};
    const deliveryEn = strictProviderEnglish(translated?.deliveryEn, 240) || strictProviderEnglish(turn?.deliveryEn || turn?.metadata?.deliveryEn, 240);
    const vocalArcEn = strictProviderEnglish(translated?.vocalArcEn, 320) || strictProviderEnglish(turn?.vocalArcEn || turn?.metadata?.vocalArcEn, 320);
    const expressionEn = strictProviderEnglish(translated?.expressionEn, 240) || strictProviderEnglish(turn?.expressionEn || turn?.metadata?.expressionEn, 240);
    const expressionArcEn = strictProviderEnglish(translated?.expressionArcEn, 280) || strictProviderEnglish(turn?.expressionArcEn || turn?.metadata?.expressionArcEn, 280);
    const bodyEn = strictProviderEnglish(translated?.bodyEn, 260) || strictProviderEnglish(turn?.bodyEn || turn?.metadata?.bodyEn, 260);
    const blockingEn = strictProviderEnglish(translated?.blockingEn, 320) || strictProviderEnglish(turn?.blockingEn || turn?.metadata?.blockingEn, 320);
    const speakerFacingEn = strictProviderEnglish(translated?.speakerFacingEn, 240) || strictProviderEnglish(turn?.speakerFacingEn || turn?.metadata?.speakerFacingEn, 240);
    const listenerReactionEn = strictProviderEnglish(translated?.listenerReactionEn, 260) || strictProviderEnglish(turn?.listenerReactionEn || turn?.metadata?.listenerReactionEn, 260);
    const deliveryZh = strictProviderChinese(translated?.deliveryZh, 180) || strictProviderChinese(turn?.delivery || turn?.sourceTone || turn?.metadata?.delivery, 180);
    const vocalArcZh = strictProviderChinese(translated?.vocalArcZh, 240);
    const expressionZh = strictProviderChinese(translated?.expressionZh, 220) || strictProviderChinese(turn?.emotionPeak || turn?.metadata?.emotionPeak, 220);
    const bodyZh = strictProviderChinese(translated?.bodyZh, 240) || strictProviderChinese(turn?.body || turn?.metadata?.body, 240);
    const blockingZh = strictProviderChinese(translated?.blockingZh, 260) || strictProviderChinese(turn?.blocking || turn?.metadata?.blocking, 260);
    const speakerFacingZh = strictProviderChinese(translated?.speakerFacingZh, 220) || strictProviderChinese(turn?.speakerFacing || turn?.metadata?.speakerFacing, 220);
    const listenerReactionZh = strictProviderChinese(translated?.listenerReactionZh, 220) || strictProviderChinese(turn?.listenerReaction || turn?.listenerBeat || turn?.metadata?.listenerReaction || turn?.metadata?.listenerBeat, 220);
    const startSecond = Number(translated?.startSecond ?? translated?.start);
    const endSecond = Number(translated?.endSecond ?? translated?.end);
    const validWindow = Number.isFinite(startSecond) && Number.isFinite(endSecond)
      && startSecond >= 0 && endSecond > startSecond && endSecond <= Number(shot?.duration || 15) + 0.05;
    return {
      ...turn,
      ...(deliveryEn ? { deliveryEn } : {}),
      ...(vocalArcEn ? { vocalArcEn } : {}),
      ...(expressionEn ? { expressionEn } : {}),
      ...(expressionArcEn ? { expressionArcEn } : {}),
      ...(bodyEn ? { bodyEn } : {}),
      ...(blockingEn ? { blockingEn } : {}),
      ...(speakerFacingEn ? { speakerFacingEn } : {}),
      ...(listenerReactionEn ? { listenerReactionEn } : {}),
      ...(deliveryZh ? { deliveryZh } : {}),
      ...(vocalArcZh ? { vocalArcZh } : {}),
      ...(expressionZh ? { expressionZh } : {}),
      ...(bodyZh ? { bodyZh } : {}),
      ...(blockingZh ? { blockingZh } : {}),
      ...(speakerFacingZh ? { speakerFacingZh } : {}),
      ...(listenerReactionZh ? { listenerReactionZh } : {}),
      ...(validWindow ? { startSecond, endSecond, start:startSecond, end:endSecond } : {}),
      metadata: {
        ...(turn?.metadata || {}),
        ...(deliveryEn ? { deliveryEn } : {}),
        ...(vocalArcEn ? { vocalArcEn } : {}),
        ...(expressionEn ? { expressionEn } : {}),
        ...(expressionArcEn ? { expressionArcEn } : {}),
        ...(bodyEn ? { bodyEn } : {}),
        ...(blockingEn ? { blockingEn } : {}),
        ...(speakerFacingEn ? { speakerFacingEn } : {}),
        ...(listenerReactionEn ? { listenerReactionEn } : {}),
        ...(deliveryZh ? { deliveryZh } : {}),
        ...(vocalArcZh ? { vocalArcZh } : {}),
        ...(expressionZh ? { expressionZh } : {}),
        ...(bodyZh ? { bodyZh } : {}),
        ...(blockingZh ? { blockingZh } : {}),
        ...(speakerFacingZh ? { speakerFacingZh } : {}),
        ...(listenerReactionZh ? { listenerReactionZh } : {})
      }
    };
  };
  const compiledSegments = Array.isArray(compiled?.segments) ? compiled.segments : [];
  const providerTimedDirections = (shot?.subshots || []).map((source, index) => {
    const translated = compiledSegments.find(item => Number(item?.index) === index) || compiledSegments[index] || {};
    const translatedStart = Number(translated?.startSecond ?? translated?.start);
    const translatedEnd = Number(translated?.endSecond ?? translated?.end);
    const start = Number.isFinite(translatedStart) ? translatedStart : (Number(source?.start) || 0);
    const end = Number.isFinite(translatedEnd) && translatedEnd > start
      ? translatedEnd
      : (Number(source?.end) || Number(shot?.duration) || 10);
    return {
      start,
      end,
      speakerId: String(source?.speakerId || ""),
      actionZh: strictProviderChinese(translated?.actionZh, 320) || strictProviderChinese(source?.action || source?.visualBeat, 320),
      framingZh: strictProviderChinese(translated?.framingZh, 140) || strictProviderChinese(source?.framing || source?.shotSize, 140),
      cameraZh: strictProviderChinese(translated?.cameraZh, 180) || strictProviderChinese(source?.camera || source?.cameraMove, 180),
      blockingZh: strictProviderChinese(translated?.blockingZh, 260) || strictProviderChinese(source?.blocking || source?.position || source?.eyelineDirection, 260),
      backgroundActionZh: strictProviderChinese(translated?.backgroundActionZh, 260) || strictProviderChinese(source?.backgroundAction || source?.ensembleAction || source?.listenerReaction, 260),
      stateBeforeZh: strictProviderChinese(translated?.stateBeforeZh, 220) || strictProviderChinese(source?.stateBefore, 220),
      stateAfterZh: strictProviderChinese(translated?.stateAfterZh, 220) || strictProviderChinese(source?.stateAfter, 220),
      soundZh: strictProviderChinese(translated?.soundZh, 180) || strictProviderChinese(source?.sound, 180),
      actionEn: strictProviderEnglish(translated?.actionEn, 320),
      visualEn: strictProviderEnglish(translated?.actionEn, 320),
      framingEn: strictProviderEnglish(translated?.framingEn, 140),
      cameraEn: strictProviderEnglish(translated?.cameraEn, 180),
      blockingEn: strictProviderEnglish(translated?.blockingEn, 260),
      backgroundActionEn: strictProviderEnglish(translated?.backgroundActionEn, 260),
      stateBeforeEn: strictProviderEnglish(translated?.stateBeforeEn, 220),
      stateAfterEn: strictProviderEnglish(translated?.stateAfterEn, 220),
      soundEn: strictProviderEnglish(translated?.soundEn, 180)
    };
  });
  const canonicalDialogueTurns = uniqueDialogueTurns(project, shot);
  return {
    ...shot,
    actionEn: strictProviderEnglish(compiled?.actionEn, 420) || shot?.actionEn || "",
    stateBeforeEn: strictProviderEnglish(compiled?.stateBeforeEn, 240) || shot?.stateBeforeEn || "",
    stateAfterEn: strictProviderEnglish(compiled?.stateAfterEn, 240) || shot?.stateAfterEn || "",
    providerTimedDirections: providerTimedDirections.some(item => item.actionEn || item.cameraEn || item.stateBeforeEn || item.stateAfterEn)
      ? providerTimedDirections
      : (shot?.providerTimedDirections || []),
    dialogueTurns: canonicalDialogueTurns.map(enrichTurn),
    subshots: (shot?.subshots || []).map(subshot => ({
      ...subshot,
      dialogueTurns: (subshot?.dialogueTurns || []).map(enrichTurn)
    })),
    providerSemanticCompileSource: "ai-batch"
  };
}

function promptReviewReferencePlan(project = {}, shot = {}, mode = "", referenceAudioMode = "image_only", apiMode = project.generation?.hailuoApiMode || "auto") {
  const imageRoles = [];
  const videos = [];
  const videoRoles = [];
  const importedImages = project.importedProductionPackage && Array.isArray(shot?.promptReviewReferencePlan?.images)
    ? shot.promptReviewReferencePlan.images
    : [];
  if (importedImages.length) {
    const lockedRoles = importedImages.map(reference => {
      const candidate = (project.candidates || []).find(item => (
        item.source === "codex-production-package"
        && item.importedAssetId
        && item.entityId === reference.entityId
      ));
      const assetId = reference.assetId
        || candidate?.importedAssetId
        || (reference.type === "product" ? project.product?.assetId : "")
        || "";
      return { ...reference, assetId, reviewPlaceholder: true };
    });
    return {
      images: lockedRoles.map((item, index) => `prompt-review://${shot.id || "shot"}/image-${index + 1}-${item.type}`),
      imageRoles: lockedRoles,
      audios: [],
      videos: [],
      videoRoles: [],
      videoAudios: [],
      referenceAudioMode: "image_only",
      hailuoApiMode: "reference_to_video",
      reviewOnly: true,
      importedReferenceOrderLocked: true
    };
  }
  const addImage = (type, entityId, label, extra = {}) => {
    if (!entityId && type !== "product") return;
    if (imageRoles.some(item => item.type === type && item.entityId === entityId)) return;
    imageRoles.push({ type, entityId, label, ...extra, reviewPlaceholder: true });
  };
  const strategy = resolveShotVideoStrategy({
    ...project,
    generation: { ...(project.generation || {}), mode: mode || project.generation?.mode }
  }, shot);
  for (const stage of strategy.frameStages || []) {
    const label = stage === "storyboard_sheet"
      ? "本镜逐秒分镜合图（生成后自动绑定）"
      : stage === "storyboard_start"
        ? "本镜剧情首帧（生成后自动绑定）"
        : "本镜剧情尾帧（生成后自动绑定）";
    addImage(stage, shot.id, label);
  }
  if (shot.sceneId && sceneReferenceRequired(project, shot)) {
    const scene = (project.scenes || []).find(item => item.id === shot.sceneId);
    addImage("scene", shot.sceneId, `场景“${scene?.name || shot.sceneId}”完整原始四视图（整张原样绑定，不裁切、不拆格）`);
  }
  // The review modal must enumerate the exact parent manifest in the same order
  // as shotReferences(). Every declared visible participant, including silent
  // entrants, keeps a stable identity; mentions of absent people add no image.
  const videoCharacterIds = shotReferenceCharacterIds(project, shot);
  for (const characterId of videoCharacterIds) {
    const character = (project.characters || []).find(item => item.id === characterId);
    addImage("character", characterId, `角色“${character?.name || characterId}”人物参考（生成后自动绑定）`);
  }
  // Keep ordering identical to shotReferences(): frame -> scene -> characters
  // -> product -> wardrobe -> props. Prompt review and submission therefore
  // share one stable <Picture N> contract.
  if (shotVideoProductReferenceRequired(project, shot) && project.product?.imagePath) {
    addImage("product", "product", `商品“${project.product?.name || "用户上传商品"}”原图参考`);
  }
  for (const binding of require("./drama-staging-contract").activeWardrobeBindings(project, shot)) {
    const wardrobe = (project.assetLibraries?.wardrobes || []).find(item => item.id === binding.wardrobeId);
    if (wardrobe?.id && wardrobe.changeRequired !== false) {
      addImage("wardrobe", wardrobe.id, `角色“${wardrobe.characterName || binding.characterId || ""}”服装“${wardrobe.name || wardrobe.id}”（生成后自动绑定）`, { characterId: binding.characterId });
    }
  }
  const propLookups = shotVideoPropBindings(project, shot).map(item => item.propId);
  for (const lookup of [...new Set(propLookups.filter(Boolean))]) {
    const prop = (project.assetLibraries?.props || []).find(item => item.id === lookup || item.name === lookup || item.id === `prop_${slug(lookup)}`);
    if (prop?.id && !isSameProductName(prop.name, project.product?.name)) {
      addImage("prop", prop.id, `剧情物品“${prop.name || prop.id}”（生成后自动绑定）`);
    }
  }
  if (strategy.usePreviousVideo) {
    const currentNumber = Number(shot.number) || 0;
    const previousShot = (project.shots || [])
      .filter(item => item.id !== shot.id && (Number(item.number) || 0) < currentNumber)
      .sort((left, right) => (Number(right.number) || 0) - (Number(left.number) || 0))[0];
    if (previousShot?.id) {
      videos.push(`prompt-review://${shot.id || "shot"}/video-1-previous-shot`);
      videoRoles.push({
        type: "previous_shot",
        entityId: previousShot.id,
        label: `上一镜 ${previousShot.id} 已确认视频（生成后自动绑定），仅从其尾帧、人物站位和环境声继续`,
        reviewPlaceholder: true
      });
    }
  }
  const speakerIds = [...new Set(uniqueDialogueTurns(project, shot).map(turn => {
    const character = (project.characters || []).find(item => item.id === turn.speakerId || item.name === turn.speaker);
    return character?.id || turn.speakerId || "";
  }).filter(Boolean))];
  const normalizedReferenceAudioMode = referenceAudioMode === "image_audio" ? "image_audio" : "image_only";
  const audios = normalizedReferenceAudioMode === "image_audio" ? speakerIds.map(characterId => {
    const character = (project.characters || []).find(item => item.id === characterId);
    return {
      characterId,
      characterName: character?.name || characterId,
      duration: HAILUO_VOICE_REFERENCE_TARGET_SECONDS,
      reviewPlaceholder: true
    };
  }) : [];
  const planned = {
    images: imageRoles.map((item, index) => `prompt-review://${shot.id || "shot"}/image-${index + 1}-${item.type}`),
    imageRoles,
    audios,
    videos,
    videoRoles,
    videoAudios: [],
    referenceAudioMode: normalizedReferenceAudioMode,
    reviewOnly: true
  };
  // Same effective strategy and filtering as generateShotVideo. Review the
  // actual provider mode, not an always-full-reference approximation.
  const effectiveStrategy = strategy.frameStages.includes("storyboard_sheet") ? "asset_direct" : strategy.strategy;
  const resolvedMode = resolveHailuoApiModeForStrategy(effectiveStrategy, apiMode, audios.length > 0 || strategy.strategy === "continuation");
  const selected = selectHailuoReferencesForMode(planned, resolvedMode);
  if (resolvedMode === "image_to_video") {
    // Provenance for reviewing how temporal frames must be made; these are
    // NOT additional video inputs and must never acquire provider Picture IDs.
    selected.frameSourceImageRoles = imageRoles.filter(role => !["storyboard_start", "storyboard_end"].includes(role.type));
  }
  return selected;
}

const TOPIC_RESPONSE_REQUIRED_FIELDS = Object.freeze([
  "slotId", "title", "genre", "relationship", "referenceKernel", "storyMechanism", "conflictDomain",
  "hookAction", "hook", "firstDialogue", "highlights", "logline",
  "reversal", "emotionalPayoff", "productPlacement", "audienceAppeal", "reason"
]);

function topicResponseJsonSchema(expectedCount = 10, { allowPartial = false } = {}) {
  const count = Math.max(1, Math.min(10, Math.floor(Number(expectedCount) || 10)));
  const stringField = () => ({ type: "string" });
  return {
    type: "object",
    required: ["topics"],
    properties: {
      topics: {
        type: "array",
        // The prompt still asks for all ten cards, while the transport schema
        // permits a provider to close valid JSON after any non-empty prefix.
        // This turns a constrained provider's 1-9 cards into usable output
        // instead of forcing it to truncate the entire JSON document.
        minItems: allowPartial ? 1 : count,
        maxItems: count,
        items: {
          type: "object",
          // These five fields are enough to display and select a coherent
          // topic. Remaining causal fields stay requested but optional so
          // providers with stricter schema dialects do not reject the request.
          required: ["title", "highlights", "logline", "hook", "reversal", "emotionalPayoff", "productPlacement"],
          properties: {
            slotId: { type: "string", enum: Array.from({ length: 10 }, (_, index) => `T${String(index + 1).padStart(2, "0")}`) },
            title: stringField(),
            genre: stringField(),
            relationship: stringField(),
            referenceKernel: stringField(),
            storyMechanism: { type: "string", enum: ["rescue_repaid", "kindness_misjudged", "sacrifice_repaid", "evidence_reversal"] },
            conflictDomain: stringField(),
            hookAction: stringField(),
            hook: stringField(),
            firstDialogue: stringField(),
            highlights: {
              type: "array",
              minItems: 3,
              maxItems: 3,
              items: stringField()
            },
            logline: stringField(),
            reversal: stringField(),
            emotionalPayoff: stringField(),
            productPlacement: stringField(),
            audienceAppeal: stringField(),
            reason: stringField()
          }
        }
      }
    }
  };
}

function topicCandidateArray(data) {
  if (Array.isArray(data)) return data;
  return Array.isArray(data?.topics) ? data.topics : [];
}

function hasNonEmptyCreativeValue(value, seen = new Set()) {
  if (typeof value === "string") return Boolean(value.trim());
  if (typeof value === "number") return Number.isFinite(value);
  if (typeof value === "boolean") return true;
  if (!value || typeof value !== "object" || seen.has(value)) return false;
  seen.add(value);
  const children = Array.isArray(value) ? value : Object.values(value);
  return children.some(child => hasNonEmptyCreativeValue(child, seen));
}

function topicProviderError(error) {
  let current = error;
  let providerError = null;
  const seen = new Set();
  while (current && typeof current === "object" && !seen.has(current)) {
    if (/^PROVIDER_/.test(String(current.code || ""))) providerError = current;
    seen.add(current);
    current = current.cause;
  }
  return providerError;
}

function topicResultDiagnostic(data, meta = {}) {
  let serialized = "";
  try { serialized = JSON.stringify(data) ?? ""; } catch { serialized = String(data ?? ""); }
  const candidates = topicCandidateArray(data);
  let validCardCount = 0;
  try {
    validCardCount = normalizeTopicOptions({ topics: candidates }, {
      expectedCount: 10,
      enforceDiversity: false,
      allowPartial: true
    }).length;
  } catch {}
  const fieldCoverage = Object.fromEntries(TOPIC_RESPONSE_REQUIRED_FIELDS.map(field => [
    field,
    candidates.filter(item => item && typeof item === "object" && item[field] !== undefined && item[field] !== null).length
  ]));
  return {
    stage: String(meta.stage || "topics"),
    provider: String(meta.provider || ""),
    model: String(meta.model || ""),
    sessionId: String(meta.sessionId || ""),
    parsedResultSha256: crypto.createHash("sha256").update(serialized, "utf8").digest("hex"),
    parsedResultChars: serialized.length,
    rootType: Array.isArray(data) ? "array" : (data === null ? "null" : typeof data),
    candidateCount: candidates.length,
    validCardCount,
    hasNonEmptyCreativeContent: hasNonEmptyCreativeValue(data),
    fieldCoverage
  };
}

function persistTopicResultDiagnostic(store, projectId, data, meta = {}) {
  const diagnostic = {
    id: makeId("topic_result"),
    at: new Date().toISOString(),
    ...topicResultDiagnostic(data, meta)
  };
  const project = store.getProject(projectId);
  const existing = Array.isArray(project?.textProviderDiagnostics?.topicResults)
    ? project.textProviderDiagnostics.topicResults
    : [];
  project.textProviderDiagnostics = {
    ...(project.textProviderDiagnostics || {}),
    lastTopicResult: diagnostic,
    topicResults: [diagnostic, ...existing].slice(0, 5)
  };
  store.saveProject(project);
  return diagnostic;
}

function characterVideoPromptForReview(character = {}, duration = 5, speechScript = "") {
  return [
    `人物视频提示词：角色“${character.name || character.id || "未命名角色"}”。`,
    `人物身份与外观：${character.appearanceDescription || character.description || character.identitySignature || "严格保持人物四视图中的脸、年龄、发型和整套服装一致"}。`,
    `音色与说话方式：${character.voiceDescription || "自然、清晰、稳定，符合角色年龄与身份"}。`,
    `画面：严格 ${Number(duration) || 5} 秒，单人正面真人中近景，纯净中性背景，双眼和完整面部始终清楚，嘴部无遮挡，不切镜，不出现第二个人。`,
    `中性校准句（不是剧本台词；从第零秒立即开口，完整说完且只说一次）：“${speechScript || "现在开始校准声音，我会保持自然、清楚、稳定。"}”`,
    "禁止字幕、标题、人物介绍、标识、水印、人物多视图、角色设定板、资产卡、参考图边框、背景音乐和第二个人声。"
  ].join("\n");
}

function characterVoicePromptForReview(character = {}, duration = 5, speechScript = "") {
  return [
    `音频资产提示词：角色“${character.name || character.id || "未命名角色"}”。`,
    `声线身份：${character.voiceDescription || "自然、清晰、稳定，符合角色年龄、经历和人物身份"}。`,
    `采样内容（与剧本台词彻底隔离）：从第零秒立即开口，用同一声线、自然呼吸和稳定响度完整说一次“${speechScript || "现在开始校准声音，我会保持自然、清楚、稳定。"}”，末字在 ${Number(duration) || 5} 秒内自然落下。`,
    "说话要有清楚的年龄感、音高、音色纹理、语速、重音和气口；干声为主，只保留极轻室内底噪，不要混入其他人声、回声、背景音乐或环境对白。",
    "若当前没有手动上传或长期音色库素材，系统只用 H3 生成一次内部音色采样并提取音频；内部采样不作为人物视频资产、不进入剧情成片，也不作为后续镜头画面参考。"
  ].join("\n");
}

function authorityConcurrencyValue(session, kind, fallback) {
  const key = kind === "video" ? "videoConcurrency" : "imageConcurrency";
  const value = Math.floor(Number(session?.[key]));
  if (Number.isFinite(value) && value >= 1) {
    return value;
  }
  if (session?.bypass === true || !session) return Math.max(1, Math.floor(Number(fallback) || 1));
  throw Object.assign(new Error(`管理后台没有返回有效的${kind === "video" ? "视频" : "图片"}并发额度，已停止新的生成任务`), {
    code: "CONCURRENCY_AUTHORITY_INVALID",
    kind
  });
}

function projectFinalDeliveryComplete(project) {
  const outputPath = String(project?.finalVideoPath || "").trim();
  return Boolean(
    outputPath
    && project?.finalVideoStale !== true
    && String(project?.status || "") === "completed"
    && fs.existsSync(outputPath)
  );
}

function completedAutomationStage(project, operation = "", targetId = "") {
  const liveStage = String(project?.automation?.stage || "").trim().toLowerCase();
  if (liveStage && !["completed", "running", "stage_completed"].includes(liveStage)) return liveStage;
  const op = String(operation || project?.automation?.operation || "").toLowerCase();
  if (op === "pipeline_from_stage") return String(targetId || project?.automation?.targetId || project?.currentStage || "script").toLowerCase();
  if (/stitch|final|delivery/.test(op)) return "stitch";
  if (/shot_videos|shot-video|shot_video|video_batch/.test(op)) return "shot_videos";
  if (/storyboard/.test(op)) return "storyboards";
  if (/asset|character|scene|voice|library/.test(op)) return "assets";
  if (/prompt/.test(op)) return "creator_prompts";
  return "script";
}

async function mapWithConcurrency(items, concurrency, worker) {
  const list = Array.isArray(items) ? items : [];
  const limit = Math.max(1, Math.min(list.length || 1, Number(concurrency) || 1));
  const results = new Array(list.length);
  let cursor = 0;
  const run = async () => {
    while (cursor < list.length) {
      const index = cursor++;
      results[index] = await worker(list[index], index);
    }
  };
  // Do not reject while sibling workers are still running.  Returning early
  // used to detach the remaining paid requests from their project operation,
  // so the UI reported failure while background model calls kept completing.
  const settled = await Promise.allSettled(Array.from({ length: Math.min(limit, list.length) }, run));
  const failed = settled.find(item => item.status === "rejected");
  if (failed) throw failed.reason;
  return results;
}

function fastUnitCacheKey(task) {
  return String(Math.max(1, Number(task?.unitStartNumber) || 1));
}

function fastPlanCacheKey(task) {
  return String(Math.max(1, Number(task?.startNumber) || 1));
}

function validFastPlanCacheEntry(entry, task) {
  const batch = Array.isArray(entry?.batch) ? entry.batch : [];
  const expectedCount = Math.max(1, Number(task?.batchSize) || 1);
  const startNumber = Math.max(1, Number(task?.startNumber) || 1);
  return batch.length === expectedCount
    && batch.every((item, index) => String(item?.id || "") === `S${String(startNumber + index).padStart(2, "0")}`);
}

function fastPlanCacheState(planTasks, storedCache = {}) {
  const tasks = Array.isArray(planTasks) ? planTasks : [];
  const source = storedCache && typeof storedCache === "object" && !Array.isArray(storedCache) ? storedCache : {};
  const cache = {};
  for (const task of tasks) {
    const key = fastPlanCacheKey(task);
    if (!validFastPlanCacheEntry(source[key], task)) continue;
    cache[key] = {
      startNumber: task.startNumber,
      endNumber: task.endNumber,
      batch: source[key].batch
    };
  }
  const prefix = [];
  for (const task of tasks) {
    const entry = cache[fastPlanCacheKey(task)];
    if (!validFastPlanCacheEntry(entry, task)) break;
    prefix.push(...entry.batch);
  }
  return {
    cache,
    prefix,
    pending: tasks.filter(task => !validFastPlanCacheEntry(cache[fastPlanCacheKey(task)], task))
  };
}

function validFastUnitCacheEntry(entry, task) {
  const batch = Array.isArray(entry?.batch) ? entry.batch : [];
  const plannedShots = Array.isArray(task?.plannedShots) ? task.plannedShots : [];
  return batch.length === plannedShots.length
    && batch.every((shot, index) => String(shot?.id || "") === String(plannedShots[index]?.id || ""));
}

function fastUnitCacheState(unitTasks, storedCache = {}, existingShots = []) {
  const tasks = Array.isArray(unitTasks) ? unitTasks : [];
  const source = storedCache && typeof storedCache === "object" && !Array.isArray(storedCache) ? storedCache : {};
  const cache = {};
  for (const task of tasks) {
    const key = fastUnitCacheKey(task);
    if (validFastUnitCacheEntry(source[key], task)) {
      cache[key] = {
        unitStartNumber: task.unitStartNumber,
        unitEndNumber: task.unitEndNumber,
        batch: source[key].batch
      };
      continue;
    }
    const prefixBatch = existingShots.slice(task.unitStartIndex, task.unitStartIndex + task.plannedShots.length);
    const prefixEntry = { batch: prefixBatch };
    if (validFastUnitCacheEntry(prefixEntry, task)) {
      cache[key] = {
        unitStartNumber: task.unitStartNumber,
        unitEndNumber: task.unitEndNumber,
        batch: prefixBatch
      };
    }
  }
  const prefix = [];
  for (const task of tasks) {
    const entry = cache[fastUnitCacheKey(task)];
    if (!validFastUnitCacheEntry(entry, task)) break;
    prefix.push(...entry.batch);
  }
  return {
    cache,
    prefix,
    pending: tasks.filter(task => !validFastUnitCacheEntry(cache[fastUnitCacheKey(task)], task))
  };
}

function scriptControlError(intent) {
  const paused = intent === "pause";
  return Object.assign(new Error(paused ? "剧本写作已暂停，已生成内容和断点均已保存" : "剧本写作已停止，已生成内容保留在编辑区"), {
    code: paused ? "SCRIPT_GENERATION_PAUSED" : "SCRIPT_GENERATION_STOPPED"
  });
}

function isScriptControlError(error) {
  return ["SCRIPT_GENERATION_PAUSED", "SCRIPT_GENERATION_STOPPED"].includes(error?.code);
}

function pipelineControlError(intent) {
  const paused = intent === "pause";
  return Object.assign(new Error(paused
    ? "自动化已暂停；未提交任务已停止，已提交视频仍在后台取回"
    : "自动化已停止；未提交任务已停止，已提交视频仍在后台取回"), {
    code: paused ? "PIPELINE_PAUSED" : "PIPELINE_STOPPED"
  });
}

function isPipelineControlError(error) {
  return isScriptControlError(error) || ["PIPELINE_PAUSED", "PIPELINE_STOPPED"].includes(error?.code);
}

function agentCreativeOutputRequired(error, code, message, extra = {}) {
  const causeMessage = String(error?.message || error || "AI 未返回可验证结果").slice(0, 300);
  return Object.assign(new Error(`${message}：${causeMessage}`), {
    code,
    causeCode: String(error?.code || "AGENT_CREATIVE_RESULT_INVALID"),
    cause: error,
    agentRequired: true,
    localCreativeFallbackUsed: false,
    noAutomaticRetry: true,
    retryRequiresExplicitResume: true,
    rawText: error?.rawText,
    rawTextLength: error?.rawTextLength,
    rawTextSha256: error?.rawTextSha256,
    rawTextTruncated: error?.rawTextTruncated,
    upstreamDone: error?.upstreamDone,
    upstreamReceipt: error?.upstreamReceipt,
    sessionId: error?.sessionId,
    attempt: error?.attempt,
    ...extra
  });
}

function hasRecoverableScriptCheckpoint(project = {}) {
  const checkpoint = project?.script?.generationCheckpoint || {};
  const analysisCheckpoint = project?.script?.analysisCheckpoint || {};
  return Boolean(
    checkpoint.directFastFailure?.retryRequiresExplicitResume === true
    || checkpoint.planContractFailure?.retryRequiresExplicitResume === true
    || checkpoint.unitContractFailure?.retryRequiresExplicitResume === true
    || checkpoint.scriptRepair?.retryRequiresExplicitResume === true
    || Array.isArray(checkpoint.semanticShotSchedule) && checkpoint.semanticShotSchedule.length > 0
    || checkpoint.directFastSpine && typeof checkpoint.directFastSpine === "object"
    || Array.isArray(checkpoint.directFastSegments) && checkpoint.directFastSegments.length > 0
    || Array.isArray(checkpoint.shotPlan) && checkpoint.shotPlan.length > 0
    || Array.isArray(project?.shots) && project.shots.length > 0
    || (analysisCheckpoint.signature && Array.isArray(analysisCheckpoint.chunks))
  );
}

function projectDurationContract(project = {}) {
  const targetSeconds = Math.round(Number(project?.generation?.targetDurationSeconds) || 0);
  const plannedSeconds = (Array.isArray(project?.shots) ? project.shots : [])
    .reduce((sum, shot) => sum + (Number(shot?.duration) || 0), 0);
  const hasShots = Array.isArray(project?.shots) && project.shots.length > 0;
  const withinReference = hasShots && targetSeconds > 0
    && Math.abs(plannedSeconds - targetSeconds) <= Math.max(5, targetSeconds * 0.08);
  return {
    targetSeconds,
    plannedSeconds,
    hasShots,
    locked: false,
    ok: hasShots,
    withinReference
  };
}

const DETACHED_AUTOMATION_RECONCILE_STATUSES = new Set([
  "running",
  "pausing",
  "stopping",
  "completed",
  "failed"
]);

function summaryHasActiveVideoWork(summary = {}) {
  return Array.isArray(summary.activeVideoJobs)
    && summary.activeVideoJobs.some(job => isActiveVideoJob({
      ...job,
      type: job?.type || job?.jobType || "shot_video"
    }));
}

function summaryMayNeedDetachedAutomationReconcile(summary = {}, options = {}) {
  const status = String(summary.automationStatus || "").trim();
  const explicitProject = options.explicitProject === true;
  // A global startup sweep may only touch states that claim live ownership.
  // Historical failed or pre-index projects are reconciled lazily when the
  // user opens that one project; loading all of them would recreate the same
  // startup freeze this guard is intended to prevent.
  return explicitProject
    || (status !== "failed" && DETACHED_AUTOMATION_RECONCILE_STATUSES.has(status))
    || summaryHasActiveVideoWork(summary);
}

function summaryMayNeedAutomaticResume(summary = {}) {
  const status = String(summary.automationStatus || "").trim();
  return !status || status === "paused_account" || status === "paused_remote";
}

function isAiLiveWritingStatus(value = "") {
  const source = String(value || "").trim();
  if (!source) return false;
  if (/^#\s*AI\s*(?:实时)?写作(?:输出|状态)/i.test(source)) return true;
  const statusSignals = [
    /模型仍在生成/,
    /以下内容会在本阶段完成后自动整理为制作剧本/,
    /当前阶段[:：]?\s*优先加速写作/,
    /批单元规划正在并行生成/,
    /超过目标时间仍继续同一任务/
  ];
  return statusSignals.filter(pattern => pattern.test(source)).length >= 2;
}

function hasAcceptedAuthoredSource(project = {}) {
  if(require('./shot-screenplay').current(project.script?.shotScreenplay,project.script?.raw||''))return true;
  const script = project.script || {};
  const raw = String(script.raw || "").trim();
  const authored = script.adaptiveAuthoring;
  if(raw && authored?.documentComplete===true && String(authored.text||'').trim()===raw) return true;
  if (!raw || authored?.status === "needs_review") return false;
  // Runtime targeting describes the writing contract, not whether writing is
  // finished. A ready receipt must belong to the exact saved revision.
  if (authored?.status === "ready" && String(authored.text || "").trim() === raw) return true;
  return script.authoredWithoutDurationTarget === true && (!authored || authored.status === "ready");
}

function scriptPipelineEntryRoute(project = {}) {
  const duration = projectDurationContract(project);
  const raw = String(project?.script?.raw || "");
  const sourceFingerprint = String(project?.script?.sourceFingerprint || "");
  const generationCheckpoint = project?.script?.generationCheckpoint;
  // During autonomous repair the visible shots/raw still belong to the rejected
  // revision. The active AI checkpoint is authoritative until the replacement
  // script is fully materialized; never route its live draft into upload analysis.
  if (projectInputMode(project) === "ai" && generationCheckpoint?.autonomousRepair === true) return "resume_generation";
  if (project.script?.adaptiveAuthoring?.status === "needs_review" && !hasAcceptedAuthoredSource(project)) return "resume_generation";
  if (duration.hasShots && sourceFingerprint
    && crypto.createHash("sha256").update(raw).digest("hex") !== sourceFingerprint) return "reanalyze_source";
  if (duration.hasShots && !duration.ok) return "reanalyze_duration";
  if (duration.hasShots && projectInputMode(project) === "manual") {
    const expectedDialogueLedger = productionDialogueLedgerFromScript(raw);
    if (expectedDialogueLedger.length
      && !sourceDialogueLedgerMatches(project?.script?.sourceDialogueLedger, expectedDialogueLedger)) {
      return "reanalyze_dialogue";
    }
  }
  if (duration.hasShots) return "ready";
  if (generationCheckpoint) return "resume_generation";
  if (project.script?.adaptiveAuthoring && !hasAcceptedAuthoredSource(project)) return "resume_generation";
  if (String(project?.script?.raw || "").trim()) {
    if (projectInputMode(project) === "ai" && isAiLiveWritingStatus(project.script.raw)) return "missing";
    return "analyze_imported";
  }
  return "missing";
}

function projectInputMode(project = {}) {
  // Once authored and reviewed, the exact text is an immutable analysis input
  // just like an upload. This does not change the saved user input preference
  // or original-runtime policy; it selects the common lossless parser.
  if(hasAcceptedAuthoredSource(project))return "manual";
  return String(project?.productionPlan?.inputMode || "ai").trim() === "manual" ? "manual" : "ai";
}

function resumedTextProvider(project = {}, settings = {}) {
  const failoverKind = String((project?.automation?.repairJournal || [])
    .find(entry => entry?.status === "provider_failover")?.providerKind || "").trim();
  const profile = failoverKind ? settings?.textProviderProfiles?.[failoverKind] : null;
  if (profile
    && String(profile.baseUrl || "").trim()
    && String(profile.model || "").trim()
    && String(profile.apiKey || "").trim()) {
    return { ...profile, authSource: "user" };
  }
  return settings?.textProvider || {};
}

function directorCompileConcurrency(project = {}, settings = {}) {
  const provider = resumedTextProvider(project, settings);
  return provider?.kind === "puream-relay" ? 4 : 8;
}

function ideaScriptBootstrapGaps(project = {}) {
  const gaps = [];
  const topics = Array.isArray(project?.ideation?.topics) ? project.ideation.topics : [];
  const selectedId = String(project?.ideation?.selectedTopicId || "").trim();
  const selectedTopic = topics.find(item => item.id === selectedId) || null;
  if (!topics.length) gaps.push("先点「一键生成选题」");
  else if (!selectedTopic) gaps.push("从已生成选题里点选一个题材");
  else {
    const topicContracts = [
      [selectedTopic.hookAction || selectedTopic.hook, "选题缺少可拍的开场冲突"],
      [selectedTopic.logline, "选题缺少可复述的故事主线"],
      [selectedTopic.reversal || selectedTopic.reversalSource || selectedTopic.proofChain, "选题缺少有铺垫的主反转"],
      [selectedTopic.emotionalPayoff || selectedTopic.settlementAction, "选题缺少行动兑现的情绪结局"]
    ];
    for (const [value, message] of topicContracts) {
      if (!String(value || "").trim()) gaps.push(message);
    }
  }
  const productReadiness = topicProductReadiness(project);
  if (productReadiness.required) gaps.push(...productReadiness.missing);
  return gaps;
}

function assertIdeaScriptBootstrapReady(project = {}) {
  const gaps = ideaScriptBootstrapGaps(project);
  if (!gaps.length) return project;
  throw Object.assign(new Error(`新项目还不能直接开跑。请先完成：${gaps.join("；")}。完成后点「生成并自动生产」，或再点「一键全流程」。`), {
    code: "SCRIPT_BOOTSTRAP_REQUIRED",
    gaps
  });
}

function assertScriptMaterializedForPipeline(project = {}) {
  if (Array.isArray(project.shots) && project.shots.length > 0 && String(project?.script?.raw || "").trim()) return project;
  const checkpoint = project?.script?.generationCheckpoint || {};
  const completedPlan = Array.isArray(checkpoint.shotPlan) ? checkpoint.shotPlan.length : 0;
  const error = Object.assign(new Error(
    completedPlan > 0
      ? `剧本仍在续写断点（已完成分镜规划 ${completedPlan} 个），请先继续写完剧本；未完整物化前不会进入资产、视频或拼接。`
      : "剧本尚未完整拆解为可生产分镜，请先完成剧本生成或导入完整剧本后再继续。"
  ), {
    code: "SCRIPT_NOT_MATERIALIZED",
    completedPlan,
    retryRequiresExplicitResume: Boolean(project?.script?.generationCheckpoint)
  });
  throw error;
}

function textFailureEvidence(error) {
  const evidence = { noAutomaticRetry: false, upstreamReceipt: null, partialText: "", rawText: "" };
  const seen = new Set();
  let current = error;
  while (current && typeof current === "object" && !seen.has(current)) {
    seen.add(current);
    if (current.noAutomaticRetry === true) evidence.noAutomaticRetry = true;
    if (!evidence.upstreamReceipt && current.upstreamReceipt) evidence.upstreamReceipt = current.upstreamReceipt;
    if (!evidence.partialText && String(current.partialText || "").trim()) evidence.partialText = String(current.partialText);
    if (!evidence.rawText && String(current.rawText || "").trim()) evidence.rawText = String(current.rawText);
    current = current.cause;
  }
  return evidence;
}

function shouldStopAutomaticTextRetry(error) {
  const evidence = textFailureEvidence(error);
  if (evidence.noAutomaticRetry || evidence.upstreamReceipt || evidence.partialText) return true;
  const code = String(error?.code || "").trim();
  if (!code) return false;
  if (["PROVIDER_TIMEOUT", "PROVIDER_REQUEST_ABORTED", "TEXT_RESULT_EMPTY", "MODEL_JSON_INVALID"].includes(code)) return true;
  return /^(PUREAM_|TEXT_PROVIDER_|PROVIDER_|OPENAI_|GEMINI_|CLAUDE_)/.test(code);
}

const SCRIPT_PLAN_HARD_VALIDATION_CODES = new Set([
  "SCRIPT_PLAN_BATCH_INVALID",
  "SCRIPT_PLAN_BATCH_SEQUENCE_INVALID",
  "SCRIPT_PLAN_BATCH_CONTRACT_FAILED"
]);
const SCRIPT_PLAN_PAID_STOP_CODES = new Set([
  ...SCRIPT_PLAN_HARD_VALIDATION_CODES,
  "MODEL_JSON_INVALID"
]);
const SCRIPT_UNIT_HARD_VALIDATION_CODES = new Set([
  "SCRIPT_UNIT_BATCH_STRUCTURE_INVALID",
  "SCRIPT_UNIT_BATCH_SEQUENCE_INVALID",
  "SCRIPT_UNIT_CONTRACT_FAILED",
  "SCRIPT_UNIT_BATCH_INVALID"
]);
const SCRIPT_UNIT_PAID_STOP_CODES = new Set([
  ...SCRIPT_UNIT_HARD_VALIDATION_CODES,
  "MODEL_JSON_INVALID"
]);

function isCompletedUpstreamTextReceipt(receipt) {
  const source = String(receipt?.receiptSource || "").trim();
  return ["puream.desktop.done", "puream.desktop.billing"].includes(source);
}

function paidPlanValidationMustStop(error, receipt) {
  return SCRIPT_PLAN_PAID_STOP_CODES.has(String(error?.code || ""))
    && isCompletedUpstreamTextReceipt(receipt);
}

function paidUnitValidationMustStop(error, receipt) {
  return SCRIPT_UNIT_PAID_STOP_CODES.has(String(error?.code || ""))
    && isCompletedUpstreamTextReceipt(receipt);
}

function planReceiptEvidence(receipt = {}) {
  const finiteOrNull = value => Number.isFinite(Number(value)) ? Number(value) : null;
  return {
    sessionId: String(receipt?.sessionId || ""),
    model: String(receipt?.model || ""),
    attempt: Number(receipt?.attempt) || 1,
    receiptSource: String(receipt?.receiptSource || ""),
    billingStatus: String(receipt?.billingStatus || ""),
    chargeCents: finiteOrNull(receipt?.chargeCents),
    chargeYuan: finiteOrNull(receipt?.chargeYuan)
  };
}

function paidPlanValidationEvidence(error, rawText, parsedData, receipt, range = {}) {
  const exactRaw = String(rawText || (parsedData === undefined ? "" : JSON.stringify(parsedData)) || "");
  const persistedLimit = 120_000;
  const persistedRaw = exactRaw.slice(0, persistedLimit);
  return {
    id: makeId("plan_contract_failure"),
    at: new Date().toISOString(),
    code: String(error?.code || "SCRIPT_PLAN_BATCH_CONTRACT_FAILED"),
    message: String(error?.message || "分段单元规划违反生产硬合同").slice(0, 2000),
    failures: Array.isArray(error?.failures) ? error.failures.slice(0, 50) : [],
    startNumber: Number(range.startNumber) || 0,
    endNumber: Number(range.endNumber) || 0,
    ideaSignature: String(range.ideaSignature || ""),
    topicId: String(range.topicId || ""),
    blueprintAttempt: Number(range.blueprintAttempt) || 1,
    noAutomaticRetry: true,
    retryRequiresExplicitResume: true,
    rawText: persistedRaw,
    rawTextLength: exactRaw.length,
    rawTextSha256: crypto.createHash("sha256").update(exactRaw, "utf8").digest("hex"),
    rawTextTruncated: exactRaw.length > persistedRaw.length,
    receipt: planReceiptEvidence(receipt)
  };
}

function plannedShotBatchSha256(plannedShots) {
  return crypto.createHash("sha256").update(JSON.stringify(Array.isArray(plannedShots) ? plannedShots : []), "utf8").digest("hex");
}

function paidUnitValidationEvidence(error, rawText, parsedData, receipt, range = {}) {
  const exactRaw = String(rawText || (parsedData === undefined ? "" : JSON.stringify(parsedData)) || "");
  const capturedFullRaw = range.rawTextTruncated !== true
    && (!Number(range.rawTextLength) || Number(range.rawTextLength) === exactRaw.length);
  const plannedShots = Array.isArray(range.plannedShots) ? range.plannedShots : [];
  const plannedShotIds = plannedShots.map(item => String(item?.id || "").toUpperCase());
  const actualRawSha256 = crypto.createHash("sha256").update(exactRaw, "utf8").digest("hex");
  return {
    id: makeId("unit_contract_failure"),
    at: new Date().toISOString(),
    code: String(error?.code || "SCRIPT_UNIT_CONTRACT_FAILED"),
    message: String(error?.message || "正式生成单元违反生产硬合同").slice(0, 2000),
    failures: Array.isArray(error?.failures) ? error.failures.slice(0, 50) : [],
    startNumber: Number(range.startNumber) || 0,
    endNumber: Number(range.endNumber) || 0,
    plannedShotIds,
    plannedShotsSha256: plannedShotBatchSha256(plannedShots),
    ideaSignature: String(range.ideaSignature || ""),
    topicId: String(range.topicId || ""),
    blueprintAttempt: Number(range.blueprintAttempt) || 1,
    draftAttempt: Number(range.draftAttempt) || 1,
    generationMode: String(range.generationMode || ""),
    noAutomaticRetry: true,
    retryRequiresExplicitResume: true,
    rawText: exactRaw,
    rawTextLength: capturedFullRaw ? exactRaw.length : (Number(range.rawTextLength) || exactRaw.length),
    rawTextSha256: capturedFullRaw ? actualRawSha256 : (String(range.rawTextSha256 || "") || actualRawSha256),
    rawTextTruncated: !capturedFullRaw,
    receipt: planReceiptEvidence(receipt)
  };
}

function paidPlanRecoveryStop(failure, recoveryCode, message, details = {}) {
  return Object.assign(new Error(message), {
    code: SCRIPT_PLAN_PAID_STOP_CODES.has(String(failure?.code || ""))
      ? String(failure.code)
      : "SCRIPT_PLAN_BATCH_CONTRACT_FAILED",
    recoveryCode,
    paidRawRecovery: true,
    noAutomaticRetry: true,
    retryRequiresExplicitResume: true,
    failureId: String(failure?.id || ""),
    ...details
  });
}

function paidUnitRecoveryStop(failure, recoveryCode, message, details = {}) {
  return Object.assign(new Error(message), {
    code: SCRIPT_UNIT_PAID_STOP_CODES.has(String(failure?.code || ""))
      ? String(failure.code)
      : "SCRIPT_UNIT_CONTRACT_FAILED",
    recoveryCode,
    paidRawRecovery: true,
    noAutomaticRetry: true,
    retryRequiresExplicitResume: true,
    failureId: String(failure?.id || ""),
    ...details
  });
}

function jsonStringTokenEnd(text, start) {
  if (text[start] !== "\"") return -1;
  let escaped = false;
  for (let index = start + 1; index < text.length; index += 1) {
    const char = text[index];
    if (escaped) {
      escaped = false;
      continue;
    }
    if (char === "\\") {
      escaped = true;
      continue;
    }
    if (char === "\"") return index;
  }
  return -1;
}

function jsonCompositeTokenEnd(text, start) {
  const opener = text[start];
  if (opener !== "{" && opener !== "[") return { end: -1, malformed: true };
  const stack = [opener === "{" ? "}" : "]"];
  for (let index = start + 1; index < text.length; index += 1) {
    const char = text[index];
    if (char === "\"") {
      const stringEnd = jsonStringTokenEnd(text, index);
      if (stringEnd < 0) return { end: -1, malformed: false };
      index = stringEnd;
      continue;
    }
    if (char === "{" || char === "[") {
      stack.push(char === "{" ? "}" : "]");
      continue;
    }
    if (char !== "}" && char !== "]") continue;
    if (stack.at(-1) !== char) return { end: -1, malformed: true };
    stack.pop();
    if (!stack.length) return { end: index, malformed: false };
  }
  return { end: -1, malformed: false };
}

function shotPlanArrayCandidate(text, arrayStart) {
  const items = [];
  let cursor = arrayStart + 1;
  while (cursor < text.length) {
    while (/\s/.test(text[cursor] || "")) cursor += 1;
    if (cursor >= text.length) return { items, truncated: true, closed: false, malformed: false, incompleteItemStarted: false, arrayStart };
    if (text[cursor] === "]") return { items, truncated: false, closed: true, malformed: false, arrayStart, arrayEnd: cursor };
    if (text[cursor] !== "{") return { items, truncated: false, closed: false, malformed: true, arrayStart };
    const objectToken = jsonCompositeTokenEnd(text, cursor);
    if (objectToken.end < 0) {
      return { items, truncated: !objectToken.malformed, closed: false, malformed: objectToken.malformed, incompleteItemStarted: !objectToken.malformed, arrayStart };
    }
    try {
      const parsed = JSON.parse(text.slice(cursor, objectToken.end + 1));
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        return { items, truncated: false, closed: false, malformed: true, arrayStart };
      }
      items.push(parsed);
    } catch {
      return { items, truncated: false, closed: false, malformed: true, arrayStart };
    }
    cursor = objectToken.end + 1;
    while (/\s/.test(text[cursor] || "")) cursor += 1;
    if (cursor >= text.length) return { items, truncated: true, closed: false, malformed: false, incompleteItemStarted: false, arrayStart };
    if (text[cursor] === "]") return { items, truncated: false, closed: true, malformed: false, arrayStart, arrayEnd: cursor };
    if (text[cursor] !== ",") return { items, truncated: false, closed: false, malformed: true, arrayStart };
    cursor += 1;
    while (/\s/.test(text[cursor] || "")) cursor += 1;
    if (cursor >= text.length) return { items, truncated: true, closed: false, malformed: false, incompleteItemStarted: true, arrayStart };
  }
  return { items, truncated: true, closed: false, malformed: false, incompleteItemStarted: false, arrayStart };
}

function shotPlanArrayCandidates(rawText) {
  const text = String(rawText || "");
  const candidates = [];
  for (let index = 0; index < text.length; index += 1) {
    if (text[index] !== "\"") continue;
    const stringEnd = jsonStringTokenEnd(text, index);
    if (stringEnd < 0) break;
    let decoded = "";
    try { decoded = JSON.parse(text.slice(index, stringEnd + 1)); } catch {}
    if (decoded === "shotPlan") {
      let cursor = stringEnd + 1;
      while (/\s/.test(text[cursor] || "")) cursor += 1;
      if (text[cursor] === ":") {
        cursor += 1;
        while (/\s/.test(text[cursor] || "")) cursor += 1;
        if (text[cursor] === "[") candidates.push(shotPlanArrayCandidate(text, cursor));
      }
    }
    index = stringEnd;
  }
  return candidates;
}

function repairTruncatedJsonObjectTail(text, objectStart) {
  const source = String(text || "");
  const topLevelCommas = [];
  const stack = ["}"];
  let inString = false;
  let escaped = false;
  for (let index = objectStart + 1; index < source.length; index += 1) {
    const char = source[index];
    if (inString) {
      if (escaped) escaped = false;
      else if (char === "\\") escaped = true;
      else if (char === "\"") inString = false;
      continue;
    }
    if (char === "\"") {
      inString = true;
      continue;
    }
    if (char === "{" || char === "[") {
      stack.push(char === "{" ? "}" : "]");
      continue;
    }
    if (char === "}" || char === "]") {
      if (stack.at(-1) !== char) break;
      stack.pop();
      if (!stack.length) return null;
      continue;
    }
    if (char === "," && stack.length === 1) topLevelCommas.push(index);
  }
  // Only discard an unfinished trailing top-level property. Earlier fields are
  // preserved byte-for-byte and the repaired object still has to pass the full
  // production validator before it can enter a checkpoint.
  for (const comma of topLevelCommas.slice(-8).reverse()) {
    const candidateText = `${source.slice(objectStart, comma).trimEnd()}}`;
    try {
      const value = JSON.parse(candidateText);
      if (value && typeof value === "object" && !Array.isArray(value)) {
        return { value, removedTailStart: comma + 1, repairedTextLength: candidateText.length };
      }
    } catch {}
  }
  return null;
}

function shotUnitArrayCandidate(text, arrayStart) {
  const items = [];
  let cursor = arrayStart + 1;
  while (cursor < text.length) {
    while (/\s/.test(text[cursor] || "")) cursor += 1;
    if (cursor >= text.length) return { items, truncated: true, closed: false, malformed: false, arrayStart };
    if (text[cursor] === "]") return { items, truncated: false, closed: true, malformed: false, arrayStart, arrayEnd: cursor };
    if (text[cursor] !== "{") return { items, truncated: false, closed: false, malformed: true, arrayStart };
    const objectStart = cursor;
    const objectToken = jsonCompositeTokenEnd(text, objectStart);
    if (objectToken.end < 0) {
      if (objectToken.malformed) return { items, truncated: false, closed: false, malformed: true, arrayStart };
      const repairedTail = repairTruncatedJsonObjectTail(text, objectStart);
      if (!repairedTail) return { items, truncated: true, closed: false, malformed: false, incompleteItemStarted: true, arrayStart };
      items.push(repairedTail.value);
      return {
        items,
        truncated: true,
        closed: false,
        malformed: false,
        incompleteItemStarted: true,
        repairedTail: {
          itemIndex: items.length - 1,
          removedTailStart: repairedTail.removedTailStart,
          repairedTextLength: repairedTail.repairedTextLength
        },
        arrayStart
      };
    }
    try {
      const parsed = JSON.parse(text.slice(objectStart, objectToken.end + 1));
      if (!parsed || typeof parsed !== "object" || Array.isArray(parsed)) {
        return { items, truncated: false, closed: false, malformed: true, arrayStart };
      }
      items.push(parsed);
    } catch {
      return { items, truncated: false, closed: false, malformed: true, arrayStart };
    }
    cursor = objectToken.end + 1;
    while (/\s/.test(text[cursor] || "")) cursor += 1;
    if (cursor >= text.length) return { items, truncated: true, closed: false, malformed: false, arrayStart };
    if (text[cursor] === "]") return { items, truncated: false, closed: true, malformed: false, arrayStart, arrayEnd: cursor };
    if (text[cursor] !== ",") return { items, truncated: false, closed: false, malformed: true, arrayStart };
    cursor += 1;
  }
  return { items, truncated: true, closed: false, malformed: false, arrayStart };
}

function shotUnitArrayCandidates(rawText) {
  const text = String(rawText || "");
  const candidates = [];
  for (let index = 0; index < text.length; index += 1) {
    if (text[index] !== "\"") continue;
    const stringEnd = jsonStringTokenEnd(text, index);
    if (stringEnd < 0) break;
    let decoded = "";
    try { decoded = JSON.parse(text.slice(index, stringEnd + 1)); } catch {}
    if (decoded === "shots") {
      let cursor = stringEnd + 1;
      while (/\s/.test(text[cursor] || "")) cursor += 1;
      if (text[cursor] === ":") {
        cursor += 1;
        while (/\s/.test(text[cursor] || "")) cursor += 1;
        if (text[cursor] === "[") candidates.push(shotUnitArrayCandidate(text, cursor));
      }
    }
    index = stringEnd;
  }
  return candidates;
}

function extractCompleteShotUnitBatch(rawText, plannedShots) {
  const expectedIds = (Array.isArray(plannedShots) ? plannedShots : []).map(item => String(item?.id || "").toUpperCase());
  if (!expectedIds.length) return { status: "invalid", code: "PAID_UNIT_RAW_BATCH_EMPTY" };
  const candidates = shotUnitArrayCandidates(rawText);
  const usable = [];
  const rejected = [];
  for (const candidate of candidates) {
    const ids = candidate.items.map(item => String(item?.id || "").toUpperCase());
    if (candidate.malformed) {
      rejected.push({ reason: "malformed", ids });
      continue;
    }
    if (candidate.items.length !== expectedIds.length) {
      rejected.push({ reason: "incomplete_batch", ids, expectedIds });
      continue;
    }
    if (ids.some((id, index) => id !== expectedIds[index])) {
      rejected.push({ reason: "non_continuous_ids", ids, expectedIds });
      continue;
    }
    usable.push({ ...candidate, ids });
  }
  if (!usable.length) {
    return {
      status: "invalid",
      code: candidates.length ? "PAID_UNIT_RAW_BATCH_INCOMPLETE" : "PAID_UNIT_RAW_SHOTS_ARRAY_NOT_FOUND",
      candidates: candidates.length,
      rejected
    };
  }
  const signatures = new Set(usable.map(item => JSON.stringify(item.items)));
  if (signatures.size !== 1) {
    return { status: "invalid", code: "PAID_UNIT_RAW_BATCH_AMBIGUOUS", candidates: usable.length, rejected };
  }
  const selected = usable.at(-1);
  return {
    status: "recovered",
    parsedData: { shots: selected.items },
    ids: selected.ids,
    extraction: {
      arrayClosed: selected.closed === true,
      sourceTruncated: selected.truncated === true,
      repairedTail: selected.repairedTail || null
    }
  };
}

/**
 * Extracts only fully closed JSON objects from a truncated shotPlan array.
 * Braces inside JSON strings are skipped by the scanner; prose/fenced-code
 * braces and unrelated JSON objects cannot become plan items.
 */
function extractCompleteShotPlanPrefix(rawText, options = {}) {
  const text = String(rawText || "");
  const startNumber = Math.max(1, Math.round(Number(options.startNumber) || 1));
  const configuredSourceExpectedCount = Math.max(0, Math.round(Number(options.sourceExpectedCount) || 0));
  const maxAcceptedCount = Math.max(1, Math.round(Number(options.maxAcceptedCount) || configuredSourceExpectedCount || SCRIPT_PLAN_BATCH_SIZE));
  const candidates = shotPlanArrayCandidates(text);

  const usable = [];
  const rejected = [];
  for (const candidate of candidates) {
    const ids = candidate.items.map(item => String(item?.id || "").toUpperCase());
    const expectedIds = candidate.items.map((_item, index) => `S${String(startNumber + index).padStart(2, "0")}`);
    if (candidate.malformed || !candidate.truncated || candidate.closed) {
      rejected.push({ reason: candidate.malformed ? "malformed" : "array_not_truncated", ids });
      continue;
    }
    if (candidate.items.length < 1) {
      rejected.push({ reason: "zero_complete_items", ids });
      continue;
    }
    if ((configuredSourceExpectedCount > 0 && candidate.items.length >= configuredSourceExpectedCount)
      || candidate.items.length > maxAcceptedCount
      || (configuredSourceExpectedCount === 0 && !candidate.incompleteItemStarted)) {
      rejected.push({ reason: "not_a_partial_prefix", ids });
      continue;
    }
    if (ids.some((id, index) => id !== expectedIds[index])) {
      rejected.push({ reason: "non_continuous_ids", ids, expectedIds });
      continue;
    }
    usable.push({ ...candidate, ids });
  }
  if (!usable.length) {
    return {
      status: "invalid",
      code: candidates.length ? "PAID_PLAN_PREFIX_NOT_RECOVERABLE" : "PAID_PLAN_PREFIX_ARRAY_NOT_FOUND",
      candidates: candidates.length,
      rejected
    };
  }
  const signatures = new Set(usable.map(item => JSON.stringify(item.items)));
  if (signatures.size !== 1) {
    return { status: "invalid", code: "PAID_PLAN_PREFIX_AMBIGUOUS", candidates: usable.length, rejected };
  }
  const selected = usable.at(-1);
  return {
    status: "recovered",
    items: selected.items,
    ids: selected.ids,
    candidates: usable.length,
    inferredSourceExpectedCount: configuredSourceExpectedCount || (selected.items.length + 1)
  };
}

function paidPlanEvidenceRange(evidence = {}) {
  const explicitStart = Math.round(Number(evidence?.startNumber) || 0);
  const explicitEnd = Math.round(Number(evidence?.endNumber) || 0);
  if (explicitStart > 0 && explicitEnd >= explicitStart) return { startNumber: explicitStart, endNumber: explicitEnd };
  const match = String(evidence?.sessionId || evidence?.receipt?.sessionId || "").match(/-S(\d+)-S(\d+)-attempt-\d+$/i);
  if (!match) return null;
  return { startNumber: Number(match[1]), endNumber: Number(match[2]) };
}

function diagnosticReceiptEvidence(evidence = {}) {
  return planReceiptEvidence(evidence?.receipt && typeof evidence.receipt === "object" ? evidence.receipt : evidence);
}

function recoverPaidPlanJsonPrefixEvidence(evidence, options = {}) {
  if (!evidence || String(evidence.code || "") !== "MODEL_JSON_INVALID") return { status: "none" };
  const checkpoint = options.checkpoint || {};
  const expectedIdeaSignature = String(options.ideaSignature || "");
  const startNumber = Math.max(1, Math.round(Number(options.startNumber) || 1));
  const currentExpectedCount = Math.max(1, Math.round(Number(options.expectedCount) || SCRIPT_PLAN_BATCH_SIZE));
  let range = paidPlanEvidenceRange(evidence);
  const receipt = diagnosticReceiptEvidence(evidence);
  const stop = (recoveryCode, message, details = {}) => ({
    status: "invalid",
    evidence,
    error: paidPlanRecoveryStop(evidence, recoveryCode, message, details)
  });

  if (!isCompletedUpstreamTextReceipt(receipt)) {
    return stop("PAID_PLAN_PREFIX_RECEIPT_NOT_TRUSTED", "截断规划没有可确认的上游完成回执，已停止本地采纳和再次付费提交");
  }
  if (range && (range.startNumber !== startNumber || range.endNumber < range.startNumber)) {
    return stop("PAID_PLAN_PREFIX_RANGE_MISMATCH", "截断规划的请求批次与当前待续批次不一致，已停止本地采纳和再次付费提交", { range, startNumber });
  }
  const checkpointIdeaSignature = String(checkpoint?.ideaSignature || "");
  const evidenceIdeaSignature = String(evidence?.ideaSignature || "");
  const isDedicatedCheckpointEvidence = evidence === checkpoint?.planContractFailure;
  const isSignedFailureEvidence = evidenceIdeaSignature === expectedIdeaSignature
    && evidence.noAutomaticRetry === true
    && evidence.retryRequiresExplicitResume === true;
  const evidenceSessionId = String(evidence?.sessionId || receipt.sessionId || "");
  const expectedSourceKey = `text:script_plan:${evidenceSessionId}:${Number(evidence?.attempt || receipt.attempt) || 1}`;
  const ledgerEntries = Array.isArray(options?.costLedger?.entries) ? options.costLedger.entries : [];
  const matchingSettledCost = ledgerEntries.find(item => (
    String(item?.sourceKey || "") === expectedSourceKey
    && String(item?.status || "") === "settled"
    && String(item?.category || "") === "text"
    && /script_plan/.test(String(item?.operation || ""))
  ));
  if (!expectedIdeaSignature || checkpointIdeaSignature !== expectedIdeaSignature) {
    return stop("PAID_PLAN_PREFIX_IDEA_SIGNATURE_MISMATCH", "截断规划与当前题材或商品签名不一致，已停止本地采纳和再次付费提交");
  }
  if (isDedicatedCheckpointEvidence || isSignedFailureEvidence) {
    if (!isSignedFailureEvidence) {
      return stop("PAID_PLAN_PREFIX_CHECKPOINT_NOT_TRUSTED", "截断规划断点缺少题材签名或付费止损标记，已停止本地采纳和再次付费提交");
    }
  } else if (!matchingSettledCost) {
    return stop("PAID_PLAN_PREFIX_LEDGER_MISMATCH", "文本失败诊断没有匹配当前项目的已结算 script_plan 账单，已停止本地采纳和再次付费提交", { expectedSourceKey });
  }
  if (options.evidenceId && String(options.evidenceId) !== String(evidence.id || "")) {
    return stop("PAID_PLAN_PREFIX_EVIDENCE_ID_MISMATCH", "指定的文本失败证据 ID 与实际诊断不一致，已停止本地采纳");
  }

  const rawText = String(evidence.rawText || "");
  const actualSha256 = crypto.createHash("sha256").update(rawText, "utf8").digest("hex");
  const expectedSha256 = String(evidence.rawTextSha256 || "").toLowerCase();
  if (options.rawTextSha256 && String(options.rawTextSha256).toLowerCase() !== expectedSha256) {
    return stop("PAID_PLAN_PREFIX_EXPECTED_SHA_MISMATCH", "指定的截断原文 SHA-256 与文本失败证据不一致，已停止本地采纳");
  }
  if (!rawText
    || evidence.rawTextTruncated === true
    || Number(evidence.rawTextLength) !== rawText.length
    || !expectedSha256
    || expectedSha256 !== actualSha256) {
    return stop("PAID_PLAN_PREFIX_INTEGRITY_MISMATCH", "截断规划原文存储不完整或 SHA-256 校验不一致，已停止本地采纳和再次付费提交", {
      expectedRawTextLength: Number(evidence.rawTextLength) || 0,
      actualRawTextLength: rawText.length,
      expectedRawTextSha256: expectedSha256,
      actualRawTextSha256: actualSha256
    });
  }

  const configuredSourceExpectedCount = range ? range.endNumber - range.startNumber + 1 : 0;
  const extracted = extractCompleteShotPlanPrefix(rawText, {
    startNumber,
    sourceExpectedCount: configuredSourceExpectedCount,
    maxAcceptedCount: currentExpectedCount
  });
  if (extracted.status !== "recovered") {
    return stop(extracted.code || "PAID_PLAN_PREFIX_NOT_RECOVERABLE", "截断规划中没有可安全采纳的完整连续单元前缀；原始证据已保留，未再次提交上游", { extraction: extracted });
  }
  const sourceExpectedCount = configuredSourceExpectedCount || extracted.inferredSourceExpectedCount;
  range = range || { startNumber, endNumber: startNumber + sourceExpectedCount - 1 };

  let plannedBatch;
  try {
    plannedBatch = validateShotPlanBatch(
      { shotPlan: extracted.items },
      startNumber,
      extracted.items.length,
      options.validationOptions || {}
    );
  } catch (cause) {
    return stop("PAID_PLAN_PREFIX_CONTRACT_INVALID", `截断规划的完整前缀未通过生产硬合同：${cause?.message || cause}；原始证据已保留，未再次提交上游`, {
      causeCode: String(cause?.code || "SCRIPT_PLAN_BATCH_CONTRACT_FAILED"),
      failures: Array.isArray(cause?.failures) ? cause.failures : []
    });
  }

  const savedIds = plannedBatch.map(item => String(item.id || ""));
  const sourceIds = Array.from({ length: sourceExpectedCount }, (_item, index) => `S${String(startNumber + index).padStart(2, "0")}`);
  return {
    status: "recovered",
    plannedBatch,
    evidence,
    recovery: {
      kind: "paid_plan_json_prefix",
      evidenceId: String(evidence.id || ""),
      evidenceSource: isDedicatedCheckpointEvidence
        ? "planContractFailure"
        : (isSignedFailureEvidence ? "live_paid_response" : "textProviderDiagnostics"),
      rawTextSha256: actualSha256,
      ideaSignature: expectedIdeaSignature,
      sourceStartNumber: range.startNumber,
      sourceEndNumber: range.endNumber,
      savedIds,
      savedCount: savedIds.length,
      missingIds: sourceIds.slice(savedIds.length),
      receipt,
      recoveredAt: new Date().toISOString()
    }
  };
}

function recoverPaidPlanJsonPrefix(checkpoint, textProviderDiagnostics, options = {}) {
  const dedicated = checkpoint?.planContractFailure;
  if (String(dedicated?.code || "") === "MODEL_JSON_INVALID") {
    return recoverPaidPlanJsonPrefixEvidence(dedicated, { ...options, checkpoint });
  }
  const failures = Array.isArray(textProviderDiagnostics?.failures) ? textProviderDiagnostics.failures : [];
  const currentStartNumber = Math.max(1, Math.round(Number(options.startNumber) || 1));
  // Every successful paid-plan recovery consumes the exact upstream response,
  // regardless of whether it was recovered as a complete raw batch or as a
  // JSON prefix. Restricting this filter to paid_plan_json_prefix re-selected
  // an already recovered paid_plan_raw diagnostic on the next batch and made
  // S13+ fail forever against the old S09-S12 response.
  const consumedRecovery = checkpoint?.planContractRecovery
    && typeof checkpoint.planContractRecovery === "object"
    ? checkpoint.planContractRecovery
    : null;
  const matching = failures.find(item => {
    if (String(item?.code || "") !== "MODEL_JSON_INVALID" || String(item?.operation || "") !== "script_plan") return false;
    const consumedEvidenceId = String(consumedRecovery?.evidenceId || consumedRecovery?.failureId || "");
    if ((consumedEvidenceId && String(item?.id || "") === consumedEvidenceId)
      || (consumedRecovery?.rawTextSha256 && String(item?.rawTextSha256 || "").toLowerCase() === String(consumedRecovery.rawTextSha256).toLowerCase())) {
      return false;
    }
    const explicitRange = paidPlanEvidenceRange(item);
    if (explicitRange) return explicitRange.startNumber === currentStartNumber;
    const firstNumbers = shotPlanArrayCandidates(item?.rawText).map(candidate => {
      const match = String(candidate?.items?.[0]?.id || "").toUpperCase().match(/^S(\d+)$/);
      return match ? Number(match[1]) : null;
    }).filter(Number.isFinite);
    // Malformed paid responses often cannot be parsed as JSON even though the
    // persisted raw text still exposes exact shot IDs. Use those IDs only to
    // classify the evidence as current/stale; actual recovery still goes
    // through SHA, receipt and full contract validation below.
    const rawNumbers = Array.from(String(item?.rawText || "").matchAll(/"id"\s*:\s*"S(\d+)"/gi))
      .map(match => Number(match[1]))
      .filter(Number.isFinite);
    const readableNumbers = Array.from(new Set([...firstNumbers, ...rawNumbers]));
    if (readableNumbers.includes(currentStartNumber)) return true;
    // Evidence that only names shots already present in the continuous
    // checkpoint is stale. Keep it in diagnostics, but never let it block the
    // next paid batch. Unknown/zero-item and forward IDs remain selected so a
    // genuinely current corrupted response still takes the local stop-loss
    // path instead of being bought again.
    return !readableNumbers.length || readableNumbers.some(number => number > currentStartNumber);
  });
  if (!matching) return { status: "none" };
  return recoverPaidPlanJsonPrefixEvidence(matching, { ...options, checkpoint });
}

/**
 * Re-uses the exact response that was already completed and billed upstream.
 * This function is deliberately pure: it never writes a checkpoint and never
 * calls a provider. The caller commits the recovered batch atomically with the
 * updated shot-plan checkpoint only after validation succeeds.
 */
function recoverPaidPlanContractFailure(checkpoint, options = {}) {
  const failure = checkpoint?.planContractFailure;
  if (!failure) return { status: "none" };

  const expectedIdeaSignature = String(options.ideaSignature || "");
  const checkpointIdeaSignature = String(checkpoint?.ideaSignature || "");
  const failureIdeaSignature = String(failure.ideaSignature || checkpointIdeaSignature);
  const startNumber = Math.max(1, Math.round(Number(options.startNumber) || 1));
  const expectedCount = Math.max(1, Math.round(Number(options.expectedCount) || SCRIPT_PLAN_BATCH_SIZE));
  const endNumber = startNumber + expectedCount - 1;
  const mismatch = (recoveryCode, message, details = {}) => ({
    status: "blocked",
    failure,
    error: paidPlanRecoveryStop(failure, recoveryCode, message, details)
  });

  if (!SCRIPT_PLAN_PAID_STOP_CODES.has(String(failure.code || ""))
    || failure.noAutomaticRetry !== true
    || failure.retryRequiresExplicitResume !== true
    || !isCompletedUpstreamTextReceipt(failure.receipt)) {
    return mismatch(
      "PAID_PLAN_RAW_NOT_TRUSTED",
      "已保存的规划失败证据不是可确认的上游已完成回执，已停止本地复用和再次付费提交"
    );
  }
  if (!expectedIdeaSignature
    || checkpointIdeaSignature !== expectedIdeaSignature
    || failureIdeaSignature !== expectedIdeaSignature) {
    return mismatch(
      "PAID_PLAN_RAW_IDEA_SIGNATURE_MISMATCH",
      "已付费规划原文与当前题材或商品签名不一致，已停止本地复用和再次付费提交",
      { expectedIdeaSignature, checkpointIdeaSignature, failureIdeaSignature }
    );
  }
  if (Number(failure.startNumber) !== startNumber || Number(failure.endNumber) !== endNumber) {
    return mismatch(
      "PAID_PLAN_RAW_BATCH_MISMATCH",
      `已付费规划原文批次与当前待续批次不一致（保存 S${String(failure.startNumber || 0).padStart(2, "0")}–S${String(failure.endNumber || 0).padStart(2, "0")}，当前 S${String(startNumber).padStart(2, "0")}–S${String(endNumber).padStart(2, "0")}），已停止再次付费提交`,
      { expectedStartNumber: startNumber, expectedEndNumber: endNumber }
    );
  }

  const rawText = String(failure.rawText || "");
  const rawTextSha256 = crypto.createHash("sha256").update(rawText, "utf8").digest("hex");
  if (!rawText
    || failure.rawTextTruncated === true
    || Number(failure.rawTextLength) !== rawText.length
    || String(failure.rawTextSha256 || "").toLowerCase() !== rawTextSha256) {
    return mismatch(
      "PAID_PLAN_RAW_INTEGRITY_MISMATCH",
      "已付费规划原文不完整或 SHA-256 校验不一致，已停止本地复用和再次付费提交",
      {
        expectedRawTextLength: Number(failure.rawTextLength) || 0,
        actualRawTextLength: rawText.length,
        expectedRawTextSha256: String(failure.rawTextSha256 || ""),
        actualRawTextSha256: rawTextSha256
      }
    );
  }

  let parsedData;
  try {
    parsedData = parseStructuredJson(rawText, {
      requiredKeys: ["shotPlan"],
      unwrapKeys: ["data", "result", "payload", "content"]
    });
  } catch (cause) {
    return {
      status: "invalid",
      failure,
      error: paidPlanRecoveryStop(
        failure,
        "PAID_PLAN_RAW_JSON_STILL_INVALID",
        `已付费规划原文仍无法在本地解析：${cause?.message || cause}；证据已保留，未再次提交上游`,
        { causeCode: String(cause?.code || "MODEL_JSON_INVALID") }
      )
    };
  }

  try {
    const plannedBatch = validateShotPlanBatch(parsedData, startNumber, expectedCount, options.validationOptions || {});
    return {
      status: "recovered",
      plannedBatch,
      parsedData,
      recovery: {
        kind: "paid_plan_raw",
        failureId: String(failure.id || ""),
        rawTextSha256,
        ideaSignature: expectedIdeaSignature,
        startNumber,
        endNumber,
        recoveredAt: new Date().toISOString()
      }
    };
  } catch (cause) {
    return {
      status: "invalid",
      failure,
      error: paidPlanRecoveryStop(
        failure,
        "PAID_PLAN_RAW_CONTRACT_STILL_INVALID",
        `已付费规划原文在当前版本本地复审后仍未通过生产硬合同：${cause?.message || cause}；证据已保留，未再次提交上游`,
        {
          causeCode: String(cause?.code || "SCRIPT_PLAN_BATCH_CONTRACT_FAILED"),
          failures: Array.isArray(cause?.failures) ? cause.failures : []
        }
      )
    };
  }
}

/**
 * Revalidates one already-completed script_units response without network I/O.
 * A malformed root may be recovered only when the complete expected shots array
 * is present, or when the final shot contains all required production fields and
 * only an unfinished trailing top-level field can be discarded. Every recovered
 * object still passes validateShotBatch before the caller commits it.
 */
function recoverPaidUnitContractFailure(checkpoint, options = {}) {
  const failure = checkpoint?.unitContractFailure;
  if (!failure) return { status: "none" };

  const plannedShots = Array.isArray(options.plannedShots) ? options.plannedShots : [];
  const plannedShotIds = plannedShots.map(item => String(item?.id || "").toUpperCase());
  const expectedIdeaSignature = String(options.ideaSignature || "");
  const checkpointIdeaSignature = String(checkpoint?.ideaSignature || "");
  const failureIdeaSignature = String(failure.ideaSignature || checkpointIdeaSignature);
  const expectedStartNumber = Math.max(1, Math.round(Number(options.startNumber) || 1));
  const expectedEndNumber = expectedStartNumber + plannedShots.length - 1;
  const expectedDraftAttempt = Math.max(1, Math.round(Number(options.draftAttempt) || 1));
  const expectedGenerationMode = String(options.generationMode || "");
  const mismatch = (recoveryCode, message, details = {}) => ({
    status: "blocked",
    failure,
    error: paidUnitRecoveryStop(failure, recoveryCode, message, details)
  });

  if (!SCRIPT_UNIT_PAID_STOP_CODES.has(String(failure.code || ""))
    || failure.noAutomaticRetry !== true
    || failure.retryRequiresExplicitResume !== true
    || !isCompletedUpstreamTextReceipt(failure.receipt)) {
    return mismatch(
      "PAID_UNIT_RAW_NOT_TRUSTED",
      "已保存的生成单元失败证据不是可确认的上游已完成回执，已停止本地复用和再次付费提交"
    );
  }
  if (!expectedIdeaSignature
    || checkpointIdeaSignature !== expectedIdeaSignature
    || failureIdeaSignature !== expectedIdeaSignature) {
    return mismatch(
      "PAID_UNIT_RAW_IDEA_SIGNATURE_MISMATCH",
      "已付费生成单元原文与当前题材或商品签名不一致，已停止本地复用和再次付费提交",
      { expectedIdeaSignature, checkpointIdeaSignature, failureIdeaSignature }
    );
  }
  if (!plannedShots.length
    || Number(failure.startNumber) !== expectedStartNumber
    || Number(failure.endNumber) !== expectedEndNumber
    || JSON.stringify(failure.plannedShotIds || []) !== JSON.stringify(plannedShotIds)
    || String(failure.plannedShotsSha256 || "").toLowerCase() !== plannedShotBatchSha256(plannedShots)) {
    return mismatch(
      "PAID_UNIT_RAW_BATCH_MISMATCH",
      `已付费生成单元原文批次与当前待续批次不一致（保存 S${String(failure.startNumber || 0).padStart(2, "0")}–S${String(failure.endNumber || 0).padStart(2, "0")}，当前 S${String(expectedStartNumber).padStart(2, "0")}–S${String(expectedEndNumber).padStart(2, "0")}），已停止再次付费提交`,
      { expectedStartNumber, expectedEndNumber, expectedIds: plannedShotIds }
    );
  }
  if (Number(failure.draftAttempt) !== expectedDraftAttempt
    || (String(failure.generationMode || "") && String(failure.generationMode || "") !== expectedGenerationMode)) {
    return mismatch(
      "PAID_UNIT_RAW_CONTEXT_MISMATCH",
      "已付费生成单元原文的写作轮次或图像策略与当前续写上下文不一致，已停止再次付费提交",
      { expectedDraftAttempt, expectedGenerationMode }
    );
  }

  const rawText = String(failure.rawText || "");
  const rawTextSha256 = crypto.createHash("sha256").update(rawText, "utf8").digest("hex");
  if (!rawText
    || failure.rawTextTruncated === true
    || Number(failure.rawTextLength) !== rawText.length
    || String(failure.rawTextSha256 || "").toLowerCase() !== rawTextSha256) {
    return mismatch(
      "PAID_UNIT_RAW_INTEGRITY_MISMATCH",
      "已付费生成单元原文不完整或 SHA-256 校验不一致，已停止本地复用和再次付费提交",
      {
        expectedRawTextLength: Number(failure.rawTextLength) || 0,
        actualRawTextLength: rawText.length,
        expectedRawTextSha256: String(failure.rawTextSha256 || ""),
        actualRawTextSha256: rawTextSha256
      }
    );
  }

  let parsedData;
  let extraction = null;
  try {
    parsedData = parseStructuredJson(rawText, {
      requiredKeys: ["shots"],
      unwrapKeys: ["data", "result", "payload", "content"]
    });
  } catch (parseCause) {
    const extracted = extractCompleteShotUnitBatch(rawText, plannedShots);
    if (extracted.status !== "recovered") {
      return {
        status: "invalid",
        failure,
        error: paidUnitRecoveryStop(
          failure,
          extracted.code || "PAID_UNIT_RAW_JSON_STILL_INVALID",
          `已付费生成单元原文没有完整、连续且可安全恢复的当前批次：${parseCause?.message || parseCause}；证据已保留，未再次提交上游`,
          { causeCode: String(parseCause?.code || "MODEL_JSON_INVALID"), extraction: extracted }
        )
      };
    }
    parsedData = extracted.parsedData;
    extraction = extracted.extraction;
  }

  try {
    const batch = validateShotBatch(
      parsedData,
      plannedShots,
      options.productName || "",
      options.videoEngine || "hailuo-h3",
      options.validationOptions || {}
    );
    return {
      status: "recovered",
      batch,
      parsedData,
      recovery: {
        kind: "paid_unit_raw",
        failureId: String(failure.id || ""),
        rawTextSha256,
        ideaSignature: expectedIdeaSignature,
        startNumber: expectedStartNumber,
        endNumber: expectedEndNumber,
        savedIds: batch.map(item => String(item?.id || "")),
        extraction,
        receipt: planReceiptEvidence(failure.receipt),
        recoveredAt: new Date().toISOString()
      }
    };
  } catch (cause) {
    return {
      status: "invalid",
      failure,
      error: paidUnitRecoveryStop(
        failure,
        "PAID_UNIT_RAW_CONTRACT_STILL_INVALID",
        `已付费生成单元原文在当前版本本地复审后仍未通过生产硬合同：${cause?.message || cause}；证据已保留，未再次提交上游`,
        {
          causeCode: String(cause?.code || "SCRIPT_UNIT_CONTRACT_FAILED"),
          failures: Array.isArray(cause?.failures) ? cause.failures : []
        }
      )
    };
  }
}

function slug(value) {
  const raw = String(value || "asset").trim();
  const ascii = raw.replace(/[^a-zA-Z0-9_-]+/g, "-").replace(/^-+|-+$/g, "").slice(0, 42);
  if (ascii) return ascii;
  // Chinese / non-ascii names must stay unique (else all collapse to "asset").
  return crypto.createHash("sha1").update(raw, "utf8").digest("hex").slice(0, 12);
}

function inferVoiceProfile(character = {}) {
  return {
    gender: explicitCharacterGender(character),
    ageBand: characterAgeBand(character)
  };
}

function voiceDescriptionTokens(value = "") {
  return String(value || "")
    .toLowerCase()
    .replace(/[^\u4e00-\u9fffA-Za-z0-9]+/g, " ")
    .split(/\s+/)
    .map(item => item.trim())
    .filter(item => item.length >= 2);
}

function scoreVoiceLibraryMatch(entry, character = {}) {
  if (!entry?.filePath) return 0;
  const profile = inferVoiceProfile(character);
  const entryProfile = {
    gender: entry.gender || inferVoiceProfile(entry).gender,
    ageBand: entry.ageBand || inferVoiceProfile(entry).ageBand
  };
  let score = 0;
  if (entry.id && character.voiceLibraryId && entry.id === character.voiceLibraryId) score += 100;
  if (profile.gender && entryProfile.gender && profile.gender === entryProfile.gender) score += 30;
  if (profile.ageBand && entryProfile.ageBand && profile.ageBand === entryProfile.ageBand) score += 25;
  const charName = String(character.name || "").trim();
  const entryName = String(entry.characterName || entry.label || "").trim();
  if (charName && entryName && (charName === entryName || charName.includes(entryName) || entryName.includes(charName))) score += 40;
  const left = new Set(voiceDescriptionTokens(character.voiceDescription || character.appearanceDescription || character.description || ""));
  const right = voiceDescriptionTokens(entry.voiceDescription || entry.label || "");
  if (left.size && right.length) {
    const overlap = right.filter(token => left.has(token)).length;
    score += Math.min(30, overlap * 8);
  }
  return score;
}

function voiceProfileCompatible(entry = {}, character = {}, options = {}) {
  if (options.manualBinding === true) return true;
  const expected = inferVoiceProfile(character);
  const actual = {
    gender: String(entry.gender || entry.voiceGender || inferVoiceProfile(entry).gender || "").trim(),
    ageBand: String(entry.ageBand || entry.voiceAgeBand || inferVoiceProfile(entry).ageBand || "").trim()
  };
  if (!expected.gender || !expected.ageBand) return false;
  if (entry.profileVerified !== true) return false;
  if (!actual.gender || expected.gender !== actual.gender) return false;
  if (!actual.ageBand || expected.ageBand !== actual.ageBand) return false;
  return true;
}

function voiceLibraryFingerprint(character = {}, profile = null) {
  const resolved = profile || inferVoiceProfile(character);
  return [
    resolved.gender || "unknown",
    resolved.ageBand || "unknown",
    String(character.voiceDescription || "").trim().slice(0, 80),
    String(character.name || "").trim()
  ].join("|");
}

const LOCAL_MEDIA_PROCESS_TIMEOUT_MS = 20 * 60_000;

function spawnCapture(executable, args, timeoutMs = LOCAL_MEDIA_PROCESS_TIMEOUT_MS, signal = null) {
  signal ||= currentLocalMediaSignal();
  return new Promise((resolve, reject) => {
    if (signal?.aborted) return reject(Object.assign(new Error("本地媒体处理已取消，原始文件保留"), { code: "LOCAL_MEDIA_CANCELLED" }));
    const child = spawn(executable, args, { windowsHide: true, stdio: ["ignore", "pipe", "pipe"] });
    let stdout = "";
    let stderr = "";
    let settled = false;
    const finish = (error, value) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      signal?.removeEventListener("abort", abort);
      if (error) reject(error); else resolve(value);
    };
    const abort = () => { child.kill(); finish(Object.assign(new Error("本地媒体处理已取消，原始文件保留"), { code: "LOCAL_MEDIA_CANCELLED" })); };
    const timer = setTimeout(() => {
      child.kill();
      finish(Object.assign(new Error("本地媒体处理超时，原始文件保留；可重试或直接导出剪映草稿"), { code: "LOCAL_MEDIA_TIMEOUT" }));
    }, Math.max(1, Number(timeoutMs) || LOCAL_MEDIA_PROCESS_TIMEOUT_MS));
    signal?.addEventListener("abort", abort, { once: true });
    child.stdout.on("data", chunk => { if (stdout.length < 500_000) stdout += chunk.toString("utf8"); });
    child.stderr.on("data", chunk => { if (stderr.length < 500_000) stderr += chunk.toString("utf8"); });
    child.on("error", error => finish(error));
    child.on("close", code => {
      if (code === 0) finish(null, { stdout, stderr });
      else finish(Object.assign(new Error(stderr.slice(-1200) || `媒体处理失败：退出码 ${code}`), { code: "FFMPEG_FAILED" }));
    });
  });
}

function parseFfmpegProgressSeconds(output = "") {
  let seconds = 0;
  for (const line of String(output || "").split(/\r?\n/)) {
    const [rawKey, ...parts] = line.trim().split("=");
    const value = parts.join("=").trim();
    if (!value) continue;
    if (rawKey === "out_time_us" || rawKey === "out_time_ms") {
      const micros = Number(value);
      if (Number.isFinite(micros)) seconds = Math.max(seconds, micros / 1_000_000);
      continue;
    }
    if (rawKey === "out_time") {
      const match = value.match(/^(\d+):(\d+):(\d+(?:\.\d+)?)$/);
      if (match) seconds = Math.max(seconds, (Number(match[1]) * 3600) + (Number(match[2]) * 60) + Number(match[3]));
    }
  }
  return seconds;
}

async function probeMediaStreamDuration(ffmpeg, filePath, streamSpecifier = "0:v:0", signal = null) {
  const sink = process.platform === "win32" ? "NUL" : "/dev/null";
  const result = await spawnCapture(ffmpeg, [
    "-hide_banner", "-loglevel", "error", "-nostats", "-progress", "pipe:1",
    // Decode into the null muxer so progress reports the end of the final
    // frame/sample, not merely the timestamp of the last compressed packet.
    "-i", filePath, "-map", streamSpecifier, "-f", "null", sink
  ], 300_000, signal);
  const seconds = parseFfmpegProgressSeconds(result.stdout);
  if (!(seconds > 0)) {
    throw Object.assign(new Error(`无法读取成片 ${streamSpecifier} 的真实时长`), {
      code: "FINAL_DURATION_PROBE_FAILED",
      filePath,
      streamSpecifier
    });
  }
  return seconds;
}

function ffmpegDrawTextValue(value = "") {
  return String(value || "")
    .replace(/[\r\n]+/g, " ")
    .replace(/\\/g, "\\\\")
    .replace(/'/g, "\\'")
    .replace(/:/g, "\\:")
    .replace(/%/g, "\\%");
}

function criticalTextOverlayFilters(shot = {}, offsetSeconds = 0) {
  // Product contract: final videos never contain subtitles, captions, titles,
  // name straps, prices or any other readable overlay. Older scripts may still
  // carry criticalOnScreenText metadata; it is descriptive evidence only and
  // must never become an FFmpeg drawtext instruction.
  void shot;
  void offsetSeconds;
  return [];
}

function finalCriticalTextOverlayFilter(shots = []) {
  let offset = 0;
  const filters = [];
  for (const shot of Array.isArray(shots) ? shots : []) {
    filters.push(...criticalTextOverlayFilters(shot, offset));
    offset += Math.max(0, Number(shot?.duration) || 0);
  }
  return filters.join(",");
}

function h3ExactStitchFilter(shots = [], targetSeconds = 0, fps = 24, aspectRatio = "9:16") {
  const filters = [];
  const concatInputs = [];
  const [width, height] = ({ "16:9": [1024, 576], "1:1": [720, 720], "4:3": [960, 720], "3:4": [720, 960], "21:9": [1344, 576] })[aspectRatio] || [576, 1024];
  shots.forEach((shot, index) => {
    const duration = Math.max(0.001, Number(shot?.duration) || 0);
    const trimStart = Math.max(0, Number(shot?.trimStartSeconds) || 0);
    const value = duration.toFixed(3).replace(/\.0+$/, "").replace(/(\.\d*?)0+$/, "$1");
    const startValue = trimStart.toFixed(3).replace(/\.0+$/, "").replace(/(\.\d*?)0+$/, "$1");
    const textOverlays = criticalTextOverlayFilters(shot);
    filters.push(`[${index}:v:0]settb=AVTB,trim=start=${startValue},setpts=PTS-STARTPTS,fps=${fps},setsar=1,scale=${width}:${height}:force_original_aspect_ratio=increase,crop=${width}:${height}:(iw-${width})/2:(ih-${height})/2,setsar=1,tpad=stop_mode=clone:stop_duration=${value},trim=duration=${value},setpts=PTS-STARTPTS,format=yuv420p${textOverlays.length ? `,${textOverlays.join(",")}` : ""}[v${index}]`);
    filters.push(shot?.hasAudio === false
      ? `anullsrc=r=48000:cl=stereo,atrim=duration=${value},asetpts=PTS-STARTPTS[a${index}]`
      : `[${index}:a:0]aresample=48000,aformat=sample_rates=48000:channel_layouts=stereo,atrim=start=${startValue},asetpts=PTS-STARTPTS,apad=pad_dur=${value},atrim=duration=${value},asetpts=PTS-STARTPTS[a${index}]`);
    concatInputs.push(`[v${index}][a${index}]`);
  });
  const target = Math.max(0.001, Number(targetSeconds) || 0).toFixed(3).replace(/\.0+$/, "").replace(/(\.\d*?)0+$/, "$1");
  filters.push(`${concatInputs.join("")}concat=n=${shots.length}:v=1:a=1[vcat][acat]`);
  filters.push(`[vcat]tpad=stop_mode=clone:stop_duration=${target},trim=duration=${target},setpts=PTS-STARTPTS[outv]`);
  // Clean the concatenated programme once (not once per shot) so seam clicks,
  // mouth pops and the persistent high-frequency/bubbling floor are reduced
  // without resetting the denoiser at every cut.  Keep the reduction moderate
  // to preserve breath, sobs and angry consonants.
  filters.push(`[acat]apad=pad_dur=${target},atrim=duration=${target},asetpts=PTS-STARTPTS,highpass=f=70,lowpass=f=14000,adeclick,afftdn=nr=8:nf=-35:tn=1,loudnorm=I=-16:LRA=9:TP=-1.5[outa]`);
  return filters.join(";");
}

async function probeLocalVideoInfo(ffmpeg, filePath, signal = null) {
  const sink = process.platform === "win32" ? "NUL" : "/dev/null";
  const result = await spawnCapture(ffmpeg, ["-hide_banner", "-loglevel", "info", "-nostats", "-progress", "pipe:1", "-i", filePath, "-map", "0:v:0", "-f", "null", sink], 300_000, signal);
  const dimensions = result.stderr.match(/Video:[^\r\n]*?\b(\d{2,5})x(\d{2,5})\b/);
  const duration = parseFfmpegProgressSeconds(result.stdout);
  if (!dimensions || !(duration > 0)) throw Object.assign(new Error(`无法读取分镜视频的真实尺寸或时长：${path.basename(filePath)}`), { code: "LOCAL_VIDEO_PROBE_FAILED" });
  return { duration, width: Number(dimensions[1]), height: Number(dimensions[2]) };
}

async function detectHeadArtifactTrimSeconds(ffmpeg, filePath, durationSeconds = 0, signal = null) {
  const duration = Math.max(0, Number(durationSeconds) || 0);
  if (duration > 0 && duration < 1.2) return 0;
  const sink = process.platform === "win32" ? "NUL" : "/dev/null";
  try {
    const result = await spawnCapture(ffmpeg, [
      "-hide_banner", "-loglevel", "info", "-t", "1.2", "-i", filePath,
      "-vn", "-af", "silencedetect=noise=-38dB:d=0.06", "-f", "null", sink
    ], 60_000, signal);
    const events = [];
    for (const match of String(result.stderr || "").matchAll(/silence_(start|end):\s*(-?\d+(?:\.\d+)?)/g)) {
      events.push({ type: match[1], time: Math.max(0, Number(match[2]) || 0) });
    }
    for (let index = 0; index < events.length; index += 1) {
      const start = events[index];
      // Silence from the first sample is not an artifact and may accompany an
      // intentional silent entrance. Only trim when a short audible onset
      // (click/pop/lip-smack) is followed by a brief silent gap.
      if (start.type !== "start" || start.time < 0.008 || start.time > 0.18) continue;
      const end = events.slice(index + 1).find(item => item.type === "end" && item.time >= start.time);
      if (!end) continue;
      const silenceSeconds = end.time - start.time;
      if (silenceSeconds < 0.06 || end.time > 0.65) continue;
      // Cut both picture and sound to the first clean post-silence frame. Pure
      // silent acting at the head is deliberately preserved.
      const trim = Math.min(0.65, end.time + 0.012);
      if (duration > 0 && duration - trim < 0.8) return 0;
      return Number(trim.toFixed(3));
    }
  } catch (error) { if (signal?.aborted) throw error; }
  return 0;
}

async function mixFixedSfxIntoVideo(ffmpeg, baseVideoPath, outputPath, plan, catalog, finalDir) {
  const allCues = (Array.isArray(plan?.shots) ? plan.shots : []).flatMap(shot => Array.isArray(shot?.cues) ? shot.cues : []);
  if (!allCues.length) {
    fs.renameSync(baseVideoPath, outputPath);
    return { applied: false, cueCount: 0, warning: "" };
  }
  const catalogById = new Map(catalog.map(item => [item.id, item]));
  const cues = allCues.map(cue => ({ ...cue, asset: catalogById.get(cue.effectId) })).filter(cue => cue.asset?.filePath && fs.existsSync(cue.asset.filePath));
  if (!cues.length) {
    fs.renameSync(baseVideoPath, outputPath);
    return { applied: false, cueCount: 0, warning: "固定音效计划没有可读取的素材，已保留无音效粗剪版" };
  }
  const uniqueAssets = [];
  const assetIndex = new Map();
  for (const cue of cues) {
    if (assetIndex.has(cue.effectId)) continue;
    assetIndex.set(cue.effectId, uniqueAssets.length + 1);
    uniqueAssets.push(cue.asset);
  }
  const inputArgs = uniqueAssets.flatMap(item => ["-i", item.filePath]);
  const filters = ["[0:a:0]aresample=48000,aformat=sample_rates=48000:channel_layouts=stereo[baseaudio]"];
  const cueLabels = [];
  const cuesByEffect = new Map();
  for (const cue of cues) {
    if (!cuesByEffect.has(cue.effectId)) cuesByEffect.set(cue.effectId, []);
    cuesByEffect.get(cue.effectId).push(cue);
  }
  let cueNumber = 0;
  for (const [effectId, effectCues] of cuesByEffect.entries()) {
    const inputIndex = assetIndex.get(effectId);
    const sourceLabels = effectCues.map((_cue, index) => `fxsrc${inputIndex}_${index}`);
    if (sourceLabels.length > 1) filters.push(`[${inputIndex}:a:0]asplit=${sourceLabels.length}${sourceLabels.map(label => `[${label}]`).join("")}`);
    effectCues.forEach((cue, index) => {
      cueNumber += 1;
      const source = sourceLabels.length > 1 ? `[${sourceLabels[index]}]` : `[${inputIndex}:a:0]`;
      const label = `fx${cueNumber}`;
      const delayMs = Math.max(250, Math.round(Number(cue.programmeTimeSeconds || 0) * 1000));
      const gain = Math.max(-40, Math.min(-4, Number(cue.gainDb) || -18));
      const duration = Math.max(0.1, Number(cue.durationSeconds) || 6);
      const fadeIn = Math.max(0, Math.min(0.5, Number(cue.fadeInSeconds) || 0.01));
      const fadeOut = Math.max(0, Math.min(0.8, Number(cue.fadeOutSeconds) || 0.06));
      const loop = cue.loop === true ? "aloop=loop=-1:size=2147483647," : "";
      const fadeOutStart = Math.max(0, duration - fadeOut);
      filters.push(`${source}aresample=48000,aformat=sample_rates=48000:channel_layouts=stereo,${loop}atrim=duration=${duration.toFixed(3)},asetpts=PTS-STARTPTS,afade=t=in:st=0:d=${fadeIn.toFixed(3)},afade=t=out:st=${fadeOutStart.toFixed(3)}:d=${fadeOut.toFixed(3)},volume=${gain}dB,adelay=${delayMs}|${delayMs}[${label}]`);
      cueLabels.push(`[${label}]`);
    });
  }
  filters.push(`[baseaudio]${cueLabels.join("")}amix=inputs=${cueLabels.length + 1}:duration=first:dropout_transition=0:normalize=0,alimiter=limit=0.95,loudnorm=I=-16:LRA=9:TP=-1.5[mixaudio]`);
  const filterScriptPath = path.join(finalDir, `.roughcut-sfx-${crypto.randomUUID().slice(0, 8)}.txt`);
  fs.writeFileSync(filterScriptPath, filters.join(";"), "utf8");
  try {
    await spawnCapture(ffmpeg, [
      "-hide_banner", "-loglevel", "error", "-y", "-i", baseVideoPath, ...inputArgs,
      "-filter_complex_script", filterScriptPath,
      "-map", "0:v:0", "-map", "[mixaudio]", "-c:v", "copy", "-c:a", "aac", "-b:a", "192k",
      "-movflags", "+faststart", outputPath
    ], 1_800_000);
    return { applied: true, cueCount: cues.length, uniqueAssetCount: uniqueAssets.length, warning: "" };
  } finally {
    try { fs.rmSync(filterScriptPath, { force: true }); } catch {}
  }
}

function splitForAnalysis(text, maxChars = 2400) {
  const normalized = String(text || "").replace(/\r\n/g, "\n").trim();
  if (!normalized) return [];
  const logicalUnits = [];
  for (const rawLine of normalized.split("\n")) {
    const line = rawLine.trim();
    if (!line) continue;
    if (line.length <= maxChars || parseSourceDialogueLedger(line).length) {
      logicalUnits.push(line);
      continue;
    }
    let remaining = line;
    while (remaining.length > maxChars) {
      const floor = Math.max(1, Math.floor(maxChars * 0.6));
      const candidate = remaining.slice(0, maxChars + 1);
      let cut = Math.max(candidate.lastIndexOf("。"), candidate.lastIndexOf("！"), candidate.lastIndexOf("？"), candidate.lastIndexOf("；"));
      if (cut < floor) cut = maxChars;
      else cut += 1;
      logicalUnits.push(remaining.slice(0, cut).trim());
      remaining = remaining.slice(cut).trim();
    }
    if (remaining) logicalUnits.push(remaining);
  }
  const chunks = [];
  let current = "";
  const push = value => { if (value.trim()) chunks.push(value.trim()); };
  for (const unit of logicalUnits.length ? logicalUnits : [normalized]) {
    if (current && current.length + unit.length + 1 > maxChars) {
      push(current);
      current = unit;
    } else {
      current = current ? `${current}\n${unit}` : unit;
    }
  }
  push(current);
  return chunks;
}

function generatedScenePlaceholderName(value = "") {
  const name = String(value || "").trim();
  return /^(?:用户原稿场景|原稿场景|剧情现场|场景)\s*\d+$/i.test(name);
}

function mergeAnalysisChunks(chunks) {
  const characters = new Map();
  const scenes = new Map();
  const props = new Map();
  const shots = [];
  const story = [];
  const sourceDialogueLedger = [];
  for (const chunk of chunks) {
    if (chunk?.story) story.push(chunk.story);
    for (const item of Array.isArray(chunk?.characters) ? chunk.characters : []) {
      const key = String(item.name || "").trim();
      if (!key) continue;
      characters.set(key, { ...(characters.get(key) || {}), ...item, name: key });
    }
    for (const item of Array.isArray(chunk?.scenes) ? chunk.scenes : []) {
      const rawKey = String(item.name || "").trim();
      const key = generatedScenePlaceholderName(rawKey) ? "剧情主要空间" : rawKey;
      if (!key) continue;
      scenes.set(key, { ...(scenes.get(key) || {}), ...item, name: key });
    }
    for (const item of Array.isArray(chunk?.props) ? chunk.props : []) {
      const key = String(item.name || "").trim();
      if (!key) continue;
      props.set(key, { ...(props.get(key) || {}), ...item, name: key });
    }
    for (const item of Array.isArray(chunk?.sourceDialogueLedger) ? chunk.sourceDialogueLedger : []) sourceDialogueLedger.push({ ...item });
  }
  const characterWidth = Math.max(2, String(characters.size).length);
  const sceneWidth = Math.max(2, String(scenes.size).length);
  const propWidth = Math.max(2, String(props.size).length);
  const canonicalCharacters = [...characters.values()].map((item, index) => ({ ...item, id: `C${String(index + 1).padStart(characterWidth, "0")}` }));
  const canonicalScenes = [...scenes.values()].map((item, index) => ({ ...item, id: `SC${String(index + 1).padStart(sceneWidth, "0")}` }));
  const canonicalProps = [...props.values()].map((item, index) => ({ ...item, id: `P${String(index + 1).padStart(propWidth, "0")}` }));
  const characterByName = new Map(canonicalCharacters.map(item => [String(item.name || "").trim(), item]));
  const sceneByName = new Map(canonicalScenes.map(item => [String(item.name || "").trim(), item]));
  const propByName = new Map(canonicalProps.map(item => [String(item.name || "").trim(), item]));
  const remapList = (values, remap) => normalizeStringArray(values).map(remap).filter(Boolean);
  for (const chunk of chunks) {
    const localCharacterMap = new Map();
    for (const item of Array.isArray(chunk?.characters) ? chunk.characters : []) {
      const canonical = characterByName.get(String(item?.name || "").trim());
      if (!canonical) continue;
      localCharacterMap.set(String(item?.name || "").trim(), canonical.id);
      if (item?.id) localCharacterMap.set(String(item.id).trim(), canonical.id);
    }
    const localSceneMap = new Map();
    for (const item of Array.isArray(chunk?.scenes) ? chunk.scenes : []) {
      const rawName = String(item?.name || "").trim();
      const canonical = sceneByName.get(generatedScenePlaceholderName(rawName) ? "剧情主要空间" : rawName);
      if (!canonical) continue;
      localSceneMap.set(String(item?.name || "").trim(), canonical);
      if (item?.id) localSceneMap.set(String(item.id).trim(), canonical);
    }
    const localPropMap = new Map();
    for (const item of Array.isArray(chunk?.props) ? chunk.props : []) {
      const canonical = propByName.get(String(item?.name || "").trim());
      if (!canonical) continue;
      localPropMap.set(String(item?.name || "").trim(), canonical.id);
      if (item?.id) localPropMap.set(String(item.id).trim(), canonical.id);
    }
    const remapCharacter = value => {
      const token = String(value || "").trim();
      return localCharacterMap.get(token) || characterByName.get(token)?.id || token;
    };
    const remapProp = value => {
      const token = String(value || "").trim();
      return localPropMap.get(token) || propByName.get(token)?.id || token;
    };
    const remapTurn = (turn = {}) => ({
      ...turn,
      speakerId: remapCharacter(turn?.speakerId || turn?.speaker),
      listenerIds: remapList(turn?.listenerIds || turn?.listeners, remapCharacter)
    });
    const remapBinding = (binding = {}) => typeof binding === "string" ? binding : ({
      ...binding,
      listenerIds: remapList(binding?.listenerIds || binding?.listeners, remapCharacter)
    });
    for (const sourceShot of Array.isArray(chunk?.shots) ? chunk.shots : []) {
      const dialogueTurns = (Array.isArray(sourceShot?.dialogueTurns) ? sourceShot.dialogueTurns : []).map(remapTurn);
      const sceneToken = String(sourceShot?.scene || sourceShot?.sceneName || sourceShot?.sceneId || "").trim();
      const canonicalScene = localSceneMap.get(sceneToken)
        || sceneByName.get(generatedScenePlaceholderName(sceneToken) ? "剧情主要空间" : sceneToken);
      const subshots = (Array.isArray(sourceShot?.subshots) ? sourceShot.subshots : []).map(subshot => {
        const localTurns = (Array.isArray(subshot?.dialogueTurns) ? subshot.dialogueTurns : []).map(remapTurn);
        return {
          ...subshot,
          visibleCharacterIds: remapList(subshot?.visibleCharacterIds, remapCharacter),
          speakerIds: remapList(subshot?.speakerIds, remapCharacter),
          offscreenSpeakerIds: remapList(subshot?.offscreenSpeakerIds, remapCharacter),
          dialogueTurns: localTurns,
          dialogue: localTurns.length ? formatDialogueTurns(localTurns) : subshot?.dialogue
        };
      });
      shots.push({
        ...sourceShot,
        scene: canonicalScene?.name || sceneToken,
        sceneId: canonicalScene?.id || String(sourceShot?.sceneId || "").trim(),
        characterIds: remapList(sourceShot?.characterIds, remapCharacter),
        scenePresenceCharacterIds: remapList(sourceShot?.scenePresenceCharacterIds, remapCharacter),
        visibleCharacterIds: remapList(sourceShot?.visibleCharacterIds, remapCharacter),
        imageReferenceCharacterIds: remapList(sourceShot?.imageReferenceCharacterIds, remapCharacter),
        videoReferenceCharacterIds: remapList(sourceShot?.videoReferenceCharacterIds, remapCharacter),
        speakerIds: remapList(sourceShot?.speakerIds, remapCharacter),
        offscreenSpeakerIds: remapList(sourceShot?.offscreenSpeakerIds, remapCharacter),
        focusCharacterId: remapCharacter(sourceShot?.focusCharacterId),
        counterpartCharacterId: remapCharacter(sourceShot?.counterpartCharacterId),
        dialogueTurns,
        dialogue: dialogueTurns.length ? formatDialogueTurns(dialogueTurns) : sourceShot?.dialogue,
        sourceDialogueBindings: (Array.isArray(sourceShot?.sourceDialogueBindings) ? sourceShot.sourceDialogueBindings : []).map(remapBinding),
        wardrobeBindings: (Array.isArray(sourceShot?.wardrobeBindings) ? sourceShot.wardrobeBindings : []).map(binding => ({ ...binding, characterId: remapCharacter(binding?.characterId) })),
        propBindings: (Array.isArray(sourceShot?.propBindings) ? sourceShot.propBindings : []).map(binding => ({
          ...binding,
          propId: remapProp(binding?.propId || binding?.id),
          holderCharacterId: remapCharacter(binding?.holderCharacterId || binding?.characterId)
        })),
        subshots
      });
    }
  }
  const dedupedSourceDialogueLedger = [...new Map(sourceDialogueLedger
    .filter(item => item && String(item.id || "").trim())
    .map(item => [String(item.id).trim(), item])).values()];
  const orderedSourceDialogueLedger = sortSourceDialogueLedger(dedupedSourceDialogueLedger).map((item, index) => ({
    ...item,
    order: index + 1,
    sourceOrder: index + 1
  }));
  return { story: story.filter(Boolean), characters: canonicalCharacters, scenes: canonicalScenes, props: canonicalProps, shots, sourceDialogueLedger: orderedSourceDialogueLedger };
}

function analysisChunksForSchedule(text, unitCount, options = {}) {
  const requestedUnitCount = Math.floor(Number(unitCount) || 0);
  // A free-form user upload has no pre-authorised shot count.  In that mode
  // chunks exist solely to keep a request transportable; they must not turn a
  // UI duration preference into a quota of model-authored shots.
  const flexibleUnitCount = requestedUnitCount <= 0;
  const count = flexibleUnitCount ? 0 : Math.max(1, requestedUnitCount);
  const source = String(text || "").trim();
  if (!flexibleUnitCount && source.length > count * STRUCTURED_TEXT_MAX_CHARS) {
    throw Object.assign(new Error(`当前 ${source.length} 字原稿无法在 ${count} 个生成单元内完整保留。请提高目标时长，或先压缩重复内容后再拆镜`), {
      code: "SCRIPT_TARGET_TOO_SHORT_FOR_SOURCE",
      sourceChars: source.length,
      unitCount: count,
      maxCharsPerUnit: STRUCTURED_TEXT_MAX_CHARS
    });
  }
  const maxSourceChars = Math.max(1000, Math.min(
    STRUCTURED_TEXT_MAX_CHARS,
    Math.floor(Number(options.maxSourceChars) || UPLOADED_ANALYSIS_MAX_SOURCE_CHARS)
  ));
  const maxUnitsPerRequest = Math.max(1, Math.min(
    8,
    Math.floor(Number(options.maxUnitsPerRequest) || UPLOADED_ANALYSIS_MAX_UNITS_PER_REQUEST)
  ));
  const desiredParallelChunks = flexibleUnitCount
    ? Math.max(1, Math.ceil(source.length / maxSourceChars))
    : Math.max(1, Math.min(count, Math.max(
      Math.ceil(count / maxUnitsPerRequest),
      Math.ceil(source.length / maxSourceChars)
    )));
  const targetChunkChars = Math.max(240, Math.min(maxSourceChars, Math.ceil(source.length / desiredParallelChunks)));
  let chunks = splitForAnalysis(source, targetChunkChars);
  while (chunks.length > desiredParallelChunks) {
    const candidates = chunks.slice(0, -1)
      .map((chunk, index) => ({ index, size: chunk.length + chunks[index + 1].length + 1 }))
      .filter(item => item.size <= maxSourceChars);
    if (!candidates.length) break;
    const target = candidates.sort((left, right) => left.size - right.size || left.index - right.index)[0];
    chunks.splice(target.index, 2, `${chunks[target.index]}\n${chunks[target.index + 1]}`);
  }
  while (chunks.length < desiredParallelChunks) {
    const splittable = chunks.map((chunk, index) => ({ index, lines: chunk.split("\n").filter(Boolean), size: chunk.length }))
      .filter(item => item.lines.length > 1)
      .sort((left, right) => right.size - left.size || left.index - right.index)[0];
    if (!splittable) break;
    const target = Math.ceil(splittable.size / 2);
    let size = 0;
    let cut = 1;
    for (let index = 0; index < splittable.lines.length - 1; index += 1) {
      size += splittable.lines[index].length + 1;
      cut = index + 1;
      if (size >= target) break;
    }
    chunks.splice(splittable.index, 1, splittable.lines.slice(0, cut).join("\n"), splittable.lines.slice(cut).join("\n"));
  }
  while (!flexibleUnitCount && chunks.length > count) {
    const candidates = chunks.slice(0, -1).map((chunk, index) => ({ index, size: chunk.length + chunks[index + 1].length }));
    const target = candidates.sort((left, right) => left.size - right.size || left.index - right.index)[0];
    chunks.splice(target.index, 2, `${chunks[target.index]}\n${chunks[target.index + 1]}`);
  }
  let cursor = 0;
  return chunks.map(chunk => {
    const lines = chunk.split("\n").map(item => item.trim()).filter(Boolean);
    const first = lines[0] || chunk;
    const last = lines.at(-1) || first;
    const foundStart = source.indexOf(first, cursor);
    const start = foundStart >= 0 ? foundStart : cursor;
    const foundEnd = source.indexOf(last, start);
    const end = foundEnd >= 0 ? Math.min(source.length, foundEnd + last.length) : Math.min(source.length, start + chunk.length);
    cursor = end;
    return { text: chunk, start, end };
  });
}

function uploadedAnalysisConcurrency(chunkSchedules = [], textProvider = {}) {
  const list = Array.isArray(chunkSchedules) ? chunkSchedules : [];
  if (!list.length) return 1;
  // Coding Plan queues large structured completions. Serializing uploaded
  // script analysis avoids two 13K-input requests starving each other before
  // either sends its first usable stream frame.
  if (/ark\.cn-[a-z0-9-]+\.volces\.com\/api\/coding\/v3/i.test(String(textProvider?.baseUrl || ""))) return 1;
  // Structured upload chunks share one source ledger.  Serialize them for
  // every provider: it lowers relay pressure and makes checkpoints a true
  // resume boundary rather than a race between concurrent long streams.
  return Math.max(1, Math.min(UPLOADED_ANALYSIS_MAX_CONCURRENCY, list.length));
}

function explicitTaggedAssetNames(text = "", labels = []) {
  const labelPattern = labels
    .map(label => String(label || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&"))
    .filter(Boolean)
    .join("|");
  if (!labelPattern) return [];
  const names = [];
  const seen = new Set();
  const add = value => {
    const name = String(value || "").trim()
      .replace(/^@+/, "")
      .replace(/^\s*(?:\*\*|__)(.+?)(?:\*\*|__)\s*$/u, "$1")
      .replace(/[；;，,。]+$/, "")
      .trim();
    if (!name || name === "无" || isProductionFieldLabel(name) || seen.has(name)) return;
    seen.add(name);
    names.push(name);
  };
  const linePattern = new RegExp(`(?:^|\\n)[ \\t]*(?:#{1,6}[ \\t]*)?(?:【[ \\t]*(?:${labelPattern})[ \\t]*】|(?:${labelPattern}))[ \\t]*[：:]?[ \\t]*([^\\n]+)`, "gi");
  for (const match of String(text || "").replace(/\r\n?/g, "\n").matchAll(linePattern)) {
    const value = String(match[1] || "").trim();
    const tagged = [...value.matchAll(/@([^\s@，、；;]+)/g)].map(item => item[1]);
    if (tagged.length) {
      tagged.forEach(add);
      continue;
    }
    const entries=value.split(/[；;]+/).map(part=>part.trim().replace(/[。.!！]+$/u,"")).filter(Boolean);
    const castDescription=/^(?:[男女中青老少年\d岁\s、]*)(?:.*(?:快递员|外卖员|配送员|服务员|独居老人|退休老人|站长|经理|老板|保安|司机|店员|医生|护士|父亲|母亲|儿子|女儿|妻子|丈夫))(?:[，,].*)?$/u;
    const describedCast=labels.some(label=>/^(?:人物|角色)$/.test(label))&&entries.length>1&&entries.every(entry=>{
      const pair=entry.split(/[，,]/);return pair.length>1&&pair[0].trim().length>=2&&castDescription.test(pair.slice(1).join('，').trim());
    });
    // Semicolons delimit cast records; their comma-separated occupations are
    // attributes of the preceding person, not additional anonymous actors.
    if(describedCast)entries.forEach(entry=>add(entry.split(/[，,]/)[0]));
    else value.split(/[，、；;]+/).forEach(add);
  }
  // Markdown uploads commonly keep action-only actors in a dedicated cast
  // section (`## 人物` followed by `**小周**：店员`). They would never appear
  // in the dialogue ledger, so omitting this section loses a real visual asset.
  let inDeclaredSection = false;
  for (const rawLine of String(text || "").replace(/\r\n?/g, "\n").split("\n")) {
    const heading = rawLine.match(/^\s*#{1,6}\s*([^#\n]+?)\s*$/u)?.[1]?.trim() || "";
    if (heading) {
      inDeclaredSection = new RegExp(`^(?:${labelPattern})(?:清单|设定|小传|资料)?$`, "i").test(heading);
      continue;
    }
    if (!inDeclaredSection || !String(rawLine || "").trim()) continue;
    const line = String(rawLine || "").trim();
    const boldCue = line.match(/^(?:[-*•]\s*)?(?:\*\*|__)([^*_：:\n]{1,32})(?:\*\*|__)\s*[：:]/u);
    const plainCue = line.match(/^(?:[-*•]\s*)?(?:C\d{1,3}\s*[｜|:：-]?\s*)?([^：:\n（(]{2,20})(?:\s*[（(][^）)]{0,40}[）)])?\s*[：:]/u);
    const tagged = [...line.matchAll(/@([^\s@，、；;：:]+)/g)].map(item => item[1]);
    if (boldCue) add(boldCue[1]);
    else if (plainCue) add(plainCue[1]);
    else tagged.forEach(add);
  }
  return names;
}

// For an AI-first upload, the standardized production script is the only
// parser-facing source of truth.  Older checkpoints may still contain cast
// pollution produced from act headings, cast-list prose or a composite label
// such as "甲、乙、围观人群".  Rebuild the character bible from the canonical
// per-line speakers plus explicit 【人物】 rows and remap every nested character
// reference locally.  This repairs an already-paid checkpoint without another
// provider request and prevents invalid assets from reaching prompt review.
function enforceCanonicalUploadedCharacterManifest(data = {}, productionScript = "", dialogueLedger = []) {
  const source = data && typeof data === "object" ? data : {};
  const ledger = sortSourceDialogueLedger(Array.isArray(dialogueLedger) ? dialogueLedger : [])
    .filter(item => !isProductionFieldLabel(item?.speaker) && !isProductionFieldLabel(item?.speakerRaw));
  const orderedNames = [];
  const seenNames = new Set();
  const addName = value => {
    const name = String(value || "").trim();
    if (!name || name === "无" || isProductionFieldLabel(name) || seenNames.has(name)) return;
    seenNames.add(name);
    orderedNames.push(name);
  };
  ledger.forEach(item => addName(item?.speaker || item?.speakerRaw));
  explicitTaggedAssetNames(productionScript, ["人物", "角色"]).forEach(addName);
  if (!orderedNames.length) return source;

  const existing = Array.isArray(source.characters) ? source.characters : [];
  const existingByName = new Map(existing
    .map(item => [String(item?.name || "").trim(), item])
    .filter(([name]) => name));
  const oldNameById = new Map(existing
    .map(item => [String(item?.id || "").trim(), String(item?.name || "").trim()])
    .filter(([id, name]) => id && name));
  const idWidth = Math.max(2, String(orderedNames.length).length);
  const characters = orderedNames.map((name, index) => {
    const prior = existingByName.get(name) || {};
    const firstLine = ledger.find(item => String(item?.speaker || item?.speakerRaw || "").trim() === name);
    return {
      ...prior,
      id: `C${String(index + 1).padStart(idWidth, "0")}`,
      name,
      description: String(prior?.description || "").trim()
        || `${name}按标准制作稿建立唯一写实人物资产；年龄、脸型、五官、发型、体型和惯用姿态跨镜固定`,
      identitySignature: String(prior?.identitySignature || "").trim()
        || `${name}的年龄段、脸型五官比例、体型姿态与发型轮廓全剧固定`,
      voiceDescription: String(prior?.voiceDescription || "").trim()
        || `${name}按标准制作稿逐句语气清楚表达，音色、语速与口型归属跨镜稳定`,
      signatureLine: String(prior?.signatureLine || firstLine?.text || `${name}按原稿完成表演`).slice(0, 36),
      importance: String(prior?.importance || (index < 2 ? "lead" : "supporting"))
    };
  });
  const canonicalByName = new Map(characters.map(item => [item.name, item]));
  const canonicalNameById = new Map(characters.map(item => [item.id, item.name]));
  const remapCharacter = value => {
    const token = String(value || "").trim();
    if (!token) return "";
    // Prefer the checkpoint's old id->name mapping.  An old C09 may have been
    // a fake "第一幕" asset even though C09 could be a valid new ordinal.
    const name = oldNameById.get(token)
      || (canonicalByName.has(token) ? token : "")
      || canonicalNameById.get(token)
      || "";
    return canonicalByName.get(name)?.id || "";
  };
  const remapReferences = (value, key = "") => {
    if (value === null || value === undefined) return value;
    if (CHARACTER_REFERENCE_ARRAY_KEYS.has(key)) {
      return normalizeStringArray(value).map(remapCharacter).filter(Boolean);
    }
    if (CHARACTER_REFERENCE_SCALAR_KEYS.has(key)) return remapCharacter(value);
    if (Array.isArray(value)) return value.map(item => remapReferences(item, ""));
    if (typeof value !== "object") return value;
    return Object.fromEntries(Object.entries(value).map(([childKey, childValue]) => [childKey, remapReferences(childValue, childKey)]));
  };
  const remapped = remapReferences({ ...source, characters: undefined });
  const canonical = {
    ...remapped,
    characters,
    canonicalCharacterManifest: {
      source: "ai-standardized-production-script",
      characterNames: orderedNames,
      dialogueSpeakerCount: new Set(ledger.map(item => String(item?.speaker || "").trim()).filter(Boolean)).size,
      repairedLocally: existing.some(item => !canonicalByName.has(String(item?.name || "").trim()))
    }
  };
  const decorated = decorateProjectAssetMetadata({
    ...canonical,
    script: { sourceDialogueLedger: ledger },
    assetLibraries: {
      ...(canonical.assetLibraries || {}),
      props: Array.isArray(canonical.props) ? canonical.props : (canonical.assetLibraries?.props || [])
    }
  });
  return {
    ...canonical,
    characters: decorated.characters,
    props: decorated.assetLibraries.props
  };
}

function canonicalizeExplicitTimedProps(shots = []) {
  const ordered = [];
  const seen = new Set();
  for (const shot of shots) {
    for (const value of Array.isArray(shot?.props) ? shot.props : []) {
      const name = String(value || "").trim();
      if (!name || seen.has(name)) continue;
      seen.add(name);
      ordered.push(name);
    }
  }
  const parentheticalBase = name => String(name || "").replace(/\s*[（(][^（）()]{1,80}[）)]\s*$/, "").trim();
  const decoratedByBase = new Map();
  for (const name of ordered) {
    const base = parentheticalBase(name);
    if (!base || base === name) continue;
    const variants = decoratedByBase.get(base) || [];
    variants.push(name);
    decoratedByBase.set(base, variants);
  }
  const canonicalFor = new Map();
  for (const name of ordered) {
    const variants = decoratedByBase.get(name) || [];
    canonicalFor.set(name, variants.length === 1 ? variants[0] : name);
  }
  const records = new Map();
  for (const name of ordered) {
    const canonicalName = canonicalFor.get(name) || name;
    const record = records.get(canonicalName) || { name: canonicalName, aliases: [] };
    if (name !== canonicalName && !record.aliases.includes(name)) record.aliases.push(name);
    records.set(canonicalName, record);
  }
  for (const shot of shots) {
    shot.props = [...new Set((Array.isArray(shot?.props) ? shot.props : []).map(name => canonicalFor.get(name) || name))];
  }
  return [...records.values()];
}

function validateScriptAnalysisChunkResult(result = {}, payload = {}) {
  const failures = [];
  if (!result?.story || typeof result.story !== "object" || Array.isArray(result.story)) failures.push("story 必须是完整故事对象");
  const shots = Array.isArray(result?.shots) ? result.shots : [];
  const characters = Array.isArray(result?.characters) ? result.characters : [];
  const scenes = Array.isArray(result?.scenes) ? result.scenes : [];
  const props = Array.isArray(result?.props) ? result.props : [];
  const requestedUnits = Number(payload?.unitCount) || 0;
  const expectedUnits = requestedUnits > 0 ? Math.max(1, requestedUnits) : 0;
  if (expectedUnits > 0 && shots.length !== expectedUnits) failures.push(`shots 必须恰好 ${expectedUnits} 个，实际 ${shots.length} 个`);
  if (expectedUnits === 0 && shots.length < 1) failures.push("自由拆镜至少需要返回 1 个可生产 shot");
  if (!characters.length) failures.push("characters 不能为空");
  if (!scenes.length) failures.push("scenes 不能为空");
  for (const scene of scenes) {
    const sceneName = scene?.name || scene?.scene || scene?.sceneName;
    if (isInvalidPhysicalSceneAssetName(sceneName) && payload?.allowSceneCanonicalization !== true) {
      failures.push(`场景“${sceneName || "未命名"}”不是物理空间，时间段/镜头标题不得进入场景资产`);
    }
  }
  if (!Array.isArray(result?.props)) failures.push("props 必须是数组；原稿没有明确物品且自然文本没有独立剧情道具时返回空数组");
  if (payload?.requireCoreProp === true && !props.length) failures.push("原稿明确存在核心道具/证物，props 不能留空");
  const explicitPropNames = normalizeStringArray(payload?.explicitPropNames);
  for (const expectedName of explicitPropNames) {
    const found = props.some(prop => String(prop?.name || "").trim() === expectedName
      || normalizeStringArray(prop?.aliases).includes(expectedName));
    if (!found) failures.push(`原稿物品/道具栏明确列出的“${expectedName}”未进入唯一道具台账`);
  }
  for (const prop of props) {
    if (prop?.coreStory !== true) failures.push(`道具“${prop?.name || "未命名"}”没有证明其参与核心因果，不得进入资产库`);
    if (!String(prop?.purpose || prop?.causalRole || "").trim()) failures.push(`核心道具“${prop?.name || "未命名"}”缺少剧情用途`);
    if (!Array.isArray(prop?.units) || !prop.units.length) failures.push(`核心道具“${prop?.name || "未命名"}”缺少参与镜号`);
  }
  return failures.length ? failures : true;
}

function scriptAnalysisRepairProgress(result = {}, payload = {}) {
  const shots = Array.isArray(result?.shots) ? result.shots : [];
  const characters = Array.isArray(result?.characters) ? result.characters : [];
  const scenes = Array.isArray(result?.scenes) ? result.scenes : [];
  const verdict = validateScriptAnalysisChunkResult(result, payload);
  const expectedUnits = Math.max(0, Number(payload?.unitCount) || 0);
  const usefulShotCount = expectedUnits > 0 ? Math.min(expectedUnits, shots.length) : shots.length;
  return {
    failureCount: verdict === true ? 0 : verdict.length,
    usefulShotCount,
    score: usefulShotCount * 100
      + (result?.story && typeof result.story === "object" && !Array.isArray(result.story) ? 20 : 0)
      + Math.min(10, characters.length) * 5
      + Math.min(10, scenes.length) * 5
      + (Array.isArray(result?.props) ? 2 : 0)
  };
}

function rejectedScriptAnalysisDraft(error) {
  let current = error;
  const visited = new Set();
  while (current && typeof current === "object" && !visited.has(current)) {
    visited.add(current);
    if (current.invalidDraft && typeof current.invalidDraft === "object") return current.invalidDraft;
    current = current.cause;
  }
  return null;
}

function sourceLedgerScriptAnalysisRecovery(error, localBound = {}, payload = {}) {
  const rejected = rejectedScriptAnalysisDraft(error) || {};
  const expectedUnits = Math.max(0, Number(payload?.unitCount) || 0);
  const rejectedShots = Array.isArray(rejected?.shots) ? rejected.shots : [];
  const localShots = Array.isArray(localBound?.shots) ? localBound.shots : [];
  const shots = expectedUnits > 0
    ? (rejectedShots.length === expectedUnits ? rejectedShots : localShots)
    : (rejectedShots.length ? rejectedShots : localShots);
  const chooseNonEmpty = (candidate, fallback) => Array.isArray(candidate) && candidate.length
    ? candidate
    : (Array.isArray(fallback) ? fallback : []);
  const rejectedProps = Array.isArray(rejected?.props) ? rejected.props : null;
  const localProps = Array.isArray(localBound?.props) ? localBound.props : [];
  return {
    ...localBound,
    ...rejected,
    story: rejected?.story && typeof rejected.story === "object" && !Array.isArray(rejected.story)
      ? rejected.story
      : localBound.story,
    characters: chooseNonEmpty(rejected?.characters, localBound?.characters),
    scenes: chooseNonEmpty(rejected?.scenes, localBound?.scenes),
    props: payload?.requireCoreProp === true && !(rejectedProps || []).length
      ? localProps
      : (rejectedProps || localProps),
    shots
  };
}

function analysisChunkSchedules(chunks, filmSchedule) {
  const list = Array.isArray(chunks) ? chunks : [];
  if (!list.length) return [];
  const totalUnits = filmSchedule.unitDurations.length;
  const counts = Array(list.length).fill(1);
  const balancedMaximum = Math.ceil(totalUnits / list.length);
  let remaining = totalUnits - counts.length;
  while (remaining > 0) {
    const candidates = list.map((chunk, position) => ({ position, score: String(chunk?.text ?? chunk ?? "").length / counts[position] }))
      .filter(item => counts[item.position] < balancedMaximum);
    const index = candidates
      .sort((left, right) => right.score - left.score || left.position - right.position)[0].position;
    counts[index] += 1;
    remaining -= 1;
  }
  let cursor = 0;
  return list.map((chunk, index) => {
    const durations = filmSchedule.unitDurations.slice(cursor, cursor + counts[index]);
    cursor += counts[index];
    return {
      text: String(chunk?.text ?? chunk ?? ""),
      start: Number(chunk?.start) || 0,
      end: Number(chunk?.end) || 0,
      index,
      unitCount: counts[index],
      durations
    };
  });
}

function localUploadedAnalysisChunk(chunk, project = {}) {
  const authoredShots = Array.isArray(chunk?.authoredShots) ? chunk.authoredShots : [];
  if (authoredShots.length) {
    const projectCharacters = Array.isArray(project?.characters) ? project.characters : [];
    let parsed = null;
    try { parsed = JSON.parse(String(chunk?.text || "")); } catch {}
    const characters = Array.isArray(parsed?.characters) && parsed.characters.length
      ? parsed.characters
      : projectCharacters;
    const scenes = Array.isArray(parsed?.scenes) && parsed.scenes.length
      ? parsed.scenes
      : [];
    const props = Array.isArray(parsed?.props) ? parsed.props : [];
    return {
      story: parsed?.story || { premise: "从结构化制作剧本本地解析" },
      characters,
      scenes,
      props,
      shots: authoredShots
    };
  }
  const ledger = (Array.isArray(chunk?.sourceDialogueLedger) ? chunk.sourceDialogueLedger : []).map(item => ({ ...item }));
  const projectCanonicalSource = Number(project?.script?.formatAdaptation?.version || 0) >= 4
    ? String(project?.script?.formatAdaptation?.productionScript || "")
    : String(project?.script?.raw || "");
  const projectLedger = parseSourceDialogueLedger(projectCanonicalSource);
  const explicitlyListedNames = explicitTaggedAssetNames(chunk?.text, ["人物", "角色"]);
  const projectListedNames = explicitTaggedAssetNames(projectCanonicalSource, ["人物", "角色"]);
  const names = [...new Set([
    ...explicitlyListedNames,
    ...ledger.map(item => String(item?.speaker || item?.speakerRaw || "").trim()).filter(Boolean),
    ...projectListedNames,
    ...projectLedger.map(item => String(item?.speaker || item?.speakerRaw || "").trim()).filter(Boolean),
    ...(Array.isArray(project?.characters) ? project.characters.map(item => String(item?.name || "").trim()).filter(Boolean) : [])
  ])];
  // A transport failure can happen on an action-only chunk after the speaking
  // characters appeared in an earlier chunk. Inherit the whole-script cast so
  // that this chunk remains structurally recoverable without inventing lines.
  // Truly narration-only material gets one neutral visual subject instead of
  // terminating the workflow; it still has no sourceDialogueBindings.
  if (!names.length && String(chunk?.text || "").trim()) names.push("叙事人物");
  if (!names.length) return {
    story: { premise: "按用户上传原稿识别人物关系、事件顺序和冲突" },
    characters: [],
    scenes: [],
    props: [],
    shots: []
  };
  const characters = names.map((name, index) => ({
    id: `C${String(index + 1).padStart(2, "0")}`,
    name,
    age: "以用户原稿与后续资产图为准",
    role: index === 0 ? "原稿主要说话人" : "原稿关系人物",
    description: `${name}的脸型、年龄纹理、发型、体态和永久识别特征以用户后续确认的资产为准`,
    identitySignature: `${name}姓名与原稿身份固定；脸型、年龄纹理和体态在全剧保持一致`,
    voiceDescription: `${name}按原稿括号语气表演；口语清楚，重音、速度和音量随原稿情绪变化`,
    signatureLine: String(ledger.find(item => item.speaker === name)?.text
      || projectLedger.find(item => item.speaker === name)?.text
      || `${name}会把原稿内容完整说清楚`).slice(0, 22),
    importance: index === 0 ? "lead" : "supporting"
  }));
  const characterByName = new Map(characters.map(item => [item.name, item]));
  const localSceneLedger = chunk?.sourceSceneLedger?.explicit
    ? chunk.sourceSceneLedger
    : buildSourceSceneLedger(chunk?.text || "");
  const scenes = (localSceneLedger.catalogue || []).length
    ? localSceneLedger.catalogue.map((item, index) => ({
      id: item.id || `SC${String(index + 1).padStart(2, "0")}`,
      name: item.name,
      description: `${item.name}的门窗、主要家具、人物走位区和正反打轴线固定；具体美术以原稿与用户资产为准`,
      interiorExterior: "以原稿为准",
      time: "以原稿为准",
      lighting: "保持人物面部和动作清楚，主光方向连续",
      atmosphere: "保留现场环境声，台词清晰",
      scenePurpose: "完整承载用户原稿的事件、对白和人物关系"
    }))
    : [{
      id: `SC${String(Number(chunk?.index || 0) + 1).padStart(2, "0")}`,
      name: "待核对物理场景",
      description: "原稿未给出可靠场景标题，后续按事件地点补齐具体空间",
      interiorExterior: "以原稿为准",
      time: "以原稿为准",
      lighting: "保持人物面部和动作清楚，主光方向连续",
      atmosphere: "保留现场环境声，台词清晰",
      scenePurpose: "完整承载用户原稿的事件、对白和人物关系"
    }];
  const sceneName = scenes[0]?.name || "待核对物理场景";
  const proseParts = String(chunk?.text || "").split(/\n+/).map(item => item.trim()).filter(Boolean);
  const estimatedTurnSeconds = item => speechWindowBounds(item?.text || "", item).targetSeconds;
  const estimatedDialogueSeconds = ledger.reduce((sum, item) => sum + estimatedTurnSeconds(item), 0);
  const adaptiveUnitCount = ledger.length
    ? Math.max(1, Math.ceil(estimatedDialogueSeconds / 12))
    : Math.max(1, Math.ceil(proseParts.length / 10), Math.ceil(String(chunk?.text || "").length / 600));
  // A free-form upload derives its fallback shot count from speakable dialogue
  // and actual source density. The settings-page target duration is never used.
  const unitCount = Number(chunk?.unitCount) > 0
    ? Math.max(1, Number(chunk.unitCount))
    : adaptiveUnitCount;
  const groups = Array.from({ length: unitCount }, () => []);
  if (ledger.length) {
    let groupIndex = 0;
    const targetTurns = Math.max(1, Math.ceil(ledger.length / unitCount));
    for (const line of ledger) {
      const current = groups[groupIndex];
      const speakers = new Set(current.map(item => item.speaker));
      const introducesThirdSpeaker = !speakers.has(line.speaker) && speakers.size >= 2;
      if (groupIndex < unitCount - 1 && current.length && (current.length >= targetTurns || introducesThirdSpeaker)) groupIndex += 1;
      groups[groupIndex].push(line);
    }
  }
  const proseGroups = Array.from({ length: unitCount }, () => []);
  proseParts.forEach((line, index) => {
    proseGroups[Math.min(unitCount - 1, Math.floor(index * unitCount / Math.max(1, proseParts.length)))].push(line);
  });
  const shots = groups.map((lines, index) => {
    const adaptiveDuration = Math.ceil(lines.reduce((sum, item) => sum + estimatedTurnSeconds(item), 0) + 1.5);
    const duration = Math.max(10, Math.min(15, Number(chunk?.durations?.[index]) || adaptiveDuration || 12));
    const speakers = [...new Set(lines.map(item => item.speaker))];
    const scenePresenceCharacterIds = speakers.map(name => characterByName.get(name)?.id).filter(Boolean);
    const visibleCharacterIds = scenePresenceCharacterIds.slice(0, 2);
    const focusCharacterId = visibleCharacterIds[0] || characters[0].id;
    const counterpartCharacterId = visibleCharacterIds.find(id => id !== focusCharacterId) || "";
    const atomicSubshotPlan = planAtomicDialogueSubshots(duration, lines.map(item => {
      const speakerId = characterByName.get(item.speaker)?.id || focusCharacterId;
      return { speakerId, text: item.text, onScreen: visibleCharacterIds.includes(speakerId) };
    }));
    const bindings = lines.map((item, turnIndex) => {
      const speakerId = characterByName.get(item.speaker)?.id || focusCharacterId;
      const listeners = visibleCharacterIds.filter(id => id !== speakerId).slice(0, 1);
      return {
        sourceDialogueId: item.id,
        listenerIds: listeners,
        subshotNumber: atomicSubshotPlan.turns[turnIndex]?.subshotNumber || 1,
        onScreen: visibleCharacterIds.includes(speakerId),
        intent: item.metadata?.intent || item.tone || "推进原稿事实",
        emotion: item.metadata?.emotion || item.tone || "按原稿处境自然表达",
        delivery: item.metadata?.delivery || item.tone || "口语清楚、句意完整",
        volume: item.metadata?.volume || "按情绪自然变化",
        pace: item.metadata?.pace || "按句意自然停连",
        body: item.metadata?.body || item.tone || "视线朝向听者，表情和手部动作与台词同步",
        listenerBeat: listeners.length ? "听者在眼神、呼吸和手部出现可见反应" : "画外听者反应由下一镜承接"
      };
    });
    const sourceAction = proseGroups[index].join("；") || lines.map(item => item.text).join("；") || "按用户原稿推进本段事件";
    const boundaries = atomicSubshotPlan.units.map(unit => [unit.start, unit.end]);
    const subshots = boundaries.map(([start, end], subIndex) => ({
      number: subIndex + 1,
      start,
      end,
      shotType: bindings.some(item => item.subshotNumber === subIndex + 1) ? "当前说话人近景" : "动作结果",
      cutReason: subIndex === 0 ? "承接上一镜事实" : "说话人轮次变化时硬切正反打",
      framing: subIndex === boundaries.length - 1 ? "说话人与动作结果同框" : "中近景",
      camera: subIndex > 0 ? "沿固定轴线切换当前说话人" : "稳定机位",
      action: `${sourceAction.slice(0, 160)}；第${subIndex + 1}拍完成可见变化`,
      sourceDialogueIds: bindings.filter(item => item.subshotNumber === subIndex + 1).map(item => item.sourceDialogueId),
      visibleCharacterIds,
      speakerIds: [],
      offscreenSpeakerIds: scenePresenceCharacterIds.filter(id => !visibleCharacterIds.includes(id)),
      sound: "连续现场环境底噪、清晰对白与同步动作声",
      transition: subIndex === boundaries.length - 1 ? "末句、视线或手部动作桥接下一镜" : "完整台词与反应接力"
    }));
    return {
      id: `U${Number(chunk?.index || 0) + 1}_${index + 1}`,
      title: `原稿拆镜${Number(chunk?.index || 0) + 1}-${index + 1}`,
      duration,
      characters: speakers,
      scene: sceneName,
      scenePresenceCharacterIds,
      visibleCharacterIds,
      focusCharacterId,
      counterpartCharacterId,
      action: sourceAction.slice(0, 240),
      stateBefore: index === 0 ? "承接用户原稿本段入口" : "承接上一镜末句和动作结果",
      stateAfter: lines.length ? `原稿台词 ${lines.at(-1).id} 已完整表达并触发下一动作` : "本段事件形成下一镜入口",
      causalLink: "严格按用户原稿事件顺序和台词顺序推进",
      visualBeat: sourceAction.slice(0, 180),
      emotion: lines.map(item => item.tone).filter(Boolean).join("→") || "按原稿情节递进",
      performance: "说话人朝向听者，以原稿语气、表情和动作完整说出台词；听者必须有可见反应",
      sourceDialogueBindings: bindings,
      sourceDialogueIds: bindings.map(item => item.sourceDialogueId),
      offscreenSpeakerIds: scenePresenceCharacterIds.filter(id => !visibleCharacterIds.includes(id)),
      productMention: false,
      productShotType: "none",
      subshots
    };
  });
  const explicitProps = explicitTaggedAssetNames(chunk?.text, ["物品", "道具", "核心道具", "关键道具"])
    .filter(name => isCoreStoryPropCandidate(name, chunk?.text, shots, project?.product?.name || ""))
    .map((name, index) => ({
    id: `P${String(index + 1).padStart(2, "0")}`,
    name,
    description: `${name}按用户原稿中的形状、材质、颜色和状态建立唯一写实资产`,
    coreStory: true,
    causalRole: "原稿中的事件、证据或关系变化需要该物件",
    purpose: "跨镜保持剧情所需的独立视觉身份",
    units: corePropUnitIds(name, shots),
    continuity: "名称、外观、持有人和状态变化按原稿连续"
  }));
  const bound = bindSourceDialogueLedgerToAnalysis({
    story: {
      synopsis: String(chunk?.text || "").replace(/\s+/g, " ").slice(0, 500),
      premise: "按用户上传原稿识别人物关系、事件顺序和冲突",
      hook: String(proseParts[0] || ledger[0]?.text || "按原稿开场").slice(0, 120),
      conflict: "保持用户原稿中的冲突与因果，不新增或改写台词",
      ending: String(proseParts.at(-1) || ledger.at(-1)?.text || "按原稿结尾").slice(0, 120)
    },
    characters,
    scenes,
    props: explicitProps,
    shots
  }, ledger);
  return enforceSourceSceneLedger(bound, chunk?.sourceSceneLedger, ledger);
}

function standardizedProductionFieldValues(body = "", labelPattern = "") {
  if (!labelPattern) return [];
  const pattern = new RegExp(`(?:^|\\n)\\s*【\\s*(?:${labelPattern})\\s*】\\s*([^\\n]*)`, "giu");
  return [...String(body || "").replace(/\r\n?/g, "\n").matchAll(pattern)]
    .map(item => String(item[1] || "").trim())
    .filter(Boolean);
}

function explicitAuthoredDurationHints(text = "") {
  const hints = new Map();
  const toSeconds = (first, second, third) => third === undefined
    ? Number(first) * 60 + Number(second)
    : Number(first) * 3600 + Number(second) * 60 + Number(third);
  const pattern = /^(?:#{1,6}\s*)?(S\d{1,4})\s*[｜|]\s*(\d{1,2}):(\d{2})(?::(\d{2}))?\s*(?:-|–|—|~|至)\s*(\d{1,2}):(\d{2})(?::(\d{2}))?/gmi;
  for (const match of String(text || "").replace(/\r\n?/g, "\n").matchAll(pattern)) {
    const start = toSeconds(match[2], match[3], match[4]);
    const end = toSeconds(match[5], match[6], match[7]);
    const duration = end - start;
    if (Number.isFinite(duration) && duration > 0) hints.set(String(match[1]).toUpperCase(), duration);
  }
  return hints;
}

function uploadedCharacterProfileHints(raw = "", characterNames = []) {
  const lines = String(raw || "").replace(/\r\n?/g, "\n").split("\n").map(line => line.trim()).filter(Boolean);
  const castRecords=lines.filter(line=>/^(?:#{1,6}\s*)?(?:人物|角色)(?:表|介绍|设定)?\s*[:：]/u.test(line))
    .flatMap(line=>line.replace(/^(?:#{1,6}\s*)?(?:人物|角色)(?:表|介绍|设定)?\s*[:：]\s*/u,'').split(/[；;]/u));
  const result = new Map();
  for (const name of characterNames) {
    const escaped = String(name || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    if (!escaped) continue;
    const cue = new RegExp(`^(?:(?:[-*•]|\\d+[.、)])\\s*)?(?:\\*\\*|__)?${escaped}(?:\\*\\*|__)?(?:\\s*[（(]([^）)]{0,80})[）)])?\\s*[，,:：｜|-]?\\s*(.*)$`, "u");
    const line = castRecords.find(item=>cue.test(item.trim())) || lines.find(item => cue.test(item)
      && !/[“”「」『』]/u.test(item) && !/^[^：:]+[（(][^）)]*[）)]\s*[:：]/u.test(item)
      && /(?:\d{1,3}\s*岁|性别|年龄|外貌|发型|女性|男性|女主|男主|老人|快递员|外卖员|站长|经理|母亲|父亲|短发|长发|穿着|身高)/u.test(item));
    if (!line) continue;
    const match = line.match(cue);
    const detail = [match?.[1], match?.[2]].map(value => String(value || "").trim()).filter(Boolean).join("，");
    const age = detail.match(/\d{1,3}\s*岁/)?.[0] || "";
    result.set(name, { age, description: detail, role:detail, source:'explicit_cast_record' });
  }
  return result;
}

function canonicalUploadedPropKey(value = "") {
  let name = String(value || "")
    .trim()
    .replace(/^[一二两三四五六七八九十\d]+\s*(?:件|把|张|份|个|本|袋|盒|套)\s*/u, "")
    .replace(/\s*[（(](?:破损|剪坏|撕坏|打开|展开|折叠|揉皱|使用|修复|缝补|状态)[^）)]*[）)]\s*$/u, "")
    .trim();
  // A continuity state is not a new asset. Use the stripped value only as a
  // grouping key; keep every authored state spelling as an alias.
  let previous = "";
  while (name && previous !== name) {
    previous = name;
    name = name.replace(/^(?:(?:已经|已)?(?:破损|剪坏|剪开|剪破|撕坏|撕破|撕碎|裂开|打开|展开|折叠|揉皱|揉成团|缝补|修复|洗净|取出|使用)(?:后)?的?)+/u, "").trim();
  }
  return name || String(value || "").trim();
}

function canonicalUploadedPropRecords(values = []) {
  const groups = new Map();
  for (const raw of Array.isArray(values) ? values : []) {
    const name = String(raw || "").trim();
    if (!name || name === "无") continue;
    const key = canonicalUploadedPropKey(name);
    const group = groups.get(key) || [];
    if (!group.includes(name)) group.push(name);
    groups.set(key, group);
  }
  return [...groups.entries()].map(([key, names]) => {
    const displayName = names.find(name => name === key)
      || [...names].sort((left, right) => left.length - right.length)[0]
      || key;
    return {
      key,
      name: displayName,
      aliases: names.filter(name => name !== displayName)
    };
  });
}

// The selected AI has already performed the only semantic rewrite here.  This
// compiler consumes that fixed parser-facing grammar deterministically.  It
// never asks a second model to restate the same story, so a long upload cannot
// be charged once for standardization and again for three lossy analysis
// drafts.  Exact dialogue IDs, speakers and scene occurrences come from the
// standardized ledgers and are carried directly into production shots.
function parseAiStandardizedProductionScript(text = "", project = {}, options = {}) {
  const source = String(text || "").replace(/\r\n?/g, "\n").trim();
  const blocks = headingBlocks(source, /^(?:#{1,6}\s*)?(S\d{1,4})\s*[｜|]\s*场景\s*[：:]\s*([^\n]+)$/gmi);
  if (!blocks.length || !/【\s*(?:动作|对白|台词|旁白|声音|承接)\s*】/u.test(source)) return null;
  const sceneLedger = options.sceneLedger?.explicit
    ? options.sceneLedger
    : buildSourceSceneLedger(source, { acceptStandardShotHeading: true });
  const dialogueLedger = sortSourceDialogueLedger(
    Array.isArray(options.dialogueLedger) && options.dialogueLedger.length
      ? options.dialogueLedger
      : productionDialogueLedgerFromScript(source, splitUploadedScriptSections(source), sceneLedger)
  );
  const assetBible = project?.script?.formatAdaptation?.assetBible && typeof project.script.formatAdaptation.assetBible === "object"
    ? project.script.formatAdaptation.assetBible
    : {};
  const bibleCharacters = Array.isArray(assetBible.characters) ? assetBible.characters : [];
  const bibleScenes = Array.isArray(assetBible.scenes) ? assetBible.scenes : [];
  const bibleProps = Array.isArray(assetBible.coreProps) ? assetBible.coreProps : (Array.isArray(assetBible.props) ? assetBible.props : []);
  const explicitlyListedNames = explicitTaggedAssetNames(source, ["人物", "角色"]);
  const orderedNames = [...new Set([
    ...explicitlyListedNames,
    ...dialogueLedger.map(item => String(item?.speaker || item?.speakerRaw || "").trim()).filter(Boolean),
    ...bibleCharacters.map(item => String(item?.name || "").trim()).filter(Boolean)
  ])];
  if (!orderedNames.length && source) orderedNames.push("叙事人物");
  const profileHints = uploadedCharacterProfileHints(project?.script?.raw || "", orderedNames);
  const characters = orderedNames.map((name, index) => {
    const bible = bibleCharacters.find(item => String(item?.name || "").trim() === name
      || normalizeStringArray(item?.aliases).includes(name)) || {};
    const hint = profileHints.get(name) || {};
    const firstLine = dialogueLedger.find(item => String(item?.speaker || item?.speakerRaw || "").trim() === name);
    const description = String(bible.description || bible.appearance || hint.description || "").trim()
      || `${name}按上传原稿建立写实人物资产，年龄纹理、脸型五官、发型、体型、服装和惯用姿态全剧固定`;
    return {
      id: `C${String(index + 1).padStart(2, "0")}`,
      name,
      aliases: normalizeStringArray(bible.aliases),
      age: String(bible.age || hint.age || "以标准制作稿为准").trim(),
      ageBand: String(bible.ageBand || bible.ageGroup || "").trim(),
      gender: String(bible.gender || bible.sex || "").trim(),
      role: String(bible.role || (index < 2 ? "主要人物" : "剧情人物")).trim(),
      description,
      sourceDescription: description,
      appearanceProvenance: {source:bible.description||bible.appearance?'source_asset_bible':hint.source||'unspecified',needsVisualDesign:!bible.descriptionEn},
      identitySignature: String(bible.identitySignature || bible.identity || "").trim()
        || `${name}的年龄段、脸型五官比例、发型轮廓、体型姿态和永久特征保持唯一且跨镜一致`,
      voiceDescription: String(bible.voiceDescription || bible.voice || "").trim()
        || `${name}按每句原稿语气清楚表达，音色、语速、音量与口型归属跨镜固定`,
      signatureLine: String(bible.signatureLine || firstLine?.text || `${name}按原稿完成表演`).slice(0, 36),
      importance: String(bible.importance || (index < 2 ? "lead" : "supporting")),
      castingTier: String(bible.castingTier || bible.roleType || "").trim(),
      roleType: String(bible.roleType || bible.castingTier || "").trim(),
      assetRequired: typeof bible.assetRequired === "boolean" ? bible.assetRequired : undefined,
      voiceAssetRequired: typeof bible.voiceAssetRequired === "boolean" ? bible.voiceAssetRequired : undefined,
      ...(hint.role&&!bible.role?{role:hint.role}:{})
    };
  });
  const characterByName = new Map(characters.map(item => [item.name, item]));
  const sceneActionByName = new Map();
  for (const block of blocks) {
    const name = String(block.match?.[2] || "").trim();
    const actions = standardizedProductionFieldValues(block.body, "动作|画面");
    const list = sceneActionByName.get(name) || [];
    list.push(...actions);
    sceneActionByName.set(name, list);
  }
  const scenes = (sceneLedger.catalogue || []).map((item, index) => {
    const bible = bibleScenes.find(scene => String(scene?.name || "").trim() === String(item?.name || "").trim()
      || normalizeStringArray(scene?.aliases).some(alias => alias === item?.name || normalizeStringArray(item?.aliases).includes(alias))) || {};
    const actionEvidence = (sceneActionByName.get(item.name) || []).join("；").slice(0, 360);
    return {
      id: item.id || `SC${String(index + 1).padStart(2, "0")}`,
      name: item.name,
      aliases: [...new Set([...normalizeStringArray(item.aliases), ...normalizeStringArray(bible.aliases)])],
      description: String(bible.description || bible.layout || "").trim()
        || `${item.name}的空间结构、门窗、主要家具、人物走位区与正反打轴线固定；剧情动作依据：${actionEvidence || "按标准制作稿布置"}`,
      interiorExterior: String(bible.interiorExterior || "以标准制作稿为准"),
      time: String(bible.time || "随剧情连续"),
      lighting: String(bible.lighting || "人物面部、手部动作和关键物品清楚，主光方向跨镜连续"),
      atmosphere: String(bible.atmosphere || "保留连续环境底噪，所有对白清楚可辨"),
      scenePurpose: String(bible.scenePurpose || "承载标准制作稿中的人物行动、对白与因果变化")
    };
  });
  const sceneByName = new Map(scenes.flatMap(scene => [[scene.name, scene], ...normalizeStringArray(scene.aliases).map(alias => [alias, scene])]));
  const durationHints = explicitAuthoredDurationHints(project?.script?.raw || "");
  for (const [shotId, duration] of options.durationHints instanceof Map ? options.durationHints : []) {
    if (Number(duration) > 0) durationHints.set(String(shotId || "").toUpperCase(), Number(duration));
  }
  const productName = String(project?.product?.name || "").trim();
  const shots = blocks.map((block, index) => {
    const sourceId = String(block.match?.[1] || `S${index + 1}`).toUpperCase();
    const start = Number(block.match?.index) || 0;
    const end = Number(blocks[index + 1]?.match?.index) || source.length;
    const blockLedger = dialogueLedger.filter(item => {
      const authoredOwner = String(item?.sourceShotId || "").trim().toUpperCase();
      if (authoredOwner) return authoredOwner === sourceId;
      const sourceStart = Number(item?.sourceStart);
      return Number.isFinite(sourceStart) && sourceStart >= start && sourceStart < end;
    });
    const declaredVisibleNames = explicitTaggedAssetNames(block.body, ["人物", "角色"]);
    const castNames = [...new Set([
      ...declaredVisibleNames,
      ...blockLedger.map(item => String(item?.speaker || item?.speakerRaw || "").trim()).filter(Boolean)
    ])];
    const scenePresenceCharacterIds = castNames.map(name => characterByName.get(name)?.id).filter(Boolean);
    const speakerIds = [...new Set(blockLedger.map(item => characterByName.get(String(item?.speaker || item?.speakerRaw || "").trim())?.id).filter(Boolean))];
    const visibleCharacterIds = [...new Set(declaredVisibleNames.map(name => characterByName.get(name)?.id).filter(Boolean))];
    const effectiveVisible = visibleCharacterIds;
    const actions = standardizedProductionFieldValues(block.body, "动作|画面");
    const sound = standardizedProductionFieldValues(block.body, "声音|音效").join("；");
    const continuation = standardizedProductionFieldValues(block.body, "承接|转场").join("；");
    const openingState = standardizedProductionFieldValues(block.body, "起始状态|开场状态").join("；");
    const action = actions.join("；") || "按标准制作稿完成本段可见动作与人物反应";
    const naturalSeconds = dialogueGroupDuration(blockLedger);
    const sourceBudget=(project.script?.formatAdaptation?.performanceBudgets||[]).find(row=>row.shotId===sourceId);
    const performanceBudget=sourceBudget?require('./source-performance-budget').evaluateBudget(sourceBudget,blockLedger):null;
    const duration = Math.max(10, Math.min(15, performanceBudget?.requiredSeconds || Number(durationHints.get(sourceId)) || Math.ceil(naturalSeconds + Math.max(3, actions.length ? 1 : 0)) || 12));
    const atomicSubshotPlan = planAtomicDialogueSubshots(duration, blockLedger.map(item => {
      const speakerId = characterByName.get(String(item?.speaker || item?.speakerRaw || "").trim())?.id || effectiveVisible[0] || "";
      return { speakerId, text: String(item?.text || item?.spokenText || ""), onScreen: effectiveVisible.includes(speakerId) };
    }));
    const bindings = blockLedger.map((item, turnIndex) => {
      const speakerId = characterByName.get(String(item?.speaker || item?.speakerRaw || "").trim())?.id || effectiveVisible[0] || "";
      const target = require('./drama-staging-contract').resolvePrimaryListener({characters}, {}, {speakerId,sourceTone:item.tone,text:item.text});
      const listenerIds = target.id ? [target.id] : [];
      const subshotNumber = atomicSubshotPlan.turns[turnIndex]?.subshotNumber || 1;
      return {
        sourceDialogueId: item.id,
        speakerId,
        listenerIds,
        primaryListenerId:target.id,
        directToViewer:target.source==='viewer',
        addressMode:target.source==='viewer'?'viewer':'',
        subshotNumber,
        onScreen: effectiveVisible.includes(speakerId),
        intent: item?.metadata?.intent || item?.tone || "推进原稿事实",
        emotion: item?.metadata?.emotion || item?.tone || "按原稿语境表达",
        delivery: item?.metadata?.delivery || item?.tone || "自然口语、吐字清楚",
        volume: item?.metadata?.volume || "按场景距离与情绪自然变化",
        pace: item?.metadata?.pace || "确保整句在本镜时长内清楚说完",
        body: item?.metadata?.body || "说话人的表情、视线与手部动作跟随句意，不把动作描述说出口",
        listenerBeat: listenerIds.length ? "听者保持闭口，以眼神、呼吸和动作做出可见反应" : "画外听者反应由下一连续镜头承接"
      };
    });
    const dialogueTurns = blockLedger.map(item => {
      const binding = bindings.find(entry => entry.sourceDialogueId === item.id) || {};
      return {
        sourceDialogueId: item.id,
        speakerId: binding.speakerId || String(item?.speaker || ""),
        speaker: String(item?.speaker || item?.speakerRaw || ""),
        text: String(item?.text || item?.spokenText || ""),
        tone: String(item?.tone || binding.delivery || "自然口语"),
        delivery: String(binding.delivery || item?.tone || "自然口语"),
        listenerIds: binding.listenerIds || [],
        primaryListenerId: binding.primaryListenerId || '',
        directToViewer: binding.directToViewer === true,
        addressMode: binding.addressMode || '',
        subshotNumber: binding.subshotNumber || 1,
        onScreen: binding.onScreen !== false
      };
    });
    const boundaries = atomicSubshotPlan.units.map(unit => [unit.start, unit.end]);
    const subshots = boundaries.map(([subStart, subEnd], subIndex) => {
      const localBindings = bindings.filter(binding => binding.subshotNumber === subIndex + 1);
      const localSpeakerIds = [...new Set(localBindings.map(binding => binding.speakerId).filter(Boolean))];
      const localBodyActions = [...new Set(localBindings.map(binding => String(binding.body || "").trim()).filter(Boolean))];
      const localVisible = [...new Set([
        ...localSpeakerIds.filter(id => effectiveVisible.includes(id)),
        ...effectiveVisible
      ])];
      return {
        number: subIndex + 1,
        start: Number(subStart.toFixed(2)),
        end: Number(subEnd.toFixed(2)),
        shotType: localBindings.length ? "当前说话人或行动近景" : "动作结果与承接镜",
        cutReason: subIndex === 0 ? "承接上一段可见尾态" : "只在完整台词结束、说话人轮次变化处硬切",
        framing: subIndex === boundaries.length - 1 ? "说话人与关键动作结果同框" : "中近景",
        camera: subIndex > 0 ? "沿既定轴线硬切当前说话人" : "稳定机位，动作发生时小幅跟随",
        action: localBodyActions.length
          ? `${localBodyActions.join("；")}；${subIndex === boundaries.length - 1 ? "末句后只完成本镜已建立动作的可见结果" : "只执行当前台词对应动作，不提前执行后续动作"}`
          : (subIndex === 0 ? action : "承接上一子镜的既有物理状态，只完成本镜可见结果，不新增发声或重演动作"),
        sourceDialogueIds: localBindings.map(binding => binding.sourceDialogueId),
        visibleCharacterIds: localVisible,
        speakerIds: localSpeakerIds,
        offscreenSpeakerIds: localSpeakerIds.filter(id => !localVisible.includes(id)),
        sound: sound || "连续现场环境底噪、清晰对白与同步动作声",
        transition: subIndex === boundaries.length - 1 ? (continuation || "以人物视线、手部动作或声音桥接下一镜") : "完整台词结束后按说话人轮次切换"
      };
    });
    const ratio = blocks.length > 1 ? index / (blocks.length - 1) : 0;
    const stage = index === 0 ? "hook" : ratio < 0.28 ? "pressure" : ratio < 0.55 ? "escalation" : ratio < 0.78 ? "main_reversal" : ratio < 0.94 ? "payoff" : "ending";
    const scene = sceneByName.get(String(block.match?.[2] || "").trim()) || scenes[0] || {};
    return {
      id: sourceId,
      title: action.split(/[。！？；]/)[0].slice(0, 32) || `标准段 ${index + 1}`,
      duration,
      ...(performanceBudget?{sourcePerformanceBudget:performanceBudget}:{}),
      characters: castNames,
      characterIds: scenePresenceCharacterIds,
      scenePresenceCharacterIds,
      visibleCharacterIds: effectiveVisible,
      focusCharacterId: speakerIds[0] || effectiveVisible[0] || "",
      counterpartCharacterId: effectiveVisible.find(id => id !== (speakerIds[0] || effectiveVisible[0])) || "",
      scene: scene.name || String(block.match?.[2] || "").trim(),
      sceneId: scene.id || "",
      action,
      dialogue: formatDialogueTurns(dialogueTurns),
      dialogueTurns,
      sourceDialogueBindings: bindings,
      sourceDialogueIds: bindings.map(binding => binding.sourceDialogueId),
      offscreenSpeakerIds: speakerIds.filter(id => !effectiveVisible.includes(id)),
      stateBefore: openingState || (index === 0 ? "按本段原始动作发生前的在场人物、位置与持物建立开场，不继承空场景资产图的无人要求" : "承接上一标准段的末拍人物位置、物品状态与情绪；场景转换按本段原始动作建立位置"),
      stateAfter: continuation || "本段对白与动作完成，形成下一段的明确入口",
      causalLink: continuation || "严格按标准制作稿的事件顺序和对白顺序推进",
      visualBeat: action.slice(0, 220),
      emotion: blockLedger.map(item => item.tone).filter(Boolean).join("→") || "按标准制作稿递进",
      performance: "只有绑定说话人按原稿语气说出逐字台词；其他人物始终闭口并用可见反应承接",
      mainlineStage: stage,
      mainlineBeat: `${action.slice(0, 160)}${continuation ? `；${continuation.slice(0, 100)}` : ""}`,
      reversalSetup: stage === "pressure" || stage === "escalation" ? action.slice(0, 120) : "",
      shotSize: "中近景与关键动作特写交替",
      cameraMove: "按视线、台词落点和动作结果进行有动机的稳定切镜",
      compositionPlan: "说话人与听者沿固定轴线分配正反打；关键手部动作使用独立特写，避免同构重复画面",
      audioPlan: sound || "逐句使用绑定人物音色；非说话人物闭口；环境底噪连续，动作声与画面同步",
      soundDesign: sound || "连续环境声、清晰对白、同步动作声",
      subshots,
      referencePlan: { images: ["有序分镜合图", "场景", ...effectiveVisible.map(id => `人物:${id}`), ...(productName && block.body.includes(productName) ? ["商品"] : [])], audios: speakerIds },
      productMention: Boolean(productName && block.body.includes(productName)),
      productShotType: productName && block.body.includes(productName) ? "natural_use" : "none"
    };
  });
  const explicitlyDeclaredCoreProps = blocks.flatMap(block => [
    ...standardizedProductionFieldValues(block.body, "核心物品|核心道具|关键物品|关键道具"),
    ...[...String(block.body || "").matchAll(/(?:^|[；;，,])\s*(?:核心物品|核心道具|关键物品|关键道具)\s*[：:]\s*([^\n；;]+)/giu)].map(match => match[1])
  ]).flatMap(value => value.split(/[，、；;]+/));
  const propRecords = canonicalUploadedPropRecords([
    ...explicitlyDeclaredCoreProps,
    ...bibleProps.map(item => String(item?.name || ""))
  ]);
  const props = propRecords
    .filter(record => !isSameProductName(record.name, productName)
      && !record.aliases.some(alias => isSameProductName(alias, productName)))
    .map((record, index) => {
      const name = record.name;
      const bible = bibleProps.find(item => {
        const bibleName = String(item?.name || "").trim();
        return bibleName === name || record.aliases.includes(bibleName)
          || normalizeStringArray(item?.aliases).some(alias => alias === name || record.aliases.includes(alias));
      }) || {};
      return {
        id: String(bible.id || `P${String(index + 1).padStart(2, "0")}`),
        name,
        aliases: [...new Set([...record.aliases, ...normalizeStringArray(bible.aliases)])],
        description: String(bible.description || `${name}按标准制作稿中的形状、材质、颜色和状态建立唯一写实资产`),
        holder: String(bible.holder || ""),
        coreStory: true,
        causalRole: String(bible.causalRole || bible.purpose || `${name}触发、证明、改变或回收核心剧情`),
        purpose: String(bible.purpose || bible.causalRole || "跨镜保持核心因果所需的独立视觉身份"),
        units: normalizeStringArray(bible.units).length ? normalizeStringArray(bible.units) : corePropUnitIds(name, shots),
        continuity: String(bible.continuity || "外观、归属、位置与状态变化按标准制作稿连续")
      };
    });
  return {
    detectedFormat: "ai_standardized_production_script",
    modeSynopsis: String(assetBible.synopsis || "").trim(),
    story: {
      storyMechanism: "fact_preserving_uploaded_story",
      premise: String(assetBible.synopsis || actionsFromShots(shots).slice(0, 280) || "按用户上传原稿推进完整故事"),
      hook: shots[0]?.action || "",
      conflict: shots[Math.min(shots.length - 1, Math.max(0, Math.floor(shots.length * 0.25)))]?.action || "",
      turns: [shots[Math.floor(shots.length * 0.5)]?.action, shots[Math.floor(shots.length * 0.75)]?.action].filter(Boolean),
      climax: shots[Math.max(0, shots.length - 2)]?.action || "",
      ending: shots.at(-1)?.stateAfter || shots.at(-1)?.action || "",
      emotionCurve: shots.map(shot => shot.emotion).filter(Boolean)
    },
    characters,
    scenes,
    props,
    shots,
    sourceDialogueLedger: dialogueLedger,
    sourceSceneLedger: sceneLedger,
    canonicalBlockCount: blocks.length
  };
}

function actionsFromShots(shots = []) {
  return (Array.isArray(shots) ? shots : []).map(shot => String(shot?.action || "").trim()).filter(Boolean).join("；");
}

function headingBlocks(text, pattern) {
  const matches = [...String(text || "").matchAll(pattern)];
  return matches.map((match, index) => ({
    match,
    body: String(text).slice(match.index + match[0].length, matches[index + 1]?.index ?? String(text).length).trim()
  }));
}

function bulletValue(body, label) {
  const escaped = String(label).replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return String(body || "").match(new RegExp(`^\\s*-\\s*${escaped}：\\s*(.+)$`, "m"))?.[1]?.trim() || "";
}

function parseSubshotTail(value) {
  const source = String(value || "").trim();
  const firstLabel = source.search(/[；;]\s*(?:对白|声音|切换|转场)\s*[：:]/);
  const action = (firstLabel >= 0 ? source.slice(0, firstLabel) : source).trim();
  // Dialogue itself contains semicolon-delimited performance metadata and may
  // contain another speaker turn. Stop only at the next known production
  // field, never at an arbitrary semicolon inside the dialogue value.
  const field = label => source.match(new RegExp(`(?:^|[；;])\\s*${label}\\s*[：:]\\s*([\\s\\S]*?)(?=[；;]\\s*(?:对白|声音|切换|转场)\\s*[：:]|$)`))?.[1]?.trim() || "";
  return {
    action,
    dialogue: field("对白"),
    sound: field("声音"),
    transition: field("(?:切换|转场)")
  };
}

function dialogueTurns(value) {
  return parseCompiledDialogueSegments(value, []).length;
}

function spokenCharacters(value) {
  return parseCompiledDialogueSegments(value, []).reduce((sum, turn) => (
    sum + String(turn.spokenText || turn.text || "").replace(/[^\u4e00-\u9fffA-Za-z0-9]/g, "").length
  ), 0);
}

function shotDialogueStats(shot) {
  const subshotDialogue = (shot.subshots || []).map(item => item.dialogue).filter(Boolean).join("；");
  const source = subshotDialogue || shot.dialogue || "";
  return { turns: dialogueTurns(source), characters: spokenCharacters(source) };
}

function blueprintCheckForFailure(code = "", message = "") {
  const source = `${String(code || "").toUpperCase()} ${String(message || "")}`;
  // Provider limits and parse/sequence integrity are execution requirements,
  // not optional creative review criteria. They remain under the structural
  // switch even when a dialogue or visual quality check is disabled.
  if (/HAILUO_.*(?:LIMIT|REFERENCE|ASSIGNMENT)|STRUCTURE_INVALID|SEQUENCE_INVALID|PARSE|MANAGED_MEDIA|REFERENCE_REQUIRED/.test(source)) return "productionStructure";
  if (/PRODUCT|商品|产品|卖点|带货/.test(source)) return "productIntegration";
  if (/DIALOGUE|SPEAKER|LISTENER|台词|对白|说话人|听者/.test(source)) return "dialogue";
  if (/EMOTION|PERFORMANCE|DELIVERY|语气|情绪|表情|表演/.test(source)) return "emotionalDelivery";
  if (/AUDIO|SOUND|VOICE|声音|音效|声线/.test(source)) return "soundDesign";
  if (/REVERSAL|EVIDENCE|反转|证据|伏笔/.test(source)) return "reversalStructure";
  if (/ESCALATION|PRESSURE|加压|冲突升级|逼迫/.test(source)) return "escalation";
  if (/TRAGEDY|悲剧|牺牲|代价/.test(source)) return "tragedyCraft";
  if (/FACE.?SLAP|打脸|清算|奖惩|PAYOFF|回收/.test(source)) return "faceSlapCraft";
  if (/CAUSAL|STATE_CHANGE|因果|状态变化|承接/.test(source)) return "causality";
  if (/VISUAL|COMPOSITION|SUBSHOT|FRAME|画面|构图|子镜头|景别|运镜/.test(source)) return "visualVariety";
  if (/STORY_CORE|MAINLINE|MOTIVE|故事核心|人物动机|主线/.test(source)) return "storyCore";
  if (/CLARITY|HOOK|清晰|理解|开场钩子/.test(source)) return "clarity";
  return "productionStructure";
}

function activeBlueprintFailures(entries = [], options = {}) {
  const checks = normalizeBlueprintAuditChecks(options.blueprintChecks || {});
  return (Array.isArray(entries) ? entries : []).filter(entry => {
    const code = entry && typeof entry === "object" ? entry.code : "";
    const message = entry && typeof entry === "object" ? entry.message : entry;
    return checks[blueprintCheckForFailure(code, message)] === true;
  });
}

function auditDramaSpec(normalized, options = {}) {
  const shots = Array.isArray(normalized?.shots) ? normalized.shots : [];
  const characters = Array.isArray(normalized?.characters) ? normalized.characters : [];
  const productName = String(options.productName || normalized?.product?.name || "").trim();
  const duration = shots.reduce((sum, shot) => sum + (Number(shot.duration) || 0), 0);
  const minutes = Math.max(duration / 60, 1 / 60);
  const dialogue = shots.map(shotDialogueStats);
  const turns = dialogue.reduce((sum, item) => sum + item.turns, 0);
  const spoken = dialogue.reduce((sum, item) => sum + item.characters, 0);
  const dialogueEligibleIndexes = shots.map((shot, index) => ({ shot, index })).filter(({ shot }) => {
    const role = `${shot?.productShotType || ""} ${shot?.shotFunction || ""}`;
    const visible = shot?.visibleCharacterIds || shot?.characterIds || shot?.characters || [];
    return Array.isArray(visible) && visible.length > 0 && !/product_(?:packshot|detail)/i.test(role);
  }).map(item => item.index);
  const denseUnits = dialogueEligibleIndexes.filter(index => dialogue[index]?.turns >= 2).length;
  const denseThreeUnits = dialogue.filter(item => item.turns >= 3).length;
  const denseFiveUnits = dialogue.filter(item => item.turns >= 5).length;
  const stageText = shot => `${shot.mainlineStage || ""} ${shot.mainlineBeat || ""} ${shot.action || ""}`;
  const countStage = pattern => shots.filter(shot => pattern.test(stageText(shot))).length;
  const reversalIndex = shots.findIndex(shot => String(shot.mainlineStage || "").trim() === "main_reversal");
  const productIndex = shots.findIndex(shot => shot.productMention || textMentionsProduct(shotContractText(shot), productName));
  const firstProductRatio = productIndex < 0 ? 1 : shots.slice(0, productIndex).reduce((sum, shot) => sum + (Number(shot.duration) || 0), 0) / Math.max(duration, 1);
  const subshotCount = shots.reduce((sum, shot) => sum + (shot.subshots?.length || 0), 0);
  const identitySignatures = characters.map(item => String(item.identitySignature || "").trim()).filter(Boolean);
  const sellingPoints = String(options.sellingPoints || normalized?.product?.sellingPoints || normalized?.product?.description || "").trim();
  const productShots = shots.filter(shot => shot.productMention);
  const themeTokens = [...productMentionTokens(productName), ...sellingPointTokens(sellingPoints)];
  const themeHits = productShots.filter(shot => {
    const blob = `${shot.dialogue || ""} ${shot.action || ""} ${shot.visualBeat || ""} ${JSON.stringify(shot.subshots || [])}`;
    return themeTokens.some(token => blob.includes(token));
  });
  const onCameraShots = shots.filter(shot => (shot.characterIds || shot.characters || []).length > 0);
  const silentSubshotCount = onCameraShots.reduce((sum, shot) => {
    const subs = Array.isArray(shot.subshots) ? shot.subshots : [];
    if (!subs.length) return sum + (shotDialogueStats(shot).characters ? 0 : 1);
    return sum + subs.filter(item => !String(item.dialogue || "").trim()).length;
  }, 0);
  const onCameraSubshotCount = onCameraShots.reduce((sum, shot) => {
    const subs = Array.isArray(shot.subshots) ? shot.subshots : [];
    return sum + Math.max(subs.length, 1);
  }, 0);
  const silentSubshotRatio = onCameraSubshotCount ? silentSubshotCount / onCameraSubshotCount : 0;
  const fieldCoverage = field => shots.length ? shots.filter(shot => String(shot[field] || "").trim()).length / shots.length : 0;
  const visualBeatKeys = shots.map(shot => String(shot.visualBeat || "").replace(/[\s，。；、：:！？!?]/g, "").slice(0, 24)).filter(Boolean);
  const metrics = {
    dialogueTurnsPerMinute: Number((turns / minutes).toFixed(1)),
    spokenCharactersPerMinute: Number((spoken / minutes).toFixed(1)),
    denseDialogueUnitRatio: dialogueEligibleIndexes.length ? Number((denseUnits / dialogueEligibleIndexes.length).toFixed(2)) : 1,
    denseThreeTurnUnitRatio: shots.length ? Number((denseThreeUnits / shots.length).toFixed(2)) : 0,
    denseFiveTurnUnitRatio: shots.length ? Number((denseFiveUnits / shots.length).toFixed(2)) : 0,
    silentSubshotRatio: Number(silentSubshotRatio.toFixed(2)),
    productThemeHitRatio: productShots.length ? Number((themeHits.length / productShots.length).toFixed(2)) : 1,
    escalationBeats: countStage(/pressure|escalation|加压|逼迫|羞辱|退路/),
    costlyKindnessBeats: shots.filter(shot => /cost_kindness|善意代价|有成本善意/.test(stageText(shot)) || (String(shot.kindnessCost || "").trim() && !/^(无|没有|不适用)$/.test(String(shot.kindnessCost).trim()))).length,
    evidenceBeats: countStage(/evidence|证据|伏笔|物证/),
    mainReversalBeats: shots.filter(shot => String(shot.mainlineStage || "").trim() === "main_reversal").length,
    payoffBeats: shots.filter(shot => String(shot.mainlineStage || "").trim() === "payoff" || /行动奖惩|兑现|回收|惩罚/.test(stageText(shot))).length,
    mainlineCoverage: shots.length ? Number((shots.filter(shot => String(shot.mainlineBeat || "").trim()).length / shots.length).toFixed(2)) : 0,
    characterIdentityCoverage: characters.length ? Number((identitySignatures.length / characters.length).toFixed(2)) : 0,
    distinctIdentitySignatures: new Set(identitySignatures).size,
    stateChangeCoverage: Math.min(fieldCoverage("stateBefore"), fieldCoverage("stateAfter")),
    causalLinkCoverage: fieldCoverage("causalLink"),
    visualBeatCoverage: fieldCoverage("visualBeat"),
    distinctVisualBeatRatio: shots.length ? Number((new Set(visualBeatKeys).size / shots.length).toFixed(2)) : 0,
    compositionPlanCoverage: fieldCoverage("compositionPlan"),
    audioPlanCoverage: fieldCoverage("audioPlan"),
    firstProductUnit: productIndex < 0 ? null : productIndex + 1,
    firstProductRatio: Number(firstProductRatio.toFixed(2)),
    reversalUnit: reversalIndex < 0 ? null : reversalIndex + 1
  };
  const checks = normalizeBlueprintAuditChecks(options.blueprintChecks || {});
  const dialogueTargets = dialogueReferenceTargets(duration);
  const hardFailures = productionHardContractFailures(normalized, {
    productName,
    commerceShotCount: options.commerceShotCount,
    requireProduct: Boolean(productName),
    requireHook: true,
    requireHookDialogue: true
  }).filter(item => checks[blueprintCheckForFailure(item.code, item.message)] !== false);
  const failures = hardFailures.slice();
  const requireMetric = (check, condition, code, message) => { if (checks[check] !== false && !condition) failures.push({ code, message }); };
  const adaptiveUploaded = normalized?.durationContract?.source === "uploaded-script-adaptive";
  const minimumSubshots = Math.ceil(adaptiveUploaded ? shots.length * 2.5 : Math.max(72, shots.length * 2.5));
  requireMetric("productionStructure", duration > 0, "DURATION", `剧总时长 ${duration} 秒无效`);
  requireMetric("productionStructure", shots.length >= Math.ceil(duration / 15), "SHOT_UNITS", `仅 ${shots.length} 个生成单元；按当前 ${duration} 秒总时长与单镜最多15秒，至少需要 ${Math.ceil(duration / 15)} 个`);
  requireMetric("visualVariety", subshotCount >= minimumSubshots, "SUBSHOT_DENSITY", `仅 ${subshotCount} 个可剪辑子镜头，至少需要 ${minimumSubshots} 个`);
  requireMetric("dialogue", metrics.dialogueTurnsPerMinute >= dialogueTargets.turnsPerMinuteMin, "DIALOGUE_TURNS", `对白仅 ${metrics.dialogueTurnsPerMinute} 轮/分钟，至少需要 ${dialogueTargets.turnsPerMinuteMin} 轮/分钟`);
  requireMetric("dialogue", metrics.spokenCharactersPerMinute >= dialogueTargets.spokenCharactersPerMinuteMin, "DIALOGUE_CHARS", `对白仅 ${metrics.spokenCharactersPerMinute} 字/分钟，至少需要 ${dialogueTargets.spokenCharactersPerMinuteMin} 字/分钟`);
  requireMetric("dialogue", metrics.denseDialogueUnitRatio >= dialogueTargets.twoTurnEligibleUnitRatioMin, "DENSE_DIALOGUE", `只有 ${Math.round(metrics.denseDialogueUnitRatio * 100)}% 适合说话的有人单元含至少两轮对白，至少需要 ${Math.round(dialogueTargets.twoTurnEligibleUnitRatioMin * 100)}%`);
  requireMetric("dialogue", metrics.silentSubshotRatio <= dialogueTargets.silentSubshotRatioMax, "SILENT_SUBSHOTS", `有人出镜子镜头中 ${Math.round(metrics.silentSubshotRatio * 100)}% 无对白，上限 ${Math.round(dialogueTargets.silentSubshotRatioMax * 100)}%`);
  requireMetric("escalation", metrics.escalationBeats >= Math.max(1, Math.min(6, Math.round(duration / 60))), "ESCALATION", `只有 ${metrics.escalationBeats} 个加压拍点，未达到当前时长需要`);
  requireMetric("tragedyCraft", metrics.costlyKindnessBeats >= Math.max(1, Math.min(2, Math.round(duration / 240))), "COSTLY_KINDNESS", `只有 ${metrics.costlyKindnessBeats} 个有成本善意拍点`);
  requireMetric("reversalStructure", metrics.evidenceBeats >= Math.max(1, Math.min(2, Math.round(duration / 180))), "EVIDENCE", `只有 ${metrics.evidenceBeats} 个证据拍点`);
  requireMetric("reversalStructure", metrics.mainReversalBeats >= 1, "MAIN_REVERSAL", "缺少被前置证据支撑的主反转");
  requireMetric("faceSlapCraft", metrics.payoffBeats >= Math.max(1, Math.min(2, Math.round(duration / 180))), "PAYOFF", `只有 ${metrics.payoffBeats} 个行动奖惩/回收拍点`);
  requireMetric("storyCore", metrics.mainlineCoverage >= 0.9, "MAINLINE", `主线推进字段覆盖率只有 ${Math.round(metrics.mainlineCoverage * 100)}%`);
  requireMetric("productionStructure", characters.length >= (adaptiveUploaded ? 1 : 3) && characters.length <= 7, "CHARACTER_COUNT", `核心角色 ${characters.length} 人，应控制在 ${adaptiveUploaded ? "1" : "3"}-7 人`);
  requireMetric("productionStructure", metrics.characterIdentityCoverage === 1 && metrics.distinctIdentitySignatures === characters.length, "CHARACTER_IDENTITY", "所有核心角色都必须有互不重复、不能只靠换衣区分的资产指纹");
  requireMetric("causality", metrics.stateChangeCoverage >= 0.9, "STATE_CHANGE", `明确起止状态的单元只有 ${Math.round(metrics.stateChangeCoverage * 100)}%`);
  requireMetric("causality", metrics.causalLinkCoverage >= 0.9, "CAUSAL_LINK", `明确因果承接的单元只有 ${Math.round(metrics.causalLinkCoverage * 100)}%`);
  requireMetric("visualVariety", metrics.visualBeatCoverage >= 0.9 && metrics.distinctVisualBeatRatio >= 0.85, "VISUAL_BEAT_DIVERSITY", `独占画面拍点覆盖 ${Math.round(metrics.visualBeatCoverage * 100)}%，去重率 ${Math.round(metrics.distinctVisualBeatRatio * 100)}%`);
  requireMetric("visualVariety", metrics.compositionPlanCoverage >= 0.9, "COMPOSITION_PLAN", `差异构图计划覆盖率只有 ${Math.round(metrics.compositionPlanCoverage * 100)}%`);
  requireMetric("soundDesign", metrics.audioPlanCoverage >= 0.9, "AUDIO_PLAN", `完整声音计划覆盖率只有 ${Math.round(metrics.audioPlanCoverage * 100)}%`);
  requireMetric("productIntegration", productShots.length === 0 || metrics.productThemeHitRatio >= 0.5, "PRODUCT_THEME", `商品窗口仅 ${Math.round(metrics.productThemeHitRatio * 100)}% 单元点到卖点/商品，至少需要 50%`);
  if (options.skipQualityGates) {
    if (options.bypassProductionContracts) {
      return {
        ok: true,
        skipped: true,
        failures: [],
        ignoredFailures: failures,
        metrics,
        note: "审核蓝图已关闭：不拦截、不回滚、不触发自动返修"
      };
    }
    return {
      ok: hardFailures.length === 0,
      skipped: true,
      failures: hardFailures,
      metrics,
      note: hardFailures.length
        ? "主观质量评分已关闭，但生产硬合同仍未通过"
        : "主观质量评分已关闭；商品窗口、开场钩子和媒体绑定硬合同已通过"
    };
  }
  return { ok: failures.length === 0, failures, metrics };
}

function stripTimedStoryboardInlineDialogue(value = "") {
  return String(value || "")
    .replace(/@[^：:“”\n]{1,24}\s*[：:]\s*[“\"][^”\"]*[”\"]/g, "说话人按对话汇总完成口型与表演")
    .replace(/台词延续\s*[：:]\s*[“\"][^”\"]*[”\"]/g, "延续上一拍说话表演")
    .replace(/\s*[，,；;]\s*[，,；;]+/g, "，")
    .trim();
}

function splitTimedDialogueSentences(value = "") {
  const text = String(value || "").trim();
  if (!text) return [];
  const parts = text.match(/[^。！？!?]+[。！？!?]+|[^。！？!?]+$/g)?.map(item => item.trim()).filter(Boolean) || [];
  return parts.length ? parts : [text];
}

function timedStoryboardSynopsis(actTitles = [], shots = [], ledger = []) {
  const cleanTitles = [...new Set(actTitles.map(item => String(item || "").trim()).filter(Boolean))];
  // Synopsis deliberately paraphrases visible action instead of quoting the
  // immutable dialogue ledger, so every authored line still appears exactly
  // once in the dialogue section and downstream video prompt.
  const middleShot = shots[Math.max(0, Math.floor(shots.length / 2))] || {};
  const opening = shots[0]?.authoredContinuity || shots[0]?.action || "人物冲突爆发";
  const middle = middleShot.authoredContinuity || middleShot.action || "关系与证据发生反转";
  const ending = shots.at(-1)?.stateAfter || shots.at(-1)?.endFrame || "人物用行动完成结果闭环";
  const arc = cleanTitles.length ? cleanTitles.join(" → ") : "冲突建立 → 证据反转 → 行动收束";
  const compact = value => String(value || "").replace(/\s+/g, "").slice(0, 72);
  return `本稿共${shots.length}个秒级分镜，剧情沿“${arc}”推进。开场以“${compact(opening)}”建立矛盾；中段以“${compact(middle)}”改变局势；结尾以“${compact(ending)}”完成收束。`;
}

/**
 * Parse the user-authored "幕 → 15秒分镜 → 秒级子镜 → 对话汇总" format
 * without spending another model request. The summary section is the only
 * dialogue truth source; inline copies are removed from visual actions.
 */
function parseTimedStoryboardScript(text) {
  const source = String(text || "").replace(/\r\n?/g, "\n");
  if (!/【对话汇总】/.test(source) || !/【0-\d+(?:\.\d+)?秒】镜头/.test(source)) return null;
  const markers = [...source.matchAll(/分镜\s*(\d+)\s*（([^）\n]+)）/g)];
  if (markers.length < 2) return null;
  const actMarkers = [...source.matchAll(/第\s*(\d+)\s*幕\s*[：:]\s*【([^】\n]+)】/g)];
  const actAt = index => {
    const found = actMarkers.filter(item => Number(item.index) <= index).at(-1);
    return { number: Math.max(1, Number(found?.[1]) || 1), title: String(found?.[2] || "").trim() };
  };
  const normalizeAuthoredName = value => String(value || "").trim().replace(/[（(](?:仅[^）)]*|画外音|旁白|不出镜)[）)]$/g, "").trim();
  const atNames = value => [...String(value || "").matchAll(/@([^\s@，、；;｜|]+)/g)].map(item => normalizeAuthoredName(item[1])).filter(Boolean);
  const field = (block, label) => {
    const match = block.match(new RegExp(`(?:^|\\n)${label}[：:]([^\\n]+)`));
    return String(match?.[1] || "").trim();
  };
  const drafts = [];
  const globalLedger = [];
  const allNames = new Set();
  const sceneRecords = new Map();
  const normalizedSceneLedger = buildSourceSceneLedger(source);
  for (let shotIndex = 0; shotIndex < markers.length; shotIndex += 1) {
    const marker = markers[shotIndex];
    const blockStart = Number(marker.index);
    const blockEnd = Number(markers[shotIndex + 1]?.index ?? source.length);
    const block = source.slice(blockStart, blockEnd);
    const header = block.split("\n", 1)[0];
    const act = actAt(blockStart);
    const duration = Math.max(1, Number(block.match(/【0-(\d+(?:\.\d+)?)秒】镜头/)?.[1]) || 15);
    const pace = String(marker[2] || "").split("·").at(-1)?.trim() || "中等节奏";
    const sceneFieldOffsets = [block.indexOf("场景：@"), block.indexOf("场景:@")].filter(value => value >= 0);
    const sceneFieldOffset = sceneFieldOffsets.length ? Math.min(...sceneFieldOffsets) : 0;
    const sceneOccurrence = sceneAtSourceOffset(normalizedSceneLedger, blockStart + Math.max(0, sceneFieldOffset));
    const sceneName = String(sceneOccurrence?.sceneName || field(block, "场景").replace(/^@/, "").trim() || header.match(/@([^｜\n]+)/)?.[1] || `场景${shotIndex + 1}`).trim();
    const cast = atNames(field(block, "人物"));
    const objects = atNames(field(block, "物品")).filter(name => name !== "无");
    cast.forEach(name => allNames.add(name));
    const weather = field(block, "天气/灯光/氛围") || "按剧情连续呈现光线、色温与情绪";
    const sceneDetails = [...block.matchAll(/(?:^|\n)场景[：:]([^@\n][^\n]*)/g)].map(item => String(item[1] || "").trim()).filter(Boolean);
    if (!sceneRecords.has(sceneName)) {
      sceneRecords.set(sceneName, {
        name: sceneName,
        description: sceneDetails[0] || `${sceneName}的固定空间结构、出入口、门窗家具与可行动区域`,
        time: String(header.match(/※\s*([^@\n]+)/)?.[1] || "按原稿").trim(),
        atmosphere: weather,
        lighting: weather,
        layout: "同一空间四视图锁定主入口正向、反向轴、左45度、右45度及门窗家具拓扑",
        cameraAnchors: ["主入口正向", "反向轴", "左侧45度", "右侧45度"],
        continuityLocks: ["四视图属于同一空间", "门窗家具拓扑固定", "主光方向与时段固定", "拍摄轴不翻转"]
      });
    }
    const summaryStart = block.indexOf("【对话汇总】");
    const soundStart = summaryStart >= 0 ? block.indexOf("【音效】", summaryStart) : -1;
    const summaryRaw = summaryStart >= 0
      ? block.slice(summaryStart + "【对话汇总】".length, soundStart >= 0 ? soundStart : block.length)
      : "";
    const summaryLines = summaryRaw
      .replace(/[ \t]+(?=@[^\s（(]{1,24}\s*[（(]\s*音色)/g, "\n")
      .split("\n").map(item => item.trim()).filter(Boolean);
    const turns = [];
    for (const summaryLine of summaryLines) {
      const match = summaryLine.match(/^@([^\s（(]+)\s*[（(]\s*音色[：:]\s*@?([^，,）)]+)\s*[，,]\s*(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)\s*秒\s*[，,]\s*([^）)]+)[）)]\s*[：:]\s*([\s\S]+)$/);
      if (!match) continue;
      const speaker = normalizeAuthoredName(match[1]);
      const voice = String(match[2]).trim();
      const turnStart = Math.max(0, Number(match[3]) || 0);
      const turnEnd = Math.max(turnStart + 0.1, Number(match[4]) || duration);
      const tone = String(match[5]).trim();
      const exactText = String(match[6]).trim().replace(/^[“\"「『]+/, "").replace(/[”\"」』]+$/, "").trim();
      allNames.add(speaker);
      const sentences = splitTimedDialogueSentences(exactText);
      const weights = sentences.map(item => Math.max(1, item.replace(/\s/g, "").length));
      const weightTotal = weights.reduce((sum, value) => sum + value, 0);
      let cursor = turnStart;
      sentences.forEach((sentence, sentenceIndex) => {
        const end = sentenceIndex === sentences.length - 1
          ? turnEnd
          : cursor + (turnEnd - turnStart) * weights[sentenceIndex] / weightTotal;
        const id = `D${String(globalLedger.length + 1).padStart(3, "0")}`;
        const ledgerEntry = {
          id,
          order: globalLedger.length + 1,
          speaker,
          speakerRaw: speaker,
          tone,
          text: sentence,
          spokenText: sentence,
          metadata: { sourceTone: tone, emotion: tone, delivery: tone, body: tone, voice },
          sourceStart: blockStart + Math.max(0, block.indexOf(summaryLine)),
          sourceEnd: blockStart + Math.max(0, block.indexOf(summaryLine)) + summaryLine.length,
          shotNumber: shotIndex + 1,
          startSecond: Number(cursor.toFixed(3)),
          endSecond: Number(end.toFixed(3))
        };
        globalLedger.push(ledgerEntry);
        turns.push({ ...ledgerEntry, voice });
        cursor = end;
      });
    }
    const timelineStart = block.search(/【0-\d+(?:\.\d+)?秒】镜头[：:]/);
    const timeline = timelineStart >= 0
      ? block.slice(timelineStart, summaryStart >= 0 ? summaryStart : block.length)
      : "";
    const subshots = [...timeline.matchAll(/(\d+(?:\.\d+)?)\s*-\s*(\d+(?:\.\d+)?)秒\s*[，,]?\s*【([\s\S]*?)】\s*[；;]/g)].map((sub, subIndex) => {
      const start = Number(sub[1]);
      const end = Number(sub[2]);
      const rawAction = String(sub[3] || "").trim();
      const localTurns = turns.filter(turn => turn.startSecond >= start && turn.startSecond < end + 0.001);
      const visibleNames = [...new Set([
        ...atNames(rawAction),
        ...cast.filter(name => rawAction.includes(name)),
        ...localTurns.map(turn => turn.speaker)
      ])];
      return {
        number: subIndex + 1,
        start,
        end,
        framing: rawAction.match(/^(全景|中景|近景|特写|大特写|远景|半身|双人|越肩)/)?.[1] || "中景",
        camera: rawAction.match(/缓慢推进|快速推进|推进|拉远|平移|跟镜头|跟拍|环绕|摇镜|固定镜头|转特写/)?.[0] || "按动作连续运镜",
        action: stripTimedStoryboardInlineDialogue(rawAction),
        dialogueTurns: localTurns,
        sourceDialogueIds: localTurns.map(turn => turn.id),
        dialogue: localTurns.map(turn => `${turn.speaker}：${turn.text}`).join("；"),
        visibleNames,
        sound: "动作声与现场环境声",
        transition: subIndex ? "由动作、视线或声音切换" : "承接上一镜动作结果"
      };
    });
    const continuity = String(block.match(/承接上一分镜[：:]\s*【([^】]+)】/)?.[1] || (shotIndex ? "承接上一分镜结果" : "开篇全景引入")).trim();
    const sound = soundStart >= 0
      ? String(block.slice(soundStart + "【音效】".length).split("【画面禁止项")[0] || "").trim()
      : "现场环境声与人物动作声";
    drafts.push({
      id: `S${String(shotIndex + 1).padStart(2, "0")}`,
      number: shotIndex + 1,
      title: `${act.title || "剧情推进"} · 分镜${shotIndex + 1}`,
      actNumber: act.number,
      actTitle: act.title,
      pace,
      weatherLightingAtmosphere: weather,
      authoredContinuity: continuity,
      duration,
      scene: sceneName,
      characters: cast,
      props: objects,
      subshots,
      dialogueTurns: turns,
      dialogue: turns.map(turn => `${turn.speaker}：${turn.text}`).join("；"),
      action: subshots.map(item => item.action).join("；") || sceneDetails[0] || continuity,
      shotSize: subshots[0]?.framing || "中景",
      cameraMove: subshots[0]?.camera || "按动作连续运镜",
      emotion: weather,
      performance: turns.map(turn => `${turn.speaker}以${turn.tone}完成逐句表演`).join("；") || "无对白表演",
      mainlineStage: shotIndex === 0 ? "hook" : "",
      mainlineBeat: continuity,
      kindnessCost: act.number === 1 ? "人物在冲突中承受可见的尊严、关系或现实代价" : "承接前幕已付出的代价",
      stateBefore: continuity,
      stateAfter: subshots.at(-1)?.action || "本镜动作结果落地",
      causalLink: `因为${continuity}，所以推进到${subshots.at(-1)?.action || "下一分镜"}`,
      visualBeat: subshots.map(item => item.action).join(" → "),
      compositionPlan: subshots.map(item => `${item.start}-${item.end}秒${item.framing}/${item.camera}`).join("；"),
      audioPlan: sound,
      soundDesign: sound,
      transitionIn: continuity,
      transitionOut: "以末拍动作、视线或声音承接下一分镜",
      startFrame: subshots[0]?.action || sceneDetails[0] || continuity,
      endFrame: subshots.at(-1)?.action || "本镜动作结果落地",
      productMention: /商品|产品|下单|链接|购物车|直播间|包装|使用|一盒|一瓶|一袋/.test(block)
    });
  }
  if (!drafts.length || !globalLedger.length) return null;
  const characterNames = [...allNames];
  const firstTextFor = name => {
    const draft = drafts.find(item => item.characters.includes(name) || item.dialogueTurns.some(turn => turn.speaker === name));
    return String(draft?.subshots?.find(item => item.action.includes(name))?.action || draft?.action || "按用户原稿角色关系与动作建立写实身份").slice(0, 220);
  };
  const voiceFor = name => globalLedger.filter(item => item.speaker === name).map(item => item.tone).filter(Boolean);
  const firstLineFor = name => globalLedger.find(item => item.speaker === name)?.text || "按剧情自然表达";
  const idByName = new Map(characterNames.map((name, index) => [name, `C${String(index + 1).padStart(2, "0")}`]));
  const characters = characterNames.map((name, index) => ({
    id: idByName.get(name),
    name,
    description: `${firstTextFor(name)}；提炼为写实人物资产，年龄、脸型、五官、发型、体型、惯用姿态和首套服装必须跨镜固定。`,
    identitySignature: `${name}专属身份锚${index + 1}：固定年龄段、脸型五官比例、体型姿态与发型轮廓，不得只靠换衣区分`,
    voiceDescription: `${[...new Set(voiceFor(name))].slice(0, 4).join("、") || "贴合人物关系自然表达"}；音色与说话节奏跨镜稳定`,
    signatureLine: firstLineFor(name),
    importance: index < 2 ? "lead" : "supporting",
    continuityLocks: ["脸型五官比例固定", "年龄体型固定", "发型轮廓固定", "同场连续服装固定"]
  }));
  drafts.forEach((shot, index) => {
    const firstIndexOfAct = drafts.findIndex(item => item.actNumber === shot.actNumber);
    shot.mainlineStage = index === 0
      ? "hook"
      : shot.actNumber >= 3
        ? "payoff"
        : shot.actNumber === 2 && index === firstIndexOfAct
          ? "main_reversal"
          : shot.actNumber === 1 ? "pressure" : "evidence";
    shot.scenePresenceCharacterIds = shot.characters.map(name => idByName.get(name)).filter(Boolean);
    shot.visibleCharacterIds = [...new Set(shot.subshots.flatMap(item => item.visibleNames.map(name => idByName.get(name)).filter(Boolean)))];
    shot.dialogueTurns = shot.dialogueTurns.map(turn => {
      const listeners = shot.characters.filter(name => name !== turn.speaker).slice(0, 2).map(name => idByName.get(name)).filter(Boolean);
      const targetSubshot = shot.subshots.findIndex(item => item.sourceDialogueIds.includes(turn.id));
      return {
        sourceDialogueId: turn.id,
        sourceTone: turn.tone,
        speakerId: idByName.get(turn.speaker) || turn.speaker,
        listenerIds: listeners,
        text: turn.text,
        delivery: turn.tone,
        emotionStart: turn.tone,
        emotionPeak: turn.tone,
        body: `${turn.tone}对应的面部微表情、视线和身体动作`,
        listenerBeat: listeners.length ? "听者闭口并给出与台词含义一致的可见反应" : "镜头用环境与动作承接",
        subshotNumber: Math.max(1, targetSubshot + 1),
        onScreen: true
      };
    });
    shot.sourceDialogueIds = shot.dialogueTurns.map(turn => turn.sourceDialogueId);
    shot.sourceDialogueBindings = shot.dialogueTurns.map(turn => ({
      sourceDialogueId: turn.sourceDialogueId,
      listenerIds: turn.listenerIds,
      subshotNumber: turn.subshotNumber,
      onScreen: true,
      intent: turn.sourceTone
    }));
    shot.subshots = shot.subshots.map(item => ({
      ...item,
      visibleCharacterIds: item.visibleNames.map(name => idByName.get(name)).filter(Boolean),
      dialogueTurns: shot.dialogueTurns.filter(turn => item.sourceDialogueIds.includes(turn.sourceDialogueId)),
      speakerIds: shot.dialogueTurns.filter(turn => item.sourceDialogueIds.includes(turn.sourceDialogueId)).map(turn => turn.speakerId),
      emotionBeat: weatherForTimedSubshot(item, shot),
      faceAction: "说话人与听者按逐句语义产生同步微表情",
      bodyAction: item.action,
      voiceDelivery: shot.dialogueTurns.filter(turn => item.sourceDialogueIds.includes(turn.sourceDialogueId)).map(turn => turn.sourceTone).join("；")
    }));
  });
  const actTitles = actMarkers.map(item => item[2]);
  const synopsis = timedStoryboardSynopsis(actTitles, drafts, globalLedger);
  const scenes = [...sceneRecords.values()].map((scene, index) => ({ id: `SC${String(index + 1).padStart(2, "0")}`, ...scene }));
  const propRecords = canonicalizeExplicitTimedProps(drafts);
  const props = propRecords.map((record, index) => ({
    id: `P${String(index + 1).padStart(2, "0")}`,
    name: record.name,
    aliases: record.aliases,
    description: `${record.name}按用户原稿状态生成写实资产，形状、材质、颜色、磨损和持有人状态跨镜固定`,
    coreStory: true,
    causalRole: "用户在原稿物品栏中明确列为需要跨镜保持一致的独立视觉资产",
    purpose: drafts.filter(shot => shot.props.includes(record.name)).map(shot => shot.authoredContinuity).slice(0, 3).join("；"),
    units: drafts.filter(shot => shot.props.includes(record.name)).map(shot => shot.id),
    continuity: "出现、持有、位置和状态变化必须按秒级分镜连续"
  }));
  return {
    detectedFormat: "timed_storyboard",
    modeSynopsis: synopsis,
    story: {
      synopsis,
      premise: synopsis,
      hook: drafts[0]?.mainlineBeat || drafts[0]?.action || "开场冲突",
      conflict: actTitles[0] || "人物关系与现实利益冲突",
      turns: actTitles,
      climax: actTitles.at(-1) || drafts.at(-1)?.action || "真相与行动落锤",
      ending: drafts.at(-1)?.endFrame || "行动结果闭环",
      emotionCurve: actTitles.length ? actTitles : ["压抑", "反转", "释放"],
      storyMechanism: "evidence_reversal"
    },
    characters,
    scenes,
    props,
    shots: drafts,
    sourceDialogueLedger: globalLedger
  };
}

function weatherForTimedSubshot(subshot = {}, shot = {}) {
  const delivery = (subshot.dialogueTurns || []).map(turn => turn.tone || turn.sourceTone).filter(Boolean).join("；");
  return delivery || shot.weatherLightingAtmosphere || shot.emotion || "按剧情自然表演";
}

function expandTimedStoryboardForProvider(data, providerKind = "", options = {}) {
  if (!data || data.detectedFormat !== "timed_storyboard") return data;
  const contract = durationContract(providerKind, options);
  const max = Number(contract.max) || 15;
  const min = Number(contract.min) || 10;
  if ((data.shots || []).every(shot => Number(shot.duration) <= max)) return data;
  const ledgerById = new Map((data.sourceDialogueLedger || []).map(item => [item.id, { ...item }]));
  const authoredTimingById = new Map((data.sourceDialogueLedger || []).map(item => [item.id, {
    startSecond: Number(item.startSecond) || 0,
    endSecond: Number(item.endSecond) || 0
  }]));
  const shots = [];
  for (const shot of data.shots || []) {
    const authoredDuration = Math.max(1, Math.round(Number(shot.duration) || max));
    const segmentCount = Math.max(1, Math.ceil(authoredDuration / max));
    const base = Math.floor(authoredDuration / segmentCount);
    const durations = Array.from({ length: segmentCount }, (_, index) => base + (index < authoredDuration - base * segmentCount ? 1 : 0));
    if (durations.some(value => value < min || value > max)) {
      throw Object.assign(new Error(`上传分镜 ${shot.number || shot.id} 的 ${authoredDuration} 秒无法适配当前供应商 ${min}-${max} 秒单元`), { code: "TIMED_STORYBOARD_DURATION_UNREPRESENTABLE" });
    }
    let offset = 0;
    durations.forEach((duration, segmentIndex) => {
      const segmentEnd = offset + duration;
      const turns = (shot.dialogueTurns || []).filter(turn => {
        const timing = authoredTimingById.get(turn.sourceDialogueId) || {};
        const start = Number(timing.startSecond);
        return start >= offset - 0.001 && (segmentIndex === durations.length - 1 ? start <= segmentEnd + 0.001 : start < segmentEnd - 0.001);
      }).map(turn => {
        const ledger = ledgerById.get(turn.sourceDialogueId);
        const timing = authoredTimingById.get(turn.sourceDialogueId) || {};
        if (ledger) {
          ledger.shotNumber = shots.length + 1;
          ledger.startSecond = Number(Math.max(0, Number(timing.startSecond) - offset).toFixed(3));
          ledger.endSecond = Number(Math.min(duration, Math.max(ledger.startSecond + 0.1, Number(timing.endSecond) - offset)).toFixed(3));
        }
        return { ...turn };
      });
      let subshots = (shot.subshots || []).filter(item => Number(item.end) > offset && Number(item.start) < segmentEnd).map((item, subIndex) => ({
        ...item,
        number: subIndex + 1,
        start: Number(Math.max(0, Number(item.start) - offset).toFixed(3)),
        end: Number(Math.min(duration, Number(item.end) - offset).toFixed(3)),
        dialogueTurns: turns.filter(turn => item.sourceDialogueIds?.includes(turn.sourceDialogueId)),
        sourceDialogueIds: turns.filter(turn => item.sourceDialogueIds?.includes(turn.sourceDialogueId)).map(turn => turn.sourceDialogueId)
      }));
      if (!subshots.length) subshots = [{ number: 1, start: 0, end: duration, framing: shot.shotSize, camera: shot.cameraMove, action: shot.action, dialogueTurns: turns, sourceDialogueIds: turns.map(turn => turn.sourceDialogueId) }];
      subshots[0].start = 0;
      subshots[subshots.length - 1].end = duration;
      shots.push({
        ...shot,
        id: `${shot.id}_${segmentIndex + 1}`,
        number: shots.length + 1,
        title: segmentCount > 1 ? `${shot.title}（${segmentIndex + 1}/${segmentCount}）` : shot.title,
        duration,
        subshots,
        dialogueTurns: turns,
        dialogue: turns.map(turn => `${turn.speakerId}：${turn.text}`).join("；"),
        sourceDialogueIds: turns.map(turn => turn.sourceDialogueId),
        sourceDialogueBindings: turns.map(turn => ({ sourceDialogueId: turn.sourceDialogueId, listenerIds: turn.listenerIds, subshotNumber: Math.max(1, subshots.findIndex(item => item.sourceDialogueIds?.includes(turn.sourceDialogueId)) + 1), onScreen: turn.onScreen !== false, intent: turn.intent || turn.sourceTone })),
        mainlineStage: segmentIndex ? (shot.mainlineStage === "hook" ? "pressure" : shot.mainlineStage) : shot.mainlineStage,
        stateBefore: segmentIndex ? `承接同一原分镜第${segmentIndex}段的末拍状态` : shot.stateBefore,
        causalLink: segmentIndex ? "同一原分镜因供应商时长上限无缝续接，人物位置、口型、动作和情绪不断裂" : shot.causalLink,
        startFrame: subshots[0]?.action || shot.startFrame,
        endFrame: subshots.at(-1)?.action || shot.endFrame
      });
      offset = segmentEnd;
    });
  }
  const orderedSourceDialogueLedger = sortSourceDialogueLedger([...ledgerById.values()]).map((item, index) => ({
    ...item,
    order: index + 1,
    sourceOrder: index + 1
  }));
  return { ...data, shots, sourceDialogueLedger: orderedSourceDialogueLedger };
}

function parseStructuredProductionScript(text) {
  const source = String(text || "").replace(/\r\n/g, "\n");
  const trimmed = source.trim();
  if (trimmed.startsWith("{") || trimmed.startsWith("[")) {
    try {
      const parsed = JSON.parse(trimmed);
      const candidate = Array.isArray(parsed) ? parsed[0] : parsed;
      if (candidate && typeof candidate === "object"
        && Array.isArray(candidate.characters)
        && Array.isArray(candidate.scenes)
        && Array.isArray(candidate.shots)
        && candidate.characters.length > 0
        && candidate.scenes.length > 0
        && candidate.shots.length > 0) return candidate;
    } catch {}
  }
  const characterBlocks = headingBlocks(source, /^###\s+(C\d{2,})\s+([^\n]+)$/gm);
  const sceneBlocks = headingBlocks(source, /^###\s+(SC\d{2,})\s+([^\n]+)$/gm);
  const shotBlocks = headingBlocks(source, /^###\s+(S\d{2,})｜([^\n]+)$/gm);
  if (characterBlocks.length < 1 || sceneBlocks.length < 1 || shotBlocks.length < 2) return null;

  const characters = characterBlocks.map(({ match, body }, index) => ({
    id: match[1],
    name: match[2].trim(),
    description: body.replace(/^\s*-\s*/gm, "").trim(),
    identitySignature: bulletValue(body, "资产指纹") || bulletValue(body, "身份指纹"),
    voiceDescription: bulletValue(body, "声线") || body.split("\n").find(line => /声线|声音/.test(line))?.replace(/^\s*-\s*/, "").trim() || "",
    signatureLine: bulletValue(body, "测试台词") || bulletValue(body, "标志台词"),
    importance: index < 2 ? "lead" : "supporting"
  }));
  const characterById = new Map(characters.map(item => [item.id, item.name]));
  const scenes = sceneBlocks.map(({ match, body }) => ({
    id: match[1],
    name: match[2].split(/[｜|]/)[0].trim(),
    description: body.replace(/^\s*-\s*/gm, "").trim(),
    time: match[2].split(/[｜|]/).at(-1)?.trim() || "",
    atmosphere: body.split("\n").find(line => /环境声|氛围/.test(line))?.replace(/^\s*-\s*/, "").trim() || ""
  }));
  const sceneById = new Map(scenes.map(item => [item.id, item.name]));

  const shots = shotBlocks.map(({ match, body }, index) => {
    const characterIds = (bulletValue(body, "人物").match(/C\d{2,}/g) || []);
    const sceneField = bulletValue(body, "场景");
    const sceneId = sceneField.match(/SC\d{2,}/)?.[0] || "";
    const action = bulletValue(body, "本单元叙事任务") || bulletValue(body, "动作");
    const dialogue = bulletValue(body, "对白");
    const startFrame = bulletValue(body, "首帧");
    const endFrame = bulletValue(body, "尾帧");
    const productNote = bulletValue(body, "商品");
    const productMention = Boolean(productNote) && !/(?:不直接出现|不出现|不直接操作|暂不展示)/.test(productNote);
    const subshots = [...body.matchAll(/^\s*-\s*subshot\s+(\d+)｜([\d.]+)[–-]([\d.]+)秒｜([^：:]+)[：:](.+)$/gmi)].map(subshot => {
      const tail = parseSubshotTail(subshot[5]);
      return { start: Number(subshot[2]), end: Number(subshot[3]), framing: subshot[4].trim(), camera: subshot[4].trim(), ...tail };
    });
    const duration = Math.max(10, Math.min(15, Number(match[2].match(/(\d+)秒/)?.[1]) || Math.ceil(Math.max(0, ...subshots.map(item => item.end))) || 12));
    const timeline = subshots.map(item => `${item.start}-${item.end}秒：${item.framing}，${item.action}`).join("；");
    return {
      id: match[1],
      title: action.split(/[，。；]/)[0] || `镜头 ${index + 1}`,
      duration,
      characters: characterIds.map(id => characterById.get(id)).filter(Boolean),
      characterIds,
      sceneId,
      scene: sceneById.get(sceneId) || sceneField.replace(/^SC\d{2,}\s*/, "").split(/[，,]/)[0].trim(),
      action,
      dialogue,
      productNote,
      shotSize: subshots[0]?.framing || "中景",
      cameraMove: subshots.map(item => item.camera).filter(Boolean).join(" → ") || "固定镜头",
      emotion: bulletValue(body, "情绪"),
      performance: subshots.map(item => item.action).join("；"),
      mainlineStage: bulletValue(body, "主线阶段"),
      mainlineBeat: bulletValue(body, "主线推进"),
      kindnessCost: bulletValue(body, "善意代价"),
      reversalSetup: bulletValue(body, "反转伏笔"),
      stateBefore: bulletValue(body, "状态变化").split("→")[0]?.trim() || startFrame,
      stateAfter: bulletValue(body, "状态变化").split("→")[1]?.trim() || endFrame,
      causalLink: bulletValue(body, "因果承接"),
      visualBeat: bulletValue(body, "独占画面拍点") || action,
      compositionPlan: bulletValue(body, "构图计划"),
      audioPlan: bulletValue(body, "全时段声音计划") || bulletValue(body, "声音"),
      soundDesign: bulletValue(body, "声音"),
      transitionIn: bulletValue(body, "进入"),
      transitionOut: bulletValue(body, "出口"),
      startFrame,
      endFrame,
      subshots,
      referencePlan: { images: ["人物", "场景", ...(productMention ? ["商品"] : []), "首尾帧"], video: "延续模式上一单元", audios: characterIds },
      productMention,
      imagePrompt: `只允许出现${characterIds.map(id => characterById.get(id)).filter(Boolean).join("、")}；首帧：${startFrame}；尾帧：${endFrame}；${action}`,
      videoPrompt: `${timeline}${dialogue ? `；对白：${dialogue}` : ""}`
    };
  });

  const referenceRepair = reconcileOrphanCharacterReferences({ characters, scenes, shots }, { allowCharacterCreation: false });
  const repairedCharacters = referenceRepair.project.characters;
  const characterByToken = new Map(repairedCharacters.flatMap(item => [
    [String(item?.id || "").trim(), item],
    [String(item?.name || "").trim(), item]
  ]).filter(([token]) => token));
  const knownSpeakerTokens = [...characterByToken.keys()];
  const sourceDialogueLedger = parseSourceDialogueLedger(source, knownSpeakerTokens).map(item => {
    const character = characterByToken.get(String(item?.speaker || "").trim())
      || characterByToken.get(String(item?.speakerRaw || "").trim());
    return {
      ...item,
      speaker: character?.name || item.speaker,
      speakerRaw: character?.name || item.speakerRaw,
      ...(character?.id ? { speakerId: character.id } : {})
    };
  });
  const shotsWithDialogueBindings = referenceRepair.project.shots.map(shot => {
    const shotDialogue = sourceDialogueLedger.filter(item => String(item?.sourceShotId || "").toUpperCase() === String(shot?.id || "").toUpperCase());
    const sourceDialogueBindings = shotDialogue.map(item => {
      const metadata = item?.metadata && typeof item.metadata === "object" ? item.metadata : {};
      const subshotIndex = (shot.subshots || []).findIndex(subshot => parseCompiledDialogueSegments(subshot?.dialogue || "", knownSpeakerTokens).some(turn => {
        const parsedCharacter = characterByToken.get(String(turn?.speaker || "").trim())
          || characterByToken.get(String(turn?.speakerRaw || "").trim());
        return String(turn?.text || turn?.spokenText || "").trim() === String(item?.text || "").trim()
          && (!parsedCharacter || parsedCharacter.id === item.speakerId);
      }));
      return {
        sourceDialogueId: item.id,
        subshotNumber: subshotIndex >= 0 ? subshotIndex + 1 : 1,
        onScreen: item?.onScreen !== false,
        intent: metadata.intent || metadata.beat || "",
        emotion: metadata.emotion || "",
        delivery: metadata.delivery || item.delivery || item.tone || "",
        volume: metadata.volume || "",
        pace: metadata.pace || "",
        stressWord: metadata.stressWord || "",
        breath: metadata.breath || "",
        body: metadata.body || "",
        listenerBeat: metadata.listenerBeat || ""
      };
    });
    return {
      ...shot,
      sourceDialogueIds: sourceDialogueBindings.map(item => item.sourceDialogueId),
      sourceDialogueBindings
    };
  });
  const structured = {
    story: { premise: "从结构化制作剧本本地解析", hook: shots[0]?.action || "", ending: shots.at(-1)?.action || "" },
    characters: repairedCharacters,
    scenes,
    shots: shotsWithDialogueBindings,
    sourceDialogueLedger
  };
  return sourceDialogueLedger.length
    ? bindSourceDialogueLedgerToAnalysis(structured, sourceDialogueLedger)
    : structured;
}

function splitUploadedScriptSections(text = "") {
  const source = String(text || "").replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").trim();
  const lines = source.split("\n");
  const bodyHeader = lines.findIndex(line => /^(?:\s*#{1,4}\s*)?(?:正式剧情|剧情正文|剧本正文|正文|正片)\s*[:：]?\s*$/i.test(line.trim()));
  const firstDramaticLine = bodyHeader >= 0
    ? lines.findIndex((line, index) => index > bodyHeader && line.trim())
    : lines.findIndex(line => /^(?:\s*#{1,4}\s*)?(?:S\d{1,3}\b|SC\d{1,3}\b|第[一二三四五六七八九十百千零〇\d]+(?:场|幕|镜)|【\s*场景\s*】|场景\s*[:：]|地点\s*[:：]|内景\s*[:：]|外景\s*[:：]|INT\.|EXT\.|INT\/EXT\.|I\/E\.|\d{1,4}[.、)]\s*(?:场景|内景|外景|INT\.|EXT\.))/i.test(line.trim()));
  if (firstDramaticLine <= 0) return { metadata: "", dramaticBody: source };
  const metadata = lines.slice(0, firstDramaticLine).join("\n").trim();
  const dramaticBody = lines.slice(firstDramaticLine).join("\n").trim();
  return dramaticBody ? { metadata, dramaticBody } : { metadata: "", dramaticBody: source };
}

function sourceDialogueLedgerMatches(actual = [], expected = []) {
  const left = sortSourceDialogueLedger(actual);
  const right = sortSourceDialogueLedger(expected);
  if (left.length !== right.length) return false;
  return right.every((item, index) => {
    const candidate = left[index] || {};
    return String(candidate.id || "") === String(item.id || "")
      && String(candidate.speaker || "").trim() === String(item.speaker || "").trim()
      && String(candidate.text || "").trim() === String(item.text || "").trim()
      && String(candidate.tone || "").trim() === String(item.tone || "").trim();
  });
}

/**
 * Build the immutable dialogue ledger from the complete upload while keeping
 * only utterances that physically belong to the dramatic body. Character
 * names often live in a preface/character bible; parsing only the stripped
 * body therefore loses narrative quotes such as “林娜质问：‘……’”. Full-text
 * parsing supplies those names and richer delivery notes, while the rebased
 * offsets keep chunk assignment relative to the production body.
 */
function maskCanonicalActionQuotes(source){
  if(!/^###\s*S\d+｜场景：/m.test(source))return source;
  let action=false;return source.split('\n').map(line=>{if(/^###/.test(line))action=false;else if(/^【/.test(line))action=!/^【(?:对白|台词|人物|核心物品)】/.test(line);return action?line.replace(/[^\r]/g,' '):line;}).join('\n');
}
function productionDialogueLedgerFromScript(text = "", providedSections = null, providedSceneLedger = null) {
  const source = String(text || "").replace(/^\uFEFF/, "").replace(/\r\n?/g, "\n").trim();
  if (!source) return [];
  if (source.startsWith("{") || source.startsWith("[")) {
    try {
      const parsed = JSON.parse(source);
      const candidate = Array.isArray(parsed) ? parsed[0] : parsed;
      if (candidate && typeof candidate === "object") {
        const characters = Array.isArray(candidate.characters) ? candidate.characters : [];
        const characterName = new Map(characters.flatMap(item => [
          [String(item?.id || "").trim(), String(item?.name || "").trim()],
          [String(item?.name || "").trim(), String(item?.name || "").trim()]
        ]).filter(([key, name]) => key && name));
        const explicit = Array.isArray(candidate.sourceDialogueLedger) ? candidate.sourceDialogueLedger : [];
        const turns = explicit.length ? explicit : (Array.isArray(candidate.shots) ? candidate.shots.flatMap(shot => [
          ...(Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : []),
          ...(Array.isArray(shot?.subshots) ? shot.subshots.flatMap(subshot => Array.isArray(subshot?.dialogueTurns) ? subshot.dialogueTurns : []) : [])
        ]) : []);
        const seen = new Set();
        return sortSourceDialogueLedger(turns).map((turn, index) => {
          const speakerToken = String(turn?.speaker || turn?.speakerId || "").trim();
          const text = String(turn?.text || turn?.spokenText || turn?.dialogue || "").trim();
          const tone = String(turn?.tone || turn?.sourceTone || turn?.delivery || "").trim()
            || inferDialogueTone({
              text,
              action: turn?.action || turn?.scene || candidate?.story?.premise,
              previousText: turns[index - 1]?.text || turns[index - 1]?.spokenText,
              nextText: turns[index + 1]?.text || turns[index + 1]?.spokenText
            });
          return {
            ...turn,
            speaker: characterName.get(speakerToken) || speakerToken,
            speakerRaw: characterName.get(speakerToken) || speakerToken,
            tone,
            text,
            spokenText: text,
            sourceStart: Number(turn?.sourceStart) || index,
            sourceEnd: Number(turn?.sourceEnd) || index + 1
          };
        }).filter(item => {
          const key = `${item.speaker}\u0000${item.text}\u0000${item.sourceDialogueId || item.id || ""}`;
          if (!item.speaker || !item.text || seen.has(key)) return false;
          seen.add(key);
          return true;
        }).map((item, index) => ({ ...item, id: `D${String(index + 1).padStart(3, "0")}`, order: index + 1, sourceOrder: index + 1 }));
      }
    } catch {}
  }
  const sections = providedSections || splitUploadedScriptSections(source);
  const body = String(sections?.dramaticBody || source).trim();
  const bodyStart = body === source ? 0 : source.indexOf(body);
  const sourceSceneLedger = providedSceneLedger || buildSourceSceneLedger(source);
  const fullLedger = bindDialogueLedgerToScenes(parseSourceDialogueLedger(maskCanonicalActionQuotes(source)), sourceSceneLedger);
  const fullBodyLedger = bodyStart >= 0
    ? fullLedger.filter(item => Number(item?.sourceStart) >= bodyStart && Number(item?.sourceEnd) <= bodyStart + body.length + 1)
      .map(item => ({
        ...item,
        sourceStart: Math.max(0, Number(item.sourceStart) - bodyStart),
        sourceEnd: Math.max(0, Number(item.sourceEnd) - bodyStart)
      }))
    : [];
  const knownNames = [...new Set(fullLedger.map(item => String(item?.speaker || "").trim()).filter(Boolean))];
  const parsedBodyLedger = parseSourceDialogueLedger(maskCanonicalActionQuotes(body), knownNames);
  const reboundBodyLedger = bindDialogueLedgerToScenes(parsedBodyLedger.map(item => ({
    ...item,
    sourceStart: Number(item.sourceStart) + Math.max(0, bodyStart),
    sourceEnd: Number(item.sourceEnd) + Math.max(0, bodyStart)
  })), sourceSceneLedger).map(item => ({
    ...item,
    sourceStart: Math.max(0, Number(item.sourceStart) - Math.max(0, bodyStart)),
    sourceEnd: Math.max(0, Number(item.sourceEnd) - Math.max(0, bodyStart))
  }));
  const merged = [];
  const seen = new Set();
  for (const item of sortSourceDialogueLedger([...fullBodyLedger, ...reboundBodyLedger])) {
    const key = `${String(item.speaker || "").trim()}\u0000${String(item.text || "").trim()}\u0000${Number(item.sourceStart) || 0}`;
    if (!item?.speaker || !item?.text || seen.has(key)) continue;
    seen.add(key);
    merged.push({ ...item });
  }
  return merged.map((item, index) => ({
    ...item,
    id: `D${String(index + 1).padStart(3, "0")}`,
    order: index + 1,
    sourceOrder: index + 1
  }));
}

function normalizeUploadedNarrativeEvidence(value = "") {
  return String(value || "")
    .normalize("NFKC")
    .replace(/(?:\*\*|__|`)/g, "")
    .replace(/[\s\p{P}\p{S}]+/gu, "")
    .toLowerCase();
}

function uploadedNarrativeEvidenceChecklist(sourceText = "", sourceDialogueLedger = []) {
  const body = splitUploadedScriptSections(sourceText).dramaticBody || String(sourceText || "");
  const dialogueTexts = sortSourceDialogueLedger(sourceDialogueLedger)
    .map(item => String(item?.text || item?.spokenText || "").trim())
    .filter(Boolean);
  const seen = new Set();
  const events = [];
  for (const sourceLine of String(body || "").replace(/\r\n?/g, "\n").split("\n")) {
    let line = String(sourceLine || "").trim();
    if (!line || /^(?:#{1,6}\s*)?(?:S\d{1,4}\b|SC\d{1,4}\b|第[一二三四五六七八九十百千零〇\d]+(?:场|幕)|场景|地点|内景|外景)\s*(?:[｜|：:]|$)/iu.test(line)) continue;
    if (/^#{1,6}\s+/u.test(line)) continue;
    // Exact dialogue is protected by the immutable dialogue ledger. Do not
    // mistake its cue, tone or surrounding quote marks for a separate event.
    if (dialogueTexts.some(text => line.includes(text))) continue;
    line = line.replace(/^(?:[-*•]\s+)/u, "").replace(/(?:\*\*|__)/g, "").trim();
    const field = line.match(/^(?:【\s*)?([^】：:\n]{1,32})(?:\s*】)?\s*[：:]/u)?.[1]?.trim() || "";
    if (field && isProductionFieldLabel(field)
      && !/^(?:动作|画面|声音|音效|承接|转场|结尾画面|产品画面要求)$/u.test(field)) continue;
    const normalized = normalizeUploadedNarrativeEvidence(line);
    if (normalized.length < 6 || seen.has(normalized)) continue;
    seen.add(normalized);
    events.push({ id: `E${String(events.length + 1).padStart(3, "0")}`, text: line, normalized });
  }
  return events;
}

function uploadedFormatAdaptationValidation(candidateText = "", sourceDialogueLedger = [], sourceSceneLedger = {}, sourceText = "") {
  const productionScript = String(candidateText || "").trim();
  const standardStructure = /^(?:#{1,6}\s*)?S\d{1,4}\s*[｜|]\s*场景\s*[：:]/mi.test(productionScript)
    && /【\s*(?:动作|对白|台词|旁白|声音|承接)\s*】/u.test(productionScript);
  const candidateSceneLedger = buildSourceSceneLedger(productionScript, { acceptStandardShotHeading: true });
  const candidateDialogueLedger = productionDialogueLedgerFromScript(
    productionScript,
    splitUploadedScriptSections(productionScript),
    candidateSceneLedger
  );
  const expectedDialogue = sortSourceDialogueLedger(sourceDialogueLedger);
  const actualDialogue = sortSourceDialogueLedger(candidateDialogueLedger);
  const dialogueParity = expectedDialogue.length === actualDialogue.length
    && expectedDialogue.every((item, index) => {
      const candidate = actualDialogue[index] || {};
      return String(candidate.speaker || "").trim() === String(item.speaker || "").trim()
        && String(candidate.text || "").trim() === String(item.text || "").trim();
    });
  const sourceScenes = Array.isArray(sourceSceneLedger?.catalogue) ? sourceSceneLedger.catalogue : [];
  const candidateScenes = Array.isArray(candidateSceneLedger?.catalogue) ? candidateSceneLedger.catalogue : [];
  const sourceSceneKeys = sourceScenes.map(item => String(item.semanticKey || item.name || "").trim()).filter(Boolean);
  const candidateSceneKeys = candidateScenes.map(item => String(item.semanticKey || item.name || "").trim()).filter(Boolean);
  const sceneCatalogueParity = !sourceSceneLedger?.explicit || (
    sourceSceneKeys.length === candidateSceneKeys.length
    && sourceSceneKeys.every(key => candidateSceneKeys.includes(key))
    && candidateSceneKeys.every(key => sourceSceneKeys.includes(key))
  );
  const occurrenceKeys = ledger => {
    const byId = new Map((ledger?.catalogue || []).map(item => [item.id, String(item.semanticKey || item.name || "").trim()]));
    return (ledger?.occurrences || []).map(item => byId.get(item.sceneId) || String(item.sceneName || "").trim()).filter(Boolean);
  };
  const sourceOccurrences = occurrenceKeys(sourceSceneLedger);
  const candidateOccurrences = occurrenceKeys(candidateSceneLedger);
  const eventOrderParity = !sourceSceneLedger?.explicit || (
    sourceOccurrences.length === candidateOccurrences.length
    && sourceOccurrences.every((key, index) => candidateOccurrences[index] === key)
  );
  const sceneParity = sceneCatalogueParity && eventOrderParity;
  const narrativeChecklist = uploadedNarrativeEvidenceChecklist(sourceText, sourceDialogueLedger);
  const candidateNarrativeText = normalizeUploadedNarrativeEvidence(productionScript);
  const missingNarrative = narrativeChecklist.filter(item => !candidateNarrativeText.includes(item.normalized));
  const narrativeParity = missingNarrative.length === 0;
  return {
    ok: Boolean(productionScript) && standardStructure && dialogueParity && sceneParity && narrativeParity,
    standardStructure,
    dialogueParity,
    sceneParity,
    narrativeParity,
    sceneCatalogueParity,
    eventOrderParity,
    expectedDialogueCount: expectedDialogue.length,
    actualDialogueCount: actualDialogue.length,
    expectedSceneCount: sourceSceneKeys.length,
    actualSceneCount: candidateSceneKeys.length,
    expectedSceneOccurrenceCount: sourceOccurrences.length,
    actualSceneOccurrenceCount: candidateOccurrences.length,
    expectedNarrativeCount: narrativeChecklist.length,
    actualNarrativeCount: narrativeChecklist.length - missingNarrative.length,
    missingDialogue: expectedDialogue.filter((item, index) => {
      const candidate = actualDialogue[index] || {};
      return String(candidate.speaker || "").trim() !== String(item.speaker || "").trim()
        || String(candidate.text || "").trim() !== String(item.text || "").trim();
    }).map(item => ({ id: item.id, speaker: item.speaker, tone: item.tone, text: item.text })),
    missingScenes: sourceScenes.filter(item => !candidateSceneKeys.includes(String(item.semanticKey || item.name || "").trim())).map(item => item.name),
    missingNarrative: missingNarrative.map(item => ({ id: item.id, text: item.text })),
    candidateSceneLedger,
    candidateDialogueLedger
  };
}

// Free-form uploads are first understood and standardized by the selected AI.
// This validator deliberately reads only that standard result and the AI's
// source-coverage declaration; it never tries to interpret arbitrary source
// prose as a scene/dialogue ledger before the AI pass.
function aiFirstUploadStandardizationValidation(result = {}) {
  const directDelivery = require('./agent-production-document').validation(result);
  if (directDelivery) return directDelivery;
  const productionScript = String(result?.productionScript || "").trim();
  const sourceAudit = result?.sourceAudit && typeof result.sourceAudit === "object" ? result.sourceAudit : {};
  const standardStructure = /^(?:#{1,6}\s*)?S\d{1,4}\s*[｜|]\s*场景\s*[：:]/mi.test(productionScript)
    && /【\s*(?:动作|对白|台词|旁白|声音|承接)\s*】/u.test(productionScript);
  const candidateSceneLedger = buildSourceSceneLedger(productionScript, { acceptStandardShotHeading: true });
  const candidateDialogueLedger = productionDialogueLedgerFromScript(
    productionScript,
    splitUploadedScriptSections(productionScript),
    candidateSceneLedger
  );
  const actualSceneOccurrenceCount = Array.isArray(candidateSceneLedger?.occurrences)
    ? candidateSceneLedger.occurrences.length
    : 0;
  const actualDialogueCount = candidateDialogueLedger.length;
  const expectedSceneOccurrenceCount = Number(sourceAudit.sceneOccurrenceCount);
  const expectedDialogueCount = Number(sourceAudit.dialogueCount);
  const declaredSceneNames = Array.isArray(sourceAudit.sceneOccurrences)
    ? sourceAudit.sceneOccurrences.map(item => String(item?.physicalSceneName || item?.scene || item || "").trim()).filter(Boolean)
    : [];
  const parsedSceneNames = (candidateSceneLedger?.occurrences || [])
    .map(item => String(item?.sceneName || item?.rawName || "").trim())
    .filter(Boolean);
  const sceneCountParity = Number.isFinite(expectedSceneOccurrenceCount)
    && expectedSceneOccurrenceCount > 0
    && expectedSceneOccurrenceCount === actualSceneOccurrenceCount;
  const dialogueCountParity = Number.isFinite(expectedDialogueCount)
    && expectedDialogueCount >= 0
    && expectedDialogueCount === actualDialogueCount;
  const declaredSceneParity = !declaredSceneNames.length || (
    declaredSceneNames.length === parsedSceneNames.length
    && declaredSceneNames.every((name, index) => normalizeUploadedNarrativeEvidence(require('./script-scene-ledger').normalizeSceneName(name)) === normalizeUploadedNarrativeEvidence(require('./script-scene-ledger').normalizeSceneName(parsedSceneNames[index])))
  );
  const sourceCoverageDeclared = sourceAudit.preservedAllDialogue === true
    && sourceAudit.preservedAllScenes === true
    && sourceAudit.preservedAllActions === true
    && sourceAudit.preservedEventOrder === true
    && sourceAudit.noInventedDialogue === true;
  const dialogueStructurePresent = actualDialogueCount > 0 || (result.sourceMode === 'silent' && actualDialogueCount === 0);
  // Counts written by the model are self-audit metadata.  A complete standard
  // script with real scenes/dialogue and an explicit lossless-coverage promise
  // is usable even when the model miscounts one row. Repeating the entire paid
  // request to repair only that arithmetic caused four calls with identical
  // usable content and never improved downstream production.
  const usable = Boolean(productionScript)
    && standardStructure
    && actualSceneOccurrenceCount > 0
    && dialogueStructurePresent
    && declaredSceneParity
    && sourceCoverageDeclared;
  return {
    ok: Boolean(productionScript)
      && standardStructure
      && actualSceneOccurrenceCount > 0
      && sceneCountParity
      && dialogueCountParity
      && declaredSceneParity
      && sourceCoverageDeclared,
    usable,
    productionScript,
    sourceAudit,
    standardStructure,
    sourceCoverageDeclared,
    sceneParity: sceneCountParity && declaredSceneParity,
    dialogueParity: dialogueCountParity,
    narrativeParity: sourceAudit.preservedAllActions === true && sourceAudit.preservedEventOrder === true,
    sceneCatalogueParity: declaredSceneParity,
    eventOrderParity: declaredSceneParity && sourceAudit.preservedEventOrder === true,
    expectedDialogueCount,
    actualDialogueCount,
    expectedSceneOccurrenceCount,
    actualSceneOccurrenceCount,
    candidateSceneLedger,
    candidateDialogueLedger
  };
}

// Uploaded scripts are compiled into a stable production envelope before any
// asset or shot extraction. The raw upload remains untouched; this envelope
// gives every later stage one scene/dialogue ledger to reference.
function buildUploadedScriptNormalization(raw = "", sections = {}, sceneLedger = {}, dialogueLedger = [], sourceFingerprint = "") {
  const body = String(sections?.dramaticBody || raw || "").trim();
  const metadata = String(sections?.metadata || "").trim();
  const scenes = Array.isArray(sceneLedger?.catalogue) ? sceneLedger.catalogue : [];
  const orderedDialogueLedger = sortSourceDialogueLedger(dialogueLedger);
  const lines = [
    "# 纯梦短剧老虎机｜上传剧本标准制作稿",
    "",
    "## 使用合同",
    "- 本稿由用户原稿编译而来；原始上传文本保存在 script.raw，不覆盖、不删减。",
    "- 只有‘正式剧情’进入成片；人物小传、背景说明和创作备注只用于建立资产与连续性。",
    "- 对白逐字来自不可变对白台账；说话人、语气、事件顺序、数字和结局不得改写。",
    "- 资产只从唯一人物、唯一物理场景、核心道具和明确换装证据建立，不把环境陈设升级为资产。",
    "",
    "## 唯一物理场景台账",
    ...(scenes.length
      ? scenes.map(item => `- ${item.id || "SC"}: ${item.name}${item.aliases?.length ? `（别名：${item.aliases.join("、")}）` : ""}`)
      : ["- 原稿未提供可靠场景标题，按正式剧情中的实际物理地点归并"]),
    "",
    "## 逐字对白台账",
    ...(orderedDialogueLedger.length
      ? orderedDialogueLedger.map(item => `- ${item.id || "D"}｜${item.sourceSceneName || item.sceneName || "未标场景"}｜${item.speaker || item.speakerRaw || "未识别说话人"}｜${item.tone || "按原稿语气"}｜${item.text || item.spokenText || ""}`)
      : ["- 原稿未识别到可拆对白；保留原文供后续本地编译器继续解析"]),
    "",
    "## 原稿背景与制作说明（仅供结构化解析）",
    metadata || "（无独立背景说明）",
    "",
    "## 正式剧情（唯一成片来源，原文保留）",
    body
  ];
  return {
    version: 3,
    sourceFingerprint: String(sourceFingerprint || ""),
    normalizedAt: new Date().toISOString(),
    normalizedScript: lines.join("\n"),
    assetManifest: { characters: [], scenes: scenes.map(item => ({ id: item.id || "", name: item.name || "", aliases: item.aliases || [] })), coreProps: [], wardrobeChanges: [] },
    validation: { dialogueParity: true, eventOrderPreserved: true, noInventedAssets: true },
    rules: ["dialogue_exact", "scene_physical_space_dedup", "core_props_only", "wardrobe_changes_only"]
  };
}

function propEvidenceText(name, source = "", shots = []) {
  const escaped = String(name || "").replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  const pattern = new RegExp(`.{0,100}${escaped}.{0,160}`, "giu");
  const sourceHits = [...String(source || "").matchAll(pattern)].map(item => item[0]);
  const shotHits = (Array.isArray(shots) ? shots : []).filter(shot => {
    const text = [shot?.action, shot?.visualBeat, shot?.causalLink, shot?.stateBefore, shot?.stateAfter, shot?.dialogue, ...(shot?.subshots || []).map(item => item?.action)].join(" ");
    return text.includes(name);
  }).map(shot => [shot?.action, shot?.visualBeat, shot?.causalLink, shot?.dialogue].filter(Boolean).join(" "));
  return [...sourceHits, ...shotHits].join(" ");
}

function isCoreStoryPropCandidate(name, source = "", shots = [], productName = "") {
  const value = String(name || "").trim();
  if (!value || value === "无" || isSameProductName(value, productName)) return false;
  const incidental = /^(手机|电话|椅子|凳子|桌子|沙发|门|窗|水龙头|抹布|毛巾|塑料盆|粉色塑料盆|化妆镜|口红|钢笔|纸巾|杯子|茶杯|碗|盘子|餐具|碎瓷片|碎纸片|普通文件|文件|包装盒|大号包装盒|蓝色包装盒|购物袋|钥匙|衣架|垃圾桶|龙虾|吃剩的龙虾|清洁棒)$/i.test(value)
    || /包装盒|包装|礼盒|清洁棒|清洁用品|家居用品/.test(value);
  const evidence = propEvidenceText(value, source, shots);
  const causal = /证据|证明|账本|账单|收据|发票|凭证|合同|协议|录音|监控|病历|遗嘱|钥匙|身份|dna|转账|付款|赔偿|欠款|唯一|关键|真相|发现|揭露|核对|签字|签订|撕毁|销毁|藏起|抢走|偷走|归还|交给|递给|拿出|拿起|打开|锁定|决定|改变|换回|救命|药物|处方|取证|证物|房产证|缴费单|暖手宝/i.test(evidence);
  const appearances = (Array.isArray(shots) ? shots : []).filter(shot => {
    const text = [shot?.action, shot?.visualBeat, shot?.causalLink, shot?.stateBefore, shot?.stateAfter, shot?.dialogue, ...(shot?.subshots || []).map(item => item?.action)].join(" ");
    return text.includes(value) || (shot?.propNames || []).some(item => String(item).trim() === value);
  }).length;
  // Generic set dressing never becomes a reusable asset merely because a
  // nearby sentence contains a causal verb. A genuinely story-bearing variant
  // must be named specifically (for example “手机录音证据”, not “手机”).
  if (incidental) return false;
  return causal || appearances >= 2;
}

function corePropUnitIds(name, shots = []) {
  const matched = (Array.isArray(shots) ? shots : []).filter(shot => {
    const text = [shot?.action, shot?.visualBeat, shot?.causalLink, shot?.dialogue, ...(shot?.subshots || []).map(item => item?.action)].join(" ");
    return text.includes(name) || (shot?.propNames || []).some(item => String(item || "").trim() === String(name || "").trim());
  }).map(shot => String(shot.id || `S${shot.number}`));
  // No semantic hit means “unresolved”, not “visible in every shot”. Marking a
  // prop as global silently injects it into unrelated references and creates
  // exactly the excessive-asset/continuity pollution this ledger is meant to
  // prevent.
  return matched;
}

function normalizeCoreStoryProps(data = {}, source = "", productName = "") {
  const sourceProps = Array.isArray(data?.props) ? data.props : [];
  const shots = Array.isArray(data?.shots) ? data.shots : [];
  const props = sourceProps.filter(prop => isCoreStoryPropCandidate(prop?.name, source, shots, productName)).map(prop => ({
    ...prop,
    coreStory: true,
    causalRole: String(prop.causalRole || prop.purpose || "由原稿中的事件、证据或关系变化驱动").trim(),
    purpose: String(prop.purpose || prop.causalRole || "跨镜保持剧情所需的独立视觉身份").trim(),
    units: [...new Set((Array.isArray(prop.units) ? prop.units : []).map(String).filter(Boolean))]
  }));
  const allowed = new Set(props.flatMap(item => [item.id, item.name, ...normalizeStringArray(item.aliases)]).map(item => String(item || "").trim()).filter(Boolean));
  const normalizedShots = shots.map(shot => ({
    ...shot,
    propNames: (Array.isArray(shot?.propNames) ? shot.propNames : []).filter(name => allowed.has(String(name || "").trim())),
    propBindings: (Array.isArray(shot?.propBindings) ? shot.propBindings : []).filter(binding => allowed.has(String(binding?.propId || binding?.name || "").trim()))
  }));
  return { ...data, props, shots: normalizedShots };
}

function inferWardrobeChangesFromSource(data = {}, source = "") {
  const text = String(source || "");
  const characters = Array.isArray(data.characters) ? data.characters : [];
  const shots = Array.isArray(data.shots) ? data.shots : [];
  if (!characters.length || !shots.length) return data;
  const changeRe = /(?:换上|换成|更换|穿上|套上|换装成)\s*([^，。；;｜|）)：:\n]{2,16})/g;
  const hits = [];
  for (const match of text.matchAll(changeRe)) {
    const garment = String(match[1] || "").split(/(?:站在|坐在|走到|走向|转身|从柜|从桌|拿起|取出|推门|出门)/)[0].replace(/[的了着过]$/, "").trim();
    if (!garment || /衣服|服装$/.test(garment) && garment.length <= 2) continue;
    if (/^(?:右膝|左膝|膝盖|护膝|双手|右手|左手|头部|腰部|肩膀)$/.test(garment)) continue;
    if (/护膝|护腰|护踝|半月板/.test(garment)) continue;
    const windowStart = Math.max(0, match.index - 16);
    const nearby = text.slice(windowStart, match.index + match[0].length);
    const character = characters.find(item => nearby.includes(item.name));
    if (!character) continue;
    hits.push({ character, garment, index: match.index });
  }
  if (!hits.length) return data;
  const outfitsByCharacter = new Map();
  const nextShots = shots.map(shot => ({ ...shot, wardrobeBindings: normalizeWardrobeBindings(shot.wardrobeBindings) }));
  for (const hit of hits) {
    const wardrobeId = `wardrobe_${hit.character.id}_${slug(hit.garment)}`;
    const list = outfitsByCharacter.get(hit.character.id) || [];
    if (!list.some(item => item.id === wardrobeId)) {
      list.push({
        id: wardrobeId,
        label: hit.garment,
        description: `${hit.character.name}换上的${hit.garment}`,
        changeRequired: true
      });
      outfitsByCharacter.set(hit.character.id, list);
    }
    const shot = nextShots.find(item => {
      const blob = [item.action, item.visualBeat, item.dialogue, ...(item.subshots || []).map(sub => sub.action || "")].join(" ");
      return blob.includes(hit.garment) || blob.includes("换上") || blob.includes("穿上");
    }) || nextShots[Math.min(nextShots.length - 1, Math.floor(hit.index / Math.max(1, text.length / nextShots.length)))];
    if (!shot.wardrobeBindings.some(item => item.characterId === hit.character.id && item.wardrobeId === wardrobeId)) {
      shot.wardrobeBindings.push({
        characterId: hit.character.id,
        wardrobeId,
        continuity: `源文换装：${hit.garment}`
      });
    }
    shot.wardrobeId = shot.wardrobeId || wardrobeId;
    shot.wardrobeLabel = shot.wardrobeLabel || hit.garment;
  }
  return {
    ...data,
    characters: characters.map(character => ({
      ...character,
      outfits: [
        ...(Array.isArray(character.outfits) ? character.outfits : []),
        ...(outfitsByCharacter.get(character.id) || [])
      ]
    })),
    shots: nextShots
  };
}

function extractCorePropsFromUploadedScript(source = "", analysis = {}, productName = "") {
  const named = [
    ...explicitTaggedAssetNames(source, ["物品", "道具", "核心道具", "关键道具"]),
    ...((analysis.props || []).map(item => item?.name).filter(Boolean))
  ];
  const unique = [...new Set(named.map(name => String(name || "").trim()).filter(Boolean))];
  return unique
    .filter(name => isCoreStoryPropCandidate(name, source, analysis.shots || [], productName))
    .map((name, index) => ({
      id: `P${String(index + 1).padStart(2, "0")}`,
      name,
      coreStory: true,
      causalRole: `${name}参与证据、决定或结局回收`,
      purpose: `${name}推动主线`,
      units: corePropUnitIds(name, analysis.shots || [])
    }));
}

function sanitizeWardrobeChanges(data = {}, source = "") {
  const inferred = inferWardrobeChangesFromSource(data, source);
  const text = String(source || "");
  const hasEvidence = /换上|换下|换成|更换|脱下|穿上|套上|换装|换衣|第二天|次日|翌日|几年后|数月后|婚礼服|病号服|工作服|校服/.test(text);
  if (hasEvidence) return inferred;
  return {
    ...inferred,
    characters: (inferred.characters || []).map(character => ({ ...character, outfits: [] })),
    shots: (inferred.shots || []).map(shot => ({ ...shot, wardrobeId: "", wardrobeLabel: "", wardrobeBindings: [] }))
  };
}

function spokenTextKey(value = "") {
  return String(value || "").toLowerCase().replace(/[^\p{L}\p{N}]+/gu, "");
}

function dialogueTextAffinity(left = "", right = "") {
  const a = spokenTextKey(left);
  const b = spokenTextKey(right);
  if (!a || !b) return 0;
  if (a === b) return 10_000 + a.length;
  if (a.includes(b) || b.includes(a)) return 2_000 + Math.min(a.length, b.length);
  const bigrams = value => {
    const result = new Set();
    if (value.length === 1) result.add(value);
    for (let index = 0; index < value.length - 1; index += 1) result.add(value.slice(index, index + 2));
    return result;
  };
  const aBigrams = bigrams(a);
  const bBigrams = bigrams(b);
  const overlap = [...aBigrams].filter(item => bBigrams.has(item)).length;
  return overlap * 20 / Math.max(1, Math.max(aBigrams.size, bBigrams.size));
}

/**
 * Older analyzed projects can contain model-invented D001/D002 identifiers
 * even though the immutable ledger was never persisted. Never trust those
 * identifiers during repair. Re-seed bindings from the actual spoken text,
 * speaker and shot order, then let bindSourceDialogueLedgerToAnalysis replace
 * every spoken line with the exact user-authored ledger entry.
 */
function seedExistingAnalysisDialogueBindings(data = {}, ledger = []) {
  const source = data && typeof data === "object" ? { ...data } : {};
  const characters = Array.isArray(source.characters) ? source.characters : [];
  const characterByName = new Map(characters.map(item => [String(item?.name || "").trim(), String(item?.id || "").trim()]));
  const shots = (Array.isArray(source.shots) ? source.shots : []).map(shot => ({
    ...shot,
    sourceDialogueBindings: [],
    sourceDialogueIds: [],
    subshots: (Array.isArray(shot?.subshots) ? shot.subshots : []).map(subshot => ({
      ...subshot,
      sourceDialogueIds: []
    }))
  }));
  const shotTurns = shots.map(shot => {
    const turns = [
      ...(Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns : []),
      ...(Array.isArray(shot?.subshots) ? shot.subshots.flatMap(subshot => Array.isArray(subshot?.dialogueTurns) ? subshot.dialogueTurns : []) : [])
    ];
    const unique = [];
    const seen = new Set();
    for (const turn of turns) {
      const key = `${String(turn?.speakerId || turn?.speaker || "")}\u0000${String(turn?.text || turn?.spokenText || "")}\u0000${Number(turn?.subshotNumber) || 1}`;
      if (seen.has(key)) continue;
      seen.add(key);
      unique.push(turn);
    }
    return unique;
  });
  for (const [ledgerIndex, item] of (Array.isArray(ledger) ? ledger : []).entries()) {
    const speakerId = characterByName.get(String(item?.speaker || "").trim()) || "";
    const expectedShotIndex = Math.min(shots.length - 1, Math.floor(ledgerIndex * Math.max(1, shots.length) / Math.max(1, ledger.length)));
    let best = { shotIndex: Math.max(0, expectedShotIndex), score: -Infinity, turn: null };
    shots.forEach((shot, shotIndex) => {
      const matchingSpeakerTurns = shotTurns[shotIndex].filter(turn => !speakerId || String(turn?.speakerId || turn?.speaker || "").trim() === speakerId || String(turn?.speaker || "").trim() === String(item?.speaker || "").trim());
      const joined = matchingSpeakerTurns.map(turn => String(turn?.text || turn?.spokenText || "")).join("");
      const closestTurn = matchingSpeakerTurns.map(turn => ({ turn, score: dialogueTextAffinity(item?.text, turn?.text || turn?.spokenText) }))
        .sort((left, right) => right.score - left.score)[0] || null;
      const speakerBonus = matchingSpeakerTurns.length ? 80 : 0;
      const orderPenalty = Math.abs(shotIndex - expectedShotIndex) * 5;
      const score = Math.max(dialogueTextAffinity(item?.text, joined), closestTurn?.score || 0) + speakerBonus - orderPenalty;
      if (score > best.score) best = { shotIndex, score, turn: closestTurn?.turn || matchingSpeakerTurns[0] || null };
    });
    const target = shots[best.shotIndex];
    if (!target) continue;
    const turn = best.turn || {};
    target.sourceDialogueBindings.push({
      sourceDialogueId: item.id,
      listenerIds: normalizeStringArray(turn.listenerIds || turn.listeners),
      subshotNumber: Math.max(1, Number(turn.subshotNumber) || 1),
      onScreen: turn.onScreen !== false,
      intent: String(turn.intent || turn.beat || "").trim(),
      emotion: String(turn.emotionPeak || turn.emotionStart || "").trim(),
      delivery: String(turn.delivery || "").trim(),
      volume: String(turn.volume || "").trim(),
      pace: String(turn.pace || "").trim(),
      stressWord: String(turn.stressWord || "").trim(),
      breath: String(turn.breath || "").trim(),
      body: String(turn.body || "").trim(),
      listenerBeat: String(turn.listenerBeat || "").trim()
    });
  }
  return { ...source, shots };
}

function inferredSceneProfile(name = "") {
  const label = String(name || "").trim();
  const outside = /街|巷|路|广场|天桥|楼下|门外|站点|路口|小区|公园|桥/.test(label);
  const night = /夜|深夜|凌晨|晚/.test(label);
  if (/车内|车厢|驾驶室/.test(label)) {
    return {
      interiorExterior: "内景",
      time: night ? "夜间" : "按剧本时段",
      description: `${label}无人空间锚点：固定前后排座椅、车门、车窗、中控台与后视镜相对位置，统一车外光向和拍摄轴线。`,
      cameraAnchors: ["前排侧向机位", "后排过肩机位", "中控台反打位"],
      layout: "前排、中控台、后排和左右车门位置固定",
      entrances: [{ name: "左右车门", position: "车厢两侧" }],
      anchorObjects: [{ name: "中控台", position: "前排中央" }, { name: "后视镜", position: "前挡风玻璃上方" }]
    };
  }
  if (/前台|大厅|大堂|门厅/.test(label)) {
    return {
      interiorExterior: "内景",
      time: night ? "夜间" : "按剧本时段",
      description: `${label}无人空间锚点：固定接待台、入口玻璃门、闸机或等候区、电梯方向和走道宽度，保持门向、家具位置与拍摄轴线一致。`,
      cameraAnchors: ["入口看向前台", "前台反打入口", "走道侧向机位"],
      layout: "入口、接待台、等候区和内部通道形成稳定纵深",
      entrances: [{ name: "主入口", position: "前台正对方向" }, { name: "内部通道", position: "前台后侧" }],
      anchorObjects: [{ name: "接待台", position: "空间中心" }, { name: "等候区", position: "接待台侧面" }]
    };
  }
  if (/广场|楼下/.test(label)) {
    return {
      interiorExterior: "外景",
      time: night ? "夜间" : "按剧本时段",
      description: `${label}无人空间锚点：固定建筑入口、台阶、铺装地面、道路边界和公共设施位置，保持建筑朝向、出入口与自然光方向一致。`,
      cameraAnchors: ["正对建筑入口", "台阶侧向机位", "广场纵深反打位"],
      layout: "建筑入口连接台阶与开阔铺装区，外围道路边界固定",
      entrances: [{ name: "建筑入口", position: "广场一侧" }, { name: "道路入口", position: "广场外缘" }],
      anchorObjects: [{ name: "入口台阶", position: "建筑正面" }, { name: "道路边界", position: "广场外缘" }]
    };
  }
  if (/街|巷|路|站点|路口|天桥/.test(label)) {
    return {
      interiorExterior: "外景",
      time: night ? "夜间" : "按剧本时段",
      description: `${label}无人空间锚点：固定道路走向、墙面或店面、出入口、路灯和排水边界，保持街巷宽度、转角关系与光向一致。`,
      cameraAnchors: ["沿道路纵深机位", "转角反打位", "入口侧向机位"],
      layout: "道路主轴、两侧边界、转角和出入口关系固定",
      entrances: [{ name: "道路入口", position: "画面纵深两端" }],
      anchorObjects: [{ name: "路灯", position: "道路侧边" }, { name: "转角", position: "道路纵深端" }]
    };
  }
  return {
    interiorExterior: outside ? "外景" : "内景",
    time: night ? "夜间" : "按剧本时段",
    description: `${label}无人空间锚点：固定门窗、墙面、地面、主要家具或设施、出入口、拍摄轴线和时段光向，供本场全部镜头连续使用。`,
    cameraAnchors: ["空间建立机位", "主轴侧向机位", "出入口反打位"],
    layout: "主要设施、出入口和人物活动通道位置固定",
    entrances: [{ name: "主出入口", position: "空间边缘" }],
    anchorObjects: [{ name: "主要设施", position: "空间视觉中心" }]
  };
}

function reconcileShotSceneCatalog(sceneInput = [], shotInput = []) {
  const sourceScenes = (Array.isArray(sceneInput) ? sceneInput : []).map(scene => ({ ...scene }));
  const placeholderIds = new Set(sourceScenes.filter(scene => generatedScenePlaceholderName(scene?.name)).map(scene => String(scene.id || "")).filter(Boolean));
  const placeholder = sourceScenes.find(scene => generatedScenePlaceholderName(scene?.name));
  const scenes = sourceScenes.filter(scene => !generatedScenePlaceholderName(scene?.name));
  if (placeholder) {
    scenes.push({
      ...placeholder,
      id: String(placeholder.id || "SC01"),
      name: "剧情主要空间",
      description: "按原稿中的地点、门窗、主要家具、人物走位区和拍摄轴连续呈现",
      source: "uploaded_script_scene_reconciled"
    });
  }
  const shots = (Array.isArray(shotInput) ? shotInput : []).map(shot => ({ ...shot }));
  const byId = new Map(scenes.map(scene => [String(scene.id || "").trim(), scene]).filter(([id]) => id));
  const byName = new Map(scenes.map(scene => [String(scene.name || "").trim(), scene]).filter(([name]) => name));
  const usedIds = new Set(byId.keys());
  let nextNumber = Math.max(0, ...[...usedIds].map(id => Number(/^SC(\d+)$/i.exec(id)?.[1]) || 0)) + 1;
  const nextId = () => {
    let id = "";
    do { id = `SC${String(nextNumber++).padStart(2, "0")}`; } while (usedIds.has(id));
    usedIds.add(id);
    return id;
  };

  for (const shot of shots) {
    const rawRequestedId = String(shot.sceneId || "").trim();
    const rawRequestedName = String(shot.sceneName || shot.scene || "").trim();
    const requestedId = placeholderIds.has(rawRequestedId) ? String(placeholder?.id || "") : rawRequestedId;
    const requestedName = generatedScenePlaceholderName(rawRequestedName) ? "剧情主要空间" : rawRequestedName;
    let scene = requestedId ? byId.get(requestedId) : null;
    if (!scene && requestedName) scene = byName.get(requestedName);
    if (!scene && requestedName) {
      const profile = inferredSceneProfile(requestedName);
      scene = {
        id: nextId(),
        name: requestedName,
        description: profile.description,
        interiorExterior: profile.interiorExterior,
        time: profile.time,
        lighting: profile.time === "夜间" ? "保持剧本夜景主光方向与色温一致" : "保持剧本时段自然光方向与色温一致",
        atmosphere: "无人空镜，仅保留稳定环境底噪",
        scenePurpose: `承载${requestedName}内连续剧情，统一空间关系与镜头方向`,
        entryAction: "由上一镜动作或视线自然进入",
        exitAction: "以人物离开、视线或动作结果自然衔接下一镜",
        transitionReason: "仅在剧情地点确实变化时切换",
        cameraAnchors: profile.cameraAnchors,
        layout: profile.layout,
        lightDirection: "主光方向固定，跨镜不得左右翻转",
        axis: "以主出入口和主要设施连线为固定拍摄轴",
        entrances: profile.entrances,
        anchorObjects: profile.anchorObjects,
        continuityLocks: ["门窗与主要设施位置固定", "拍摄轴与光向固定", "同一时段色温和环境状态固定"],
        source: "shot_scene_reconciled"
      };
      scenes.push(scene);
      byId.set(scene.id, scene);
      byName.set(scene.name, scene);
    }
    if (scene) {
      shot.sceneId = scene.id;
      shot.sceneName = scene.name;
    }
  }
  return { scenes, shots };
}

function normalizeAnalysis(data, project) {
  const characters = ensureStoryBibleCharacterAssets(data?.characters).map((item, index) => ({
    id: item.id || makeId("character"),
    name: String(item.name || `角色${index + 1}`),
    aliases: normalizeStringArray(item.aliases),
    age: String(item.age || ""),
    ageBand: String(item.ageBand || item.ageGroup || ""),
    gender: String(item.gender || item.sex || ""),
    role: String(item.role || ""),
    description: String(item.description || item.appearance || ""),
    descriptionEn: String(item.descriptionEn || ""),
    sourceDescription: String(item.sourceDescription ?? item.description ?? item.appearance ?? ""),
    appearanceProvenance: item.appearanceProvenance ? structuredClone(item.appearanceProvenance) : undefined,
    visualDesign: item.visualDesign ? structuredClone(item.visualDesign) : undefined,
    identitySignature: String(item.identitySignature || item.identity || ""),
    voiceDescription: String(item.voiceDescription || item.voice || ""),
    signatureLine: String(item.signatureLine || item.testLine || ""),
    continuityLocks: normalizeStringArray(item.continuityLocks),
    importance: item.importance || "supporting",
    castingTier: String(item.castingTier || item.roleType || ""),
    roleType: String(item.roleType || item.castingTier || ""),
    assetRequired: typeof item.assetRequired === "boolean" ? item.assetRequired : undefined,
    voiceAssetRequired: typeof item.voiceAssetRequired === "boolean" ? item.voiceAssetRequired : undefined,
    outfits: (Array.isArray(item.outfits) ? item.outfits : []).map((outfit, outfitIndex) => ({
      id: String(outfit?.id || `outfit_${outfitIndex + 1}`),
      label: String(outfit?.label || outfit?.name || `服装${outfitIndex + 1}`).trim(),
      description: String(outfit?.description || outfit?.appearance || "").trim(),
      units: Array.isArray(outfit?.units) ? outfit.units.map(String) : [],
      changeReason: String(outfit?.changeReason || "").trim(),
      continuityLocks: Array.isArray(outfit?.continuityLocks) ? outfit.continuityLocks.map(String) : []
    })).filter(outfit => outfit.label)
  }));
  const props = (Array.isArray(data?.props) ? data.props : []).map((item, index) => ({
    id: item.id || makeId("prop"),
    name: String(item.name || `道具${index + 1}`).trim(),
    aliases: normalizeStringArray(item.aliases),
    description: String(item.description || item.appearance || "").trim(),
    holder: String(item.holder || "").trim(),
    units: Array.isArray(item.units) ? item.units.map(String) : [],
    purpose: String(item.purpose || "").trim(),
    coreStory: item.coreStory === true,
    assetRequired: typeof item.assetRequired === "boolean" ? item.assetRequired : undefined,
    causalRole: String(item.causalRole || "").trim(),
    continuity: String(item.continuity || "").trim(),
    stateTransitions: (Array.isArray(item.stateTransitions) ? item.stateTransitions : []).map(transition => (
      transition && typeof transition === "object" ? { ...transition } : transition
    ))
  })).filter(item => item.name);
  const scenes = (Array.isArray(data?.scenes) ? data.scenes : []).map((item, index) => {
    const rawDescription = String(item.description || "");
    return {
      id: item.id || makeId("scene"),
      name: String(item.name || `场景${index + 1}`),
      sourceDescription: String(item.sourceDescription ?? rawDescription),
      sourceDescriptionOrigin: 'agent_analysis',
      description: sanitizeEmptySceneDescription(rawDescription, Array.isArray(data?.characters) ? data.characters : characters),
      interiorExterior: String(item.interiorExterior || "").trim(),
      time: String(item.time || ""),
      lighting: String(item.lighting || "").trim(),
      atmosphere: String(item.atmosphere || "").replace(/[坐站躺跪蹲靠]着的人|有人谈话|人物活动/g, "环境安静"),
      scenePurpose: String(item.scenePurpose || "").trim(),
      entryAction: String(item.entryAction || "").trim(),
      exitAction: String(item.exitAction || "").trim(),
      transitionReason: String(item.transitionReason || "").trim(),
      cameraAnchors: normalizeStringArray(item.cameraAnchors),
      layout: String(item.layout || "").trim(),
      lightDirection: String(item.lightDirection || "").trim(),
      axis: String(item.axis || "").trim(),
      entrances: (Array.isArray(item.entrances) ? item.entrances : []).map(entrance => (
        entrance && typeof entrance === "object" ? { ...entrance } : entrance
      )),
      anchorObjects: (Array.isArray(item.anchorObjects) ? item.anchorObjects : []).map(anchor => (
        anchor && typeof anchor === "object" ? { ...anchor } : anchor
      )),
      continuityLocks: Array.isArray(item.continuityLocks) ? item.continuityLocks.map(String) : []
    };
  });
  const characterByName = new Map(characters.map(item => [item.name, item.id]));
  const sceneByName = new Map(scenes.map(item => [item.name, item.id]));
  const shots = (Array.isArray(data?.shots) ? data.shots : []).map((item, index) => {
    const names = Array.isArray(item.characters) ? item.characters.map(String) : [];
    const resolveCharacterId = value => characterByName.get(String(value || "").trim()) || String(value || "").trim();
    const explicitPresence = normalizeStringArray(item.scenePresenceCharacterIds).map(resolveCharacterId).filter(Boolean);
    const scenePresenceCharacterIds = explicitPresence.length
      ? explicitPresence
      : names.map(name => resolveCharacterId(name)).filter(Boolean);
    const scenePresenceCharacterNames = scenePresenceCharacterIds.map(id => characters.find(character => character.id === id)?.name || id);
    const normalizedDialogueTurns = (Array.isArray(item.dialogueTurns) ? item.dialogueTurns : []).map(turn => {
      const normalized = normalizeDialogueTurn(turn, turn?.subshotNumber || 1);
      return {
        ...normalized,
        speakerId: resolveCharacterId(normalized.speakerId),
        listenerIds: normalizeStringArray(normalized.listenerIds).map(resolveCharacterId).filter(Boolean)
      };
    }).filter(turn => turn.speakerId && turn.text);
    const duration = normalizeTargetDurationSeconds(
      Number(item.duration) || Number(project.generation?.shotDuration) || 10,
      project.generation?.engine === "hailuo-h3" ? "puream-hailuo-h3" : "puream-hailuo-h3"
    );
    const normalizedSubshots = (Array.isArray(item.subshots) ? item.subshots : []).map((subshot, subIndex) => {
      const localTurns = (Array.isArray(subshot.dialogueTurns) ? subshot.dialogueTurns : normalizedDialogueTurns.filter(turn => turn.subshotNumber === subIndex + 1)).map(turn => {
        const normalized = normalizeDialogueTurn(turn, subIndex + 1);
        return {
          ...normalized,
          speakerId: resolveCharacterId(normalized.speakerId),
          listenerIds: normalizeStringArray(normalized.listenerIds).map(resolveCharacterId).filter(Boolean)
        };
      }).filter(turn => turn.speakerId && turn.text);
      return {
        number: subIndex + 1,
        start: Math.max(0, Number(subshot.start) || 0),
        end: Math.max(0, Number(subshot.end) || 0),
        shotType: String(subshot.shotType || subshot.function || "").trim(),
        cutReason: String(subshot.cutReason || subshot.transition || "").trim(),
        framing: String(subshot.framing || subshot.shotSize || ""),
        camera: String(subshot.camera || subshot.cameraMove || ""),
        action: String(subshot.action || ""),
        actionEn: String(subshot.actionEn || ""),
        visualEn: String(subshot.visualEn || ""),
        cameraEn: String(subshot.cameraEn || ""),
        stateBeforeEn: String(subshot.stateBeforeEn || ""),
        stateAfterEn: String(subshot.stateAfterEn || ""),
        soundEn: String(subshot.soundEn || ""),
        soundEvents: Array.isArray(subshot.soundEvents) ? subshot.soundEvents : [],
        dialogue: formatDialogueTurns(localTurns) || String(subshot.dialogue || ""),
        dialogueTurns: localTurns,
        sourceDialogueIds: normalizeStringArray(subshot.sourceDialogueIds || localTurns.map(turn => turn.sourceDialogueId)).filter(Boolean),
        sound: String(subshot.sound || ""),
        transition: String(subshot.transition || ""),
        visibleCharacterIds: normalizeStringArray(subshot.visibleCharacterIds).map(resolveCharacterId).filter(Boolean),
        speakerIds: normalizeStringArray(subshot.speakerIds).map(resolveCharacterId).filter(Boolean),
        offscreenSpeakerIds: normalizeStringArray(subshot.offscreenSpeakerIds).map(resolveCharacterId).filter(Boolean),
        speakerFacing: String(subshot.speakerFacing || "").trim(),
        listenerFacing: String(subshot.listenerFacing || "").trim(),
        eyelineDirection: String(subshot.eyelineDirection || "").trim(),
        emotionBeat: String(subshot.emotionBeat || "").trim(),
        faceAction: String(subshot.faceAction || "").trim(),
        bodyAction: String(subshot.bodyAction || "").trim(),
        voiceDelivery: String(subshot.voiceDelivery || "").trim()
      };
    });
    const authoredVisibleCharacterIds = normalizeStringArray(item.visibleCharacterIds).map(resolveCharacterId).filter(Boolean);
    const visibleCharacterIds = authoredVisibleCharacterIds.length
      ? authoredVisibleCharacterIds
      : [...new Set(normalizedSubshots.flatMap(subshot => subshot.visibleCharacterIds))];
    const requestedFocusCharacterId = resolveCharacterId(item.focusCharacterId);
    const focusCharacterId = visibleCharacterIds.includes(requestedFocusCharacterId)
      ? requestedFocusCharacterId
      : (visibleCharacterIds[0] || "");
    const requestedCounterpartCharacterId = resolveCharacterId(item.counterpartCharacterId);
    const counterpartCharacterId = visibleCharacterIds.includes(requestedCounterpartCharacterId)
      && requestedCounterpartCharacterId !== focusCharacterId
      ? requestedCounterpartCharacterId
      : (visibleCharacterIds.find(id => id !== focusCharacterId) || "");
    const authoredCharacterIds = [...new Set([
      ...normalizeStringArray(item.characterIds).map(resolveCharacterId),
      ...names.map(name => resolveCharacterId(name))
    ].filter(id => characters.some(character => character.id === id)))];
    const activeCharacterIds = [...new Set([
      ...authoredCharacterIds,
      ...visibleCharacterIds,
      ...normalizedDialogueTurns.map(turn => turn.speakerId),
      ...normalizedSubshots.flatMap(subshot => subshot.dialogueTurns.map(turn => turn.speakerId)),
      ...normalizeStringArray(item.offscreenSpeakerIds).map(resolveCharacterId)
    ].filter(Boolean))];
    const publishedCharacterIds = authoredCharacterIds.length
      ? authoredCharacterIds
      : (activeCharacterIds.length ? activeCharacterIds : scenePresenceCharacterIds.slice(0, 2));
    const shot = {
      id: item.id || makeId("shot"),
      stagingContractVersion: String(item.stagingContractVersion || ""),
      continuityCastState: item.continuityCastState || item.castState || [],
      actionBeats: Array.isArray(item.actionBeats) ? item.actionBeats : [],
      soundEvents: Array.isArray(item.soundEvents) ? item.soundEvents : [],
      productPresentation: item.productPresentation && typeof item.productPresentation === "object" ? { ...item.productPresentation } : null,
      number: index + 1,
      title: String(item.title || `镜头 ${index + 1}`),
      actNumber: Math.max(1, Number(item.actNumber) || 1),
      actTitle: String(item.actTitle || "").trim(),
      pace: String(item.pace || "").trim(),
      weatherLightingAtmosphere: String(item.weatherLightingAtmosphere || item.weather || "").trim(),
      authoredContinuity: String(item.authoredContinuity || item.continuity || "").trim(),
      duration,
      ...(item.sourcePerformanceBudget&&typeof item.sourcePerformanceBudget==='object'?{sourcePerformanceBudget:structuredClone(item.sourcePerformanceBudget)}:{}),
      characterIds: publishedCharacterIds,
      characterNames: publishedCharacterIds.map(id => characters.find(character => character.id === id)?.name || id),
      scenePresenceCharacterIds,
      scenePresenceCharacterNames,
      sceneId: sceneByName.get(String(item.scene || "")) || "",
      sceneName: String(item.scene || ""),
      wardrobeLabel: String(item.wardrobe || item.outfit || item.costume || "").trim(),
      propNames: (Array.isArray(item.props) ? item.props : []).map(String).filter(Boolean),
      action: String(item.action || item.description || ""),
      dialogue: String(item.dialogue || ""),
      shotSize: String(item.shotSize || item.framing || "中景"),
      cameraMove: String(item.cameraMove || item.camera || "固定镜头"),
      emotion: String(item.emotion || ""),
      emotionArc: item.emotionArc && typeof item.emotionArc === "object" ? { ...item.emotionArc } : {},
      performanceBeats: item.performanceBeats && typeof item.performanceBeats === "object" ? { ...item.performanceBeats } : {},
      performance: String(item.performance || ""),
      focusCharacterId,
      counterpartCharacterId,
      shotFunction: String(item.shotFunction || item.shotType || "").trim(),
      sceneObjective: String(item.sceneObjective || item.scenePurpose || "").trim(),
      transitionReason: String(item.transitionReason || item.cutReason || "").trim(),
      mainlineStage: String(item.mainlineStage || ""),
      mainlineBeat: String(item.mainlineBeat || ""),
      kindnessCost: String(item.kindnessCost || ""),
      reversalSetup: String(item.reversalSetup || ""),
      stateBefore: String(item.stateBefore || ""),
      stateAfter: String(item.stateAfter || ""),
      causalLink: String(item.causalLink || ""),
      visualBeat: String(item.visualBeat || item.action || ""),
      compositionPlan: String(item.compositionPlan || ""),
      audioPlan: String(item.audioPlan || item.soundDesign || item.sound || ""),
      soundDesign: String(item.soundDesign || item.sound || ""),
      transitionIn: String(item.transitionIn || ""),
      transitionOut: String(item.transitionOut || ""),
      startFrame: String(item.startFrame || ""),
      endFrame: String(item.endFrame || ""),
      sourceDialogueBindings: (Array.isArray(item.sourceDialogueBindings) ? item.sourceDialogueBindings : []).map(binding => normalizeSourceDialogueBinding(binding, binding?.subshotNumber || 1)),
      sourceDialogueIds: normalizeStringArray(item.sourceDialogueIds || normalizedDialogueTurns.map(turn => turn.sourceDialogueId)).filter(Boolean),
      dialogueTurns: normalizedDialogueTurns.length
        ? normalizedDialogueTurns
        : normalizedSubshots.flatMap(subshot => subshot.dialogueTurns),
      subshots: normalizedSubshots,
      sourceEditShots: (Array.isArray(item.sourceEditShots) ? item.sourceEditShots : []).map(source => ({
        number: Number(source.number) || 0,
        start: Number(source.start) || 0,
        end: Number(source.end) || 0,
        cutType: String(source.cutType || ""),
        evidence: String(source.evidence || "")
      })),
      referencePlan: item.referencePlan && typeof item.referencePlan === "object" ? item.referencePlan : {},
      productMention: Boolean(item.productMention),
      productNote: String(item.productNote || item.productInstruction || "").trim(),
      productShotType: String(item.productShotType || "none").trim().toLowerCase() || "none",
      productCausalBridge: normalizeProductCausalBridge(item.productCausalBridge),
      productBinding: item.productBinding && typeof item.productBinding === "object" ? { ...item.productBinding } : null,
      visibleCharacterIds,
      imageReferenceCharacterIds: [...visibleCharacterIds],
      videoReferenceCharacterIds: [...visibleCharacterIds],
      offscreenSpeakerIds: normalizeStringArray(item.offscreenSpeakerIds).map(resolveCharacterId).filter(Boolean),
      secondPanels: normalizeSecondPanels(item.secondPanels, duration, item),
      promptMode: "system",
      manualImagePrompt: "",
      manualVideoPrompt: "",
      systemImagePrompt: String(item.imagePrompt || ""),
      systemVideoPrompt: String(item.videoPrompt || ""),
      hailuoPromptSpec: null
    };
    const sourceSpec = item.hailuoPromptSpec || item.hailuoPrompt;
    if (projectVideoEngine(project) === "hailuo-h3" && sourceSpec) {
      const strategy = resolveShotVideoStrategy(project, shot).strategy;
      const fingerprint = promptFingerprint(project, shot, strategy || project?.generation?.mode || "keyframe");
      try {
        shot.hailuoPromptSpec = normalizePromptSpec(sourceSpec, shot, fingerprint);
        validatePromptSpec(shot.hailuoPromptSpec, shot, fingerprint);
      } catch {
        shot.hailuoPromptSpec = null;
      }
    }
    return shot;
  });
  const reconciledScenes = reconcileShotSceneCatalog(scenes, shots);
  const referenceRepair = reconcileOrphanCharacterReferences({
    ...project,
    characters,
    scenes: reconciledScenes.scenes,
    shots: reconciledScenes.shots,
    sourceDialogueLedger: Array.isArray(data?.sourceDialogueLedger) ? data.sourceDialogueLedger : []
  });
  const decorated = decorateProjectAssetMetadata({
    ...project,
    characters: referenceRepair.project.characters,
    scenes: referenceRepair.project.scenes,
    shots: referenceRepair.project.shots,
    script: {
      ...(project.script || {}),
      sourceDialogueLedger: Array.isArray(data?.sourceDialogueLedger) ? data.sourceDialogueLedger : []
    },
    assetLibraries: {
      ...(project.assetLibraries || {}),
      props
    }
  });
  return {
    detectedFormat: String(data?.detectedFormat || "").trim(),
    modeSynopsis: String(data?.modeSynopsis || data?.story?.synopsis || "").trim(),
    story: data?.story || [],
    characters: decorated.characters,
    scenes: decorated.scenes,
    props: decorated.assetLibraries.props,
    shots: decorated.shots,
    sourceDialogueLedger: Array.isArray(data?.sourceDialogueLedger) ? data.sourceDialogueLedger.map(item => ({ ...item })) : []
  };
}

function retimeSubshotsToDuration(subshots, durationSeconds, shot = {}) {
  const duration = Math.max(0.001, Number(durationSeconds) || 0.001);
  const source = Array.isArray(subshots) && subshots.length
    ? subshots.map(item => ({ ...item }))
    : Array.from({ length: 3 }, (_, index) => ({
        number: index + 1,
        start: index / 3,
        end: (index + 1) / 3,
        framing: shot.shotSize || "中景",
        camera: shot.cameraMove || "固定镜头",
        action: shot.action || shot.visualBeat || `推进第${index + 1}拍`
      }));
  const sourceEnd = Math.max(0.001, ...source.map(item => Number(item.end) || 0));
  const round = value => Number(Math.max(0, Math.min(duration, value)).toFixed(3));
  const result = source.map((item, index) => ({
    ...item,
    number: index + 1,
    start: round((Number(item.start) || 0) / sourceEnd * duration),
    end: round((Number(item.end) || sourceEnd) / sourceEnd * duration)
  })).sort((left, right) => left.start - right.start || left.end - right.end);
  result[0].start = 0;
  for (let index = 0; index < result.length; index += 1) {
    if (index > 0) result[index].start = result[index - 1].end;
    const minimumEnd = index === result.length - 1 ? duration : result[index].start + 0.001;
    result[index].end = round(Math.max(minimumEnd, result[index].end));
  }
  result[result.length - 1].end = duration;
  return result;
}

// Keep the duration contract helpful rather than punitive.  Imported or
// provider-authored analyses occasionally place several complete lines into a
// very short unit.  Before prompt compilation, split only at existing dialogue
// boundaries and lengthen the affected unit if needed.  The source wording,
// source IDs and their order are preserved; a crowded script never becomes a
// user-facing validation error merely because it needs one more continuous
// shot.
function naturalDialogueSeconds(turn = {}) {
  return estimateActedSpeechSeconds(turn?.text || turn?.spokenText, turn);
}

function dialogueGroupDuration(turns = [], shot = {}) {
  const speech = (Array.isArray(turns) ? turns : []).reduce((sum, turn) => sum + naturalDialogueSeconds(turn), 0);
  const authoredAction = estimatePhysicalActionSeconds(shot?.actionEn || shot?.visualBeatEn || shot?.action || shot?.visualBeat);
  const visualReserve = Math.max(3, Number(shot?.visualReserveSeconds) || authoredAction);
  return Math.max(10, Math.ceil(0.3 + speech + visualReserve + 0.35));
}

function splitShotForSoftDialogueTiming(shot = {}) {
  const turns = Array.isArray(shot?.dialogueTurns) ? shot.dialogueTurns.filter(turn => String(turn?.text || turn?.spokenText || "").trim()) : [];
  // The source planner already accounts for concurrent motion and legal speech
  // rates. Do not add the legacy blanket three-second reserve a second time.
  if (shot.sourcePerformanceBudget && turns.length) {
    const budget = require('./source-performance-budget').evaluateBudget(shot.sourcePerformanceBudget, turns);
    if (!budget.issues.length && budget.requiredSeconds <= Number(shot.duration)) return [{...shot, sourcePerformanceBudget:budget, dialogueTimingAdjusted:false}];
  }
  const required = dialogueGroupDuration(turns, shot);
  const current = Math.max(1, Number(shot?.duration) || 10);
  if (!turns.length || required <= current + 0.5) return [{ ...shot, dialogueTimingAdjusted: false }];
  const maxUnitSeconds = 15;
  const groups = [];
  let group = [];
  let groupSeconds = 0;
  for (const turn of turns) {
    const nextSeconds = naturalDialogueSeconds(turn);
    if (group.length && groupSeconds + nextSeconds + 3.65 > maxUnitSeconds) {
      groups.push(group);
      group = [];
      groupSeconds = 0;
    }
    group.push(turn);
    groupSeconds += nextSeconds;
  }
  if (group.length) groups.push(group);
  // A single long line has no safe word boundary to split locally.  Let the
  // prompt planner advise a compact performance after stretching it to the
  // largest provider-safe unit; no exception is raised.
  if (groups.length === 1) {
    return [{
      ...shot,
      duration: Math.min(maxUnitSeconds, required),
      dialogueTimingAdjusted: true,
      dialogueTimingOverflowAdvisory: required > maxUnitSeconds
    }];
  }
  const bindingById = new Map((Array.isArray(shot?.sourceDialogueBindings) ? shot.sourceDialogueBindings : [])
    .map(binding => [String(binding?.sourceDialogueId || binding?.sourceId || binding?.id || "").trim(), binding]));
  return groups.map((groupTurns, index) => {
    const ids = groupTurns.map(turn => String(turn?.sourceDialogueId || "").trim()).filter(Boolean);
    const subshots = (Array.isArray(shot?.subshots) ? shot.subshots : []).map(subshot => {
      const localTurns = groupTurns.filter(turn => Number(turn?.subshotNumber) === Number(subshot?.number));
      const localSpeakerIds = [...new Set(localTurns.map(turn => String(turn?.speakerId || "").trim()).filter(Boolean))];
      return {
        ...subshot,
        sourceDialogueIds: localTurns.map(turn => turn.sourceDialogueId).filter(Boolean),
        dialogueTurns: localTurns,
        dialogue: formatDialogueTurns(localTurns),
        // A soft split can move the original subshot's line into the adjacent
        // production unit. Do not leave its old speaker/mouth metadata behind
        // on what is now a silent reaction or action beat.
        speakerIds: localSpeakerIds,
        offscreenSpeakerIds: localSpeakerIds.filter(id => !(subshot?.visibleCharacterIds || []).includes(id)),
        voiceDelivery: localTurns.map(turn => turn.sourceTone || turn.delivery || "").filter(Boolean).join("；")
      };
    });
    return {
      ...shot,
      duration: Math.min(maxUnitSeconds, dialogueGroupDuration(groupTurns, index === groups.length - 1 ? shot : {})),
      dialogueTurns: groupTurns,
      dialogue: formatDialogueTurns(groupTurns),
      sourceDialogueIds: ids,
      sourceDialogueBindings: ids.map(id => bindingById.get(id)).filter(Boolean),
      subshots,
      stateBefore: index === 0 ? shot.stateBefore : "承接上一连续镜头的可见尾态和人物站位",
      stateAfter: index === groups.length - 1 ? shot.stateAfter : "本句结束后的听者反应，下一连续镜头从该反应接续",
      dialogueTimingAdjusted: true,
      dialogueTimingSplitFrom: shot.id || "",
      dialogueTimingOverflowAdvisory: false
    };
  });
}

function softScheduleDialogueShots(shots = [], targetSeconds = 0) {
  const expanded = (Array.isArray(shots) ? shots : []).flatMap(splitShotForSoftDialogueTiming);
  let plannedSeconds = expanded.reduce((sum, shot) => sum + (Number(shot?.duration) || 0), 0);
  let excess = Math.max(0, plannedSeconds - Math.max(0, Number(targetSeconds) || 0));
  // Prefer taking spare silent coverage before extending total runtime.  Never
  // squeeze a dialogue unit back below its natural plan just to satisfy a
  // configured number.
  for (const shot of expanded) {
    if (excess <= 0) break;
    const hasDialogue = Array.isArray(shot?.dialogueTurns) && shot.dialogueTurns.length;
    if (hasDialogue) continue;
    const reducible = Math.max(0, (Number(shot?.duration) || 0) - 5);
    const reduction = Math.min(reducible, excess);
    if (reduction > 0) {
      shot.duration = Math.round(((Number(shot.duration) || 0) - reduction) * 10) / 10;
      excess -= reduction;
    }
  }
  plannedSeconds = expanded.reduce((sum, shot) => sum + (Number(shot?.duration) || 0), 0);
  const idWidth = Math.max(2, String(expanded.length).length);
  const retimed = expanded.map((shot, index) => {
    const duration = Math.max(10, Math.min(15, Number(shot?.duration) || 12));
    const next = {
      ...shot,
      id: `S${String(index + 1).padStart(idWidth, "0")}`,
      number: index + 1,
      duration,
      subshots: retimeSubshotsToDuration(shot?.subshots, duration, shot)
    };
    next.secondPanels = normalizeSecondPanels(shot?.secondPanels, duration, next);
    return next;
  });
  return {
    shots: retimed,
    plannedSeconds: retimed.reduce((sum, shot) => sum + shot.duration, 0),
    extendedSeconds: Math.max(0, plannedSeconds - Math.max(0, Number(targetSeconds) || 0)),
    adjustedShotCount: retimed.filter(shot => shot.dialogueTimingAdjusted).length
  };
}

function conformImportedAnalysisToDurationContract(data, project, options = {}) {
  let normalized = normalizeAnalysis(data, project);
  if (!normalized.shots.length) {
    throw Object.assign(new Error("上传剧本没有拆出可生产分镜，请检查原稿内容"), { code: "SCRIPT_ANALYSIS_EMPTY" });
  }
  const providerKind = projectVideoProviderKind(project);
  const adaptive = projectInputMode(project) === "manual";
  const advisoryDurationOnly = options?.advisoryDurationOnly === true;
  const configuredTarget = Math.max(30, Math.round(Number(project?.generation?.targetDurationSeconds) || 300));
  const authoredRuntimeSeconds = normalized.shots.reduce((sum, shot) => sum + Math.max(0, Number(shot?.duration) || 0), 0);
  const estimatedDurations = Array.isArray(options?.durationEstimate?.normalizedDurations)
    ? options.durationEstimate.normalizedDurations.map(Number)
    : [];
  const unitContract = durationContract(providerKind, { engine: projectVideoEngine(project) });
  const authoredShotDurationsLocked = options?.durationEstimate?.authoredShotDurationsLocked === true
    && estimatedDurations.length === normalized.shots.length
    && estimatedDurations.every(value => Number.isFinite(value) && value >= unitContract.min && value <= unitContract.max);
  const targetSeconds = authoredShotDurationsLocked
    ? estimatedDurations.reduce((sum, value) => sum + value, 0)
    : authoredRuntimeSeconds > 0
      ? authoredRuntimeSeconds
      : adaptive
        ? Math.max(1, Math.round(Number(options.adaptiveTargetSeconds) || configuredTarget))
        : configuredTarget;
  const durations = authoredShotDurationsLocked
    ? Object.freeze([...estimatedDurations])
    : normalized.shots.map(shot => normalizeTargetDurationSeconds(
        Number(shot.duration) || Number(project?.generation?.shotDuration) || 10,
        unitContract
      ));
  const idWidth = Math.max(2, String(normalized.shots.length).length);
  const shots = normalized.shots.map((shot, index) => {
    const duration = durations[index];
    const subshots = retimeSubshotsToDuration(shot.subshots, duration, shot);
    const next = {
      ...shot,
      id: `S${String(index + 1).padStart(idWidth, "0")}`,
      number: index + 1,
      duration,
      subshots
    };
   next.secondPanels = normalizeSecondPanels(shot.secondPanels, duration, next);
    next.productCausalBridge = deriveProductCausalBridge(next, project?.product || {}, { characters: project?.characters });
   return next;
  });
  // Bind dialogue to the owning Sxx first. Product matching must see the
  // post-repair turns, otherwise a leftover line like “这是护膝。” can stamp
  // an earlier shot and survive after the line is moved.
  if (Array.isArray(normalized.sourceDialogueLedger) && normalized.sourceDialogueLedger.length) {
    normalized = bindSourceDialogueLedgerToAnalysis({ ...normalized, shots }, normalized.sourceDialogueLedger);
  } else {
    normalized = { ...normalized, shots };
  }
  const timingSchedule = softScheduleDialogueShots(normalized.shots, targetSeconds);
  // The source ledger records the analytical Sxx owner.  Soft splitting adds
  // continuous production units, so refresh only that local owner pointer
  // while retaining the original owner for audit.  This keeps the exact-line
  // parity checker meaningful without treating a safe split as a mismatch.
  const scheduledOwnerByDialogueId = new Map(timingSchedule.shots.flatMap(shot =>
    (Array.isArray(shot?.sourceDialogueIds) ? shot.sourceDialogueIds : [])
      .map(id => [String(id || "").trim(), String(shot?.id || "").trim()])
  ).filter(([id, owner]) => id && owner));
  const scheduledLedger = (Array.isArray(normalized.sourceDialogueLedger) ? normalized.sourceDialogueLedger : [])
    .map(item => {
      const nextOwner = scheduledOwnerByDialogueId.get(String(item?.id || "").trim());
      return nextOwner && nextOwner !== item?.sourceShotId
        ? { ...item, sourceOriginalShotId: item?.sourceOriginalShotId || item?.sourceShotId || "", sourceShotId: nextOwner }
        : item;
    });
  normalized = { ...normalized, shots: timingSchedule.shots, sourceDialogueLedger: scheduledLedger };
  normalized = applyUploadedProductBindings(normalized, project);
  assertSourceDialogueParity(normalized, normalized.sourceDialogueLedger);
  const plannedSeconds = normalized.shots.reduce((sum, shot) => sum + shot.duration, 0);
  const effectiveTargetSeconds = plannedSeconds;
  return {
    ...normalized,
    shots: normalized.shots,
    durationContract: {
      locked: false,
      targetSeconds: effectiveTargetSeconds,
      requestedTargetSeconds: configuredTarget,
      plannedSeconds,
      unitCount: normalized.shots.length,
      providerKind,
      source: adaptive ? "uploaded-script-adaptive" : "ai-authoring-reference",
      durationPolicy: advisoryDurationOnly ? "explicit-advisory" : "semantic-unit-adaptive",
      authoredShotDurationsLocked,
      authoredShotDurations: authoredShotDurationsLocked ? [...durations] : [],
      estimate: adaptive && options.durationEstimate ? { ...options.durationEstimate } : null,
      dialogueTiming: {
        mode: "soft-adaptive",
        adjustedShotCount: timingSchedule.adjustedShotCount,
        extendedSeconds: timingSchedule.extendedSeconds,
        advisory: timingSchedule.extendedSeconds > 0
      },
      checkedAt: new Date().toISOString()
    }
  };
}

function scriptQualityGateOptions(settings, extra = {}) {
  const checks = blueprintAuditChecks(settings);
  const scriptEnabled = isQualityGatesEnabled(settings, "script");
  const structuralEnabled = scriptEnabled && checks.productionStructure !== false;
  return {
    ...extra,
    blueprintChecks: checks,
    // The master/module switch skips the full audit. The production-structure
    // detail only bypasses structural contracts; every other selected detail
    // must continue to run independently.
    skipQualityGates: !scriptEnabled,
    bypassProductionContracts: !structuralEnabled,
    // Creative review is always advisory at runtime. Shape/parsing/provider
    // requirements remain hard, but a score or blueprint opinion may never
    // strand a usable script or erase the user's material.
    advisoryOnly: scriptEnabled
  };
}

const SEMANTIC_SCORE_ALIASES = {
  reversalStructure: ["reversalStructure", "reversal"],
  soundDesign: ["soundDesign", "audioPlan"]
};

function normalizeFailureShotId(value) {
  const match = String(value || "").trim().toUpperCase().match(/^S?0*(\d{1,4})$/);
  if (!match) return "";
  const number = Number(match[1]);
  return Number.isInteger(number) && number > 0 ? `S${String(number).padStart(2, "0")}` : "";
}

function normalizeFailureOwner(value) {
  const normalized = String(value || "").trim().toLowerCase().replace(/[\s_-]+/g, "");
  if (["storybible", "story", "global", "all"].includes(normalized)) return normalized === "storybible" ? "storyBible" : normalized;
  if (["shotplan", "plan", "blueprintshots", "plantail"].includes(normalized)) return "shotPlan";
  if (["shots", "units", "scriptunits", "productionshots", "draft"].includes(normalized)) return "shots";
  return "";
}

function normalizeFailureShotRange(value) {
  let startValue;
  let endValue;
  if (Array.isArray(value)) {
    [startValue, endValue] = value;
  } else if (value && typeof value === "object") {
    startValue = value.start ?? value.from ?? value.startShot ?? value.startId;
    endValue = value.end ?? value.to ?? value.endShot ?? value.endId;
  } else {
    const match = String(value || "").trim().match(/(S?\d+)\s*[-–—~至]\s*(S?\d+)/i);
    if (match) [, startValue, endValue] = match;
  }
  const start = normalizeFailureShotId(startValue);
  const end = normalizeFailureShotId(endValue || startValue);
  if (!start || !end) return null;
  const startNumber = Number(start.slice(1));
  const endNumber = Number(end.slice(1));
  return startNumber <= endNumber ? { start, end } : { start: end, end: start };
}

function scriptFailureItems(failure) {
  if (Array.isArray(failure)) return failure;
  if (!failure || typeof failure !== "object") return [];
  const candidates = [
    failure.review?.hardFailures,
    failure.audit?.failures,
    failure.hardFailures,
    failure.failures
  ];
  return candidates.find(Array.isArray) || [];
}

function isProductScriptFailure(item = {}) {
  const code = String(item?.code || "").trim().toUpperCase();
  if (code.startsWith("PRODUCT_") || code === "PRODUCT_THEME" || code === "SCORE_PRODUCTINTEGRATION" || code === "SCORE_PRODUCT_INTEGRATION") return true;
  return /商品|产品|品类动作|使用情境|卖点|productCausalBridge/i.test(String(item?.message || ""));
}

function scriptFailureRepairRoute(failure, options = {}) {
  const phase = String(options.phase || "blueprint").toLowerCase() === "full" ? "full" : "blueprint";
  const target = phase === "blueprint" ? "shotPlan" : "shots";
  const unitCount = Math.max(1, Math.round(Number(options.unitCount) || 30));
  const productEntryIndex = Math.max(0, Math.round(Number(options.productEntryIndex) || Math.floor(unitCount * 0.65)));
  const productTailStart = productTailRange(unitCount, productEntryIndex, Number(options.targetDurationSeconds) || unitCount * 10).startNumber;
  const items = scriptFailureItems(failure).filter(item => item && typeof item === "object");
  const unscoped = reason => ({ scoped: false, phase, target, unitCount, reason, failureCodes: items.map(item => String(item.code || "SEMANTIC_FAILURE")) });
  if (!items.length) return unscoped("no_hard_failures");

  let startNumber = unitCount + 1;
  let reportedEndNumber = 0;
  let productOnly = true;
  for (const item of items) {
    const productFailure = isProductScriptFailure(item);
    productOnly = productOnly && productFailure;
    const owner = normalizeFailureOwner(item.owner || item.failureOwner || item.contractOwner);
    if (owner && owner !== target) return unscoped(`owner_${owner}_cannot_repair_${target}`);
    if (!owner && !productFailure) return unscoped("missing_owner");

    const ids = [
      ...(Array.isArray(item.shots) ? item.shots : []),
      item.shotId
    ].map(normalizeFailureShotId).filter(Boolean);
    const explicitRange = normalizeFailureShotRange(item.shotRange || item.range);
    if (explicitRange) ids.push(explicitRange.start, explicitRange.end);
    const numbers = ids.map(id => Number(id.slice(1))).filter(number => number >= 1 && number <= unitCount);
    if (!numbers.length) {
      if (!productFailure) return unscoped("missing_shot_range");
      numbers.push(productTailStart, unitCount);
    }
    let itemStart = Math.min(...numbers);
    let itemEnd = Math.max(...numbers);
    // A late product fix is a causal chain, not a one-shot keyword patch.
    if (productFailure && itemStart >= productTailStart) {
      itemStart = productTailStart;
      itemEnd = unitCount;
    }
    startNumber = Math.min(startNumber, itemStart);
    reportedEndNumber = Math.max(reportedEndNumber, itemEnd);
  }
  if (!Number.isFinite(startNumber) || startNumber < 1 || startNumber > unitCount) return unscoped("invalid_shot_range");
  return {
    scoped: true,
    phase,
    target,
    owner: target,
    unitCount,
    startNumber,
    endNumber: unitCount,
    reportedEndNumber: Math.max(startNumber, reportedEndNumber),
    keepCount: startNumber - 1,
    productOnly,
    failureCodes: items.map(item => String(item.code || "SEMANTIC_FAILURE"))
  };
}

function normalizedRepairMatchText(value = "") {
  return String(value || "")
    .replace(/\s+/g, "")
    .replace(/[，。！？；：,.!?;:'"“”‘’（）()\[\]{}<>《》]/g, "")
    .toLowerCase();
}

function foundryFormalScriptFailures(error, project = {}) {
  const report = error?.details?.report;
  const issues = [
    ...(Array.isArray(report?.levels?.technical?.issues) ? report.levels.technical.issues : []),
    ...(Array.isArray(report?.levels?.story?.issues) ? report.levels.story.issues : [])
  ].filter(item => item?.severity === "blocking");
  const shots = Array.isArray(project.shots) ? project.shots : [];
  return issues.map(item => {
    const ids = new Set((String(item?.message || "").match(/S\d{1,4}/gi) || []).map(normalizeFailureShotId).filter(Boolean));
    const repeated = new Set((Array.isArray(item?.details?.repeated) ? item.details.repeated : [])
      .map(entry => normalizedRepairMatchText(Array.isArray(entry) ? entry[0] : entry?.text || entry?.value || ""))
      .filter(Boolean));
    if (repeated.size && item.id === "repeated_action_template") {
      for (const shot of shots) {
        if (repeated.has(normalizedRepairMatchText(shot.action || shot.visualBeat || shot.title || ""))) ids.add(normalizeFailureShotId(shot.id));
      }
    }
    if (repeated.size && item.id === "repeated_dialogue") {
      for (const shot of shots) {
        const turns = Array.isArray(shot.dialogueTurns) ? shot.dialogueTurns : [{ text: shot.dialogue || "" }];
        if (turns.some(turn => repeated.has(normalizedRepairMatchText(turn.spokenText || turn.text || "")))) ids.add(normalizeFailureShotId(shot.id));
      }
    }
    return {
      code: String(item?.id || "FOUNDRY_FORMAL_QUALITY_FAILURE").toUpperCase(),
      owner: "shots",
      shots: [...ids].filter(Boolean),
      message: String(item?.message || "正式生产质检未通过")
    };
  });
}

function hasFoundationalScriptCorruption(project = {}, failures = []) {
  const shots = Array.isArray(project?.shots) ? project.shots : [];
  if (!shots.length) return false;
  const missingSceneIds = new Set(failures
    .filter(item => String(item?.code || "").toUpperCase() === "SHOT_SCENE_MISSING")
    .flatMap(item => Array.isArray(item?.shots) ? item.shots : [])
    .map(normalizeFailureShotId)
    .filter(Boolean));
  const widespreadSceneLoss = missingSceneIds.size >= Math.max(3, Math.ceil(shots.length * 0.8));
  if (!widespreadSceneLoss) return false;

  return hasPollutedStoryFoundation(project);
}

function hasPollutedStoryFoundation(project = {}, storyBible = null) {
  const characters = Array.isArray(storyBible?.characters)
    ? storyBible.characters
    : (Array.isArray(project?.characters) ? project.characters : []);
  const scenes = Array.isArray(storyBible?.scenes)
    ? storyBible.scenes
    : (Array.isArray(project?.scenes) ? project.scenes : []);
  const foundationText = JSON.stringify({
    story: storyBible?.story || project?.script?.analysis || "",
    characterNames: characters.map(item => item?.name || ""),
    scenes: scenes.map(item => ({ name: item?.name || "", description: item?.description || "" }))
  });
  const pollutedFoundation = /AI\s*实时写作|模型仍在生成|当前阶段|批单元规划|我会按\s*S\d+|自动整理为制作剧本/.test(foundationText);
  const invalidCharacters = characters.some(item => /^(?:讲述者|当前阶段|我会按|模型|系统|assistant|AI)/i.test(String(item?.name || "").trim()));
  const genericSceneCatalog = !scenes.length || scenes.every(item => /^(?:剧情主要空间|主要空间|待生成|默认场景|空镜)$/i.test(String(item?.name || "").trim()));
  return pollutedFoundation || invalidCharacters || genericSceneCatalog;
}

function scriptRepairFailureSnapshot({ storyBible = null, shotPlan = [], shots = [] } = {}) {
  const payload = {
    storyBible: storyBible && typeof storyBible === "object" ? storyBible : null,
    shotPlan: Array.isArray(shotPlan) ? shotPlan : [],
    shots: Array.isArray(shots) ? shots : []
  };
  const rawJson = JSON.stringify(payload);
  return {
    format: "json",
    rawJson,
    rawJsonLength: rawJson.length,
    rawJsonSha256: crypto.createHash("sha256").update(rawJson, "utf8").digest("hex"),
    shotPlanCount: payload.shotPlan.length,
    shotCount: payload.shots.length,
    capturedAt: new Date().toISOString()
  };
}

function scriptRepairMarker(error, route, snapshot) {
  return {
    kind: "scoped_script_repair",
    phase: route.phase,
    target: route.target,
    owner: route.owner || "",
    scoped: route.scoped === true,
    startNumber: route.scoped ? route.startNumber : 1,
    endNumber: route.scoped ? route.endNumber : route.unitCount,
    reportedEndNumber: route.reportedEndNumber || route.endNumber || route.unitCount,
    keepCount: route.scoped ? route.keepCount : 0,
    productOnly: route.productOnly === true,
    failureCode: String(error?.code || "SCRIPT_QUALITY_FAILED"),
    failureCodes: route.failureCodes || [],
    reason: route.reason || "",
    retryRequiresExplicitResume: true,
    noAutomaticRetry: true,
    failureSnapshot: snapshot,
    createdAt: new Date().toISOString()
  };
}

function normalizeSemanticReview(data, options = {}) {
  const source = data && typeof data === "object" ? data : {};
  const enabledFields = Array.isArray(options.enabledFields) && options.enabledFields.length >= 0
    ? options.enabledFields.filter(field => SEMANTIC_SCORE_FIELDS.includes(field))
    : [...SEMANTIC_SCORE_FIELDS];
  const enabledSet = new Set(enabledFields);
  const productionStructureEnabled = options.productionStructureEnabled !== false;
  const scores = Object.fromEntries(SEMANTIC_SCORE_FIELDS.map(field => {
    const aliases = SEMANTIC_SCORE_ALIASES[field] || [field];
    const raw = aliases.map(key => source.scores?.[key]).find(value => value !== undefined && value !== null && value !== "");
    return [field, Math.max(0, Math.min(100, Number(raw) || 0))];
  }));
  const hardFailures = (Array.isArray(source.hardFailures) ? source.hardFailures : []).map(item => {
    const shots = [...(Array.isArray(item?.shots) ? item.shots : []), item?.shotId]
      .map(normalizeFailureShotId)
      .filter(Boolean);
    const shotRange = normalizeFailureShotRange(item?.shotRange || item?.range);
    return {
      code: String(item?.code || "SEMANTIC_FAILURE"),
      owner: normalizeFailureOwner(item?.owner || item?.failureOwner || item?.contractOwner),
      shots: [...new Set(shots)],
      ...(shotRange ? { shotRange } : {}),
      message: String(item?.message || "终审发现未说明的问题")
    };
  }).filter(item => {
    const field = blueprintCheckForFailure(item.code, item.message);
    return field === "productionStructure" ? productionStructureEnabled : enabledSet.has(field);
  });
  const repairDirectives = (Array.isArray(source.repairDirectives) ? source.repairDirectives : []).map(String).filter(Boolean);
  const scoreFailures = enabledFields.filter(field => scores[field] < 80).map(field => ({ code: `SCORE_${field.toUpperCase()}`, shots: [], message: `${BLUEPRINT_AUDIT_LABELS[field] || field}仅 ${scores[field]} 分，最低 80 分` }));
  const verdict = String(source.verdict || "").toLowerCase();
  return {
    ok: verdict === "pass" && hardFailures.length === 0 && scoreFailures.length === 0,
    verdict: verdict === "pass" ? "pass" : "revise",
    scores,
    enabledFields,
    skippedFields: SEMANTIC_SCORE_FIELDS.filter(field => !enabledSet.has(field)),
    hardFailures: [...hardFailures, ...scoreFailures],
    summary: String(source.summary || ""),
    repairDirectives
  };
}

function semanticRepairContext(failure) {
  if (!failure || typeof failure !== "object") return "";
  const review = failure.review && typeof failure.review === "object" ? failure.review : {};
  return JSON.stringify({
    failureCode: String(failure.code || "SCRIPT_BLUEPRINT_SEMANTIC_REVIEW_FAILED"),
    summary: String(review.summary || failure.message || "蓝图终审未通过"),
    scores: review.scores && typeof review.scores === "object" ? review.scores : {},
    hardFailures: Array.isArray(review.hardFailures) ? review.hardFailures : [],
    repairDirectives: Array.isArray(review.repairDirectives) ? review.repairDirectives : []
  });
}

function semanticReviewFromLiveRaw(raw) {
  const source = String(raw || "");
  const marker = source.lastIndexOf('{"verdict"');
  if (marker < 0) return null;
  try {
    const parsed = JSON.parse(source.slice(marker).trim());
    const review = normalizeSemanticReview(parsed);
    return review.verdict === "revise" ? review : null;
  } catch {
    return null;
  }
}

function markLiveScriptAsFailed(raw, title, status) {
  const source = String(raw || "");
  const heading = String(title || "AI 写作质量终审未通过");
  const state = String(status || "已停止自动写作；终审报告和定向修订断点均已保存。");
  if (!source) return `# ${heading}\n\n- 状态：${state}`;
  if (!source.startsWith("# AI 实时写作输出")) return `# ${heading}\n\n- 状态：${state}\n\n${source}`;
  return source
    .replace("# AI 实时写作输出", `# ${heading}`)
    .replace(/- 状态：模型仍在生成；[^\n]*/, `- 状态：${state}`);
}

