      if(this.scriptGenerationFlights.has(projectId))return this.scriptGenerationFlights.get(projectId);
      const flight=Promise.resolve().then(()=>this.runTrackedOperation(projectId, "idea_script", "", async () => {
        await this.generateCompleteScript(projectId, { ...options, track: false });
        return this.prepareWrittenScriptForConfirmation(projectId);
      }));
