          "Schema: {\"items\":[{\"shotId\":\"S01\",\"actionEn\":\"complete causal action with IDs\",\"stateBeforeEn\":\"exact physical before-state\",\"stateAfterEn\":\"exact visible after-state\",\"segments\":[{\"index\":0,\"startSecond\":0.0,\"endSecond\":3.2,\"actionZh\":\"与英文完全同序的中文动作\",\"framingZh\":\"中文景别\",\"cameraZh\":\"中文运镜或切镜\",\"blockingZh\":\"人物站位朝向视线轴\",\"backgroundActionZh\":\"听者或群像反应\",\"stateBeforeZh\":\"中文段前状态\",\"stateAfterZh\":\"中文段后状态\",\"soundZh\":\"中文现场声\",\"actionEn\":\"complete timed action with IDs or chronological time-compression montage\",\"framingEn\":\"camera framing\",\"cameraEn\":\"camera move, hard cut or montage cut\",\"blockingEn\":\"exact screen positions, facing, eyeline and 180-degree axis\",\"backgroundActionEn\":\"specific silent listener or authored ensemble action\",\"stateBeforeEn\":\"segment before-state\",\"stateAfterEn\":\"segment after-state\",\"soundEn\":\"location ambience and synchronized action SFX only\"}],\"dialogue\":[{\"sourceDialogueId\":\"D001\",\"startSecond\":0.0,\"endSecond\":3.2,\"deliveryZh\":\"中文说话意图与强度\",\"deliveryEn\":\"English intent and intensity\",\"vocalArcZh\":\"音量声调语速停顿重音气息三段变化\",\"vocalArcEn\":\"three-phase volume, pitch, pace, pause, stress and breath arc\",\"expressionZh\":\"中文表情\",\"expressionEn\":\"specific visible expression\",\"expressionArcEn\":\"three-phase facial micro-expression arc\",\"bodyZh\":\"中文肢体动作\",\"bodyEn\":\"exact body/hand action with IDs\",\"blockingZh\":\"中文站位\",\"blockingEn\":\"speaker and listener screen position\",\"speakerFacingZh\":\"中文朝向视线\",\"speakerFacingEn\":\"face torso eyeline and axis\",\"listenerReactionZh\":\"中文听者反应\",\"listenerReactionEn\":\"line-specific silent listener reaction\"}]}]}.",
