    const useReferenceAudio = assetSettings.videoProvider?.hailuoReferenceAudioMode === "image_audio";
    if (useReferenceAudio) this.materializeReusableCharacterVoices(projectId);
    this.reconcileProductionContracts(projectId, { markScriptFailed: false });
    let project = annotateProjectShotStrategies(this.store.getProject(projectId));
    // A validated Codex production package already owns the exact per-shot
    // dialogue partition, speaker assignment and manual H3 prompt.  Running the
    // generic ledger rebinder here redistributed the same ordered lines across
    // neighboring shots whenever their line counts differed, while leaving the
    // locked prompts unchanged.  The result was correct global text but wrong
    // speakers/actions per shot.  Package mode is validation-only at this edge.
    if (!isProductionPackageMode(project?.generation?.mode) && !require('./shot-screenplay').runtimeCurrent(project) && project.script?.sourceSceneLedger?.explicit && project.script?.sourceDialogueLedger?.length) {
      const corrected=enforceSourceSceneLedger(project,project.script.sourceSceneLedger,project.script.sourceDialogueLedger);
      project={...project,shots:corrected.shots};
    }
    const dialogueRepaired = isProductionPackageMode(project?.generation?.mode)
